INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`)
VALUES (92683, 102, 'nl', 'Angora-konijnen', 'Het angorakonijn heeft een bijzonder lange en pluizige vacht, waardoor het eruitziet als een rondlopende wolk. Oorspronkelijk werd zijn wol gebruikt voor de productie van fijne garens, maar in de dierentuin mag het gewoon lekker knuffelig zijn. Bezoekers kijken graag toe hoe het lekker knabbelt en af en toe in zijn zachte vacht verdwijnt.'),
       (92684, 102, 'fr', 'lapin angora', 'Le lapin angora possède un pelage particulièrement long et duveteux, qui lui donne l''air d''un nuage en mouvement. À l''origine, sa laine servait à la fabrication de fils fins, mais au zoo, il est simplement là pour nous faire fondre de tendresse. Les visiteurs aiment l''observer tandis qu''il grignote tranquillement et qu''il disparaît de temps à autre dans sa fourrure moelleuse.'),
       (92685, 102, 'es', 'conejo de angora', 'El conejo de angora tiene un pelaje especialmente largo y mullido, que le da el aspecto de una nube andante. Originalmente, su lana se utilizaba para fabricar hilos finos, pero en el zoo solo tiene que ser mimoso. A los visitantes les encanta observarlo mientras mordisquea tranquilamente y, de vez en cuando, se esconde entre su suave pelaje.'),
       (92686, 103, 'nl', 'Bever', 'De bever is een echte bouwmeester en gebruikt zijn sterke tanden om bomen om te hakken en dammen te bouwen. In de natuur geeft hij hele rivierlandschappen een nieuwe vorm en creëert hij nieuwe leefgebieden voor veel andere diersoorten. In jouw dierentuin weet hij de bezoekers te boeien wanneer hij takken sleept, onder water duikt en aan zijn burcht werkt.'),
       (92687, 103, 'fr', 'Castor', 'Le castor est un véritable bâtisseur : il utilise ses dents puissantes pour abattre des arbres et construire des barrages. Dans la nature, il remodèle des paysages fluviaux entiers et crée de nouveaux habitats pour de nombreuses autres espèces. Dans ton zoo, il enchante les visiteurs lorsqu’il transporte des brindilles, plonge sous l’eau et travaille à la construction de son terrier.'),
       (92688, 103, 'es', 'Castor', 'El castor es un auténtico constructor y utiliza sus fuertes dientes para talar árboles y construir presas. En la naturaleza, transforma paisajes fluviales enteros y crea nuevos hábitats para muchas otras especies. En tu zoológico, cautiva a los visitantes cuando arrastra ramas, se sumerge y trabaja en su madriguera.'),
       (92689, 104, 'nl', 'Blauwvoetjan', 'De blauwvoetgent staat vooral bekend om zijn opvallende, felblauwe poten, waarmee hij tijdens de paringsdans ware dansshows opvoert. Hij leeft doorgaans aan de kusten van de Stille Oceaan en is een behendige duiker die vissen jaagt door zich vanaf grote hoogte in het water te storten. In de dierentuin zorgen zijn waggelende gang en de trotse manier waarop hij zijn kleurrijke poten laat zien voor veel glimlachende gezichten.'),
       (92690, 104, 'fr', 'Fou à pieds bleus', 'Le fou à pieds bleus est surtout connu pour ses pieds d''un bleu éclatant, avec lesquels il exécute de véritables spectacles de danse lors de la parade nuptiale. Il vit généralement sur les côtes du Pacifique et est un plongeur habile qui chasse les poissons en plongeant dans l''eau depuis une grande hauteur. Au zoo, sa démarche dandinante et la façon dont il exhibe fièrement ses pattes colorées font naître de nombreux sourires.'),
       (92691, 104, 'es', 'Alcatraz de patas azules', 'El alcatraz de patas azules es conocido sobre todo por sus llamativas patas de un azul brillante, con las que realiza auténticos espectáculos de baile durante el cortejo. Suele vivir en las costas del Pacífico y es un hábil buceador que caza peces lanzándose al agua desde gran altura. En el zoo, su andar contoneado y la forma en que luce con orgullo sus coloridas patas hacen sonreír a muchos visitantes.'),
       (92692, 105, 'nl', 'damhert', 'Het damhert is een elegante bosbewoner met een karakteristiek, schepvormig gewei. Zijn gevlekte vacht doet denken aan zonnevlekken in het bos en biedt hem in de natuur een goede camouflage. In jouw dierentuin loopt hij rustig door het verblijf, snuffelt aan het gras en maakt indruk op de bezoekers met zijn majestueuze uitstraling.'),
       (92693, 105, 'fr', 'daim', 'Le daim est un élégant habitant des forêts, doté d’un bois caractéristique en forme de pelle. Son pelage tacheté rappelle les taches de soleil dans la forêt et lui offre un excellent camouflage dans la nature. Dans ton zoo, il se promène tranquillement dans son enclos, renifle les herbes et impressionne les visiteurs par son allure majestueuse.'),
       (92694, 105, 'es', 'gamo', 'El gamo es un elegante habitante del bosque con una característica cornamenta en forma de pala. Su pelaje manchado recuerda a los rayos de sol que se filtran en el bosque y le proporciona un buen camuflaje en la naturaleza. En tu zoológico, se pasea tranquilamente por el recinto, husmea entre la hierba e impresiona a los visitantes con su porte majestuoso.'),
       (92695, 106, 'nl', 'Grote pampaskonijn', 'Het grote pampaskonijn, ook wel ‘mara’ genoemd, lijkt op een kruising tussen een konijn en een klein ree. Het komt oorspronkelijk uit de graslanden van Zuid-Amerika en trekt vaak in paren door het landschap. In de dierentuin rent het nieuwsgierig rond of ligt het ontspannen in de zon, altijd klaar voor de volgende sprint.'),
       (92696, 106, 'fr', 'Grand lièvre de la pampa', 'Le grand lièvre de la pampa, également appelé « mara », ressemble à un croisement entre un lapin et un petit chevreuil. Originaire des prairies d''Amérique du Sud, il se déplace souvent en couple. Au zoo, il court partout avec curiosité ou se repose tranquillement au soleil, toujours prêt pour un nouveau sprint.'),
       (92697, 106, 'es', 'Liebre de la pampa grande', 'La liebre de la pampa, también conocida como «mara», parece una mezcla entre un conejo y un ciervo pequeño. Es originaria de las praderas de Sudamérica y suele desplazarse por el terreno en parejas. En el zoo corre de un lado a otro con curiosidad o descansa relajada al sol, siempre lista para la próxima carrera.'),
       (92698, 107, 'nl', 'Grote panda', 'De reuzenpanda is met zijn zwart-witte vacht een van de bekendste symbolen voor de bescherming van diersoorten. Ondanks zijn omvang voedt hij zich voornamelijk met bamboe en brengt hij vele uren per dag door met gezellig knabbelen. In jouw dierentuin zit hij vaak ontspannen, met een bamboestengel in zijn poten, en betovert hij de bezoekers met zijn vredige karakter.'),
       (92699, 107, 'fr', 'Grand panda', 'Avec son pelage noir et blanc, le grand panda est l''un des symboles les plus connus de la protection des espèces. Malgré sa taille imposante, il se nourrit principalement de bambou et passe de nombreuses heures par jour à le grignoter tranquillement. Dans ton zoo, il est souvent assis, détendu, une tige de bambou entre les pattes, et enchante les visiteurs par son caractère paisible.'),
       (92700, 107, 'es', 'Panda gigante', 'El panda gigante, con su pelaje blanco y negro, es uno de los símbolos más conocidos de la conservación de las especies. A pesar de su tamaño, se alimenta principalmente de bambú y pasa muchas horas al día comiendo tranquilamente. En tu zoológico suele estar sentado relajado, con una caña de bambú entre las patas, y cautiva a los visitantes con su carácter tranquilo.'),
       (92701, 108, 'nl', 'Haas', 'Het konijn is een snelle vluchtkunstenaar met lange achterpoten en grote, spitse oren. Het leeft in open landschappen en vertrouwt op zijn snelheid en waakzaamheid om aan gevaren te ontsnappen. In de dierentuin huppelt hij behendig door het verblijf, verzorgt hij zichzelf grondig en zorgt hij bij kinderen voor veel „O, wat schattig!“-momenten.'),
       (92702, 108, 'fr', 'lièvre', 'Le lièvre est un spécialiste de la fuite, doté de longues pattes arrière et de grandes oreilles dressées. Il vit dans des paysages ouverts et compte sur sa rapidité et sa vigilance pour échapper aux dangers. Au zoo, il sautille agilement dans son enclos, se toilette longuement et suscite chez les enfants de nombreux moments d’émerveillement : « Oh, comme c’est mignon ! ».'),
       (92703, 108, 'es', 'Liebre', 'La liebre es una experta en la huida, con largas patas traseras y grandes orejas erguidas. Vive en paisajes abiertos y confía en su velocidad y su vigilancia para escapar de los peligros. En el zoo, corretea ágilmente por el recinto, se acicala a fondo y provoca muchos momentos de «¡Qué monada!» entre los niños.'),
       (92704, 111, 'nl', 'Husarenaap', 'De Husarenaap is een van de snelste primaten ter wereld en kan tijdens zijn vlucht indrukwekkende snelheden halen. Met zijn roodachtige vacht en lichte gezicht is hij gemakkelijk te herkennen en ziet hij er altijd een beetje ernstig uit. In de dierentuin is hij meestal in beweging: hij klimt, rent en kijkt nieuwsgierig toe wat de bezoekers zoal uitspoken.'),
       (92705, 111, 'fr', 'singe des Husarenes', 'Le singe de Husarena est l''un des primates les plus rapides au monde et peut atteindre des vitesses impressionnantes lorsqu''il prend la fuite. Avec son pelage rougeâtre et son visage clair, il est facile à reconnaître et a toujours l''air un peu sérieux. Au zoo, il est presque toujours en mouvement : il grimpe, court et observe avec curiosité ce que font les visiteurs.'),
       (92706, 111, 'es', 'Mono de Husarena', 'El mono de Husarena es uno de los primates más rápidos del mundo y puede alcanzar velocidades impresionantes cuando huye. Con su pelaje rojizo y su cara clara, es fácil de reconocer y siempre parece un poco serio. En el zoo suele estar en constante movimiento: trepa, corre y observa con curiosidad lo que hacen los visitantes.'),
       (92707, 112, 'nl', 'Jaguarundi', 'De jaguarundi is een slanke, klein ogende wilde kat met een ongewoon lang lichaam en een korte vacht. Hij leeft vooral in Midden- en Zuid-Amerika en is een behendige jager die zich zowel op de grond als in struiken voortbeweegt. In jouw dierentuin sluipt hij geruisloos door het verblijf, duikt tussen de planten op en verdwijnt weer bijna geruisloos.'),
       (92708, 112, 'fr', 'Jaguarundi', 'Le jaguarundi est un chat sauvage élancé, d''apparence menue, au corps exceptionnellement long et au pelage court. Il vit principalement en Amérique centrale et en Amérique du Sud et est un chasseur habile qui se déplace aussi bien au sol que dans les buissons. Dans ton zoo, il se faufile sans bruit à travers son enclos, surgit entre les plantes et disparaît à nouveau presque sans faire de bruit.'),
       (92709, 112, 'es', 'Jaguarundi', 'El jaguarundi es un felino salvaje esbelto y de aspecto pequeño, con un cuerpo inusualmente alargado y pelaje corto. Vive principalmente en América Central y del Sur y es un hábil cazador que se desplaza tanto por el suelo como entre los matorrales. En tu zoológico, se desliza silenciosamente por el recinto, aparece entre la vegetación y vuelve a desaparecer casi sin hacer ruido.'),
       (92710, 113, 'nl', 'Klunkerkraanvogel', 'De sierkraanvogel dankt zijn naam aan de opvallende sierveren en huidplooien op zijn kop en nek. Net als alle kraanvogels is hij een elegante danser, die indruk maakt met zijn vleugelslagen en sprongen. In de dierentuin paraderen de dieren door het verblijf en laten ze zich graag bewonderen terwijl ze hun prachtige verenkleed verzorgen.'),
       (92711, 113, 'fr', 'Grue à collier', 'La grue à plumes ornées doit son nom à ses plumes décoratives voyantes et aux fanons qui ornent sa tête et son cou. Comme toutes les grues, c''est une danseuse élégante qui impressionne par ses battements d''ailes et ses sauts. Au zoo, les animaux se pavanent dans leur enclos et se laissent volontiers admirer lorsqu''ils lissent leur magnifique plumage.'),
       (92712, 113, 'es', 'Grulla de Klunker', 'La grulla joyera debe su nombre a las llamativas plumas decorativas y a los pliegues de piel que tiene en la cabeza y el cuello. Como todas las grullas, es una elegante bailarina que impresiona con el batir de sus alas y sus saltos. En el zoo, los animales se pavonean por el recinto y, mientras acicalan su magnífico plumaje, disfrutan de que los admiren.'),
       (92713, 114, 'nl', 'Kortebekegels', 'De kortsnavelegel is een stekelige insecteneter uit Australië, die een beetje doet denken aan een stekelige miereneter. Met zijn lange tong spoort hij mieren en termieten op in hun nesten. In jouw dierentuin snuffelt hij nieuwsgierig door het verblijf, graaft hij kleine gaatjes en rolt hij zich bij gevaar op tot een stekelige bal.'),
       (92714, 114, 'fr', 'Hérisson à bec court', 'Le hérisson à bec court est un insectivore hérissé originaire d''Australie, qui rappelle un peu un fourmilier hérissé. Grâce à sa longue langue, il repère les fourmis et les termites dans leurs nids. Dans ton zoo, il explore son enclos avec curiosité, creuse de petits trous et, en cas de danger, se recroqueville pour former une boule hérissée de piquants.'),
       (92715, 114, 'es', 'Erizo de hocico corto', 'El erizo de hocico corto es un insectívoro espinoso de Australia que recuerda un poco a un oso hormiguero espinoso. Con su larga lengua, localiza hormigas y termitas en sus nidos. En tu zoo, husmea con curiosidad por el recinto, cava pequeños agujeros y, ante el peligro, se enrosca formando una bola llena de púas.'),
       (92716, 115, 'nl', 'Lippenbeer', 'De lipbeer heeft een ruige vacht en een lange, beweeglijke snuit, waarmee hij insecten uit hun nesten zuigt. Hij komt vooral in India voor en is dol op termietenheuvels en zoete vruchten. In de dierentuin kun je hem zien terwijl hij met smakkende lippen zijn voedsel opzuigt en daarbij vrolijk snuift.'),
       (92717, 115, 'fr', 'ours à lèvres', 'L''ours à lèvres a un pelage hirsute et un museau long et mobile, grâce auquel il aspire les insectes hors de leurs nids. Il vit principalement en Inde et raffole des termitières et des fruits sucrés. Au zoo, on peut l''observer en train d''aspirer sa nourriture en claquant des lèvres, tout en haletant joyeusement.'),
       (92718, 115, 'es', 'Oso de labios', 'El oso labial tiene un pelaje hirsuto y un hocico largo y ágil, con el que succiona insectos de sus nidos. Habita principalmente en la India y le encantan los termiteros y las frutas dulces. En el zoo se le puede observar cómo aspira la comida haciendo ruidos con los labios y resoplando alegremente.'),
       (92719, 116, 'nl', 'lepelaar', 'De lepelaar is een elegante waadvogel met een karakteristieke lepelvormige snavel. Hiermee doorzoekt hij ondiepe wateren op zoek naar kleine vissen en ongewervelde dieren. In jouw dierentuin schrijdt hij rustig door het waterbassin en laat hij zijn bijzondere snavel zachtjes heen en weer slingeren.'),
       (92720, 116, 'fr', 'Löffler',
        'Der Löffler ist ein eleganter Watvogel mit einem charakteristischen löffelförmigen Schnabel. Mit diesem durchkämmt er flache Gewässer, um kleine Fische und Wirbellose aufzuspüren. In deinem Zoo schreitet er gemächlich durchs Wasserbecken und lässt seinen ungewöhnlichen Schnabel sanft hin und her pendeln.'),
       (92721, 116, 'es', 'spoonbill', 'La espátula es una elegante ave zancuda con un característico pico en forma de cuchara. Con él, remueve las aguas poco profundas para localizar pequeños peces e invertebrados. En tu zoo, camina tranquilamente por el estanque y balancea suavemente su peculiar pico de un lado a otro.'),
       (92722, 117, 'nl', 'Manenwolf', 'De manenwolf is geen echte wolf, maar een aparte soort wilde hond met zeer lange poten en een felrode vacht. Hij leeft in de graslanden van Zuid-Amerika en is een nogal schuwe eenling. In de dierentuin sluipt hij elegant door zijn territorium, snuffelt aan het gras en luistert aandachtig naar elk geluid.'),
       (92723, 117, 'fr', 'Loup à crinière', 'Le loup à crinière n''est pas un véritable loup, mais une espèce distincte de chien sauvage aux pattes très longues et au pelage rouge vif. Il vit dans les prairies d''Amérique du Sud et est un animal solitaire plutôt farouche. Au zoo, il se déplace avec élégance dans son enclos, renifle les herbes et tend l''oreille à chaque bruit.'),
       (92724, 117, 'es', 'Lobo de melena', 'El lobo de melena no es un lobo propiamente dicho, sino una especie propia de perro salvaje con patas muy largas y pelaje de un rojo brillante. Vive en las praderas de Sudamérica y es un animal solitario y bastante tímido. En el zoo, se desliza con elegancia por su territorio, olfatea la hierba y escucha atentamente cada ruido.'),
       (92725, 118, 'nl', 'Mantsjoerische kraanvogel', 'De Mantsjoerij-kraanvogel is een majestueuze vogel met een zwart-wit verenkleed en een rode vlek op zijn kop. In veel Aziatische culturen geldt hij als symbool van geluk en een lang leven. In jouw dierentuin voert hij zijn gracieuze dansen uit en maakt hij indruk op bezoekers met zijn brede vleugelslagen.'),
       (92726, 118, 'fr', 'Grue de Mandchourie', 'La grue de Mandchourie est un oiseau majestueux au plumage blanc et noir, avec une tache rouge sur la tête. Dans de nombreuses cultures asiatiques, elle est considérée comme un symbole de bonheur et de longue vie. Dans ton zoo, elle exécute ses danses gracieuses et impressionne les visiteurs par ses grands battements d''ailes.'),
       (92727, 118, 'es', 'Grulla de Manchuria', 'La grulla de Manchuria es un ave majestuosa con plumaje blanco y negro y una mancha roja en la cabeza. En muchas culturas asiáticas se la considera un símbolo de buena suerte y larga vida. En tu zoológico, muestra sus elegantes danzas e impresiona a los visitantes con sus amplios aleteos.'),
       (92728, 119, 'nl', 'neusbeer', 'De neusbeer is met zijn lange, beweeglijke snuit een nieuwsgierige acrobaat in het verblijf. Hij komt voor in Midden- en Zuid-Amerika en is voortdurend op zoek naar insecten, fruit en kleine lekkernijen. In de dierentuin klimt hij behendig in bomen, snuffelt overal rond en zorgt met zijn gezellige karakter voor veel vermaak.'),
       (92729, 119, 'fr', 'coati', 'Avec son long museau agile, le coati est un acrobate curieux dans son enclos. Originaire d''Amérique centrale et d''Amérique du Sud, il est constamment à la recherche d''insectes, de fruits et de petites friandises. Au zoo, il grimpe habilement aux branches, renifle partout et, grâce à son caractère sociable, nous divertit beaucoup.'),
       (92730, 119, 'es', 'coatí', 'El coatí, con su hocico largo y ágil, es un acróbata curioso dentro de su recinto. Es originario de América Central y del Sur y está siempre en busca de insectos, frutos y pequeños manjares. En el zoo trepa con destreza por las ramas, husmea por todas partes y, gracias a su carácter sociable, ofrece un gran espectáculo.'),
       (92731, 120, 'nl', 'Nilgau-antilope', 'De Nilgauantilope is de grootste antilopensoort van Azië en doet met zijn krachtige lichaamsbouw bijna denken aan een klein paard. Mannetjes hebben een grijsblauwe vacht, terwijl vrouwtjes eerder bruin van kleur zijn. In jouw dierentuin grazen ze rustig in hun verblijf en laten ze zich graag door bezoekers observeren terwijl ze herkauwen.'),
       (92732, 120, 'fr', 'antilope du Nilgau', 'L''antilope du Nil est la plus grande espèce d''antilope d''Asie et, avec sa carrure imposante, elle fait presque penser à un petit cheval. Les mâles ont un pelage gris-bleu, tandis que les femelles sont plutôt brunes. Dans ton zoo, elles paissent tranquillement dans leur enclos et se laissent volontiers observer par les visiteurs pendant qu''elles ruminent.'),
       (92733, 120, 'es', 'antílope del Nilo', 'El antílope del Nilo es la especie de antílope más grande de Asia y, con su complexión robusta, recuerda casi a un caballo pequeño. Los machos tienen un pelaje gris azulado, mientras que las hembras son más bien de color marrón. En tu zoo pastan tranquilamente en su recinto y les gusta que los visitantes los observen mientras rumian.'),
       (92734, 121, 'nl', 'Nilwaran', 'De nilwaran is een grote, krachtige hagedis die langs Afrikaanse waterlopen leeft. Met zijn gespleten tong spoort hij prooien op en is hij zowel op het land als in het water een goede jager. In de dierentuin ligt hij graag lui in de zon, om vervolgens plotseling verbazingwekkend snel weg te rennen.'),
       (92735, 121, 'fr', 'Nilwaran', 'Le nilwaran est un grand lézard robuste qui vit au bord des cours d''eau africains. Grâce à sa langue fourchue, il repère ses proies et est un excellent chasseur, tant sur terre que dans l''eau. Au zoo, il aime se prélasser au soleil, avant de s''élancer soudain avec une rapidité étonnante.'),
       (92736, 121, 'es', 'Nilwaran', 'El nilwaran es un lagarto grande y robusto que habita a orillas de los cursos de agua africanos. Con su lengua bífida localiza a sus presas y es un buen cazador tanto en tierra como en el agua. En el zoo le gusta tumbarse perezosamente al sol para, de repente, salir corriendo con una rapidez asombrosa.'),
       (92737, 122, 'nl', 'Oostelijke grasuil', 'De oostelijke grasuil is een onopvallende nachtvlinder die vooral ’s nachts actief is. Hij leeft in graslanden en velden en vormt een belangrijk onderdeel van de voedselketen. In jouw dierentuin fladdert hij zachtjes door de avondlucht en zorgt hij als kleine, bijzondere gast voor een sfeervolle ambiance.'),
       (92738, 122, 'fr', 'Hibou des prés oriental', 'La phalène des prairies est un papillon de nuit discret, principalement actif la nuit. Elle vit dans les prairies et les champs et joue un rôle important dans la chaîne alimentaire. Dans ton zoo, elle vole doucement dans l''air du soir et, en tant que petite invitée d''exception, elle contribue à créer une ambiance chaleureuse.'),
       (92739, 122, 'es', 'Búho de las praderas oriental', 'La polilla oriental de la hierba es una discreta mariposa nocturna que se activa sobre todo por la noche. Vive en praderas y campos, y es un eslabón importante de la cadena alimentaria. En tu zoológico, revolotea silenciosamente en el aire del atardecer y, como pequeña e especial invitada, crea un ambiente evocador.'),
       (92740, 123, 'nl', 'Pantserneshorn', 'De gepantserde neushoorn dankt zijn naam aan de dikke, plaatachtige huidplooien die op een harnas lijken. Hij komt uit Azië en brengt veel tijd door in modderpoelen en waterpoelen. In jouw dierentuin stapt hij rustig door het verblijf, wrijft zich tegen bomen en geniet van een verfrissend modderbad.'),
       (92741, 123, 'fr', 'rhinocéros blindé', 'Le rhinocéros indien tire son nom des plis épais de sa peau, qui ressemblent à des plaques et lui donnent l''air de porter une armure. Originaire d''Asie, il passe beaucoup de temps dans les mares de boue et les points d''eau. Dans ton zoo, il se promène tranquillement dans son enclos, se frotte contre les arbres et savoure un bain de boue rafraîchissant.'),
       (92742, 123, 'es', 'rinoceronte acorazado', 'El rinoceronte indio debe su nombre a los gruesos pliegues de su piel, que parecen placas y se asemejan a una armadura. Es originario de Asia y pasa mucho tiempo en charcos de barro y de agua. En tu zoológico, camina tranquilamente por el recinto, se frota contra los árboles y disfruta de un refrescante baño de barro.'),
       (92743, 125, 'nl', 'Poitou-ezels', 'De Poitou-ezel is gemakkelijk te herkennen aan zijn lange, ruige vacht en zijn grote oren. Hij komt oorspronkelijk uit Frankrijk en behoort tot de oudste en zeldzaamste ezelrassen ter wereld. In de dierentuin weet hij het publiek te bekoren met zijn rustige karakter en zijn ietwat ruige charme.'),
       (92744, 125, 'fr', 'Âne du Poitou', 'L''âne du Poitou se reconnaît facilement à sa longue robe hirsute et à ses grandes oreilles. Originaire de France, il fait partie des races d''ânes les plus anciennes et les plus rares au monde. Au zoo, il séduit par son caractère tranquille et son charme un peu débraillé.'),
       (92745, 125, 'es', 'Burro de Poitou', 'El burro de Poitou se reconoce fácilmente por su pelaje largo y hirsuto y sus grandes orejas. Es originario de Francia y es una de las razas de burros más antiguas y raras del mundo. En el zoo cautiva a los visitantes con su carácter tranquilo y su encanto un tanto desaliñado.'),
       (92746, 126, 'nl', 'Reuzenkonijnen', 'Het reuzenkonijn doet zijn naam alle eer aan en weegt aanzienlijk meer dan zijn kleinere verwanten. Ondanks zijn grootte is het meestal zachtaardig en houdt het van gezellige rustplekjes. In jouw dierentuin zit het graag ontspannen in het stro en knabbelt het langzaam aan grote porties groente.'),
       (92747, 126, 'fr', 'Lapin géant', 'Le lapin géant fait honneur à son nom et pèse nettement plus lourd que ses petits cousins. Malgré sa taille, il est généralement docile et adore les coins tranquilles où se reposer. Dans ton zoo, il aime se détendre dans la paille et grignoter tranquillement de grandes portions de légumes.'),
       (92748, 126, 'es', 'Conejos gigantes', 'El conejo gigante hace honor a su nombre y pesa bastante más que sus parientes más pequeños. A pesar de su tamaño, suele ser dócil y le encantan los lugares tranquilos donde descansar. En tu zoológico le gusta sentarse relajado sobre la paja y ir comiendo poco a poco grandes raciones de verduras.'),
       (92749, 127, 'nl', 'Buiskat', 'De rietkat is een schuwe wilde kat die het liefst in rietgebieden en langs waterkanten leeft. Haar vacht is meestal effen van kleur en biedt een goede camouflage in het hoge gras. In de dierentuin beweegt ze zich rustig en voorzichtig, luistert aandachtig en laat zich vaak pas na wat geduld aan bezoekers zien.'),
       (92750, 127, 'fr', 'gratte-tuyau', 'Le chat des roseaux est un félin sauvage timide qui vit de préférence dans les roselières et au bord des cours d’eau. Son pelage est généralement uni et lui offre un bon camouflage dans les hautes herbes. Au zoo, il se déplace calmement et prudemment, tend l’oreille avec attention et ne se montre souvent aux visiteurs qu’après un peu de patience.'),
       (92751, 127, 'es', 'Desatascador de tuberías', 'El gato de los juncos es un felino salvaje tímido que prefiere vivir en zonas de juncos y a orillas de los cursos de agua. Su pelaje suele ser de un solo color y le proporciona un buen camuflaje entre la hierba alta. En el zoológico se mueve con calma y cautela, escucha con atención y, a menudo, solo se deja ver por los visitantes tras un poco de paciencia.'),
       (92752, 129, 'nl', 'Klapschildpad', 'De bijtschildpad is een indrukwekkend grote zoetwaterschildpad met een krachtige kaak. Ze lijkt traag, maar kan bliksemsnel toeslaan als er prooi binnen bereik komt. In de dierentuin ligt ze vaak op de bodem van het bassin of zonnen ze zich op een steen, terwijl bezoekers haar prehistorische uiterlijk bewonderen.'),
       (92753, 129, 'fr', 'Tortue à mâchoires rétractables', 'La tortue à mâchoires est une tortue d''eau douce d''une taille impressionnante, dotée de mâchoires puissantes. Elle semble lente, mais peut mordre à la vitesse de l''éclair dès qu''une proie se trouve à sa portée. Au zoo, elle repose souvent au fond de son bassin ou se prélasse au soleil sur un rocher, tandis que les visiteurs s''émerveillent devant son allure préhistorique.'),
       (92754, 129, 'es', 'Tortuga mordedora', 'La tortuga mordedora es una tortuga de agua dulce de un tamaño impresionante y con una mandíbula poderosa. Aunque parece lenta, puede morder con la rapidez del rayo cuando una presa se acerca a su alcance. En el zoo suele estar tumbada en el fondo del estanque o tomando el sol sobre una piedra, mientras los visitantes admiran su aspecto prehistórico.'),
       (92755, 130, 'nl', 'Schots hooglandrund', 'Het Schotse Hooglandrund is met zijn lange vacht en machtige hoorns een echte blikvanger. Het komt uit de ruige streken van Schotland en is uitstekend aangepast aan weer en wind. In jouw dierentuin ziet het er gezellig en vredig uit, terwijl het langzaam het gras afgraast en zijn vacht in de wind wappert.'),
       (92756, 130, 'fr', 'Bovins des Highlands écossais', 'Avec son long pelage et ses cornes imposantes, le bœuf des Highlands écossais attire vraiment tous les regards. Originaire des régions rudes d''Écosse, il est parfaitement adapté aux intempéries. Dans ton zoo, il semble détendu et paisible tandis qu''il broute tranquillement l''herbe et que son pelage flotte au gré du vent.'),
       (92757, 130, 'es', 'Vaca de las Tiernas Escocesas', 'La vaca de las Tierras Altas de Escocia, con su largo pelaje y sus imponentes cuernos, llama mucho la atención. Es originaria de las regiones más inhóspitas de Escocia y está perfectamente adaptada al viento y a las inclemencias del tiempo. En tu zoológico se la ve tranquila y apacible, mientras pasta lentamente la hierba y el viento le agita el pelaje.'),
       (92758, 131, 'nl', 'schoensnavel', 'De schoensnavel dankt zijn naam aan zijn enorme, schoenvormige snavel, die hem een bijna prehistorisch uiterlijk geeft. Hij leeft in Afrikaanse moerassen en ligt daar geduldig op de loer naar vissen en andere prooien. In de dierentuin staat hij vaak roerloos in het water en verbaast hij bezoekers met zijn stoïcijnse kalmte.'),
       (92759, 131, 'fr', 'bec en forme de chaussure', 'Le bec-de-chaussure doit son nom à son immense bec en forme de chaussure, qui lui donne un aspect presque préhistorique. Il vit dans les marécages africains où il guette patiemment les poissons et autres proies. Au zoo, il reste souvent immobile dans l''eau et étonne les visiteurs par son calme stoïque.'),
       (92760, 131, 'es', 'Pico de zapato', 'El picozapato debe su nombre a su enorme pico con forma de zapato, que le da un aspecto casi prehistórico. Vive en los pantanos africanos, donde acecha pacientemente a los peces y otras presas. En el zoo suele permanecer inmóvil en el agua y sorprende a los visitantes con su calma estoica.'),
       (92761, 132, 'nl', 'Zwaan', 'De zwaan staat symbool voor elegantie en gratie en glijdt schijnbaar moeiteloos over het water. Met zijn lange nek en witte verenkleed trekt hij overal de aandacht. In jouw dierentuin vormt hij op de vijver een schilderachtig decor en zorgt hij voor rustige, romantische momenten.'),
       (92762, 132, 'fr', 'Cygne', 'Le cygne est un symbole d''élégance et de grâce ; il glisse sur l''eau avec une aisance apparente. Avec son long cou et son plumage blanc, il attire tous les regards. Dans ton zoo, il offre un décor pittoresque sur l''étang et procure des moments de calme et de romantisme.'),
       (92763, 132, 'es', 'Cisne', 'El cisne es un símbolo de elegancia y gracia, y se desliza por el agua con aparente facilidad. Con su largo cuello y su plumaje blanco, atrae todas las miradas allá donde va. En tu zoo, crea un pintoresco escenario en el estanque y te regala momentos tranquilos y románticos.'),
       (92764, 133, 'nl', 'Shetlandpony', 'De Shetlandpony is klein, robuust en verbazingwekkend sterk voor zijn grootte. Hij komt oorspronkelijk van de winderige Shetlandeilanden en heeft een dikke vacht die hem goed beschermt. In de dierentuin geniet hij van de aaiende handjes van de kinderen en draaft hij vrolijk door zijn verblijf.'),
       (92765, 133, 'fr', 'poney des Shetland', 'Le poney des Shetland est petit, robuste et étonnamment vigoureux pour sa taille. Originaire des îles des Shetland, balayées par le vent, il possède un pelage épais qui le protège bien. Au zoo, il apprécie les caresses des enfants et trotte joyeusement dans son enclos.'),
       (92766, 133, 'es', 'poni de las Shetland', 'El poni de Shetland es pequeño, robusto y sorprendentemente fuerte para su tamaño. Es originario de las ventosas islas de Shetland y tiene un pelaje denso que le protege bien. En el zoo, disfruta de las caricias de los niños y trota alegremente por su recinto.'),
       (92767, 134, 'nl', 'Stekel-Ibis', 'De stekelibis is een opvallend ogende vogel met een kale kop en een glanzend donker verenkleed. Vroeger kwam hij in Europa op grote schaal voor, maar tegenwoordig is hij zeldzaam geworden en staat hij onder bescherming. In jouw dierentuin laat hij zich graag zien terwijl hij op rotsen zit en zijn veren in de zon laat glinsteren.'),
       (92768, 134, 'fr', 'Courge épineuse', 'Le cormoran huppé est un oiseau à l''allure singulière, avec une tête nue et un plumage sombre et brillant. Autrefois très répandu en Europe, il est aujourd''hui devenu rare et fait l''objet d''une protection. Dans ton zoo, il aime se montrer perché sur des rochers et laisser ses plumes scintiller au soleil.'),
       (92769, 134, 'es', 'Stachelibis', 'El ibis espinoso es un ave de aspecto peculiar, con la cabeza desnuda y un plumaje oscuro y brillante. Antiguamente estaba muy extendido en Europa, pero hoy en día se ha vuelto escaso y está protegido. En tu zoológico le gusta dejarse ver posado sobre las rocas y dejar que sus plumas brillen al sol.'),
       (92770, 136, 'nl', 'Tapir', 'De tapir lijkt met zijn korte snuit op een kruising tussen een varken en een klein neusdiertje. Hij leeft in tropische bossen en houdt ervan om af en toe een duik te nemen in rivieren en poelen. In de dierentuin slentert hij rustig door zijn verblijf, knabbelt aan bladeren en geniet van uitgebreide modderbaden.'),
       (92771, 136, 'fr', 'Tapir', 'Avec sa trompe courte, le tapir ressemble à un croisement entre un cochon et un petit nez. Il vit dans les forêts tropicales et adore se baigner dans les rivières et les mares. Au zoo, il se promène tranquillement dans son enclos, grignote des feuilles et prend de longs bains de boue.'),
       (92772, 136, 'es', 'Tapir', 'El tapir parece una mezcla entre un cerdo y una nariz pequeña, con su trompa corta. Vive en los bosques tropicales y le encanta darse un chapuzón en ríos y charcas. En el zoo, pasea tranquilamente por su recinto, mordisquea hojas y disfruta de largos baños de barro.'),
       (92773, 137, 'nl', 'Woudraap', 'De woudibis is een zeldzaam geworden ibis met een glanzend zwart verenkleed en een kale kop. Vroeger kwam hij ook in Europa voor, maar tegenwoordig wordt hij via fokprogramma’s weer uitgezet. In jouw dierentuin zit hij graag op verhoogde plekken en laat hij de bezoekers zijn opvallende silhouet zien.'),
       (92774, 137, 'fr', 'Ibis chauve', 'Le ibis chauve est une espèce d''ibis devenue rare, au plumage noir brillant et à la tête chauve. Autrefois présent en Europe, il fait aujourd''hui l''objet de programmes d''élevage visant à le réintroduire. Dans ton zoo, il aime se percher en hauteur pour montrer aux visiteurs sa silhouette caractéristique.'),
       (92775, 137, 'es', 'ibis de bosque', 'El ibis eremita es una especie de ibis que se ha vuelto muy escasa, con un plumaje negro brillante y la cabeza calva. Antiguamente también vivía en Europa; hoy en día se está reintroduciendo mediante programas de cría. En tu zoológico le gusta posarse en lugares elevados y mostrar a los visitantes sus contornos característicos.'),
       (92776, 138, 'nl', 'Wasbeer', 'De wasbeer is een slimme kleine roofdier die meteen opvalt door zijn „masker“ op het gezicht. In de natuur doorzoekt hij rivieren, vuilnisbakken en alles wat op voedsel lijkt. In de dierentuin klimt hij behendig in klimboompjes en voerspeeltjes en maakt hij indruk op de bezoekers met zijn behendigheid.'),
       (92777, 138, 'fr', 'raton laveur', 'Le raton laveur est un petit prédateur rusé qui se remarque immédiatement grâce à son « masque » facial. Dans la nature, il fouille les rivières, les poubelles et tout ce qui ressemble à de la nourriture. Au zoo, il grimpe habilement aux arbres d''escalade et aux jouets à nourriture, et impressionne les visiteurs par son agilité.'),
       (92778, 138, 'es', 'mapache', 'El mapache es un pequeño depredador muy astuto que llama la atención de inmediato por su «máscara» facial. En la naturaleza, rebusca en ríos, contenedores de basura y cualquier lugar que parezca contener comida. En el zoo, trepa con destreza por los árboles y los juguetes con comida, e impresiona a los visitantes con su agilidad.'),
       (92779, 139, 'nl', 'Witte ooievaar', 'De witte ooievaar staat bij velen bekend als een geluksbrenger die naar verluidt baby’s brengt. Hij broedt graag op hoge daken en schoorstenen en keert jaar na jaar terug naar zijn nest. In jouw dierentuin struint hij door het verblijf, klappert met zijn snavel en is op zoek naar lekkernijen.'),
       (92780, 139, 'fr', 'Cigogne blanche', 'La cigogne blanche est connue de beaucoup comme un porte-bonheur qui, dit-on, apporte les bébés. Elle aime nicher sur les toits élevés et les cheminées, et revient année après année vers ses nids. Dans ton zoo, elle se promène dans son enclos, claque du bec et guette les friandises.'),
       (92781, 139, 'es', 'Cigüeña blanca', 'La cigüeña blanca es conocida por muchos como un símbolo de buena suerte que, según se dice, trae bebés. Le gusta anidar en tejados altos y chimeneas, y vuelve año tras año a sus nidos. En tu zoológico, se pasea por el recinto, hace ruido con el pico y busca algo rico para comer.'),
       (92782, 140, 'nl', 'Waterkudu', 'De waterkoedoe is een grote antilopensoort die de voorkeur geeft aan moerasgebieden en dichte begroeiing. Zijn gedraaide hoorns en gestreepte vacht maken hem bijzonder opvallend. In de dierentuin beweegt hij zich rustig en waakzaam door zijn territorium en wekt hij met zijn majestueuze verschijning bewondering op.'),
       (92783, 140, 'fr', 'koudou d''eau', 'Le koudou aquatique est une grande espèce d''antilope qui affectionne les zones humides et la végétation dense. Ses cornes torsadées et son pelage rayé le rendent particulièrement remarquable. Au zoo, il se déplace calmement et avec vigilance dans son enclos et suscite l''émerveillement par son allure majestueuse.'),
       (92784, 140, 'es', 'Cudú acuático', 'El kudú acuático es una especie de antílope de gran tamaño que prefiere las zonas húmedas y la vegetación densa. Sus cuernos retorcidos y su pelaje rayado lo hacen especialmente llamativo. En el zoo se mueve con tranquilidad y vigilancia por su territorio y causa asombro con su majestuoso aspecto.'),
       (92785, 201, 'nl', 'Adelaarsbuizerd', 'De adelaarsbuizerd is een krachtige roofvogel die met zijn brede vleugels majestueus door de lucht cirkelt. Hij leeft in open landschappen en berggebieden en houdt scherp uitkijk naar prooien. In jouw dierentuin maakt hij indruk met zijn doordringende blik en indrukwekkende spanwijdte tijdens trainingsvluchten.'),
       (92786, 201, 'fr', 'Buse aigle', 'La buse aigle est un rapace puissant qui plane majestueusement dans le ciel grâce à ses larges ailes. Elle vit dans les paysages ouverts et les montagnes, à l''affût de ses proies. Dans ton zoo, elle impressionne par son regard perçant et son envergure impressionnante lors de ses vols d''entraînement.'),
       (92787, 201, 'es', 'Azor águila', 'El halcón águila es un robusto ave rapaz que, con sus amplias alas, sobrevuela majestuosamente el cielo. Habita en paisajes abiertos y zonas montañosas, y vigila atentamente en busca de presas. En tu zoológico, impresiona con su mirada penetrante y su impresionante envergadura durante los vuelos de entrenamiento.'),
       (92788, 202, 'nl', 'Amerikaanse bizon', 'De Amerikaanse bizon zwierf ooit in enorme kuddes over de prairies van Noord-Amerika. Met zijn massieve lichaam en dichte vacht trotseert hij wind en weer. In de dierentuin stampt hij krachtig door het verblijf, wentelt zich in het stof en laat zien hoe indrukwekkend kuddedieren kunnen zijn.'),
       (92789, 202, 'fr', 'Bison d''Amérique', 'Le bison d''Amérique parcourait autrefois les prairies d''Amérique du Nord en immenses troupeaux. Avec son corps massif et son pelage épais, il défie le vent et les intempéries. Au zoo, il arpente d''un pas puissant son enclos, se roule dans la poussière et montre à quel point les animaux grégaires peuvent être imposants.'),
       (92790, 202, 'es', 'Bisonte americano', 'El bisonte americano solía recorrer las praderas de Norteamérica en enormes manadas. Con su cuerpo robusto y su espeso pelaje, desafía el viento y las inclemencias del tiempo. En el zoológico, camina con paso firme por el recinto, se revuelca en el polvo y demuestra lo imponentes que pueden llegar a ser los animales gregarios.'),
       (92791, 203, 'nl', 'Andesvos', 'De Andese vos leeft in de hooggelegen gebieden van Zuid-Amerika en is perfect aangepast aan het ruige klimaat. Zijn dichte vacht beschermt hem tegen de kou, en hij is zowel jager als aaseter. In jouw dierentuin dwaalt hij nieuwsgierig door het verblijf en observeert hij alles met alerte, slimme ogen.'),
       (92792, 203, 'fr', 'renard des Andes', 'Le renard des Andes vit dans les hauteurs d''Amérique du Sud et est parfaitement adapté à ce climat rude. Son pelage épais le protège du froid, et c''est à la fois un chasseur et un charognard. Dans ton zoo, il arpente son enclos avec curiosité et observe tout d''un regard vif et intelligent.'),
       (92793, 203, 'es', 'Zorro andino', 'El zorro andino vive en las zonas altas de Sudamérica y se ha adaptado perfectamente al clima riguroso. Su denso pelaje le protege del frío, y es tanto cazador como carroñero. En tu zoológico, deambula con curiosidad por el recinto y lo observa todo con ojos despiertos e inteligentes.'),
       (92794, 204, 'nl', 'Angorageit', 'De angorageit staat bekend om haar lange, krullende vacht, waaruit de kostbare mohairwol wordt gewonnen. Ze komt oorspronkelijk uit Turkije en houdt van schrale, droge landschappen. In de dierentuin ziet ze er met haar warrige kapsel bijzonder sympathiek uit en geniet ze ontspannen van het herkauwen in de zon.'),
       (92795, 204, 'fr', 'chèvre angora', 'La chèvre angora est connue pour sa longue toison bouclée, dont on tire la précieuse laine mohair. Originaire de Turquie, elle apprécie les paysages arides et secs. Au zoo, avec sa toison hirsute, elle est particulièrement attachante et aime ruminer tranquillement au soleil.'),
       (92796, 204, 'es', 'cabra de angora', 'La cabra de angora es conocida por su pelaje largo y rizado, del que se obtiene la preciada lana de mohair. Es originaria de Turquía y le encantan los paisajes áridos y secos. En el zoo resulta especialmente simpática con su pelaje revuelto y disfruta rumiando tranquilamente al sol.'),
       (92797, 205, 'nl', 'Bongo-antilope', 'De bongo-antilope is een van de grootste en kleurrijkste antilopen van Afrika. Haar roodbruine vacht met witte strepen helpt haar om zich in het dichte bos te camoufleren. In jouw dierentuin loopt ze rustig rond en maakt ze indruk met haar lange hoorns en haar prachtige vachtpatroon.'),
       (92798, 205, 'fr', 'Antilope bongo', 'L''antilope bongo est l''une des plus grandes et des plus colorées d''Afrique. Son pelage roux strié de blanc lui permet de se fondre dans la forêt dense. Dans ton zoo, elle se promène tranquillement et impressionne par ses longues cornes et ses magnifiques motifs.'),
       (92799, 205, 'es', 'Antílope bongo', 'El antílope bongo es uno de los antílopes más grandes y coloridos de África. Su pelaje de color marrón rojizo con rayas blancas le ayuda a camuflarse en el denso bosque. En tu zoológico, se pasea tranquilamente e impresiona con sus largos cuernos y su elegante pelaje.'),
       (92800, 206, 'nl', 'Capibara', 'De capibara is het grootste knaagdier ter wereld en een echte watersportliefhebber. Hij leeft in Zuid-Amerika en brengt veel tijd door met pootjebaden in rivieren en moerassen. In jouw dierentuin ligt hij graag halfnat op de oever te dommelen en laat hij zich door niets uit zijn rust brengen.'),
       (92801, 206, 'fr', 'Capybara', 'Le capybara est le plus grand rongeur du monde et un véritable passionné de sports nautiques. Il vit en Amérique du Sud et passe beaucoup de temps à barboter dans les rivières et les marécages. Dans ton zoo, il aime somnoler, encore un peu mouillé, sur la berge, sans que rien ne vienne troubler sa tranquillité.'),
       (92802, 206, 'es', 'Capibara', 'El capibara es el roedor más grande del mundo y un auténtico aficionado a los deportes acuáticos. Vive en Sudamérica y pasa mucho tiempo chapoteando en ríos y pantanos. En tu zoológico le gusta dormitar medio mojado en la orilla y nada le hace perder la calma.'),
       (92803, 207, 'nl', 'Dikdik', 'De dikdik is een piepkleine antilopensoort met grote ogen en een iets langere snuit. Hij leeft in de struiklandschappen van Afrika en verblijft het liefst in de schaduw van lage struiken. In jouw dierentuin flitst hij behendig door het struikgewas en laat hij de harten van de bezoekers in een oogwenk smelten.'),
       (92804, 207, 'fr', 'Dikdik', 'Le dik-dik est une minuscule espèce d''antilope aux grands yeux et au museau légèrement allongé. Il vit dans les zones de brousse d''Afrique et préfère rester à l''ombre des buissons bas. Dans ton zoo, il se faufile agilement à travers les sous-bois et fait fondre le cœur des visiteurs en un clin d''œil.'),
       (92805, 207, 'es', 'Dikdik', 'El dikdik es una especie de antílope diminuto, con ojos grandes y un hocico ligeramente alargado. Vive en las zonas de matorral de África y prefiere permanecer a la sombra de los arbustos bajos. En tu zoológico se mueve ágilmente entre la maleza y derrite los corazones de los visitantes en un abrir y cerrar de ojos.'),
       (92806, 208, 'nl', 'Emu', 'De emoe is de op één na grootste vogel ter wereld en een naaste verwant van de struisvogel. In Australië zwerft hij door open landschappen en kan hij verbazingwekkend snel rennen. In de dierentuin loopt hij nieuwsgierig langs het hek en bekijkt hij de bezoekers met alerte ogen.'),
       (92807, 208, 'fr', 'Emu', 'L''émeu est le deuxième plus grand oiseau du monde et un proche parent de l''autruche. En Australie, il arpente les grands espaces et peut courir à une vitesse étonnante. Au zoo, il se promène avec curiosité le long de la clôture et observe les visiteurs d''un œil attentif.'),
       (92808, 208, 'es', 'Emu', 'El emú es el segundo ave más grande del mundo y un pariente cercano del avestruz. En Australia deambula por paisajes abiertos y es capaz de correr a una velocidad asombrosa. En el zoológico, camina con curiosidad a lo largo de la valla y observa a los visitantes con mirada atenta.'),
       (92809, 209, 'nl', 'Aardwolf', 'De aardwolf lijkt een beetje op een kleine hyena, maar eet vooral termieten. Met zijn lange tong likt hij de insecten uit hun holen en is daarmee een heel bijzondere specialist. In jouw dierentuin snuffelt hij aandachtig op de grond en is hij blij met elke voedselverstopping.'),
       (92810, 209, 'fr', 'loup de terre', 'Le loup de terre ressemble un peu à une petite hyène, mais il se nourrit principalement de termites. Grâce à sa longue langue, il lèche les insectes hors de leurs terriers, ce qui en fait un spécialiste tout à fait particulier. Dans ton zoo, il renifle attentivement le sol et se réjouit de chaque cachette de nourriture.'),
       (92811, 209, 'es', 'lobo de tierra', 'El lobo de tierra se parece un poco a una hiena pequeña, pero se alimenta principalmente de termitas. Con su larga lengua, saca a los insectos de sus madrigueras, lo que lo convierte en un especialista muy singular. En tu zoológico, olfatea atentamente el suelo y se alegra cada vez que encuentra un escondite con comida.'),
       (92812, 210, 'nl', 'Biggenstank', 'De biggenskunk dankt zijn naam aan zijn ietwat varkensachtige snuit, in combinatie met het typische skunkpatroon. Hij is nachtdier en vertrouwt bij gevaar op zijn beroemde geurverdedigingstruc. In de dierentuin laat hij zich meestal in de avonduren zien en wekt hij met zijn onhandige gang veel belangstelling.'),
       (92813, 210, 'fr', 'Porc-fouine', 'Le « Ferkelskunk » doit son nom à son museau légèrement porcine, associé au pelage caractéristique du skunk. Il est nocturne et, en cas de danger, il compte sur sa célèbre technique de défense olfactive. Au zoo, il se montre généralement en fin de journée et suscite beaucoup d''intérêt avec sa démarche maladroite.'),
       (92814, 210, 'es', 'Lechón de zorrillo', 'El «Ferkelskunk» debe su nombre a su hocico, que recuerda ligeramente al de un cerdo, combinado con el pelaje típico de la mofeta. Es un animal nocturno y, ante el peligro, recurre a su famoso truco de defensa olfativa. En el zoo suele dejarse ver sobre todo al atardecer y despierta mucho interés con su andar torpe.'),
       (92815, 211, 'nl', 'Flamingo', 'De flamingo is met zijn roze verenkleed en lange poten een echte ster onder de watervogels. Zijn kleur dankt hij aan de kleurstoffen in zijn voedsel, zoals kleine kreeftachtigen. In jouw dierentuin staat hij graag op één poot in het water en zorgt hij samen met zijn kleurrijke kolonie voor een vakantiesfeer.'),
       (92816, 211, 'fr', 'Flamant rose', 'Avec son plumage rose et ses longues pattes, le flamant rose est une véritable star parmi les oiseaux aquatiques. Il doit sa couleur aux pigments présents dans son alimentation, notamment des petits crustacés. Dans ton zoo, il aime se tenir sur une patte dans l''eau et, avec sa colonie colorée, il crée une ambiance de vacances.'),
       (92817, 211, 'es', 'Flamenco', 'El flamenco, con su plumaje rosa y sus largas patas, es toda una estrella entre las aves acuáticas. Su color se debe a los pigmentos de su alimentación, como los pequeños crustáceos. En tu zoológico le gusta mantenerse de pie sobre una sola pata en el agua y, junto con su colorida colonia, crea un ambiente veraniego.'),
       (92818, 212, 'nl', 'vorkhouder', 'De vorkbok is een typische bewoner van de Noord-Amerikaanse prairies en kan enorme snelheden halen. Zijn hoorns vertakken zich als een vork, waaraan hij zijn naam te danken heeft. In jouw dierentuin rent hij met gemak door het verblijf en laat hij zien hoeveel energie hij in zich heeft.'),
       (92819, 212, 'fr', 'support de fourche', 'Le bison d''Amérique est un habitant typique des prairies nord-américaines et peut atteindre des vitesses impressionnantes. Ses cornes se ramifient comme une fourche, ce qui lui a valu son nom. Dans ton zoo, il parcourt l''enclos avec aisance et montre toute l''énergie dont il dispose.'),
       (92820, 212, 'es', 'Soporte de horquilla', 'El antílope de las praderas es un habitante típico de las praderas norteamericanas y puede alcanzar velocidades enormes. Sus cuernos se ramifican como una horquilla, lo que le ha valido su nombre. En tu zoológico recorre con facilidad el recinto y demuestra toda la energía que tiene.'),
       (92821, 213, 'nl', 'Cheetah', 'De cheeta is het snelste landdier ter wereld en bereikt in korte tijd indrukwekkende topsnelheden. Zijn slanke lichaam en lange poten zijn perfect afgestemd op de sprint. In de dierentuin zie je hem vaak rustig liggen, maar zijn waakzame ogen verraden dat hij op elk moment een sprint zou kunnen maken.'),
       (92822, 213, 'fr', 'Guépard', 'Le guépard est l''animal terrestre le plus rapide au monde et atteint en peu de temps des vitesses de pointe impressionnantes. Son corps élancé et ses longues pattes sont parfaitement adaptés au sprint. Au zoo, on le voit souvent se reposer tranquillement, mais son regard vigilant trahit le fait qu''il pourrait se lancer dans un sprint à tout moment.'),
       (92823, 213, 'es', 'Guepardo', 'El guepardo es el animal terrestre más rápido del mundo y alcanza impresionantes velocidades máximas en muy poco tiempo. Su cuerpo esbelto y sus largas patas están perfectamente adaptados para correr a toda velocidad. En el zoológico se le ve a menudo descansando tranquilamente, pero sus ojos alertas delatan que podría echarse a correr en cualquier momento.'),
       (92824, 214, 'nl', 'Goudfazant', 'De goudfazant maakt indruk met zijn kleurrijke verenkleed en de gouden kuif op zijn kop. Hij komt oorspronkelijk uit de bossen van China, maar is tegenwoordig wereldwijd te zien in parken en dierentuinen. In jouw dierentuin paradeert hij als een kleine koning door het verblijf en laat hij zijn schitterende kleuren zien.'),
       (92825, 214, 'fr', 'faisan doré', 'Le faisan doré impressionne par son plumage coloré et sa crête dorée. Originaire des forêts chinoises, on le trouve aujourd’hui dans les parcs et les zoos du monde entier. Dans ton zoo, il se pavane comme un petit roi dans son enclos et exhibe ses couleurs chatoyantes.'),
       (92826, 214, 'es', 'Faisán dorado', 'El faisán dorado impresiona por su colorido plumaje y la cresta dorada que luce en la cabeza. Es originario de los bosques de China, pero hoy en día se puede ver en parques y zoológicos de todo el mundo. En tu zoológico, se pavonea por el recinto como un pequeño rey y hace alarde de sus colores iridiscentes.'),
       (92827, 216, 'nl', 'Gordeldier', 'Het gordeldier heeft een benig pantser, waardoor het eruitziet als een klein levend schild. Sommige soorten kunnen zich bij gevaar zelfs tot een balletje oprollen. In de dierentuin trippelt het op korte pootjes door het verblijf en graaft het nieuwsgierig in de grond op zoek naar voedsel.'),
       (92828, 216, 'fr', 'Tatou', 'Le tatou est doté d’une carapace osseuse qui lui donne l’air d’un petit bouclier vivant. Certaines espèces peuvent même se recroqueviller en boule en cas de danger. Au zoo, il trottine dans son enclos sur ses petites pattes et creuse le sol avec curiosité à la recherche de nourriture.'),
       (92829, 216, 'es', 'armadillo', 'El armadillo tiene una coraza ósea que le da el aspecto de un pequeño escudo viviente. Algunas especies pueden incluso enrollarse como una bola cuando hay peligro. En el zoo, se pasea con paso ligero por el recinto con sus patitas cortas y escarba con curiosidad en el suelo en busca de comida.'),
       (92830, 217, 'nl', 'Halsbandpekari', 'Het halsbandpekari is een op een wild zwijn lijkend dier uit Noord- en Zuid-Amerika. Het dankt zijn naam aan de lichtere vachtband rond zijn nek. In jouw dierentuin struint het in groepen door het verblijf en communiceert het met grommende en knorrende geluiden.'),
       (92831, 217, 'fr', 'Pécari à collier', 'Le pécari à collier est un animal ressemblant à un sanglier, originaire d''Amérique du Nord et d''Amérique du Sud. Il doit son nom à l''anneau de fourrure plus clair qui entoure son cou. Dans ton zoo, il parcourt son enclos en groupe et communique par des grognements et des grincements.'),
       (92832, 217, 'es', 'Pecarí de collar', 'El pecarí de collar es un animal parecido al jabalí, originario de América del Norte y del Sur. Debe su nombre al anillo de pelaje más claro que tiene alrededor del cuello. En tu zoológico, deambula en grupos por el recinto y se comunica mediante gruñidos y gemidos.'),
       (92833, 218, 'nl', 'hertgeitantilope', 'De hertengeitantilope is een behendige antilope uit de open landschappen van India. Mannetjes hebben een donkere vacht en opvallende, gedraaide hoorns, terwijl vrouwtjes eerder licht van kleur zijn. In jouw dierentuin rennen ze vrolijk door het verblijf en houden ze kleine wedstrijden.'),
       (92834, 218, 'fr', 'antilope cerf-chèvre', 'L''antilope cerf-chèvre est une antilope agile originaire des plaines ouvertes de l''Inde. Les mâles ont un pelage foncé et des cornes torsadées très voyantes, tandis que les femelles ont un pelage plutôt clair. Dans ton zoo, elles courent joyeusement à travers l''enclos et s''adonnent à de petites courses.'),
       (92835, 218, 'es', 'Antílope ciervo', 'El antílope ciervo es un ágil antílope propio de los paisajes abiertos de la India. Los machos tienen un pelaje oscuro y unos llamativos cuernos retorcidos, mientras que las hembras suelen tener un pelaje más claro. En tu zoológico, corretean alegremente por el recinto y se enzarzan en pequeñas carreras.'),
       (92836, 219, 'nl', 'Karakal', 'De karakal is een elegante wilde kat met opvallende, zwarte oorkwastjes. Hij kan met indrukwekkende sprongen vogels in volle vlucht vangen. In jouw dierentuin sluipt hij geruisloos door het verblijf, klimt behendig en laat steeds weer trots zijn oorkwastjes zien.'),
       (92837, 219, 'fr', 'Karakal', 'Le caracal est un chat sauvage élégant aux oreilles noires en forme de pinceaux très caractéristiques. Il est capable d''attraper des oiseaux en plein vol grâce à ses bonds impressionnants. Dans ton zoo, il se faufile silencieusement dans son enclos, grimpe avec agilité et ne manque jamais de montrer fièrement ses oreilles en forme de pinceaux.'),
       (92838, 219, 'es', 'Karakal', 'El karakal es un elegante felino salvaje con unas llamativas orejas en forma de pincel de color negro. Es capaz de atrapar aves en pleno vuelo con impresionantes saltos. En tu zoológico, se desliza silenciosamente por el recinto, trepa con destreza y no deja de mostrar con orgullo sus orejas en forma de pincel.'),
       (92839, 220, 'nl', 'kattenfret', 'De kattenfret behoort tot de familie van de katachtigen en doet een beetje denken aan een kruising tussen een kat en een marter. Het is een nachtdier en zoekt graag zijn toevlucht in dichte begroeiing. In de dierentuin laat hij zich graag in de schemering zien en verkent hij nieuwsgierig elk hoekje van zijn verblijf.'),
       (92840, 220, 'fr', 'Furet-chat', 'Le furet-chat appartient à la famille des viverridés et ressemble un peu à un croisement entre un chat et une martre. C''est un animal nocturne qui apprécie la végétation dense pour s''y cacher. Au zoo, il aime se montrer au crépuscule et explore avec curiosité chaque recoin de son enclos.'),
       (92841, 220, 'es', 'Hurón gato', 'La comadreja gata pertenece a la familia de los felinos y se parece un poco a una mezcla entre un gato y una marta. Es un animal nocturno y le gusta la vegetación densa para esconderse. En el zoo suele dejarse ver al atardecer y explora con curiosidad cada rincón de su recinto.'),
       (92842, 221, 'nl', 'Lama', 'De lama is een typische bewoner van de Andes en wordt al eeuwenlang door de lokale bevolking als lastdier gebruikt. Hij staat bekend om zijn zachte vacht – en om het af en toe spugen als hij zich gestoord voelt. In jouw dierentuin zorgt hij met zijn nieuwsgierige karakter en grappige kapsel steeds weer voor veel gelach.'),
       (92843, 221, 'fr', 'Lama', 'Le lama est un habitant typique des Andes et, depuis des siècles, un animal de bât pour les populations locales. Il est connu pour sa fourrure douce – et pour cracher de temps en temps lorsqu’il se sent dérangé. Dans ton zoo, il ne manque jamais de faire rire grâce à sa nature curieuse et à sa coiffure amusante.'),
       (92844, 221, 'es', 'Lama', 'El llama es un habitante típico de los Andes y, desde hace siglos, un animal de carga para la población de la zona. Es conocido por su suave pelaje y por escupir de vez en cuando cuando se siente molesto. En tu zoológico, con su carácter curioso y su divertido peinado, siempre hace reír a todo el mundo.'),
       (92845, 222, 'nl', 'Masai-giraffe', 'De Masai-giraf is de grootste ondersoort van de giraf en heeft een onregelmatig, netachtig vlekkenpatroon. Met haar lange nek kan ze zelfs de hoogste bladeren van de bomen bereiken. In jouw dierentuin kijkt ze over alle andere dieren heen en knabbelt ze ontspannen aan de boomtoppen.'),
       (92846, 222, 'fr', 'Girafe masaï', 'La girafe masaï est la plus grande sous-espèce de girafe ; elle présente un motif de taches irrégulier, semblable à un filet. Grâce à son long cou, elle peut atteindre même les feuilles les plus hautes des arbres. Dans ton zoo, elle domine tous les autres animaux du regard et grignote tranquillement les cimes des arbres.'),
       (92847, 222, 'es', 'Jirafa masái', 'La jirafa masái es la subespecie más grande de jirafa y presenta un patrón de manchas irregular en forma de red. Con su largo cuello, llega incluso a las hojas más altas de los árboles. En tu zoológico, se asoma por encima de todos los demás animales y mordisquea tranquilamente las copas de los árboles.'),
       (92848, 223, 'nl', 'oryxantilope', 'De oryxantilope is met zijn lange, rechte hoorns en lichte vacht perfect aangepast aan woestijnen en halfwoestijnen. Hij kan lange tijd zonder water en gaat zeer zuinig om met zijn lichaamsvocht. In jouw dierentuin ziet hij er met zijn heldere tekening bijzonder statig uit en rust hij graag in de schaduw.'),
       (92849, 223, 'fr', 'oryx', 'Avec ses longues cornes droites et son pelage clair, l''oryx est parfaitement adapté aux environnements désertiques et semi-désertiques. Il peut rester longtemps sans boire et économise ses réserves d''énergie. Dans ton zoo, il dégage une grande élégance grâce à ses traits bien définis et aime se reposer à l''ombre.'),
       (92850, 223, 'es', 'antílope órix', 'El órix, con sus cuernos largos y rectos y su pelaje claro, está perfectamente adaptado a los entornos desérticos y semidesérticos. Puede pasar largos periodos sin beber agua y gasta muy poca energía. En tu zoológico, con su pelaje de colores bien definidos, tiene un aspecto especialmente elegante y le gusta descansar a la sombra.'),
       (92851, 224, 'nl', 'Pauw', 'De pauw staat wereldwijd bekend om zijn prachtige staart, waarmee het mannetje de vrouwtjes het hof maakt. Zijn schitterende verenkleed straalt in blauwe en groene tinten en is versierd met oogvlekken. In jouw dierentuin verrukt hij de bezoekers wanneer hij zijn staartspreiding toont en trots door het verblijf schrijdt.'),
       (92852, 224, 'fr', 'Paon', 'Le paon est mondialement connu pour sa magnifique queue en éventail, grâce à laquelle le mâle courtise les femelles. Son plumage chatoyant resplendit de nuances de bleu et de vert et est orné de taches en forme d''yeux. Dans ton zoo, il ravit les visiteurs lorsqu''il déploie sa queue en éventail et se promène fièrement dans son enclos.'),
       (92853, 224, 'es', 'pavo real', 'El pavo real es mundialmente famoso por su magnífica cola, con la que el macho corteja a las hembras. Su plumaje iridiscente brilla en tonos azules y verdes y está adornado con manchas en forma de ojo. En tu zoológico, deleita a los visitantes cuando despliega su cola y se pasea orgulloso por el recinto.'),
       (92854, 225, 'nl', 'Quokka', 'De quokka is een kleine kangoeroe uit Australië die beroemd is geworden door zijn ogenschijnlijk glimlachende gezicht. Hij is nieuwsgierig, meestal vriendelijk en bijna berucht om zijn selfies. In jouw dierentuin huppelt hij vrolijk rond en laat hij met zijn charme alle harten smelten.'),
       (92855, 225, 'fr', 'Quokka', 'Le quokka est un petit kangourou d''Australie qui est devenu célèbre grâce à son air apparemment souriant. Curieux et généralement sympathique, il est presque devenu célèbre pour ses selfies. Dans ton zoo, il sautille joyeusement et fait fondre tous les cœurs grâce à son charme.'),
       (92856, 225, 'es', 'Quokka', 'El quokka es un pequeño canguro de Australia que se ha hecho famoso por su cara, que parece sonreír. Es curioso, casi siempre simpático y casi que famoso por hacerse selfies. En tu zoológico salta alegremente de un lado a otro y, con su encanto, derrite los corazones de todos.'),
       (92857, 226, 'nl', 'Rendier', 'Het rendier is perfect aangepast aan koude gebieden en speelt in veel winterverhalen een hoofdrol. Zowel mannetjes als vrouwtjes hebben een gewei, wat bij herten ongebruikelijk is. In jouw dierentuin slentert het rustig door het verblijf, schudt de sneeuw uit zijn vacht en brengt bezoekers in winterstemming.'),
       (92858, 226, 'fr', 'renne', 'Le renne est parfaitement adapté aux régions froides et joue un rôle central dans de nombreux contes d''hiver. Les mâles comme les femelles portent des bois, ce qui est inhabituel chez les cerfs. Dans ton zoo, il se promène tranquillement dans son enclos, secoue la neige de son pelage et plonge les visiteurs dans l''ambiance hivernale.'),
       (92859, 226, 'es', 'reno', 'El reno está perfectamente adaptado a las regiones frías y desempeña un papel protagonista en muchas historias invernales. Tanto los machos como las hembras tienen cuernos, algo inusual en los ciervos. En tu zoológico, se pasea tranquilamente por su recinto, se sacude la nieve del pelaje y crea un ambiente invernal entre los visitantes.'),
       (92860, 227, 'nl', 'Reuzenschildpad', 'De reuzenschildpad kan ontzettend oud worden en staat bekend om zijn rustige, bedaarde karakter. Hij leeft op eilanden zoals de Galapagos-eilanden en beweegt zich voort in zijn eigen, zeer gemoedelijke tempo. In jouw dierentuin sjokt ze langzaam door haar rijk en laat ze zien dat je het in het leven ook wel eens rustig aan mag doen.'),
       (92861, 227, 'fr', 'tortue géante', 'La tortue géante peut atteindre un âge très avancé et est connue pour son caractère calme et tranquille. Elle vit sur des îles telles que les îles Galápagos et se déplace à son propre rythme, très tranquille. Dans ton zoo, elle arpente lentement son royaume et montre qu''il est parfois bon de prendre la vie avec calme.'),
       (92862, 227, 'es', 'Tortuga gigante', 'La tortuga gigante puede llegar a vivir muchísimos años y es conocida por su carácter tranquilo y pausado. Vive en islas como las Galápagos y se mueve a su propio ritmo, muy pausado. En tu zoológico, recorre lentamente su territorio y demuestra que, a veces, en la vida también hay que tomarse las cosas con calma.'),
       (92863, 228, 'nl', 'Rosada-Drusenkopf', 'De Rosada-drusenkop is een opvallend gekleurde hagedis met glanzende delen op zijn huid. Hij houdt van zonnige plekjes waar hij zijn lichaamstemperatuur kan regelen. In jouw dierentuin zit hij graag op warme stenen en kijkt hij met stoïcijnse kalmte toe hoe het er allemaal aan toe gaat.'),
       (92864, 228, 'fr', 'Rosada-Tête-de-Druse', 'Le lézard à tête drusée de Rosada est un lézard aux couleurs vives, avec des zones de peau brillantes. Il adore les endroits ensoleillés où il peut réguler sa température corporelle. Dans ton zoo, il aime se percher sur des pierres chaudes et observer ce qui se passe autour de lui avec un calme stoïque.'),
       (92865, 228, 'es', 'Cabeza de drusa de Rosada', 'El lagarto de Rosada es un lagarto de colores llamativos con zonas de la piel de colores vivos. Le encantan los lugares soleados, donde puede regular su temperatura corporal. En tu zoológico le gusta sentarse sobre piedras calientes y observar lo que sucede a su alrededor con estoica tranquilidad.'),
       (92866, 229, 'nl', 'Rood reuzenkangoeroe', 'De rode reuzenkangoeroe is de grootste van alle kangoeroes en een symbool van de Australische fauna. Hij verplaatst zich met krachtige sprongen en gebruikt zijn staart om zijn evenwicht te bewaren. In de dierentuin rust hij graag in de schaduw, om daarna weer met grote sprongen door het verblijf te huppelen.'),
       (92867, 229, 'fr', 'Kangourou géant rouge', 'Le kangourou géant rouge est le plus grand de tous les kangourous et un symbole de la faune australienne. Il se déplace par de puissants bonds et utilise sa queue pour garder l''équilibre. Au zoo, il aime se reposer à l''ombre, avant de repartir en bondissant à grands pas à travers son enclos.'),
       (92868, 229, 'es', 'Canguro gigante rojo', 'El canguro rojo gigante es el más grande de todos los canguros y un símbolo de la fauna australiana. Se desplaza dando saltos enérgicos y utiliza la cola para mantener el equilibrio. En el zoológico le gusta descansar a la sombra para luego volver a saltar por el recinto dando grandes zancadas.'),
       (92869, 231, 'nl', 'Zwartvoetkat', 'De zwartvoetkat behoort tot de kleinste wilde katten van Afrika en is toch een zeer succesvolle jager. Ze is nachtdier en beweegt zich geruisloos door het gras en het struikgewas. In jouw dierentuin laat ze zich vooral bij schemering zien en weet ze het publiek te bekoren met haar combinatie van schattigheid en wildheid.'),
       (92870, 231, 'fr', 'chat à pattes noires', 'Le chat à pattes noires fait partie des plus petits chats sauvages d''Afrique, mais n''en reste pas moins une chasseuse redoutable. Nocturne, il se déplace sans bruit à travers l''herbe et les buissons. Dans ton zoo, il se montre surtout au crépuscule et séduit par son mélange de douceur et de sauvagerie.'),
       (92871, 231, 'es', 'Gato de patas negras', 'El gato de patas negras es uno de los gatos salvajes más pequeños de África y, sin embargo, es una cazadora muy eficaz. Es nocturno y se mueve silenciosamente entre la hierba y los matorrales. En tu zoológico se deja ver sobre todo al atardecer y cautiva por su mezcla de ternura y salvajismo.'),
       (92872, 232, 'nl', 'secretaris', 'De secretaris is een grote roofvogel die, in tegenstelling tot veel van zijn verwanten, meestal op de grond rondloopt. Met zijn lange poten schrijdt hij door de savanne en jaagt hij op slangen en andere kleine dieren. In de dierentuin wekt hij veel bewondering door zijn trotse houding en de „verenkrans“ achter op zijn kop.'),
       (92873, 232, 'fr', 'secrétaire', 'Le secrétaire est un grand rapace qui, contrairement à bon nombre de ses congénères, se déplace principalement au sol. De ses longues pattes, il arpente la savane et chasse les serpents et autres petits animaux. Au zoo, son port fière et la « couronne de plumes » à l''arrière de sa tête suscitent beaucoup d''admiration.'),
       (92874, 232, 'es', 'Secretario', 'El secretario es una gran ave rapaz que, a diferencia de muchos de sus parientes, suele desplazarse por el suelo. Con sus largas patas, recorre la sabana y caza serpientes y otros pequeños animales. En el zoo, su porte majestuoso y la «corona de plumas» que luce en la parte posterior de la cabeza despiertan gran admiración.'),
       (92875, 233, 'nl', 'Serval', 'De serval is een slanke, langbenige wilde kat met grote oren en een gevlekte vacht. Hij kan met indrukwekkende sprongen vogels uit de lucht plukken en luistert naar de zachtste geluiden in het gras. In jouw dierentuin sluipt hij oplettend door het verblijf, springt hij op hoge plekken en houdt hij alles nauwlettend in de gaten.'),
       (92876, 233, 'fr', 'Serval', 'Le serval est un chat sauvage élancé, aux pattes longues, doté de grandes oreilles et d''un pelage tacheté. Il est capable d''attraper des oiseaux en plein vol grâce à ses bonds impressionnants et tend l''oreille pour percevoir les moindres bruits dans l''herbe. Dans ton zoo, il se faufile avec vigilance à travers son enclos, bondit sur des points élevés et observe tout avec une grande attention.'),
       (92877, 233, 'es', 'Serval', 'El serval es un felino salvaje esbelto y de patas largas, con orejas grandes y pelaje manchado. Es capaz de atrapar aves en pleno vuelo con impresionantes saltos y está atento a los más mínimos ruidos entre la hierba. En tu zoológico, se desliza con atención por el recinto, salta a lugares elevados y lo observa todo con gran atención.'),
       (92878, 234, 'nl', 'Zilverdachs', 'De zilverdas is een klein, dasachtig roofdier met een opvallend vachtpatroon. Hij leeft teruggetrokken en is meestal in de schemering actief. In de dierentuin graaft hij ijverig in de grond en laat zich slechts af en toe aan de geduldige bezoekers zien.'),
       (92879, 234, 'fr', 'Silberdachs', 'Le blaireau argenté est un petit prédateur ressemblant à un blaireau, au pelage au motif caractéristique. Il mène une vie solitaire et est généralement actif au crépuscule. Au zoo, il creuse avec ardeur dans le sol et ne se montre qu’occasionnellement aux visiteurs patients.'),
       (92880, 234, 'es', 'Silberdachs', 'El tejón plateado es un pequeño depredador parecido al tejón, con un pelaje de colores llamativos. Vive de forma solitaria y suele estar activo al atardecer. En el zoo, excava con ahínco en el suelo y solo se deja ver de vez en cuando a los visitantes pacientes.'),
       (92881, 235, 'nl', 'Zilveren reuzengalago', 'De zilveren reuzengalago is een nachtactieve springkunstenaar met grote ogen en lange achterpoten. Hij leeft in bomen en springt met grote sprongen van tak naar tak. In jouw dierentuin is hij vooral ’s avonds actief en trekt hij met zijn geruisloze sprongen bewonderende blikken.'),
       (92882, 235, 'fr', 'Galago géant argenté', 'Le galago géant argenté est un acrobate nocturne doté de grands yeux et de longues pattes arrière. Il vit dans les arbres et se déplace de branche en branche à grands bonds. Dans ton zoo, il est surtout actif le soir et ses sauts silencieux ne manquent pas d''émerveiller les visiteurs.'),
       (92883, 235, 'es', 'Galago gigante plateado', 'El galago gigante plateado es un saltador acrobático nocturno con ojos grandes y patas traseras largas. Vive en los árboles y se desplaza de rama en rama dando grandes saltos. En tu zoológico está activo sobre todo por la noche y, con sus silenciosos saltos, deja a todos boquiabiertos.'),
       (92884, 236, 'nl', 'Steppeschubdier', 'Het steppeschubdier is volledig bedekt met hoornachtige schubben en lijkt bijna op een levende dennenkegel. Bij gevaar rolt het zich op tot een stevige bal. In jouw dierentuin sluipt het rustig rond, snuffelt naar insecten en lijkt het wel een wezen uit een ander tijdperk.'),
       (92885, 236, 'fr', 'Pangolin des steppes', 'Le pangolin des steppes est entièrement recouvert d''écailles cornées et ressemble presque à une pomme de pin vivante. En cas de danger, il se recroqueville pour former une boule compacte. Dans ton zoo, il se déplace tranquillement, renifle à la recherche d''insectes et donne l''impression d''être une créature venue d''une autre époque.'),
       (92886, 236, 'es', 'Pangolín de las estepas', 'El pangolín de la estepa está completamente cubierto de escamas córneas y parece casi una piña viviente. Ante el peligro, se enrosca formando una bola compacta. En tu zoológico se mueve sigilosamente, olfatea en busca de insectos y da la impresión de ser un ser de otra época.'),
       (92887, 237, 'nl', 'steppezebra', 'De steppezebra leeft in de open savannes van Afrika en is onmiskenbaar dankzij zijn strepenpatroon. Elk strepenpatroon is uniek, net als een vingerafdruk. In jouw dierentuin draven ze in familiegroepen door het verblijf en zorgen ze voor een levendig zwart-wit schouwspel.'),
       (92888, 237, 'fr', 'zèbre des steppes', 'Le zèbre des steppes vit dans les savanes ouvertes d''Afrique et se reconnaît immédiatement à son pelage rayé. Chaque motif est unique, à l''instar d''une empreinte digitale. Dans ton zoo, ils trottinent en famille à travers leur enclos, offrant un spectacle vivant tout en noir et blanc.'),
       (92889, 237, 'es', 'cebra de la estepa', 'La cebra de la estepa habita en las sabanas abiertas de África y es inconfundible por su patrón de rayas. Cada patrón de rayas de una cebra es único, como una huella dactilar. En tu zoológico, trotan en grupo familiar por el recinto y ofrecen un animado espectáculo en blanco y negro.'),
       (92890, 239, 'nl', 'Tigeriltis', 'De tijgeriltis is een klein dier uit de familie van de roofdieren met een opvallend gevlekt patroon. Hij is nachtdier en leeft verscholen in holen en ondergrondse burchten. In de dierentuin laat hij zich graag zien in verblijven met veel structuur, verkent hij elk hoekje en verrast hij bezoekers met zijn behendigheid.'),
       (92891, 239, 'fr', 'Tigeriltis', 'Le tigre-ilti est un petit animal apparenté aux carnivores, au pelage tacheté très caractéristique. Nocturne, il vit à l''abri dans des grottes et des terriers. Au zoo, il aime se montrer dans des enclos riches en structures, explore chaque recoin et surprend les visiteurs par son agilité.'),
       (92892, 239, 'es', 'Tigeriltis', 'El tigre de Iltis es un pequeño animal emparentado con los depredadores que presenta un llamativo pelaje moteado. Es nocturno y vive escondido en cuevas y madrigueras. En el zoológico le gusta mostrarse en recintos con gran variedad de estructuras, explora cada rincón y sorprende a los visitantes con su agilidad.'),
       (92893, 240, 'nl', 'dwergflamingo', 'De dwergflamingo is kleiner dan zijn beroemde verwanten, maar des te intenser roze gekleurd. Hij leeft in grote kolonies aan zoute meren in Afrika. In jouw dierentuin vormt hij een druk, kleurrijk tapijt van lange poten en gebogen halzen.'),
       (92894, 240, 'fr', 'Flamant nain', 'Le flamant nain est plus petit que ses célèbres cousins, mais sa couleur rose n''en est que plus intense. Il vit en grandes colonies au bord des lacs salés d''Afrique. Dans ton zoo, il forme un tapis animé et coloré, composé de longues pattes et de cous recourbés.'),
       (92895, 240, 'es', 'Flamenco enano', 'El flamenco enano es más pequeño que sus famosos parientes, pero su color rosa es mucho más intenso. Vive en grandes colonias en los lagos salinos de África. En tu zoológico forma una alfombra bulliciosa y colorida de patas largas y cuellos curvados.'),
       (92896, 241, 'nl', 'Drusenkopf', 'De drusenkop is een robuuste hagedis met een opvallende kop en een ruwe schubbenhuid. Hij houdt van warme, droge leefgebieden en brengt veel tijd door met zonnebaden. In jouw dierentuin ligt hij graag roerloos op een tak en lijkt hij wel een klein, levend standbeeld.'),
       (92897, 241, 'fr', 'Tête de Druzen', 'Le lézard à tête de drus est un reptile robuste, doté d''une tête caractéristique et d''une peau écailleuse et rugueuse. Il affectionne les habitats chauds et secs et passe beaucoup de temps à se prélasser au soleil. Dans ton zoo, il aime se prélasser immobile sur une branche, ressemblant ainsi à une petite statue vivante.'),
       (92898, 241, 'es', 'Cabeza de Drusen', 'El lagarto de cabeza rugosa es un reptil robusto, con una cabeza característica y una piel escamosa y áspera. Le encantan los hábitats cálidos y secos, y pasa mucho tiempo tomando el sol. En tu zoológico le gusta quedarse inmóvil sobre una rama, pareciendo una pequeña estatua viviente.'),
       (92899, 301, 'nl', 'Afrikaanse goudkat', 'De Afrikaanse goudkat is een zeldzame wilde kat uit de regenwouden van Afrika. Haar vacht kan variëren van roodachtig tot grijs en biedt een goede camouflage in het dichte struikgewas. In jouw dierentuin blijft ze vaak verscholen in de vegetatie en laat ze zich slechts even zien aan nieuwsgierige bezoekers.'),
       (92900, 301, 'fr', 'Chat doré africain', 'Le chat doré d''Afrique est un félin sauvage rare originaire des forêts tropicales d''Afrique. Son pelage, dont la couleur varie du roux au gris, lui offre un excellent camouflage dans les sous-bois denses. Dans ton zoo, il reste souvent à l''abri de la végétation et ne se montre que brièvement aux visiteurs curieux.'),
       (92901, 301, 'es', 'Gato dorado africano', 'El gato dorado africano es un felino salvaje poco común de las selvas tropicales de África. Su pelaje puede variar desde tonos rojizos hasta grises y le proporciona un buen camuflaje entre la densa maleza. En tu zoológico suele permanecer al amparo de la vegetación y solo se deja ver brevemente ante los visitantes curiosos.'),
       (92902, 302, 'nl', 'Australische spookvleermuis', 'De Australische spookvleermuis heeft lange, smalle vleugels en een ietwat mysterieuze naam. Hij is nachtdier en jaagt tijdens de vlucht met grote precisie op insecten. In jouw dierentuin is hij vooral in het donker actief en zorgt hij in het vleermuizenhuis voor een zacht gefladder.'),
       (92903, 302, 'fr', 'Chauve-souris fantôme d''Australie', 'La chauve-souris fantôme d''Australie a des ailes longues et étroites et un nom quelque peu mystérieux. Elle est nocturne et chasse les insectes en vol avec une grande précision. Dans ton zoo, elle est surtout active dans l''obscurité et fait entendre un léger battement d''ailes dans la volière des chauves-souris.'),
       (92904, 302, 'es', 'Murciélago fantasma australiano', 'El murciélago fantasma australiano tiene alas largas y estrechas y un nombre un tanto misterioso. Es nocturno y caza insectos en vuelo con gran precisión. En tu zoológico se mueve sobre todo en la oscuridad y produce un suave aleteo en la casa de los murciélagos.'),
       (92905, 303, 'nl', 'Blauwe leguaan', 'De blauwe leguaan is een bedreigde hagedissoort afkomstig van de Kaaimaneilanden en valt op door zijn blauwachtige kleur. Hij houdt van rotsachtige, zonnige plekken en eet voornamelijk planten. In jouw dierentuin zit hij graag op hoge rotsblokken en observeert hij zijn omgeving vanuit een veilige positie.'),
       (92906, 303, 'fr', 'Iguane bleu', 'L''iguane bleu est une espèce de lézard menacée originaire des îles Caïmans qui se distingue par sa couleur bleutée. Il affectionne les endroits rocheux et ensoleillés et se nourrit principalement de végétaux. Dans ton zoo, il aime se percher sur des rochers en hauteur et observer son environnement depuis un endroit sûr.'),
       (92907, 303, 'es', 'Iguana azul', 'El iguana azul es una especie de lagarto en peligro de extinción originaria de las Islas Caimán y destaca por su coloración azulada. Le encantan los lugares rocosos y soleados y se alimenta principalmente de plantas. En tu zoológico le gusta sentarse en rocas elevadas y observar su entorno desde una posición segura.'),
       (92908, 304, 'nl', 'Blauwkopkroonduif', 'De blauwkuifduif behoort tot de grootste duivensoorten ter wereld en heeft een prachtige verenkuif. Hij komt uit de regenwouden van Nieuw-Guinea en beweegt zich meestal rustig over de grond. In jouw dierentuin schreidt hij waardig door het verblijf en toont hij trots zijn elegante kuif.'),
       (92909, 304, 'fr', 'Pigeon à tête bleue', 'Le pigeon à crête bleue compte parmi les plus grandes espèces de pigeons au monde et arbore une magnifique crête de plumes. Originaire des forêts tropicales de Nouvelle-Guinée, il se déplace généralement tranquillement au sol. Dans ton zoo, il arpente dignement son enclos et exhibe fièrement son élégante crête.'),
       (92910, 304, 'es', 'Paloma coronada de cabeza azul', 'La paloma coronada de cresta azul es una de las especies de paloma más grandes del mundo y luce una magnífica cresta de plumas. Es originaria de las selvas tropicales de Nueva Guinea y suele moverse tranquilamente por el suelo. En tu zoológico, se desplaza con dignidad por el recinto y muestra con orgullo su elegante cresta.'),
       (92911, 305, 'nl', 'Brilbeer', 'De brilbeer is de enige beer die in Zuid-Amerika inheems is en heeft lichte vlekken rond de ogen. Deze vlekken doen denken aan een bril en geven hem een vriendelijke uitstraling. In jouw dierentuin klimt hij graag, speelt hij met boomstammen en neemt hij af en toe een uitgebreide rustpauze.'),
       (92912, 305, 'fr', 'ours à lunettes', 'L''ours à lunettes est le seul ours originaire d''Amérique du Sud ; il porte des marques claires autour des yeux. Ces marques rappellent des lunettes et lui donnent un air sympathique. Dans ton zoo, il aime grimper, jouer avec des troncs d''arbres et s''accorder de longues pauses pour se reposer.'),
       (92913, 305, 'es', 'Oso de anteojos', 'El oso de anteojos es el único oso autóctono de Sudamérica y tiene unas manchas claras alrededor de los ojos. Estas manchas recuerdan a unos anteojos y le dan un aspecto simpático. En tu zoológico le gusta trepar, jugar con troncos y disfrutar de largos momentos de descanso.'),
       (92914, 306, 'nl', 'brilslang', 'De brilslang is een van de bekendste kobra’s en laat bij gevaar zijn kenmerkende nekkap zien. Op deze kap is vaak een patroonachtige ‘brilvlek’ te zien. In jouw dierentuin leeft hij achter veilige ruiten en fascineert hij bezoekers met zijn elegante, maar ontzagwekkende verschijning.'),
       (92915, 306, 'fr', 'Serpent à lunettes', 'Le cobra à lunettes est l''un des cobras les plus connus ; lorsqu''il se sent menacé, il déploie sa collerette caractéristique. Sur cette collerette, on distingue souvent une « tache en forme de lunettes » ressemblant à un motif. Dans ton zoo, il vit derrière des vitres sécurisées et fascine les visiteurs par son allure élégante mais imposante.'),
       (92916, 306, 'es', 'Serpiente de anteojos', 'La cobra de anteojos es una de las cobras más conocidas y, cuando se siente amenazada, despliega su característica cresta en el cuello. En esta cresta suele verse una «mancha en forma de anteojos» que parece un dibujo. En tu zoológico vive protegida tras unos cristales de seguridad y fascina a los visitantes con su aspecto elegante, pero que inspira respeto.'),
       (92917, 308, 'nl', 'Eland', 'De eland is het grootste lid van de hertenfamilie en is gemakkelijk te herkennen aan zijn brede, schepvormige gewei. Hij leeft in noordelijke bossen en houdt van moerassige gebieden en drinkplaatsen. In jouw dierentuin maakt hij met zijn omvang en kalmte een bijzonder indrukwekkende indruk.'),
       (92918, 308, 'fr', 'élan', 'L''élan est le plus grand représentant de la famille des cervidés et se reconnaît facilement à ses larges bois en forme de pelle. Il vit dans les forêts nordiques et apprécie particulièrement les zones marécageuses et les points d''eau. Dans ton zoo, il est particulièrement impressionnant par sa taille et son calme.'),
       (92919, 308, 'es', 'Alce', 'El alce es el miembro más grande de la familia de los cérvidos y se reconoce fácilmente por su amplia cornamenta en forma de pala. Vive en los bosques nórdicos y le encantan las zonas pantanosas y los abrevaderos. En tu zoológico resulta especialmente impresionante por su tamaño y su serenidad.'),
       (92920, 309, 'nl', 'Europese wilde kat', 'De Europese wildekat lijkt sterk op een huiskat, maar is steviger gebouwd en erg schuw. Hij leeft in bossen en vermijdt meestal het contact met mensen. In jouw dierentuin heeft hij veel schuilplaatsen nodig en beloont hij je met zeldzame, maar des te spannendere waarnemingen.'),
       (92921, 309, 'fr', 'Chat sauvage européen', 'Le chat sauvage européen ressemble beaucoup à un chat domestique, mais il est plus robuste et très craintif. Il vit dans les forêts et évite généralement tout contact avec l''homme. Dans ton zoo, il a besoin de nombreuses cachettes et te récompensera par des apparitions rares, mais d''autant plus passionnantes.'),
       (92922, 309, 'es', 'Gato montés europeo', 'El gato montés europeo se parece mucho a un gato doméstico, pero tiene una complexión más robusta y es muy tímido. Habita en los bosques y suele evitar el contacto con las personas. En tu zoológico necesita muchos escondites y, a cambio, te regalará avistamientos poco frecuentes, pero por eso mismo aún más emocionantes.'),
       (92923, 310, 'nl', 'Europese das', 'De Europese das is een nachtdier met een karakteristieke zwart-witte tekening op de kop. Hij leeft in uitgebreid vertakte holen en is een ijverige graver. In jouw dierentuin kun je hem zien wroeten in de grond en lekker luieren in zijn hol.'),
       (92924, 310, 'fr', 'Blattre européen', 'Le blaireau européen est un prédateur nocturne au motif noir et blanc caractéristique sur la tête. Il vit dans des terriers très ramifiés et est un fouisseur assidu. Dans ton zoo, on peut l''observer en train de fouiller le sol et de somnoler tranquillement dans son terrier.'),
       (92925, 310, 'es', 'Tejo europeo', 'El tejón europeo es un depredador nocturno con un característico patrón blanco y negro en la cabeza. Vive en madrigueras muy ramificadas y es un excavador incansable. En tu zoológico se le puede observar excavando en el suelo y dormitando plácidamente en su madriguera.'),
       (92926, 311, 'nl', 'Europees ree', 'Het Europese ree is een typische bewoner van onze bossen en velden. Het heeft een sierlijk postuur en is altijd alert om gevaren tijdig te herkennen. In jouw dierentuin komt het bijzonder zachtaardig over en kun je het goed observeren terwijl het graast en herkauwt.'),
       (92927, 311, 'fr', 'Chevreuil européen', 'Le chevreuil européen est un habitant typique de nos forêts et de nos champs. De constitution gracile, il est toujours à l’affût pour détecter les dangers à temps. Dans ton zoo, il semble particulièrement docile et on peut facilement l’observer en train de brouter et de ruminer.'),
       (92928, 311, 'es', 'Corzo europeo', 'El corzo europeo es un habitante típico de nuestros bosques y campos. Tiene una complexión delicada y está siempre alerta para detectar cualquier peligro a tiempo. En tu zoológico se muestra especialmente dócil y se le puede observar bien mientras pasta y rumia.'),
       (92929, 314, 'nl', 'Geelkuifkakadu’s', 'De geelkuifkaketoe is een levendige papegaai met een wit verenkleed en een felgele kuif. Hij is erg gezellig, luidruchtig en buitengewoon intelligent. In je dierentuin zorgt hij met zijn gekrijs, geklim en speelse gedrag voor geweldig vermaak.'),
       (92930, 314, 'fr', 'Cacatoès à huppe jaune', 'Le cacatoès à huppe jaune est un perroquet vif au plumage blanc et à la huppe d''un jaune éclatant. Il est très sociable, bruyant et extrêmement intelligent. Dans ton zoo, il te divertira à merveille avec ses cris, ses acrobaties et son comportement enjoué.'),
       (92931, 314, 'es', 'Cacatúa de cresta amarilla', 'El cacatúa de cresta amarilla es un loro muy vivaz, con plumaje blanco y una cresta de color amarillo brillante. Es muy sociable, ruidoso y sumamente inteligente. En tu zoológico te ofrecerá el mejor entretenimiento con sus graznidos, sus trepadas y su comportamiento juguetón.'),
       (92932, 315, 'nl', 'Ginsterkat', 'De ginsterkat is een slank, nachtactief roofdier met een lange staart en een prachtig vlekkenpatroon. Ze kan uitstekend klimmen en zwerft ’s nachts door haar territorium op zoek naar voedsel. In jouw dierentuin heeft ze veel schuilplaatsen nodig en laat ze vooral ’s avonds haar elegantie zien.'),
       (92933, 315, 'fr', 'chat des genêts', 'Le chat des genêts est un prédateur élancé et nocturne, doté d''une longue queue et d''un magnifique pelage tacheté. C''est un excellent grimpeur qui parcourt son territoire la nuit à la recherche de nourriture. Dans ton zoo, il a besoin de nombreuses cachettes et dévoile toute son élégance surtout en fin de journée.'),
       (92934, 315, 'es', 'Gato de retama', 'El gato del retamo es un depredador esbelto y nocturno, con una cola larga y un bonito pelaje manchado. Es un excelente trepador y, por la noche, recorre su territorio en busca de alimento. En tu zoológico necesitará muchos escondites y mostrará su elegancia sobre todo al atardecer.'),
       (92935, 316, 'nl', 'Goodfellow-boomkangoeroe', 'In tegenstelling tot zijn verwanten leeft het Goodfellow-boomkangoeroe meestal in de bomen. Hij komt uit de regenwouden van Nieuw-Guinea en heeft een dichte, roodbruine vacht. In jouw dierentuin klimt hij behendig van tak naar tak en lijkt hij bijna op een kangoeroe in klimmodus.'),
       (92936, 316, 'fr', 'Kangourou arboricole de Goodfellow', 'Contrairement à ses cousins, le kangourou arboricole de Goodfellow vit principalement dans les arbres. Originaire des forêts tropicales de Nouvelle-Guinée, il est doté d''un pelage épais, de couleur rouge-brun. Dans ton zoo, il grimpe habilement de branche en branche et donne presque l''impression d''être un kangourou en mode escalade.'),
       (92937, 316, 'es', 'Canguro arbóreo de Goodfellow', 'A diferencia de sus parientes, el canguro arbóreo de Goodfellow suele vivir en los árboles. Es originario de las selvas tropicales de Nueva Guinea y tiene un pelaje denso de color marrón rojizo. En tu zoológico trepa con destreza de rama en rama y parece casi un canguro en modo trepador.'),
       (92938, 317, 'nl', 'Grote paradijsvogel', 'De grote paradijsvogel staat bekend om zijn spectaculaire baltsveren en kunstzinnige dansen. Hij leeft in de bossen van Nieuw-Guinea en zet tijdens het paarseizoen een ware show neer. In jouw dierentuin betovert hij met zijn kleuren en elegante bewegingen iedereen die hem ziet.'),
       (92939, 317, 'fr', 'Grand oiseau de paradis', 'Le grand oiseau de paradis est célèbre pour son plumage nuptial spectaculaire et ses danses gracieuses. Il vit dans les forêts de Nouvelle-Guinée et offre un véritable spectacle pendant la période de reproduction. Dans ton zoo, il enchante tous ceux qui l''observent par ses couleurs et ses mouvements élégants.'),
       (92940, 317, 'es', 'Pájaro del paraíso mayor', 'El ave del paraíso gigante es famosa por su espectacular plumaje nupcial y sus elegantes danzas. Vive en los bosques de Nueva Guinea y, durante la época de apareamiento, ofrece todo un espectáculo. En tu zoológico, cautiva a todos los que lo ven con sus colores y sus elegantes movimientos.'),
       (92941, 318, 'nl', 'Hoornvogel', 'De helmhoornvogel heeft een opvallend hoornachtig uitsteeksel op zijn snavel, waaraan hij zijn naam te danken heeft. Hij leeft in tropische bossen en voedt zich met fruit en kleine dieren. In jouw dierentuin vliegt hij met krachtige vleugelslagen door de volière en roept luid door de ruimte.'),
       (92942, 318, 'fr', 'Calao à cornes', 'Le calao à cornes porte une corne bien visible sur son bec, d’où son nom. Il vit dans les forêts tropicales et se nourrit de fruits et de petits animaux. Dans ton zoo, il vole à grands coups d’ailes à travers la volière et pousse des cris puissants.'),
       (92943, 318, 'es', 'Aguavida de cuerno', 'El cálao de casco lleva una llamativa protuberancia en forma de cuerno en el pico, de ahí su nombre. Vive en los bosques tropicales y se alimenta de frutos y pequeños animales. En tu zoológico, vuela por el recinto de las pajareras con enérgicas batidas de alas y emite fuertes graznidos.'),
       (92944, 319, 'nl', 'mooikopwallaby', 'De mooi-gezichtwallaby is een kleine kangoeroe met een bijzonder zachte gezichtsuitdrukking. Hij leeft in Australië en geeft de voorkeur aan struikachtige leefgebieden. In jouw dierentuin huppelt hij zachtjes door het verblijf en kijkt hij de bezoekers nieuwsgierig aan met zijn grote ogen.'),
       (92945, 319, 'fr', 'wallaby à beau visage', 'Le wallaby à visage mignon est un petit kangourou à l''expression particulièrement douce. Il vit en Australie et affectionne les habitats buissonneux. Dans ton zoo, il sautille tranquillement dans son enclos et regarde les visiteurs avec curiosité, ses grands yeux écarquillés.'),
       (92946, 319, 'es', 'Wallaby de cara bonita', 'El ualabí de cara bonita es un pequeño canguro con una expresión facial especialmente dulce. Vive en Australia y prefiere los hábitats con mucha vegetación. En tu zoológico, salta silenciosamente por el recinto y mira a los visitantes con curiosidad, con sus grandes ojos.'),
       (92947, 320, 'nl', 'Indische sterrenschildpad', 'De Indische sterrenschildpad is te herkennen aan zijn opvallende, stervormig getekende schild. Hij komt oorspronkelijk uit droge gebieden in India en Sri Lanka. In de dierentuin beweegt hij zich rustig voort, maar bij elke stap komt het kunstzinnige patroon van zijn schild goed tot zijn recht.'),
       (92948, 320, 'fr', 'Tortue étoilée indienne', 'La tortue étoilée de l''Inde se reconnaît à sa carapace aux motifs étoilés très caractéristiques. Elle est originaire des régions arides de l''Inde et du Sri Lanka. Au zoo, elle se déplace tranquillement, mais chacun de ses pas met en valeur les motifs artistiques de sa carapace.'),
       (92949, 320, 'es', 'Tortuga estrellada de la India', 'La tortuga estrellada de la India se reconoce por su llamativo caparazón con un dibujo en forma de estrella. Es originaria de las regiones áridas de la India y Sri Lanka. En el zoo se mueve con tranquilidad, pero cada paso deja al descubierto el artístico diseño de su caparazón.'),
       (92950, 321, 'nl', 'Kiwi', 'De kiwi is een niet-vliegende vogel uit Nieuw-Zeeland en het nationale dier van het land. Hij heeft een borstelachtig verenkleed en gebruikt zijn lange snavel om in de grond naar voedsel te zoeken. In jouw dierentuin leeft hij in een verduisterde ruimte en laat hij zich vooral zien tijdens rondleidingen voor nachtbrakers.'),
       (92951, 321, 'fr', 'kiwi', 'Le kiwi est un oiseau incapable de voler originaire de Nouvelle-Zélande et l''animal emblématique de ce pays. Il possède un plumage hérissé et utilise son long bec pour fouiller le sol à la recherche de nourriture. Dans ton zoo, il vit dans un espace obscurci et ne se montre principalement que lors des visites guidées nocturnes.'),
       (92952, 321, 'es', 'Kiwi', 'El kiwi es un ave no voladora originaria de Nueva Zelanda y el animal nacional de ese país. Tiene un plumaje similar a unas cerdas y utiliza su largo pico para hurgar en el suelo en busca de alimento. En tu zoológico vive en una zona oscurecida y se deja ver sobre todo durante las visitas guiadas nocturnas.'),
       (92953, 322, 'nl', 'Koala', 'De koala is een buideldier uit Australië dat het grootste deel van de tijd in eucalyptusbomen doorbrengt. Hij slaapt tot wel 20 uur per dag en ziet er daarbij altijd heerlijk ontspannen uit. In jouw dierentuin hangt hij gezellig in takvertakkingen, knabbelt hij aan eucalyptusbladeren en straalt hij pure rust uit.'),
       (92954, 322, 'fr', 'Koala', 'Le koala est un marsupial originaire d''Australie qui passe la majeure partie de son temps dans les eucalyptus. Il dort jusqu''à 20 heures par jour et semble toujours merveilleusement détendu. Dans ton zoo, il est confortablement suspendu dans les fourches des branches, grignote des feuilles d''eucalyptus et respire la sérénité à l''état pur.'),
       (92955, 322, 'es', 'Koala', 'El koala es un marsupial originario de Australia que pasa la mayor parte del tiempo en los eucaliptos. Duerme hasta 20 horas al día y siempre parece maravillosamente relajado. En tu zoo, se cuelga cómodamente de las horquillas de las ramas, mordisquea hojas de eucalipto y irradia pura serenidad.'),
       (92956, 323, 'nl', 'Kusu', 'De kusu, ook wel possum genoemd, is een nachtdier uit de orde van de buideldieren dat in Australië en Nieuw-Guinea voorkomt. Hij leeft meestal in bomen en gebruikt zijn grijpstaart om te klimmen. In jouw dierentuin is hij een rustige bewoner die ’s nachts nieuwsgierig door zijn verblijf dwaalt.'),
       (92957, 323, 'fr', 'Kusu', 'Le kusu, également appelé opossum, est un marsupial nocturne originaire d''Australie et de Nouvelle-Guinée. Il vit principalement dans les arbres et utilise sa queue préhensile pour grimper. Dans ton zoo, c''est un compagnon discret qui, la nuit, arpente son enclos avec curiosité.'),
       (92958, 323, 'es', 'Kusu', 'El kusu, también conocido como zarigüeya, es un marsupial nocturno originario de Australia y Nueva Guinea. Suele vivir en los árboles y utiliza su cola prensil para trepar. En tu zoológico es un compañero silencioso que, por las noches, deambula con curiosidad por su recinto.'),
       (92959, 324, 'nl', 'Maanbeer', 'De maanbeer, ook wel kraagbeer genoemd, heeft een lichte halve maanvormige vlek op zijn borst. Hij leeft in Azië en brengt veel tijd door met klimmen en het zoeken naar voedsel. In jouw dierentuin klimt hij graag op platforms en laat daarbij steeds weer trots zijn maanvormige vlek op zijn borst zien.'),
       (92960, 324, 'fr', 'Ours de la Lune', 'L''ours lunaire, également appelé « ours à collier », porte une tache claire en forme de demi-lune sur la poitrine. Il vit en Asie et passe beaucoup de temps à grimper et à chercher de la nourriture. Dans ton zoo, il aime grimper sur les plateformes et, ce faisant, exhibe fièrement sa demi-lune.'),
       (92961, 324, 'es', 'Oso lunar', 'El oso lunar, también conocido como oso de collar, tiene una mancha clara en forma de media luna en el pecho. Vive en Asia y pasa mucho tiempo trepando y buscando comida. En tu zoológico le gusta trepar a las plataformas y, al hacerlo, muestra con orgullo una y otra vez la media luna de su pecho.'),
       (92962, 325, 'nl', 'Noordopossum', 'De noordelijke buidelrat is het enige buideldier van Noord-Amerika en een echte overlevingskunstenaar. Bij gevaar doet hij zich soms dood om vijanden te misleiden. In jouw dierentuin snuffelt hij nieuwsgierig rond in voederbakjes en laat hij zien hoe veelzijdig een kleine buidelrat kan zijn.'),
       (92963, 325, 'fr', 'opossum du Nord', 'L''opossum du Nord est le seul marsupial d''Amérique du Nord et un véritable maître de la survie. En cas de danger, il fait parfois le mort pour tromper ses prédateurs. Dans ton zoo, il fouille avec curiosité les cachettes de nourriture et montre à quel point un petit marsupial peut être polyvalent.'),
       (92964, 325, 'es', 'Oposum del norte', 'La zarigüeya del norte es el único marsupial de América del Norte y un auténtico maestro de la supervivencia. A veces, ante el peligro, se hace la muerta para engañar a sus enemigos. En tu zoológico, rebusca con curiosidad en los escondites de comida y demuestra lo versátil que puede ser un pequeño marsupial.'),
       (92965, 326, 'nl', 'Okapi', 'De okapi is een naaste verwant van de giraf, ook al lijkt hij meer op een kruising tussen een paard en een zebra. Hij leeft in de dichte regenwouden van Congo en is erg schuw. In jouw dierentuin zoekt hij graag rustige plekjes op en verrast hij bezoekers met zijn gestreepte poten.'),
       (92966, 326, 'fr', 'Okapi', 'L''okapi est un proche parent de la girafe, même s''il ressemble davantage à un croisement entre un cheval et un zèbre. Il vit dans les forêts tropicales denses du Congo et est très farouche. Dans ton zoo, il apprécie les recoins tranquilles et surprend les visiteurs avec ses pattes rayées.'),
       (92967, 326, 'es', 'Okapi', 'El okapi es un pariente cercano de la jirafa, aunque más bien parece una mezcla entre un caballo y una cebra. Vive en las densas selvas tropicales del Congo y es muy tímido. En tu zoológico, aprecia los rincones tranquilos donde refugiarse y sorprende a los visitantes con sus patas rayadas.'),
       (92968, 327, 'nl', 'Penseeloorvarken', 'Het borsteloorzwijn is een kleurrijk wild zwijn uit Afrika met opvallende gezichtsmarkeringen. Het dankt zijn naam aan de lange haarborstels aan zijn oren. In jouw dierentuin wentelt het zich enthousiast in de modder en snuffelt het met zijn snuit in alle hoeken en gaten.'),
       (92969, 327, 'fr', 'cochon à oreilles en pinceau', 'Le phacochère à oreilles en pinceau est un sanglier africain aux couleurs vives, doté d''un motif facial très caractéristique. Il doit son nom aux longues mèches de poils en forme de pinceau qui ornent ses oreilles. Dans ton zoo, il se vautre avec délectation dans la boue et fouille chaque recoin avec son museau.'),
       (92970, 327, 'es', 'Cerdo de orejas de pincel', 'El jabalí de orejas en forma de pincel es un jabalí africano de colores vivos con llamativos dibujos en la cara. Debe su nombre a los largos mechones de pelo que tiene en las orejas. En tu zoológico, se revuelca con entusiasmo en el barro y husmea con el hocico en cada rincón.'),
       (92971, 328, 'nl', 'Rode brulaap', 'De rode brulaap staat bekend om zijn luide kreten, die ver door het regenwoud weerklinken. Hij leeft in bomen en eet vooral bladeren. In jouw dierentuin laat hij zijn diepe stem horen en herinnert hij iedereen eraan dat een apenverblijf nooit echt stil is.'),
       (92972, 328, 'fr', 'Singe hurleur rouge', 'Le singe hurleur rouge est connu pour ses cris puissants qui résonnent loin dans la forêt tropicale. Il vit dans les arbres et se nourrit principalement de feuilles. Dans ton zoo, il fait résonner sa voix grave et rappelle à tout le monde qu''un enclos de singes n''est jamais vraiment silencieux.'),
       (92973, 328, 'es', 'Mono aullador rojo', 'El mono aullador rojo es conocido por sus fuertes aullidos, que resuenan a lo largo y ancho de la selva tropical. Vive en los árboles y se alimenta principalmente de hojas. En tu zoológico, deja oír su voz grave y nos recuerda a todos que un recinto de monos nunca está realmente en silencio.'),
       (92974, 329, 'nl', 'Rode panda', 'De rode panda is een kleine, klimmende bamboeliefhebber met een pluizige staart. Hij leeft in de bergbossen van Azië en is vooral in bomen te vinden. In jouw dierentuin klautert hij behendig over takken en slaapt hij opgerold als een knus bolletje bont.'),
       (92975, 329, 'fr', 'Panda roux', 'Le panda roux est un petit animal qui adore grimper et se nourrir de bambou, avec une queue duveteuse. Il vit dans les forêts de montagne d''Asie et se déplace principalement dans les arbres. Dans ton zoo, il se balance habilement sur les branches et dort recroquevillé, tel une adorable boule de poils.'),
       (92976, 329, 'es', 'Panda rojo', 'El panda rojo es un animalito al que le encanta trepar y comer bambú, y tiene una cola mullida. Vive en los bosques de montaña de Asia y se mueve sobre todo por los árboles. En tu zoológico, trepa con destreza por las ramas y duerme acurrucado como un mullido ovillo de pelo.'),
       (92977, 331, 'nl', 'Rode vos', 'De rode vos is een flexibel roofdier dat in bossen, velden en zelfs steden leeft. Met zijn rode vacht en zijn pluimstaart is hij gemakkelijk te herkennen. In jouw dierentuin laat hij zijn slimme, nieuwsgierige kant zien en houdt hij alles nauwlettend in de gaten.'),
       (92978, 331, 'fr', 'renard roux', 'Le renard roux est un prédateur qui s''adapte facilement et vit dans les forêts, les champs et même les villes. Avec son pelage roux et sa queue touffue, il est facile à reconnaître. Dans ton zoo, il montre son côté rusé et curieux et observe attentivement tout ce qui se passe.'),
       (92979, 331, 'es', 'Zorro rojo', 'El zorro rojo es un depredador adaptable que vive en bosques, campos e incluso ciudades. Es fácil de reconocer por su pelaje rojo y su cola tupida. En tu zoológico muestra su lado astuto y curioso, y observa con mucha atención todo lo que sucede a su alrededor.'),
       (92980, 332, 'nl', 'Chimpansee', 'De chimpansee is een van onze naaste verwanten en maakt indruk met zijn intelligentie. In groepen heeft hij een complexe sociale structuur en gebruikt hij gereedschap in het dagelijks leven. In jouw dierentuin klimt hij, speelt hij, maakt hij ruzie en verzoent hij zich weer – bijna als een kleine apenstad.'),
       (92981, 332, 'fr', 'chimpanzé', 'Le chimpanzé est l''un de nos plus proches parents et impressionne par son intelligence. Au sein de son groupe, il évolue selon une structure sociale complexe et utilise des outils au quotidien. Dans ton zoo, il grimpe, joue, se dispute et se réconcilie – un peu comme dans une petite ville de singes.'),
       (92982, 332, 'es', 'chimpancé', 'El chimpancé es uno de nuestros parientes más cercanos y sorprende por su inteligencia. En grupo, presenta una estructura social compleja y utiliza herramientas en su vida cotidiana. En tu zoológico trepa, juega, se pelea y se reconcilia, casi como si fuera una pequeña ciudad de monos.'),
       (92983, 333, 'nl', 'Sumatra-neushoorn', 'De Sumatraanse neushoorn is de kleinste nog levende neushoorn en ernstig bedreigd. Hij heeft meestal twee hoorns en leeft in dichte regenwouden. In jouw dierentuin is hij een echte trekpleister en een ambassadeur voor de bescherming van tropische leefgebieden.'),
       (92984, 333, 'fr', 'Rhinocéros de Sumatra', 'Le rhinocéros de Sumatra est le plus petit rhinocéros vivant et est gravement menacé. Il possède généralement deux cornes et vit dans les forêts tropicales denses. Dans ton zoo, c''est une véritable attraction et un ambassadeur de la protection des habitats tropicaux.'),
       (92985, 333, 'es', 'Rinoceronte de Sumatra', 'El rinoceronte de Sumatra es el rinoceronte vivo más pequeño y se encuentra en grave peligro de extinción. Suele tener dos cuernos y vive en densas selvas tropicales. En tu zoológico es una auténtica atracción y un embajador de la protección de los hábitats tropicales.'),
       (92986, 334, 'nl', 'Tanuki', 'De tanuki, ook wel marterhond genoemd, komt uit Oost-Azië en lijkt op een kruising tussen een wasbeer en een hond. In de Japanse folklore wordt hij beschouwd als een vrolijke, ondeugende gedaanteverwisselaar. In jouw dierentuin gedraagt hij zich eerder rustig, snuffelt nieuwsgierig rond en knuffelt graag met soortgenoten.'),
       (92987, 334, 'fr', 'Tanuki', 'Le tanuki, également appelé chien-martr, est originaire d''Asie de l''Est et ressemble à un croisement entre un raton laveur et un chien. Dans le folklore japonais, il est considéré comme un métamorphe joyeux et espiègle. Dans ton zoo, il se montre plutôt tranquille, renifle avec curiosité et aime se blottir contre ses congénères.'),
       (92988, 334, 'es', 'Tanuki', 'El tanuki, también conocido como perro martilla, es originario de Asia Oriental y tiene el aspecto de una mezcla entre un mapache y un perro. En el folclore japonés se le considera un metamorfo alegre y travieso. En tu zoológico se muestra más bien tranquilo, husmea con curiosidad y le gusta acurrucarse con otros ejemplares de su especie.'),
       (92989, 335, 'nl', 'Tasmaanse duivel', 'De Tasmaanse duivel is een krachtig buideldier met een luid gegrom en een indrukwekkende bijtkracht. Hij leeft in Tasmanië en eet vooral aas, maar is ook een snelle jager. In jouw dierentuin rolt hij zich tijdens het eten in een ware voedselroes, wat bij bezoekers voor verbaasde blikken zorgt.'),
       (92990, 335, 'fr', 'Diable de Tasmanie', 'Le diable de Tasmanie est un marsupial robuste qui grogne bruyamment et possède une force de morsure impressionnante. Il vit en Tasmanie et se nourrit principalement de charognes, mais c''est aussi un chasseur rapide. Dans ton zoo, il se laisse aller à de véritables frénésies alimentaires lorsqu’il mange, ce qui suscite l’émerveillement des visiteurs.'),
       (92991, 335, 'es', 'Demonio de Tasmania', 'El demonio de Tasmania es un marsupial robusto que emite un fuerte gruñido al morder y posee una impresionante fuerza de mordida. Vive en Tasmania y se alimenta principalmente de carroña, aunque también es un cazador ágil. En tu zoológico, cuando come, se revuelca en un auténtico torbellino de comida, lo que deja a los visitantes con cara de asombro.'),
       (92992, 336, 'nl', 'doodshoofdaapjes', 'Het doodshoofdaapje is klein, behendig en heeft een gezichts tekening die aan een schedel doet denken. Het leeft in de bossen van Midden- en Zuid-Amerika en is zelden alleen onderweg. In jouw dierentuin raast het in groepjes door het verblijf en is het voortdurend aan het klimmen, springen en piepen.'),
       (92993, 336, 'fr', 'singe-tête-de-mort', 'Le singe-tête-de-mort est petit, agile et présente un motif facial qui rappelle un crâne. Il vit dans les forêts d''Amérique centrale et d''Amérique du Sud et se déplace rarement seul. Dans ton zoo, il file à toute allure en groupe à travers son enclos et passe son temps à grimper, à sauter et à pousser des cris aigus.'),
       (92994, 336, 'es', 'mono calavera', 'El mono calavera es pequeño, ágil y tiene un dibujo en la cara que recuerda a una calavera. Vive en los bosques de América Central y del Sur y rara vez se mueve por su cuenta. En tu zoológico, corre a toda velocidad por el recinto en grupo y no para de trepar, saltar y chilliar.'),
       (92995, 337, 'nl', 'Tundrawolf', 'De toendrawolf leeft in de koude gebieden van het noorden en heeft een dikke, lichte wintervacht. Hij jaagt in roedels en legt grote afstanden af in de uitgestrekte toendra. In jouw dierentuin laat hij in de groep zijn sociale vaardigheden zien en maakt hij indruk met zijn doordringende gehuil.'),
       (92996, 337, 'fr', 'Loup de la toundra', 'Le loup de la toundra vit dans les régions froides du Nord et possède un pelage d''hiver épais et clair. Il chasse en meute et parcourt de longues distances dans l''immensité de la toundra. Dans ton zoo, il montre ses aptitudes sociales au sein du groupe et impressionne par ses hurlements perçants.'),
       (92997, 337, 'es', 'Lobo de la tundra', 'El lobo de la tundra vive en las frías regiones del norte y tiene un pelaje de invierno denso y claro. Caza en manada y recorre grandes distancias por las extensiones de la tundra. En tu zoológico, muestra sus habilidades sociales cuando está en grupo e impresiona con su aullido penetrante.'),
       (92998, 338, 'nl', 'Urson', 'De Urson is een Noord-Amerikaans stekelvarken met lange, puntige stekels waarmee hij zich verdedigt. Hij beweegt zich vrij langzaam en brengt veel tijd door in bomen. In jouw dierentuin klimt hij rustig in de takken en laat hij zijn stekels glinsteren in het licht – maar je kunt hem beter niet aanraken.'),
       (92999, 338, 'fr', 'Urson', 'L''Urson est un porc-épic nord-américain doté de longues épines pointues qui lui servent à se défendre. Il se déplace plutôt lentement et passe beaucoup de temps dans les arbres. Dans ton zoo, il grimpe tranquillement sur les branches et laisse ses épines scintiller à la lumière – mais mieux vaut ne pas le toucher.'),
       (93000, 338, 'es', 'Urson', 'El urson es un puercoespín norteamericano con púas largas y puntiagudas que le sirven para defenderse. Se mueve con bastante lentitud y pasa mucho tiempo en los árboles. En tu zoológico trepa tranquilamente por las ramas y deja que sus púas brillen a la luz, pero es mejor no tocarlo.'),
       (93001, 339, 'nl', 'Bos hond', 'De bos hond is een kleine, gedrongen wilde hond uit Zuid-Amerika met korte poten. Hij jaagt in een roedel en is bijzonder goed aangepast aan het leven in het dichte bos. In jouw dierentuin is hij bijna altijd in beweging en laat hij zien hoeveel energie er in zo’n klein lichaam kan zitten.'),
       (93002, 339, 'fr', 'chien des bois', 'Le chien des bois est un petit chien sauvage trapu originaire d''Amérique du Sud, aux pattes courtes. Il chasse en meute et est particulièrement bien adapté à la vie dans la forêt dense. Dans ton zoo, il est presque toujours en mouvement et montre toute l''énergie que peut receler un si petit corps.'),
       (93003, 339, 'es', 'Perro del bosque', 'El perro del bosque es un perro salvaje pequeño y robusto, originario de Sudamérica, con patas cortas. Caza en manada y está especialmente adaptado a la vida en el bosque denso. En tu zoológico está casi siempre en movimiento y demuestra cuánta energía puede albergar un cuerpo tan pequeño.'),
       (93004, 340, 'nl', 'Wildzwijn', 'Het wilde zwijn is de wilde verwant van ons gedomesticeerde varken en voelt zich thuis in bossen en velden. Het is een krachtige wroeter en houdt van modder en vochtige grond. In jouw dierentuin wentelt het zich vrolijk in de modder en gromt het tevreden als het lekkere wortels vindt.'),
       (93005, 340, 'fr', 'sanglier', 'Le sanglier est le cousin sauvage de notre cochon domestique et se sent chez lui dans les forêts et les champs. C''est un fouisseur infatigable qui adore la boue et le sol humide. Dans ton zoo, il se vautre joyeusement et grogne de satisfaction lorsqu’il trouve de délicieuses racines.'),
       (93006, 340, 'es', 'jabalí', 'El jabalí es el pariente salvaje de nuestro cerdo doméstico y se siente a gusto en bosques y campos. Es un animal que excava con fuerza y le encanta el barro y la tierra húmeda. En tu zoológico se revuelca alegremente y gruñe satisfecho cuando encuentra deliciosas raíces.'),
       (93007, 341, 'nl', 'Zebraducker', 'De zebraducker is een zeldzame, in het bos levende antilope uit Afrika. Zijn naam doet denken aan dwergen, en hij is inderdaad vrij klein en schuw. In jouw dierentuin houdt hij van dichte begroeiing en laat hij zich alleen met een beetje geluk zien.'),
       (93008, 341, 'fr', 'canard zébré', 'Le zébracou est une antilope africaine rare qui vit dans les forêts. Son nom évoque les nains, et il est en effet plutôt petit et timide. Dans ton zoo, il apprécie les végétations denses et ne se laisse apercevoir qu’avec un peu de chance.'),
       (93009, 341, 'es', 'pato cebra', 'El antílope cebra es un antílope africano poco común que vive en los bosques. Su nombre recuerda a los enanos y, de hecho, es bastante pequeño y tímido. En tu zoológico, prefiere las zonas con vegetación densa y solo se deja ver con un poco de suerte.'),
       (93010, 343, 'nl', 'Zwarte ooievaar', 'De zwarte ooievaar is schuwere dan zijn witte soortgenoot en leeft voornamelijk in ongestoorde bossen. Zijn donkere verenkleed glinstert metaalachtig in de zon. In jouw dierentuin beweegt hij zich rustig en terughoudend, een bijzondere ontdekking voor oplettende bezoekers.'),
       (93011, 343, 'fr', 'Cigogne noire', 'La cigogne noire est plus farouche que sa cousine blanche et vit principalement dans des forêts préservées. Son plumage foncé présente des reflets métalliques au soleil. Dans ton zoo, elle se déplace calmement et discrètement, ce qui en fait une découverte particulière pour les visiteurs attentifs.'),
       (93012, 343, 'es', 'Cigüeña negra', 'La cigüeña negra es más tímida que su pariente blanca y vive principalmente en bosques tranquilos. Su plumaje oscuro brilla con un tono metálico al sol. En tu zoológico se mueve con calma y discreción, lo que supone un descubrimiento especial para los visitantes atentos.'),
       (93013, 401, 'nl', 'Afrikaanse ezel', 'De Afrikaanse ezel is de wilde voorouder van onze tamme ezels en heeft zich aangepast aan droge steppegebieden. Hij heeft vaak een grijze vacht met donkere poten en strepen op de schouders. In jouw dierentuin laat hij zijn robuuste kant zien en laat hij af en toe een krachtige „I-A“ door het verblijf galmen.'),
       (93014, 401, 'fr', 'Âne africain', 'L''âne africain est l''ancêtre sauvage de nos ânes domestiques et s''est adapté aux steppes arides. Il présente souvent un pelage gris, avec des pattes foncées et des rayures sur les épaules. Dans ton zoo, il montre son côté robuste et fait parfois résonner un « I-A » puissant à travers l''enclos.'),
       (93015, 401, 'es', 'Burro africano', 'El burro africano es el antepasado salvaje de nuestros burros domésticos y está adaptado a las estepas áridas. Suele tener el pelaje gris, con las patas oscuras y rayas en los hombros. En tu zoológico muestra su lado robusto y, de vez en cuando, resuena por todo el recinto con un potente «I-A».'),
       (93016, 402, 'nl', 'Alpaca', 'De alpaca is met zijn donzige vacht en zachte blik een favoriet van veel bezoekers. Hij komt oorspronkelijk uit de Andes en wordt vooral gehouden vanwege zijn zachte wol. In jouw dierentuin loopt hij nieuwsgierig door het verblijf en laat hij zich graag fotograferen, mits er wat afstand wordt gehouden.'),
       (93017, 402, 'fr', 'Alpaga', 'Avec sa fourrure duveteuse et son regard doux, l''alpaga est l''un des animaux préférés de nombreux visiteurs. Originaire des Andes, il est principalement élevé pour sa laine douce. Dans ton zoo, il se promène avec curiosité dans son enclos et se laisse volontiers photographier, à condition de garder une certaine distance de sécurité.'),
       (93018, 402, 'es', 'Alpaca', 'La alpaca, con su pelaje mullido y su mirada dulce, es una de las favoritas de muchos visitantes. Es originaria de los Andes y se cría principalmente por su suave lana. En tu zoológico, se pasea con curiosidad por el recinto y, desde una distancia prudencial, se deja fotografiar con gusto.'),
       (93019, 404, 'nl', 'Alpensteenbok', 'De alpengems is een klimkunstenaar die moeiteloos steile rotswanden beklimt. Zijn imposante hoorns en krachtige lichaamsbouw maken hem onmiskenbaar. In jouw dierentuin maakt hij met gemak gebruik van rotsformaties en laat hij bezoekers zien wat evenwicht inhoudt.'),
       (93020, 404, 'fr', 'bouquetin des Alpes', 'Le bouquetin des Alpes est un véritable grimpeur d''exception, capable d''escalader sans peine les parois rocheuses escarpées. Ses cornes imposantes et sa carrure puissante le rendent facilement reconnaissable. Dans ton zoo, il évolue avec aisance sur les formations rocheuses et montre aux visiteurs ce qu''est l''équilibre.'),
       (93021, 404, 'es', 'cabra montés de los Alpes', 'El cabra montés alpino es un auténtico maestro de la escalada que trepa sin esfuerzo por escarpadas paredes rocosas. Sus imponentes cuernos y su complexión robusta lo hacen inconfundible. En tu zoológico, se mueve con facilidad por las estructuras rocosas y muestra a los visitantes lo que significa el equilibrio.'),
       (93022, 406, 'nl', 'Argali', 'De argali is het grootste wilde schaap ter wereld en leeft in de bergen van Centraal-Azië. Zijn indrukwekkende, spiraalvormige hoorns kunnen erg groot worden. In jouw dierentuin loopt hij rustig over de rotsachtige delen van zijn verblijf en toont hij trots zijn prachtige hoorns.'),
       (93023, 406, 'fr', 'Argali', 'L''argali est le plus grand mouton sauvage du monde et vit dans les montagnes d''Asie centrale. Ses impressionnantes cornes en spirale peuvent atteindre une taille considérable. Dans ton zoo, il se promène tranquillement sur les terrains rocailleux de son enclos et exhibe fièrement ses magnifiques cornes.'),
       (93024, 406, 'es', 'Argali', 'El argalí es el carnero salvaje más grande del mundo y habita en las montañas de Asia Central. Sus impresionantes cuernos, en forma de espiral, pueden alcanzar un tamaño considerable. En tu zoológico, deambula tranquilamente por las zonas rocosas de su recinto y muestra con orgullo sus magníficos cuernos.'),
       (93025, 408, 'nl', 'baardgier', 'De baardgier is een machtige roofvogel die zich heeft gespecialiseerd in botten. Hij laat botten vanaf grote hoogte vallen om bij het voedzame beenmerg te komen. In jouw dierentuin zweeft hij in wijde cirkels boven de volière en laat hij zijn indrukwekkende silhouet zien.'),
       (93026, 408, 'fr', 'gypaète barbu', 'Le gypaète barbu est un puissant rapace spécialisé dans la consommation d''os. Il laisse tomber les os depuis une grande hauteur afin d''accéder à la moelle, très nutritive. Dans ton zoo, il plane en décrivant de larges cercles au-dessus de la volière, dévoilant ainsi sa silhouette imposante.'),
       (93027, 408, 'es', 'buitre barbudo', 'El quebrantahuesos es una imponente ave rapaz especializada en los huesos. Deja caer los huesos desde gran altura para acceder a la nutritiva médula. En tu zoológico, sobrevuela el aviario describiendo amplios círculos y mostrando su imponente silueta.'),
       (93028, 409, 'nl', 'boomstekel', 'Het boomstekelvarken is een klimmend stekelvarken dat veel tijd in bomen doorbrengt. Zijn stekels bieden een effectieve bescherming tegen vijanden. In je dierentuin klimt hij in een rustig tempo in de takken en trekt hij nieuwsgierige blikken naar zich toe.'),
       (93029, 409, 'fr', 'Hérisson des arbres', 'Le porc-épic grimpeur est un porc-épic grimpeur qui passe beaucoup de temps dans les arbres. Ses piquants lui offrent une protection efficace contre ses prédateurs. Dans ton zoo, il grimpe sur les branches à un rythme tranquille et attire tous les regards curieux.'),
       (93030, 409, 'es', 'Espino de árbol', 'El puercoespín trepador es un puercoespín que pasa mucho tiempo en los árboles. Sus púas le sirven como protección eficaz contra los depredadores. En tu zoológico, trepa por las ramas a un ritmo pausado y atrae las miradas de los curiosos.'),
       (93031, 410, 'nl', 'Bergnyala', 'De bergnyala is een zeldzame antilope uit de hooglandgebieden van Ethiopië. Ze heeft een donkere vacht en opvallende witte vlekken. In jouw dierentuin ziet ze er bijzonder elegant uit wanneer ze rustig door het verblijf loopt.'),
       (93032, 410, 'fr', 'Nyala des montagnes', 'Le nyala des montagnes est une antilope rare originaire des hauts plateaux d''Éthiopie. Il possède un pelage foncé et des marques blanches bien visibles. Dans ton zoo, il est particulièrement élégant lorsqu''il se promène tranquillement dans son enclos.'),
       (93033, 410, 'es', 'Bergnyala', 'El nyala de montaña es un antílope poco común de las regiones montañosas de Etiopía. Tiene un pelaje de color oscuro y llamativas manchas blancas. En tu zoológico se ve especialmente elegante cuando camina tranquilamente por el recinto.'),
       (93034, 411, 'nl', 'Falklandkaraka', 'De Falklandkaraka is een vogel van de Falklandeilanden en gewend aan het ruige eilandleven. Hij is nieuwsgierig en maakt graag gebruik van door mensen gecreëerde structuren. In jouw dierentuin laat hij zich zien als een levendig, slim dier met een grote behoefte aan beweging.'),
       (93035, 411, 'fr', 'Caracara des Malouines', 'Le caracara des Malouines est un oiseau originaire des îles Malouines, habitué à la vie rude de ces îles. Curieux, il aime profiter des structures créées par l''homme. Dans ton zoo, il se révèle être un animal vif et intelligent, doté d''un grand besoin de mouvement.'),
       (93036, 411, 'es', 'Caraca de las Malvinas', 'El caracara de las Malvinas es un ave originaria de las Islas Malvinas, acostumbrada a la dura vida isleña. Es curioso y le gusta aprovechar las estructuras creadas por el ser humano. En tu zoológico se muestra como un animal vivaz e inteligente, con muchas ganas de moverse.'),
       (93037, 412, 'nl', 'Vlekkenstinkdier', 'De gevlekte stinkdier is kleiner dan de gestreepte stinkdier, maar heeft daarentegen een bonte vacht. Ook hij beschikt over het beroemde afweersysteem met geur, dat hij alleen in noodgevallen gebruikt. In jouw dierentuin is hij meestal nachtdier en laat hij zich vooral ’s avonds zien.'),
       (93038, 412, 'fr', 'Skunk tacheté', 'Le putois tacheté est plus petit que le putois rayé, mais il est par contre tacheté de couleurs vives. Lui aussi dispose du fameux mécanisme de défense odorant, qu''il n''utilise qu''en cas d''urgence. Dans ton zoo, il est généralement nocturne et se montre surtout en fin de journée.'),
       (93039, 412, 'es', 'Zorrillo manchado', 'El zorrillo moteado es más pequeño que el zorrillo rayado, pero tiene un pelaje moteado de colores. También cuenta con el famoso sistema de defensa olfativo, que solo utiliza en caso de emergencia. En tu zoológico suele ser nocturno y se deja ver sobre todo al atardecer.'),
       (93040, 413, 'nl', 'Gewone stekelvarken', 'Het gewone stekelvarken heeft een indrukwekkend pantser van lange, puntige stekels. Bij gevaar zet het deze rechtop en ratelt het als waarschuwing. In jouw dierentuin trekt het dankzij zijn spectaculaire silhouet meteen de aandacht.'),
       (93041, 413, 'fr', 'Porc-épic commun', 'Le porc-épic commun est doté d’une impressionnante armure composée de longues épines pointues. En cas de danger, il dresse ses épines et les fait cliqueter pour se faire entendre. Dans ton zoo, il attire immédiatement tous les regards grâce à sa silhouette spectaculaire.'),
       (93042, 413, 'es', 'Puercoespín común', 'El puercoespín común luce una impresionante armadura formada por púas largas y puntiagudas. Ante el peligro, las eriza y las sacude para dar la voz de alarma. En tu zoológico, llamará la atención de inmediato gracias a su espectacular silueta.'),
       (93043, 414, 'nl', 'Goudneus', 'De goudneus-aap is een zeldzame aap uit de bergbossen van China met een opvallende, goudkleurige vacht. Zijn korte, naar boven gerichte neusstomp geeft hem een uniek uiterlijk. In jouw dierentuin klautert hij in groepen door het verblijf en wekt hij met zijn uiterlijk verwondering op.'),
       (93044, 414, 'fr', 'Tête-de-bœuf dorée', 'Le singe à nez retroussé doré est une espèce rare originaire des forêts de montagne chinoises, qui se distingue par son pelage doré. Son nez court et retroussé lui confère un visage unique. Dans ton zoo, il grimpe en groupe à travers son enclos et suscite l''émerveillement par son apparence.'),
       (93045, 414, 'es', 'Nariz chata dorada', 'El mono de nariz chata dorada es una especie poco común de los bosques de montaña de China que destaca por su llamativo pelaje dorado. Su nariz corta y chata, orientada hacia arriba, le da un aspecto único. En tu zoológico, estos monos trepan en grupos por el recinto y sorprenden a los visitantes con su aspecto.'),
       (93046, 415, 'nl', 'Goldtakin', 'De goudtakin is een imposant hoefdier uit de Himalaya, dat vooral opvalt door zijn gouden vacht. Hij lijkt op een kruising tussen een geit en een gnoe en is perfect aangepast aan het hooggebergte. In jouw dierentuin staat hij graag op verhoogde platforms en laat hij de wind door zijn vacht waaien.'),
       (93047, 415, 'fr', 'Goldtakin', 'Le takin doré est un ongulé imposant originaire de l''Himalaya, dont la fourrure dorée attire particulièrement l''attention. Il ressemble à un croisement entre une chèvre et un gnou et est parfaitement adapté à la haute montagne. Dans ton zoo, il aime se tenir sur des plates-formes surélevées et laisser le vent souffler dans sa fourrure.'),
       (93048, 415, 'es', 'Goldtakin', 'El takín dorado es un imponente ungulado del Himalaya cuyo pelaje dorado llama especialmente la atención. Parece una mezcla entre una cabra y un ñu, y está perfectamente adaptado a la alta montaña. En tu zoológico le gusta subirse a plataformas elevadas y dejar que el viento le acaricie el pelaje.'),
       (93049, 416, 'nl', 'Hermelijn', 'De hermelijn is een klein roofdier dat in de winter vaak een sneeuwwitte vacht krijgt. Vroeger gold het in deze periode als symbool van zuiverheid en werd het zeer gewaardeerd. In jouw dierentuin verandert de kleur van zijn vacht in de loop van het jaar en laat het zien hoe goed camouflage kan werken.'),
       (93050, 416, 'fr', 'hermine', 'L''hermine est un petit prédateur dont le pelage devient souvent blanc comme neige en hiver. À cette époque, elle était autrefois considérée comme un symbole de pureté et était très appréciée. Dans ton zoo, elle change de couleur de pelage au fil des saisons et montre à quel point le camouflage peut être efficace.'),
       (93051, 416, 'es', 'Arminio', 'El armiño es un pequeño depredador cuyo pelaje suele volverse blanco como la nieve en invierno. Antiguamente, en esta época se le consideraba un símbolo de pureza y era muy apreciado. En tu zoológico, cambia el color de su pelaje a lo largo del año y demuestra lo bien que puede funcionar el camuflaje.'),
       (93052, 417, 'nl', 'Katta', 'De katta is een lemuur uit Madagaskar en staat vooral bekend om zijn gestreepte staart. Hij leeft in groepen en geniet graag van zonnebadjes met uitgestrekte armen. In jouw dierentuin springt hij speels van tak naar tak en zet hij samen met zijn groep een waar lemuurtheater op.'),
       (93053, 417, 'fr', 'Katta', 'Le katta est un lémurien originaire de Madagascar, surtout connu pour sa queue rayée. Il vit en groupe et aime prendre des bains de soleil, les bras écartés. Dans ton zoo, il sautille joyeusement de branche en branche et, avec son groupe, met en scène un véritable spectacle de lémuriens.'),
       (93054, 417, 'es', 'Katta', 'El katta es un lémur de Madagascar, conocido sobre todo por su cola anillada. Vive en grupos y le encanta tomar el sol con los brazos extendidos. En tu zoológico, salta juguetonamente de rama en rama y, junto con su grupo, monta un auténtico espectáculo de lémures.'),
       (93055, 418, 'nl', 'Kodiakbeer', 'De Kodiakbeer is een van de grootste bruine beren ter wereld en leeft op de Kodiak-eilanden in Alaska. Hij voedt zich met vis, bessen en andere dingen die de natuur te bieden heeft. In jouw dierentuin maakt hij indruk met zijn imposante postuur en geniet hij vooral van waterbassins en voerspelletjes.'),
       (93056, 418, 'fr', 'ours de Kodiak', 'L''ours de Kodiak est l''un des plus grands ours bruns du monde et vit sur les îles Kodiak, en Alaska. Il se nourrit de poissons, de baies et de tout ce que la nature lui offre. Dans ton zoo, il impressionne par sa stature imposante et apprécie tout particulièrement les bassins et les jeux de nourriture.'),
       (93057, 418, 'es', 'Oso de Kodiak', 'El oso Kodiak es uno de los osos pardos más grandes del mundo y vive en las islas Kodiak, en Alaska. Se alimenta de peces, bayas y otros alimentos que le ofrece la naturaleza. En tu zoológico impresiona por su imponente complexión y disfruta especialmente de las piscinas y los juegos de alimentación.'),
       (93058, 419, 'nl', 'Luipaard', 'De luipaard is een behendige jager die graag bomen gebruikt als rustplaats en uitkijkpost. Zijn gevlekte vacht vormt een perfecte camouflage in het schaduwspel van het bos. In jouw dierentuin ligt hij vaak ontspannen op hoge platforms en houdt hij alles vanuit een veilige hoogte in de gaten.'),
       (93059, 419, 'fr', 'Léopard', 'Le léopard est un chasseur habile qui aime utiliser les arbres comme lieu de repos et comme poste d''observation. Son pelage tacheté lui offre un camouflage parfait dans le jeu d''ombres et de lumières de la forêt. Dans ton zoo, il est souvent allongé, détendu, sur de hautes plateformes, d''où il observe tout depuis une hauteur sûre.'),
       (93060, 419, 'es', 'Leopardo', 'El leopardo es un hábil cazador al que le gusta utilizar los árboles como lugar de descanso y mirador. Su pelaje manchado le proporciona un camuflaje perfecto entre las sombras del bosque. En tu zoológico suele tumbarse relajado en plataformas elevadas y observar todo desde una altura segura.'),
       (93061, 420, 'nl', 'Luchs', 'De lynx is de grootste Europese wilde kat en goed te herkennen aan zijn puntige oren. Het is een geruisloze jager die meestal in de schemering op pad is. In jouw dierentuin heeft hij rustplekken nodig en beloont hij geduldige bezoekers met een stille verschijning.'),
       (93062, 420, 'fr', 'lynx', 'Le lynx est le plus grand félin sauvage d''Europe et se reconnaît facilement à ses oreilles en forme de pinceaux. C''est un chasseur silencieux qui chasse principalement au crépuscule. Dans ton zoo, il a besoin d''espaces où se retirer et récompense les visiteurs patients par une apparition discrète.'),
       (93063, 420, 'es', 'Lince', 'El lince es el felino silvestre más grande de Europa y se reconoce fácilmente por sus orejas en forma de pincel. Es un cazador silencioso que suele salir al atardecer. En tu zoo necesita espacios donde refugiarse y recompensa a los visitantes pacientes con una aparición discreta.'),
       (93064, 421, 'nl', 'Manul', 'De manul, ook wel Pallaskat genoemd, heeft een bijzonder dichte, pluizige vacht en een grimmige blik. Hij leeft in de schrale steppen en berggebieden van Azië en kan goed tegen extreme temperaturen. In jouw dierentuin lijkt hij op een kleine, heel pluizige wilde kat met een sterk karakter.'),
       (93065, 421, 'fr', 'Manul', 'Le manul, également appelé « chat de Pallas », possède un pelage particulièrement épais et duveteux, ainsi qu''un visage farouche. Il vit dans les steppes arides et les montagnes d''Asie et s''adapte aux températures extrêmes. Dans ton zoo, il ressemble à un petit chat sauvage très duveteux doté d''un fort caractère.'),
       (93066, 421, 'es', 'Manul', 'El manul, también conocido como gato de Pallas, tiene un pelaje especialmente denso y mullido y un rostro feroz. Vive en las estepas áridas y las montañas de Asia y se adapta a temperaturas extremas. En tu zoológico parece un pequeño gato montés muy peludo con mucho carácter.'),
       (93067, 423, 'nl', 'Ozelot', 'De ocelot is een middelgrote wilde kat met een prachtig gevlekte vacht. Hij leeft in de bossen van Amerika en is een behendige klimmer en jager. In jouw dierentuin slentert hij elegant door zijn verblijf en laat hij steeds weer zijn katachtige gratie zien.'),
       (93068, 423, 'fr', 'Ocelot', 'L''ocelot est un félin sauvage de taille moyenne au pelage magnifiquement tacheté. Il vit dans les forêts d''Amérique et est un grimpeur et un chasseur habile. Dans ton zoo, il se promène avec élégance dans son enclos et ne cesse de montrer sa grâce féline.'),
       (93069, 423, 'es', 'Ocelote', 'El ocelote es un felino salvaje de tamaño mediano con un pelaje moteado de gran belleza. Vive en los bosques de América y es un hábil trepador y cazador. En tu zoológico, se pasea con elegancia por su recinto y no deja de mostrar su gracia felina.'),
       (93070, 425, 'nl', 'Puma', 'De poema, ook wel bergrijder genoemd, leeft in allerlei habitats, van het regenwoud tot in het hooggebergte. Het is een flexibele solitair en een krachtige sprinter. In jouw dierentuin beweegt hij zich soepel door het verblijf en laat hij zijn indrukwekkende atletische vermogen zien.'),
       (93071, 425, 'fr', 'Puma', 'Le puma, également appelé « lion des montagnes », vit dans de nombreux habitats, de la forêt tropicale à la haute montagne. C''est un animal solitaire très adaptable et un sprinter puissant. Dans ton zoo, il se déplace avec agilité dans son enclos et fait preuve d''une impressionnante agilité.'),
       (93072, 425, 'es', 'Puma', 'El puma, también conocido como «león de montaña», habita en numerosos hábitats, desde la selva tropical hasta las altas montañas. Es un animal solitario y adaptable, además de un potente velocista. En tu zoológico, se mueve con agilidad por el recinto y hace gala de su impresionante capacidad atlética.'),
       (93073, 426, 'nl', 'Reuzen-turoko', 'De reuzen-turako is een kleurrijke Afrikaanse vogel met een krachtig lichaam en een luide roep. Zijn groene en blauwe verenkleed schittert in het zonlicht. In jouw dierentuin springt hij behendig van tak naar tak en laat hij zijn kenmerkende roep horen.'),
       (93074, 426, 'fr', 'Géant de Turako', 'Le turaco géant est un oiseau africain aux couleurs vives, au corps robuste et au cri puissant. Son plumage vert et bleu brille au soleil. Dans ton zoo, il bondit agilement de branche en branche et fait résonner ses cris caractéristiques.'),
       (93075, 426, 'es', 'Turan gigante', 'El turaco gigante es un colorido pájaro africano de cuerpo robusto y canto estridente. Su plumaje verde y azul brilla bajo la luz del sol. En tu zoológico, salta ágilmente de rama en rama y entona sus característicos cantos.'),
       (93076, 427, 'nl', 'Rothund', 'De roodhond is een sociale wilde hond uit Azië die in roedels jaagt. Hij is gemakkelijk te herkennen aan zijn roodbruine vacht en zijn puntige oren. In jouw dierentuin laat hij zien hoe goed hij in een roedel kan samenwerken en is hij voortdurend in beweging.'),
       (93077, 427, 'fr', 'Chien roux', 'Le chien roux est un chien sauvage sociable originaire d''Asie qui chasse en meute. Son pelage roux et ses oreilles pointues le rendent facilement reconnaissable. Dans ton zoo, il fait preuve d''un excellent esprit d''équipe au sein de la meute et est constamment en mouvement.'),
       (93078, 427, 'es', 'Perro rojo', 'El perro rojo es un perro salvaje sociable originario de Asia que caza en manada. Su pelaje de color rojo óxido y sus orejas puntiagudas lo hacen fácilmente reconocible. En tu zoológico demuestra su capacidad para trabajar en equipo dentro de la manada y no para de moverse.'),
       (93079, 428, 'nl', 'Walliser zwartneusschaap', 'Het Walliser zwartneusschaap valt vooral op door zijn zwarte gezichtsmarkering en zijn witte, krullende vacht. Het ras komt oorspronkelijk uit de Zwitserse Alpen en staat bekend als zeer robuust. In jouw dierentuin betovert het de bezoekers met zijn vriendelijke blik en zijn pluizige uiterlijk.'),
       (93080, 428, 'fr', 'Mouton à nez noir du Valais', 'Le mouton à nez noir du Valais se distingue particulièrement par ses marques noires sur le museau et sa toison blanche et bouclée. Originaire des Alpes suisses, il est réputé pour sa grande robustesse. Dans ton zoo, il enchante les visiteurs par son regard amical et son aspect duveteux.'),
       (93081, 428, 'es', 'Oveja de nariz negra del Valais', 'La oveja de nariz negra del Valais llama especialmente la atención por sus marcas negras en la cara y su pelaje blanco y rizado. Es originaria de los Alpes suizos y se considera una raza muy resistente. En tu zoo, encanta a los visitantes con su mirada amable y su aspecto mullido.'),
       (93082, 429, 'nl', 'Wapiti', 'De wapiti is een Noord-Amerikaans hert met een indrukwekkend gewei. Tijdens de bronsttijd klinkt zijn kenmerkende, heldere roep ver door de bossen. In jouw dierentuin maakt hij indruk met zijn omvang en zijn majestueuze uitstraling.'),
       (93083, 429, 'fr', 'Wapiti', 'Le wapiti est un cerf d''Amérique du Nord doté d''un panache impressionnant. À la période du rut, son cri caractéristique et aigu résonne au loin dans les forêts. Dans ton zoo, il impressionne par sa taille et son allure majestueuse.'),
       (93084, 429, 'es', 'Wapiti', 'El wapití es un ciervo norteamericano con una cornamenta impresionante. Durante la época de celo, su característico y agudo bramido resuena por todo el bosque. En tu zoológico, impresiona por su tamaño y su porte majestuoso.'),
       (93085, 430, 'nl', 'Witkopzeearend', 'De Amerikaanse zeearend is het nationale symbool van de VS en een machtige visjager. Met zijn witte kop en staart steekt hij duidelijk af tegen zijn donkere lichaam. In jouw dierentuin trekt hij met zijn vluchten en zijn scherpe blik alle aandacht naar zich toe.'),
       (93086, 430, 'fr', 'Pygargue à tête blanche', 'Le pygargue à tête blanche est l''emblème des États-Unis et un redoutable chasseur de poissons. Avec sa tête et sa queue blanches, il se détache nettement de son corps sombre. Dans ton zoo, il attire tous les regards par ses vols et son regard perçant.'),
       (93087, 430, 'es', 'Águila calva', 'El águila calva es el animal heráldico de EE. UU. y una poderosa cazadora de peces. Con su cabeza y su cola blancas, destaca claramente sobre su cuerpo oscuro. En tu zoológico, acapara toda la atención con sus vuelos y su mirada penetrante.'),
       (93088, 431, 'nl', 'Wolf', 'De wolf is een zeer sociaal roedeldier met een sterk jachtinstinct. Hij communiceert via geluiden, lichaamstaal en geuren. In jouw dierentuin laat de roedel op indrukwekkende wijze zien hoe belangrijk samenhorigheid in het dierenrijk kan zijn.'),
       (93089, 431, 'fr', 'Loup', 'Le loup est un animal très sociable qui vit en meute et possède un instinct de chasse très développé. Il communique par des cris, le langage corporel et les odeurs. Dans ton zoo, la meute illustre de manière impressionnante à quel point la cohésion peut être importante dans le règne animal.'),
       (93090, 431, 'es', 'Lobo', 'El lobo es un animal muy sociable que vive en manadas y tiene un marcado instinto cazador. Se comunica mediante sonidos, lenguaje corporal y olores. En tu zoológico, la manada demuestra de forma impresionante lo importante que puede ser la cohesión en el reino animal.'),
       (93091, 501, 'nl', 'Afrikaanse civetkat', 'De Afrikaanse civetkat is een nachtdier met een kenmerkende geur. Vroeger werden haar geurstoffen zelfs gebruikt bij de productie van parfum. In jouw dierentuin sluipt ze geruisloos door de nachtverblijven en houdt ze zich meestal in het halfduister op.'),
       (93092, 501, 'fr', 'Cibette d''Afrique', 'La civette africaine est un prédateur nocturne au parfum particulier. Autrefois, ses sécrétions odorantes étaient même utilisées dans la fabrication de parfums. Dans ton zoo, elle se déplace silencieusement dans les enclos nocturnes et reste généralement dans la pénombre.'),
       (93093, 501, 'es', 'Cibeta africana', 'La civeta africana es un depredador nocturno con un olor característico. Antiguamente, sus secreciones incluso se utilizaban en la fabricación de perfumes. En tu zoológico, deambula silenciosamente por las zonas nocturnas y suele mantenerse en la penumbra.'),
       (93094, 502, 'nl', 'Afrikaanse olifant', 'De Afrikaanse olifant is het grootste landzoogdier ter wereld. Zijn enorme oren en indrukwekkende slagtanden maken hem onmiskenbaar. In jouw dierentuin is hij de vriendelijke reus die met zijn slurf speelt, een bad neemt en een blijvende indruk achterlaat op de bezoekers.'),
       (93095, 502, 'fr', 'Éléphant d''Afrique', 'L''éléphant d''Afrique est le plus grand mammifère terrestre du monde. Ses oreilles gigantesques et ses défenses imposantes le rendent unique. Dans ton zoo, c''est un géant au caractère doux qui joue avec sa trompe, se baigne et laisse une impression inoubliable aux visiteurs.'),
       (93096, 502, 'es', 'Elefante africano', 'El elefante africano es el mamífero terrestre más grande del mundo. Sus enormes orejas y sus imponentes colmillos lo hacen inconfundible. En tu zoológico es el gigante bondadoso que juega con la trompa, se baña y deja a los visitantes profundamente impresionados.'),
       (93097, 503, 'nl', 'Afrikaanse struisvogel', 'De Afrikaanse struisvogel is de grootste levende vogel en een snelle loper. Hoewel hij niet kan vliegen, haalt hij indrukwekkende snelheden als hij wegvlucht. In jouw dierentuin rent hij graag door het verblijf en kijkt hij nieuwsgierig over het hek.'),
       (93098, 503, 'fr', 'Autruche africaine', 'L''autruche d''Afrique est le plus grand oiseau vivant et un coureur rapide. Bien qu''elle ne puisse pas voler, elle atteint des vitesses impressionnantes lorsqu''elle s''enfuit. Dans ton zoo, elle aime courir à travers l''enclos et jeter un œil curieux par-dessus la clôture.'),
       (93099, 503, 'es', 'Avestruz africano', 'El avestruz africano es el ave más grande que existe y corre muy rápido. Aunque no puede volar, alcanza velocidades impresionantes cuando huye. En tu zoológico le encanta correr por el recinto y asomarse con curiosidad por encima de la valla.'),
       (93100, 504, 'nl', 'Afrikaanse witruggier', 'De Afrikaanse witruggier is een aaseter die een belangrijke rol speelt in het ecosysteem. Hij houdt de savanne schoon door kadavers snel op te ruimen. In jouw dierentuin laat hij op indrukwekkende wijze zien dat ook minder populaire dieren echte helpers van het milieu zijn.'),
       (93101, 504, 'fr', 'Vautour à dos blanc d''Afrique', 'Le vautour à dos blanc d''Afrique est un nécrophage qui joue un rôle important dans l''écosystème. Il contribue à la propreté de la savane en éliminant rapidement les cadavres. Dans ton zoo, il démontre de manière impressionnante que même les animaux les moins appréciés sont de véritables protecteurs de l''environnement.'),
       (93102, 504, 'es', 'Buitre de lomo blanco africano', 'El buitre africano de lomo blanco es un carroñero que desempeña un papel importante en el ecosistema. Mantiene limpia la sabana al eliminar rápidamente los cadáveres. En tu zoológico demuestra de forma impresionante que incluso los animales menos populares son auténticos defensores del medio ambiente.'),
       (93103, 505, 'nl', 'Afrikaanse wilde hond', 'De Afrikaanse wilde hond heeft nog verschillende andere namen, waaronder “Painted Hunting Dog” en “Cape Hunting Dog”. Ze komen vooral voor in Oost- en Zuid-Afrika. Afrikaanse wilde honden leven in hechte sociale groepen van twee tot 27 individuen. Hun korte vacht bestaat uit gele, grijze, witte en zwarte vlekken. Geen twee honden hebben dezelfde tekeningen en kleurstellingen, waardoor natuurbeschermers de individuen gemakkelijk kunnen identificeren. \\n\\nAfrikaanse wilde honden zijn sterk gespecialiseerd in een vleesetend dieet. Ze jagen op gazellen en andere antilopen, wrattenzwijnen, gnoes en hun kalveren, struisvogels en kalveren van Afrikaanse buffels. \\n\\nDe Afrikaanse wilde hond (Lycaon pictus) is ernstig bedreigd en staat op de Rode Lijst van de IUCN vermeld als „Bedreigd” als gevolg van illegale jacht door mensen.'),
       (93104, 505, 'fr', 'Chien sauvage d''Afrique', 'Le chien sauvage d''Afrique porte plusieurs autres noms, notamment « chien de chasse tacheté » et « chien de chasse du Cap ». On le trouve principalement en Afrique orientale et australe. Les chiens sauvages d''Afrique vivent en groupes sociaux très soudés comptant entre deux et 27 individus. Leur pelage court présente des taches jaunes, grises, blanches et noires. Il n’y a pas deux chiens présentant les mêmes marques et les mêmes colorations, ce qui permet aux défenseurs de l’environnement d’identifier facilement chaque individu. \\n\\nLes chiens sauvages d’Afrique sont parfaitement adaptés à un régime carnivore. Ils chassent les gazelles et autres antilopes, les phacochères, les gnous et leurs petits, les autruches et les petits de buffles d’Afrique. \\n\\nLe chien sauvage d’Afrique (Lycaon pictus) est gravement menacé et figure sur la Liste rouge de l’UICN dans la catégorie « En danger » en raison de la prédation illégale par l’homme.'),
       (93105, 505, 'es', 'Perro salvaje africano', 'El perro salvaje africano recibe otros nombres, entre ellos «perro de caza pintado» y «perro de caza del Cabo». Se encuentra principalmente en el este y el sur de África. Los perros salvajes africanos viven en grupos sociales muy unidos, de entre dos y 27 individuos. Su pelaje corto presenta manchas amarillas, grises, blancas y negras. No hay dos ejemplares con las mismas marcas ni la misma coloración, lo que facilita a los conservacionistas la identificación de cada individuo. \\n\\nLos perros salvajes africanos están altamente especializados para una dieta carnívora. Cazan gacelas y otros antílopes, jabalíes africanos, ñus y sus crías, avestruces y crías de búfalo africano. \\n\\nEl perro salvaje africano (Lycaon pictus) se encuentra en grave peligro de extinción y figura como «En peligro» en la Lista Roja de la UICN debido a la caza ilegal por parte del ser humano.'),
       (93106, 506, 'nl', 'Breedbekneushoorn', 'De brede-bekneushoorn heeft een brede, vierkante bek die ideaal is om te grazen. Hij leeft in Afrika en brengt veel tijd door met eten en rusten. In jouw dierentuin is het een indrukwekkende reus, die er echter meestal verrassend rustig uitziet.'),
       (93107, 506, 'fr', 'Rhinocéros à bouche large', 'Le rhinocéros blanc a une bouche large et carrée, idéale pour brouter. Il vit en Afrique et passe beaucoup de temps à manger et à se reposer. Dans ton zoo, c''est un géant impressionnant qui semble pourtant souvent étonnamment calme.'),
       (93108, 506, 'es', 'Rinoceronte de boca ancha', 'El rinoceronte de boca ancha tiene un hocico ancho y cuadrado, ideal para pastar. Vive en África y pasa gran parte del tiempo comiendo y descansando. En tu zoológico es un gigante impresionante que, sin embargo, suele dar una impresión de serenidad sorprendente.'),
       (93109, 508, 'nl', 'Dromedaris', 'De dromedaris is een woestijndier met slechts één bult, die dient als vetreserve. Hij is perfect aangepast aan hitte en droogte en kan lange tijd zonder water. In jouw dierentuin slentert hij rustig door het zandverblijf en ziet hij er altijd een beetje ontspannen en slaperig uit.'),
       (93110, 508, 'fr', 'dromadaire', 'Le dromadaire est un animal du désert doté d’une seule bosse, qui lui sert de réserve de graisse. Il est parfaitement adapté à la chaleur et à la sécheresse et peut se passer d’eau pendant longtemps. Dans ton zoo, il se promène tranquillement dans son enclos de sable et semble toujours un peu détendu et endormi.'),
       (93111, 508, 'es', 'dromedario', 'El dromedario es un animal del desierto con una sola joroba, que le sirve para almacenar grasa. Está perfectamente adaptado al calor y a la sequía, y puede pasar mucho tiempo sin beber agua. En tu zoológico, deambula tranquilamente por el recinto de arena y siempre parece un poco relajado y adormilado.'),
       (93112, 509, 'nl', 'Aardvarken', 'Het aardvarken is een nachtactieve insecteneter met een lange snuit en krachtige graafklauwen. Het is dol op termietenheuvels en mierenhopen. In jouw dierentuin graaft het ijverig in de grond en is het een stille ster van de nachtelijke verblijven.'),
       (93113, 509, 'fr', 'porc-taupe', 'Le phalanger est un insectivore nocturne doté d''une longue trompe et de puissantes griffes pour creuser. Il adore les termitières et les fourmilières. Dans ton zoo, il creuse sans relâche dans le sol et est la star secrète des enclos nocturnes.'),
       (93114, 509, 'es', 'cerdito de tierra', 'El cerdito de tierra es un insectívoro nocturno con una larga trompa y unas poderosas garras para excavar. Le encantan los termiteros y los hormigueros. En tu zoológico, excava sin descanso en el suelo y es la estrella secreta de las zonas nocturnas.'),
       (93115, 510, 'nl', 'meerkatten', 'Het stokstaartje is een kleine wachter van de savanne, die graag rechtop staat en de omgeving in de gaten houdt. Het leeft in groepen en verdeelt de taken bij het zoeken naar voedsel en het houden van de wacht. In jouw dierentuin zijn de stokstaartjes met hun drukke bewegingen en nieuwsgierige blikken echte publiekslievelingen.'),
       (93116, 510, 'fr', 'suricates', 'Le suricate est un petit sentinelle de la savane qui aime se tenir debout pour guetter. Il vit en groupe et se répartit les tâches entre la recherche de nourriture et la surveillance. Dans ton zoo, les suricates, avec leurs mouvements agités et leurs regards curieux, sont de véritables chouchous du public.'),
       (93117, 510, 'es', 'suricata', 'El suricata es un pequeño centinela de la sabana al que le gusta mantenerse erguido y estar atento. Vive en grupos y se reparten las tareas de búsqueda de alimento y vigilancia. En tu zoológico, las suricatas, con sus movimientos inquietos y sus miradas curiosas, son auténticas estrellas entre el público.'),
       (93118, 511, 'nl', 'Fennek', 'De fennec is een woestijnvos met enorme oren, die hem helpen om af te koelen. Hij is nachtdier en zeer goed aangepast aan het leven in droge gebieden. In jouw dierentuin ziet hij er met zijn grote oorbellen bijzonder schattig en mysterieus uit.'),
       (93119, 511, 'fr', 'Fennec', 'Le fennec est un renard du désert doté d''oreilles immenses qui l''aident à se rafraîchir. C''est un animal nocturne, parfaitement adapté à la vie dans les régions arides. Dans ton zoo, avec ses grandes boucles d''oreilles, il a l''air particulièrement mignon et mystérieux.'),
       (93120, 511, 'es', 'Fennek', 'El fennec es un zorro del desierto con unas orejas enormes que le ayudan a refrescarse. Es nocturno y está muy adaptado a la vida en regiones áridas. En tu zoológico, con sus grandes adornos en las orejas, resulta especialmente adorable y misterioso.'),
       (93121, 512, 'nl', 'Nijlpaard', 'Het nijlpaard brengt het grootste deel van de dag in het water door en komt vooral ’s nachts aan land om te grazen. Ondanks zijn rustige uiterlijk kan het erg snel en krachtig zijn. In jouw dierentuin borrelt het in het bassin, gaapt het indrukwekkend wijd en spettert het graag een beetje.'),
       (93122, 512, 'fr', 'hippopotame', 'L''hippopotame passe la majeure partie de la journée dans l''eau et ne sort à terre que la nuit pour brouter. Malgré son air tranquille, il peut se montrer très rapide et puissant. Dans ton zoo, il barbote dans son bassin, bâille de manière impressionnante et aime bien éclabousser un peu.'),
       (93123, 512, 'es', 'hipopótamo', 'El hipopótamo pasa la mayor parte del día en el agua y sale a pastar en tierra sobre todo por la noche. A pesar de su aspecto tranquilo, puede ser muy rápido y fuerte. En tu zoológico, burbujea en el estanque, bosteza de forma impresionante y le gusta salpicar un poco.'),
       (93124, 513, 'nl', 'giraffengazelle', 'De giraffengazelle, ook wel gerenuk genoemd, heeft een bijzonder lange nek en kan zich zelfs rechtop zetten om te eten. Ze leeft in droge gebieden van Afrika en heeft maar weinig water nodig. In jouw dierentuin staat ze vaak op haar achterpoten om bij bladeren te komen, wat voor verbaasde blikken zorgt.'),
       (93125, 513, 'fr', 'gazelle girafe', 'La gazelle girafe, également appelée gérénuk, possède un cou particulièrement long et peut même se dresser sur ses pattes arrière pour se nourrir. Elle vit dans les régions arides d''Afrique et se contente de très peu d''eau. Dans ton zoo, elle se dresse souvent sur ses pattes arrière pour atteindre les feuilles, ce qui suscite l''émerveillement des visiteurs.'),
       (93126, 513, 'es', 'gacela jirafa', 'La gacela jirafa, también conocida como gerenuc, tiene un cuello especialmente largo y es capaz incluso de erguirse para comer. Vive en zonas áridas de África y se conforma con muy poca agua. En tu zoológico suele ponerse de pie sobre las patas traseras para alcanzar las hojas, lo que provoca miradas de asombro.'),
       (93127, 514, 'nl', 'Grote miereneter', 'De grote miereneter is onmiskenbaar te herkennen aan zijn lange snuit en zijn pluimachtige staart. Zijn favoriete voedsel bestaat uit mieren en termieten, die hij met zijn kleverige tong oppakt. In jouw dierentuin stapt hij rustig door het verblijf en lijkt hij een vriendelijke, ietwat ongewone bezoeker.'),
       (93128, 514, 'fr', 'Grand fourmilier', 'Avec son long museau et son panache de poils touffu à l''extrémité de la queue, le grand fourmilier est facilement reconnaissable. Il se nourrit principalement de fourmis et de termites, qu''il attrape à l''aide de sa langue collante. Dans ton zoo, il se promène tranquillement dans son enclos et donne l''impression d''être un visiteur sympathique, bien qu''un peu insolite.'),
       (93129, 514, 'es', 'Osante', 'El oso hormiguero grande es inconfundible por su largo hocico y su cola tupida. Sus alimentos favoritos son las hormigas y las termitas, que captura con su lengua pegajosa. En tu zoológico, se pasea tranquilamente por el recinto y parece un visitante simpático, aunque un poco insólito.'),
       (93130, 515, 'nl', 'Honingdak', 'De honingdas, ook wel ratel genoemd, staat bekend als een zeer onverschrokken en strijdlustig dier. Hij voedt zich met honing, insecten en zelfs giftige slangen. In jouw dierentuin laat hij zijn sterke karakter zien en is hij een kleine, maar indrukwekkende roofdier.'),
       (93131, 515, 'fr', 'Toit de miel', 'Le blaireau mellifère, également appelé « ratel », est considéré comme très intrépide et combatif. Il se nourrit de miel, d''insectes et même de serpents venimeux. Dans ton zoo, il fait preuve d''un caractère bien trempé et s''impose comme un petit prédateur impressionnant.'),
       (93132, 515, 'es', 'Techo de miel', 'El tejón melero, también conocido como «ratel», tiene fama de ser muy intrépido y de saber defenderse bien. Se alimenta de miel, insectos e incluso serpientes venenosas. En tu zoológico demuestra su fuerte carácter y es un depredador pequeño, pero impresionante.'),
       (93133, 516, 'nl', 'Impala', 'De impala is een elegante Afrikaanse antilope, bekend om zijn grote sprongen. Hij leeft in kuddes en gebruikt zijn snelheid om aan roofdieren te ontsnappen. In jouw dierentuin springt hij lichtvoetig door het verblijf en lijkt hij altijd waakzaam.'),
       (93134, 516, 'fr', 'Impala', 'L''impala est une élégante antilope d''Afrique, connue pour ses grands bonds. Vivant en troupeaux, il met à profit sa rapidité pour échapper à ses prédateurs. Dans ton zoo, il bondit avec agilité à travers son enclos et semble toujours sur ses gardes.'),
       (93135, 516, 'es', 'Impala', 'El impala es un elegante antílope africano, conocido por sus amplios saltos. Se desplaza en manadas y aprovecha su velocidad para escapar de los depredadores. En tu zoológico, salta con agilidad por el recinto y siempre parece estar alerta.'),
       (93136, 517, 'nl', 'Kaapbuffel', 'De Kaffernbuffel is een imposant Afrikaans rund met enorme hoorns. Hij staat bekend als onvoorspelbaar en wordt door veel dieren gerespecteerd. In jouw dierentuin straalt hij kracht uit terwijl hij rustig gras eet of in de modder baadt.'),
       (93137, 517, 'fr', 'buffle du Cap', 'Le buffle cafre est un imposant bovidé africain doté de cornes gigantesques. Considéré comme imprévisible, il est respecté par de nombreux animaux. Dans ton zoo, il dégage une grande force tandis qu’il broute tranquillement de l’herbe ou se vautre dans la boue.'),
       (93138, 517, 'es', 'búfalo cafre', 'El búfalo cafre es un imponente bovino africano con cuernos enormes. Se le considera impredecible y muchos animales le respetan. En tu zoológico irradia fuerza mientras come hierba tranquilamente o se revuelca en el barro.'),
       (93139, 518, 'nl', 'Kaapse grote koedoe', 'De Kaapse grote kudu is een indrukwekkende antilope met meterslange, spiraalvormige hoorns. Zijn gestreepte flanken geven hem een extra elegante uitstraling. In jouw dierentuin trekt hij met zijn koninklijke uitstraling meteen alle aandacht.'),
       (93140, 518, 'fr', 'Grand koudou du Cap', 'Le grand koudou du Cap est une antilope impressionnante, dotée de cornes spiralées mesurant plusieurs mètres de long. Ses flancs rayés lui confèrent une élégance supplémentaire. Dans ton zoo, il attirera immédiatement tous les regards grâce à son allure royale.'),
       (93141, 518, 'es', 'Cudú grande del Cabo', 'El gran kudú del Cabo es un antílope impresionante con cuernos de un metro de largo y en forma de espiral. Su costado rayado le aporta un toque adicional de elegancia. En tu zoológico, con su aspecto majestuoso, acaparará todas las miradas de inmediato.'),
       (93142, 519, 'nl', 'lepelhond', 'De lepelhond is een kleine wilde hond met grote oren die aan lepels doen denken. Hij voedt zich voornamelijk met insecten en is nachtdier. In jouw dierentuin luistert hij met zijn reusachtige oorantennes in alle richtingen en ziet hij er daarbij bijzonder schattig uit.'),
       (93143, 519, 'fr', 'Chien-cuillère', 'Le chien-cuillère est un petit chien sauvage doté de grandes oreilles qui rappellent des cuillères. Il se nourrit principalement d''insectes et est nocturne. Dans ton zoo, il tend l''oreille dans toutes les directions grâce à ses antennes géantes, ce qui le rend particulièrement mignon.'),
       (93144, 519, 'es', 'Perro cuchara', 'El perro cuchara es un pequeño perro salvaje con orejas grandes que recuerdan a unas cucharas. Se alimenta principalmente de insectos y es nocturno. En tu zoológico, aguzando el oído con sus enormes orejas a modo de antenas, escucha en todas direcciones, lo que le da un aspecto especialmente gracioso.'),
       (93145, 520, 'nl', 'Leeuw', 'De leeuw draagt niet voor niets de titel ‘koning der dieren’. Hij leeft in roedels, rust veel, maar is ongelooflijk krachtig tijdens de jacht. In jouw dierentuin liggen leeuwen graag in de zon, brullen indrukwekkend en laten hun majestueuze aanwezigheid zien.'),
       (93146, 520, 'fr', 'Lion', 'Ce n''est pas pour rien que le lion porte le titre de « roi des animaux ». Vivant en meute, il se repose beaucoup, mais fait preuve d''une force incroyable lorsqu''il chasse. Dans ton zoo, les lions aiment se prélasser au soleil, rugir de manière impressionnante et afficher leur présence majestueuse.'),
       (93147, 520, 'es', 'León', 'No en vano el león lleva el título de «rey de los animales». Vive en manadas, descansa mucho, pero es increíblemente poderoso cuando caza. En tu zoológico, a los leones les encanta tumbarse al sol, rugir de forma impresionante y mostrar su majestuosa presencia.'),
       (93148, 521, 'nl', 'Netgiraffe', 'De netgiraf heeft een vlekkenpatroon met bijzonder fijne mazen, dat doet denken aan een net. Ze leeft in Afrika en gebruikt haar lange nek om hooggelegen bladeren te bereiken. In jouw dierentuin torent ze boven alle andere dieren uit en geniet ze van verse takjes.'),
       (93149, 521, 'fr', 'Girafe du Net', 'La girafe à mailles possède un motif tacheté aux mailles particulièrement fines, qui rappelle un filet. Elle vit en Afrique et utilise son long cou pour atteindre les feuilles situées en hauteur. Dans ton zoo, elle domine tous les autres animaux et se régale de branches fraîches.'),
       (93150, 521, 'es', 'Jirafa de la red', 'La jirafa reticulada tiene un patrón de manchas de malla muy fina que recuerda a una red. Vive en África y utiliza su largo cuello para alcanzar las hojas que se encuentran en las copas de los árboles. En tu zoológico, sobresale por encima de todos los demás animales y disfruta comiendo ramitas frescas.'),
       (93151, 522, 'nl', 'Reuzenelenantilope', 'De reuzenelenantilope is de grootste antilopensoort ter wereld. Ondanks haar omvang is ze behendig en kan ze indrukwekkende sprongen maken. In jouw dierentuin beweegt ze zich majestueus door het verblijf en maakt ze indruk met haar zachte kracht.'),
       (93152, 522, 'fr', 'Élanantile géante', 'L''éléphant d''Afrique est la plus grande espèce d''antilope au monde. Malgré sa taille, il est agile et capable d''effectuer des bonds impressionnants. Dans ton zoo, il se déplace majestueusement dans son enclos et impressionne par sa force gracieuse.'),
       (93153, 522, 'es', 'Antílope elénico gigante', 'El antílope gigante es la especie de antílope más grande del mundo. A pesar de su tamaño, es ágil y puede dar saltos impresionantes. En tu zoológico, se mueve majestuosamente por el recinto e impresiona con su fuerza apacible.'),
       (93154, 523, 'nl', 'Roodsnaveltoko', 'De roodsnaveltoko is een kleine neushoornvogel met een felrode snavel. Hij is nieuwsgierig en gebruikt zijn snavel behendig bij het eten. In jouw dierentuin huppelt hij van tak naar tak en laat hij zijn opvallende roep horen.'),
       (93155, 523, 'fr', 'Toko à bec rouge', 'Le toco à bec rouge est un petit calao au bec d''un rouge vif. Il est curieux et se sert habilement de son bec pour se nourrir. Dans ton zoo, il sautille de branche en branche et fait entendre ses cris caractéristiques.'),
       (93156, 523, 'es', 'Toco de pico rojo', 'El toco de pico rojo es un pequeño pájaro rinoceronte con un pico de color rojo brillante. Es curioso y utiliza su pico con destreza a la hora de alimentarse. En tu zoológico salta de rama en rama y deja oír sus característicos gritos.'),
       (93157, 524, 'nl', 'Zandkat', 'De zandkat is perfect aangepast aan het leven in de woestijn en heeft een dikke vacht aan haar poten. Daardoor kan ze ook over heet zand lopen. In jouw dierentuin lijkt ze wel een kleine, statige woestijnprinses die graag in het zand op de loer ligt.'),
       (93158, 524, 'fr', 'chat des sables', 'Le chat des sables est parfaitement adapté à la vie dans le désert et possède un pelage épais au niveau des pattes. Cela lui permet de courir même sur le sable brûlant. Dans ton zoo, il ressemble à une petite princesse du désert, élégante, qui aime se cacher dans le sable.'),
       (93159, 524, 'es', 'Gato de las arenas', 'El gato del desierto está perfectamente adaptado a la vida en el desierto y tiene un pelaje denso en las patas. Así puede correr incluso sobre la arena caliente. En tu zoológico parece una pequeña y elegante princesa del desierto a la que le encanta acechar entre la arena.'),
       (93160, 525, 'nl', 'Schabrackenhyena', 'De schabrackhyena heeft een lange, ruige vacht met donkere strepen. Ze is voornamelijk een aaseter, maar eet ook kleinere prooidieren. In jouw dierentuin slentert ze rustig door het verblijf en laat ze zien hoe belangrijk ze is als ‘opruimdienst’ van de natuur.'),
       (93161, 525, 'fr', 'hyène à dos tacheté', 'La hyène tachetée a un pelage long et hirsute, strié de rayures sombres. Elle se nourrit principalement de charognes, mais chasse également de petites proies. Dans ton zoo, elle déambule tranquillement dans son enclos et démontre son talent inestimable en tant que « service de nettoyage » de la nature.'),
       (93162, 525, 'es', 'Hiena de Schabrack', 'La hiena rayada tiene un pelaje largo y hirsuto con rayas oscuras. Se alimenta principalmente de carroña, aunque también caza presas más pequeñas. En tu zoológico, deambula tranquilamente por el recinto y demuestra su importante talento como «servicio de limpieza» de la naturaleza.'),
       (93163, 526, 'nl', 'Boeket uit Somalië', 'De Somalistruis is een ondersoort van de struis met blauwachtige poten en nek. Hij leeft in de droge gebieden van de Hoorn van Afrika. In jouw dierentuin slentert hij door het verblijf en houdt hij met zijn grote ogen alles in de gaten.'),
       (93164, 526, 'fr', 'Bouquet somali', 'L''autruche de Somalie est une sous-espèce d''autruche aux pattes et au cou bleuâtres. Elle vit dans les régions arides de la Corne de l''Afrique. Dans ton zoo, elle se promène dans son enclos et observe tout autour d''elle avec ses grands yeux.'),
       (93165, 526, 'es', 'Ramo de somali', 'El avestruz de Somalia es una subespecie del avestruz que tiene las patas y el cuello azulados. Vive en las zonas áridas del Cuerno de África. En tu zoológico, se pasea por el recinto y lo observa todo con sus grandes ojos.'),
       (93166, 527, 'nl', 'Spitsneusneushoorn', 'De puntneusneushoorn heeft een puntige bovenlip, waarmee hij bladeren kan vastpakken. Hij wordt ernstig bedreigd en staat centraal in tal van beschermingsprojecten. In jouw dierentuin is hij een indrukwekkende ambassadeur voor het behoud van diersoorten.'),
       (93167, 527, 'fr', 'rhinocéros à bec pointu', 'Le rhinocéros noir possède une bouche en forme de bec pointu, située au niveau de la lèvre supérieure, qui lui permet d''attraper les feuilles. Espèce gravement menacée, il fait l''objet de nombreux projets de protection. Dans ton zoo, c''est un ambassadeur impressionnant de la préservation des espèces.'),
       (93168, 527, 'es', 'Rinoceronte de hocico puntiagudo', 'El rinoceronte de hocico puntiagudo tiene un hocico que se estrecha hacia arriba, lo que le ayuda a agarrar las hojas. Es una especie muy amenazada y es el protagonista de numerosos proyectos de conservación. En tu zoológico es un impresionante embajador de la conservación de las especies.'),
       (93169, 528, 'nl', 'Kameel', 'De driebultkameel is een kameel met twee bulten en leeft in koude woestijnen en steppen. Zijn dikke vacht beschermt hem tegen extreme temperaturen. In jouw dierentuin pronkt hij trots met zijn ruige vacht en slentert hij rustig door het verblijf.'),
       (93170, 528, 'fr', 'chameau de Bactriane', 'Le dromadaire est un chameau à deux bosses qui vit dans les déserts et les steppes froids. Son pelage épais le protège des températures extrêmes. Dans ton zoo, il exhibe fièrement son pelage hirsute et se promène tranquillement dans son enclos.'),
       (93171, 528, 'es', 'camello', 'El camello de dos jorobas es un animal que vive en desiertos y estepas fríos. Su espeso pelaje le protege de las temperaturas extremas. En tu zoo, luce con orgullo su pelaje hirsuto y se pasea tranquilamente por el recinto.'),
       (93172, 529, 'nl', 'Gevlekte hyena', 'De gevlekte hyena is een sociale roofdier met een echt gevoel voor humor – zo klinkt haar roep tenminste. Ze is een van de meest succesvolle jagers van de savanne. In jouw dierentuin zorgt ze met haar geluiden en haar temperamentvolle gedrag voor spanning.'),
       (93173, 529, 'fr', 'hyène tachetée', 'La hyène tachetée est un prédateur sociable doté d''un véritable sens de l''humour – du moins, c''est ce que laisse penser son cri. C''est l''une des chasseuses les plus redoutables de la savane. Dans ton zoo, elle crée une ambiance animée grâce à ses cris et à son comportement plein de tempérament.'),
       (93174, 529, 'es', 'hiena moteada', 'La hiena manchada es un depredador social con un auténtico sentido del humor —al menos, eso es lo que parece por su aullido—. Es una de las cazadoras más exitosas de la sabana. En tu zoológico, su voz y su comportamiento enérgico aportan emoción.'),
       (93175, 530, 'nl', 'wrattenzwijn', 'Het wrattenzwijn heeft opvallende huidplooien in het gezicht en indrukwekkende slagtanden. Het leeft in Afrika en is een goede loper met veel karakter. In jouw dierentuin wroet het vrolijk in de grond en haalt het elke modderpoel grondig overhoop.'),
       (93176, 530, 'fr', 'phacochère', 'Le phacochère arbore des protubérances cutanées caractéristiques sur le visage et d''impressionnantes défenses. Il vit en Afrique et est un excellent coureur doté d''un fort caractère. Dans ton zoo, il fouille joyeusement le sol et remue minutieusement chaque mare de boue.'),
       (93177, 530, 'es', 'jabalí verrugoso', 'El jabalí verrugoso tiene unos llamativos pliegues de piel en la cara y unos colmillos impresionantes. Vive en África y es un buen corredor con mucho carácter. En tu zoológico, escarba alegremente el suelo y remueve a fondo cada charco de barro.'),
       (93178, 531, 'nl', 'Witkopuil', 'De witgezichtuil valt op door zijn contrastrijke gezicht en zijn grote ogen. Het is een geruisloze nachtjager die kleine prooidieren verrast. In jouw dierentuin zit ze overdag graag verstopt en ’s nachts verandert ze in een geruisloze jager.'),
       (93179, 531, 'fr', 'Hibou à face blanche', 'La chouette à face blanche se distingue par son visage aux contrastes marqués et ses grands yeux. C''est une chasseuse nocturne silencieuse qui surprend ses petites proies. Dans ton zoo, elle aime rester cachée pendant la journée et se transforme en chasseuse silencieuse la nuit venue.'),
       (93180, 531, 'es', 'Búho de cara blanca', 'El búho de cara blanca destaca por su cara llena de contrastes y sus grandes ojos. Es un cazador nocturno silencioso que sorprende a sus presas pequeñas. En tu zoológico le gusta permanecer escondido durante el día y por la noche se convierte en una cazadora silenciosa.'),
       (93181, 532, 'nl', 'Witstaartmanguste', 'De witstaartmanguste is een kleine roofdiersoort met een lichtgekleurd staartuiteinde. Hij leeft in groepen en is erg actief. In jouw dierentuin rent hij nieuwsgierig door het verblijf en onderzoekt hij alles heel nauwkeurig.'),
       (93182, 532, 'fr', 'Mangouste à queue blanche', 'La mangouste à queue blanche est une petite espèce de prédateur dont l''extrémité de la queue est claire. Elle vit en groupe et est très active. Dans ton zoo, elle se précipite avec curiosité à travers son enclos et examine tout avec beaucoup d''attention.'),
       (93183, 532, 'es', 'mangosta de cola blanca', 'La mangosta de cola blanca es una pequeña especie de depredador con la punta de la cola de color claro. Vive en grupos y es muy activa. En tu zoológico, corre con curiosidad por el recinto y lo examina todo con mucho detenimiento.'),
       (93184, 533, 'nl', 'Wollige gier', 'De wolkopgier heeft, zoals de naam al zegt, een vacht op zijn kop die er wollig uitziet. Hij is een belangrijke aaseter en zorgt voor hygiëne in de natuur. In jouw dierentuin cirkelt hij boven het verblijf en laat hij zien dat ook gieren een indrukwekkende majesteit kunnen uitstralen.'),
       (93185, 533, 'fr', 'Vautour à tête laineuse', 'Comme son nom l''indique, le vautour à tête laineuse possède un plumage sur la tête d''aspect laineux. C''est un charognard essentiel qui contribue à la propreté de la nature. Dans ton zoo, il plane au-dessus de son enclos et montre que même les vautours peuvent dégager une majesté impressionnante.'),
       (93186, 533, 'es', 'buitre de cabeza lanuda', 'El buitre de cabeza lanuda tiene, como su nombre indica, un plumaje en la cabeza de aspecto lanudo. Es un importante carroñero y se encarga de mantener la limpieza en la naturaleza. En tu zoológico sobrevuela el recinto y demuestra que incluso los buitres pueden irradiar una majestuosidad impresionante.'),
       (93187, 534, 'nl', 'Zebramanguste', 'De zebramanguste heeft een gestreepte vacht die een beetje aan een zebra doet denken. Ze leeft in groepen en is voortdurend in beweging. In jouw dierentuin rent ze van schuilplaats naar schuilplaats en verveelt ze zich nauwelijks.'),
       (93188, 534, 'fr', 'mangouste zébrée', 'La mangouste zébrée a un pelage rayé qui rappelle un peu celui d''un zèbre. Elle vit en groupe et est constamment en mouvement. Dans ton zoo, elle court d''un abri à l''autre et ne laisse guère de place à l''ennui.'),
       (93189, 534, 'es', 'mangosta cebra', 'La mangosta cebra tiene un pelaje rayado que recuerda un poco al de una cebra. Vive en grupos y no para quieta ni un momento. En tu zoológico corre de un refugio a otro y no deja que te aburras ni un instante.'),
       (93190, 535, 'nl', 'Reuzenrappenantilope', 'De reuzenantilope is een zeldzame en zeer indrukwekkende antilope met grote, gebogen hoorns. Haar donkere vacht staat in schril contrast met de lichte vlekken. In jouw dierentuin straalt ze waardigheid en kracht uit en is ze een echte trekpleister voor bezoekers.'),
       (93191, 535, 'fr', 'Antilope noire géante', 'L''antilope noire géante est une espèce rare et très impressionnante, dotée de grandes cornes recourbées. Son pelage foncé contraste fortement avec ses marques claires. Dans ton zoo, elle dégage une impression de dignité et de puissance et constitue un véritable atout pour les visiteurs.'),
       (93192, 535, 'es', 'Antílope negro gigante', 'El antílope negro gigante es un antílope poco común y muy impresionante, con cuernos grandes y curvados. Su pelaje oscuro contrasta fuertemente con las manchas claras. En tu zoológico irradia dignidad y fuerza, y es una auténtica atracción para los visitantes.'),
       (93193, 536, 'nl', 'Witstaartgnoe', 'De witstaartgnoe is een gnoesoort met een opvallende lichte staart. Hij leeft in Afrikaanse savannes en trekt vaak in grote kuddes rond. In jouw dierentuin zorgt hij met zijn levendige karakter en af en toe een bokkensprong voor veel dynamiek.'),
       (93194, 536, 'fr', 'Gnou à queue blanche', 'Le gnou à queue blanche est une espèce de gnou qui se distingue par sa queue claire. Il vit dans les savanes africaines et se déplace souvent en grands troupeaux. Dans ton zoo, il apporte beaucoup de dynamisme grâce à son caractère vif et à ses sauts de bouc occasionnels.'),
       (93195, 536, 'es', 'gnu de cola blanca', 'El ñu de cola blanca es una especie de ñu que destaca por su cola de color claro. Vive en las sabanas africanas y suele desplazarse en grandes manadas. En tu zoológico aporta mucho dinamismo con su carácter vivaz y sus ocasionales saltos de cabra.'),
       (93196, 537, 'nl', 'Aziatische ezel', 'De Aziatische ezel leeft in de droge steppen en halfwoestijnen van Azië. Hij is aangepast aan een leven met weinig water en extreme hitte. In jouw dierentuin ziet hij er robuust en waakzaam uit, terwijl hij zijn omgeving aandachtig in de gaten houdt.'),
       (93197, 537, 'fr', 'Âne d''Asie', 'L''âne d''Asie vit dans les steppes arides et les régions semi-désertiques d''Asie. Il est adapté à une vie où l''eau se fait rare et où la chaleur est intense. Dans ton zoo, il semble robuste et vigilant, tandis qu''il observe attentivement son environnement.'),
       (93198, 537, 'es', 'Burro asiático', 'El burro asiático vive en las estepas secas y los entornos semidesérticos de Asia. Se ha adaptado a una vida con poca agua y mucho calor. En tu zoológico se le ve robusto y alerta, mientras observa atentamente lo que le rodea.'),
       (93199, 601, 'nl', 'Banteng', 'De banteng is een wilde rundersoort uit Zuidoost-Azië met elegant gebogen hoorns. Hij leeft in bossen en open landschappen. In jouw dierentuin laat hij zijn krachtige kant zien, maar blijft hij meestal rustig en kalm.'),
       (93200, 601, 'fr', 'Banteng', 'Le banteng est une espèce de bovin sauvage originaire d''Asie du Sud-Est, dotée de cornes aux courbes élégantes. Il vit dans les forêts et les espaces ouverts. Dans ton zoo, il montre son côté puissant, mais reste la plupart du temps calme et serein.'),
       (93201, 601, 'es', 'Banteng', 'El banteng es una especie de bovino salvaje del sudeste asiático con cuernos de formas elegantes. Vive en bosques y paisajes abiertos. En tu zoológico muestra su lado más enérgico, aunque suele mantenerse tranquilo y sereno.'),
       (93202, 602, 'nl', 'baardvarken', 'Het baardzwijn heeft een opvallende „baard“ van lange haren op zijn snuit. Het leeft in de bossen van Zuidoost-Azië en houdt van vochtige leefgebieden. In jouw dierentuin snuffelt het nieuwsgierig rond en wroet het met zijn bebaarde snuit in de grond.'),
       (93203, 602, 'fr', 'cochon à barbe', 'Le phacochère à barbe arbore une « barbe » remarquable, composée de longs poils, sur le museau. Il vit dans les forêts d’Asie du Sud-Est et affectionne les milieux humides. Dans ton zoo, il fouine avec curiosité et creuse le sol avec son museau barbu.'),
       (93204, 602, 'es', 'cerdo barbudo', 'El cerdo barbudo tiene una llamativa «barba» de pelo largo en el hocico. Vive en los bosques del sudeste asiático y le encantan los hábitats húmedos. En tu zoológico, curiosea con curiosidad y hurga en el suelo con su cara barbuda.'),
       (93205, 603, 'nl', 'Berggorilla', 'De berggorilla is een zachtaardige reus die in de nevelwouden van Centraal-Afrika leeft. Hij voedt zich voornamelijk met planten en leeft in familiegroepen. In jouw dierentuin is hij een indrukwekkende ambassadeur voor de bescherming van het regenwoud.'),
       (93206, 603, 'fr', 'Gorille de montagne', 'Le gorille de montagne est un géant au caractère doux qui vit dans les forêts brumeuses d''Afrique centrale. Il se nourrit principalement de végétaux et vit en groupes familiaux. Dans ton zoo, c''est un ambassadeur impressionnant de la protection de la forêt tropicale.'),
       (93207, 603, 'es', 'Gorila de montaña', 'El gorila de montaña es un gigante apacible que vive en los bosques nubosos de África Central. Se alimenta principalmente de plantas y vive en grupos familiares. En tu zoológico es un impresionante embajador de la protección de la selva tropical.'),
       (93208, 604, 'nl', 'Binturong', 'De binturong, ook wel schubkat genoemd, heeft een lange grijpstaart en ruikt naar verluidt naar verse popcorn. Hij klimt graag en is vooral in bomen te vinden. In jouw dierentuin hangt hij ontspannen in de takken en snuift nieuwsgierig de lucht op.'),
       (93209, 604, 'fr', 'Binturong', 'Le binturong, également appelé « chat-tatu », possède une longue queue préhensile et aurait une odeur de pop-corn frais. Il aime grimper et se déplace principalement dans les arbres. Dans ton zoo, il est suspendu, détendu, parmi les branches et renifle l''air avec curiosité.'),
       (93210, 604, 'es', 'Binturong', 'El binturong, también conocido como «gato de los escudos», tiene una larga cola prensil y, según dicen, huele a palomitas recién hechas. Le gusta trepar y se mueve sobre todo por los árboles. En tu zoológico se cuelga relajado de las ramas y olfatea el aire con curiosidad.'),
       (93211, 605, 'nl', 'Blauwogige maki', 'De blauwoogmaki is een lemuur met opvallend blauwe ogen – een echte bijzonderheid in het dierenrijk. Hij komt uit Madagaskar en is ernstig bedreigd. In jouw dierentuin fascineert hij bezoekers met zijn intense blik en zijn levendige klimkunsten.'),
       (93212, 605, 'fr', 'Lemur aux yeux bleus', 'Le maki aux yeux bleus est un lémurien aux yeux d''un bleu saisissant – une véritable particularité dans le règne animal. Originaire de Madagascar, il est gravement menacé. Dans ton zoo, il fascine les visiteurs par son regard intense et ses talents d''escaladeur.'),
       (93213, 605, 'es', 'Lemur de ojos azules', 'El maki de ojos azules es un lémur con unos llamativos ojos azules, algo realmente singular en el reino animal. Es originario de Madagascar y se encuentra en grave peligro de extinción. En tu zoológico, fascina a los visitantes con su intensa mirada y sus ágiles habilidades trepadoras.'),
       (93214, 608, 'nl', 'Brilvleermuis', 'De brilvleermuis is een vleermuis met een brilachtige tekening rond de ogen. Hij voedt zich met fruit en speelt een belangrijke rol bij de bestuiving. In jouw dierentuin hangt hij ondersteboven in de vleermuisafdeling en knabbelt hij aan zoet fruit.'),
       (93215, 608, 'fr', 'chauve-souris à lunettes', 'La chauve-souris à lunettes est une chauve-souris dont les yeux sont entourés d''un motif ressemblant à des lunettes. Elle se nourrit de fruits et joue un rôle important dans la pollinisation. Dans ton zoo, elle est suspendue la tête en bas dans l''enclos des chauves-souris et grignote des fruits sucrés.'),
       (93216, 608, 'es', 'Murciélago de anteojos', 'El murciélago de anteojos es un murciélago con un dibujo alrededor de los ojos que se asemeja a unas gafas. Se alimenta de frutas y desempeña un papel importante en la polinización. En tu zoo, cuelga boca abajo en la zona de los murciélagos y picotea frutas dulces.'),
       (93217, 609, 'nl', 'Luiaard', 'De luiaard staat bekend om zijn trage tempo en zijn ontspannen karakter. Hij hangt het grootste deel van de tijd ondersteboven in bomen en beweegt zich alleen als dat nodig is. In jouw dierentuin laat hij zien dat je af en toe ook heel rustig van het leven mag genieten.'),
       (93218, 609, 'fr', 'paresseux', 'Le paresseux est célèbre pour sa lenteur et son caractère décontracté. Il passe la plupart de son temps la tête en bas dans les arbres et ne bouge que lorsque c''est nécessaire. Dans ton zoo, il montre qu''on a le droit, de temps en temps, de profiter de la vie en prenant son temps.'),
       (93219, 609, 'es', 'Perezoso', 'El perezoso es famoso por su ritmo lento y su carácter tranquilo. Se pasa la mayor parte del tiempo colgado boca abajo de los árboles y solo se mueve cuando es necesario. En tu zoológico, demuestra que a veces también se puede disfrutar de la vida sin prisas.'),
       (93220, 610, 'nl', 'Goudkroonvleermuis', 'De goudkroonvleermuis is een grote, fruitetende vleermuis met een gouden kop. Hij komt oorspronkelijk uit de Filippijnen en is ernstig bedreigd. In jouw dierentuin is hij een belangrijke herinnering aan het belang van de bescherming van tropische bossen.'),
       (93221, 610, 'fr', 'Chauve-souris à couronne dorée', 'La chauve-souris à couronne dorée est une grande chauve-souris frugivore au crâne doré. Originaire des Philippines, elle est gravement menacée. Dans ton zoo, elle constitue un rappel important de la nécessité de protéger les forêts tropicales.'),
       (93222, 610, 'es', 'Murciélago de corona dorada', 'El murciélago de corona dorada es un murciélago frugívoro de gran tamaño con el pelaje de la cabeza de color dorado. Es originario de Filipinas y se encuentra en grave peligro de extinción. En tu zoológico, su presencia es un importante recordatorio de la necesidad de proteger los bosques tropicales.'),
       (93223, 611, 'nl', 'Grote anaconda', 'De grote anaconda is een van de zwaarste slangen ter wereld en leeft in de moerassen van Zuid-Amerika. Het is een behendige sluipjager die in het water op prooien wacht. In jouw dierentuin glijdt ze rustig door het waterbassin en zorgt ze voor een echte junglesfeer.'),
       (93224, 611, 'fr', 'Grand anaconda', 'Le grand anaconda est l''un des serpents les plus lourds au monde et vit dans les marécages d''Amérique du Sud. C''est une chasseuse à l''affût très habile qui attend ses proies dans l''eau. Dans ton zoo, il se déplace tranquillement dans son bassin et crée une véritable ambiance de jungle.'),
       (93225, 611, 'es', 'Anaconda gigante', 'La anaconda gigante es una de las serpientes más pesadas del mundo y vive en los pantanos de Sudamérica. Es una hábil cazadora al acecho que espera a sus presas en el agua. En tu zoológico, se desliza tranquilamente por el estanque y crea un auténtico ambiente de selva.'),
       (93226, 612, 'nl', 'Grote otterspitsmuis', 'De grote otterspitsmuis is een klein, semi-aquatisch zoogdier met een gestroomlijnd lichaam. Hij jaagt in het water op insecten en kleine prooidieren. In jouw dierentuin schiet hij soepel door het water en zorgt hij voor levendige onderwateracties.'),
       (93227, 612, 'fr', 'Grande musaraigne à queue en pointe', 'La grande musaraigne-loutre est un petit mammifère semi-aquatique au corps profilé. Elle chasse les insectes et les petites proies dans l''eau. Dans ton zoo, elle file avec agilité dans l''eau et anime la vie sous-marine.'),
       (93228, 612, 'es', 'Musaraña de punta de nutria grande', 'La musaraña-nutria grande es un pequeño mamífero semiacuático con un cuerpo aerodinámico. Caza insectos y pequeñas presas en el agua. En tu zoológico, se desliza ágilmente por el agua y ofrece un espectáculo submarino lleno de vida.'),
       (93229, 613, 'nl', 'Harpyie', 'De harpij is een krachtige roofvogel uit de regenwouden van Zuid- en Midden-Amerika. Met haar krachtige klauwen kan ze zelfs grotere prooien vangen. In jouw dierentuin maakt ze indruk met haar majestueuze verschijning en haar indringende blik.'),
       (93230, 613, 'fr', 'Harpyie', 'L''harpie est un puissant rapace originaire des forêts tropicales d''Amérique du Sud et d''Amérique centrale. Grâce à ses griffes puissantes, elle est capable d''attraper même des proies de grande taille. Dans ton zoo, elle impressionne par son allure majestueuse et son regard perçant.'),
       (93231, 613, 'es', 'Arpía', 'La arpía es una poderosa ave rapaz de las selvas tropicales de América del Sur y Central. Con sus poderosas garras es capaz de atrapar incluso presas de gran tamaño. En tu zoológico impresiona por su aspecto majestuoso y su mirada penetrante.'),
       (93232, 614, 'nl', 'Felrode ara', 'De felrode ara is een schitterend gekleurde papegaai uit de tropen van Amerika. Hij is intelligent, luidruchtig en vormt een paar voor het leven. In jouw dierentuin vliegt hij kleurrijk door de volière en zorgt hij voor een echte tropische sfeer.'),
       (93233, 614, 'fr', 'Ara rouge vif', 'L''ara rouge vif est un perroquet aux couleurs éclatantes originaire des régions tropicales d''Amérique. Intelligent et bruyant, il vit en couple pour la vie. Dans ton zoo, il vole dans la volière, resplendissant de ses couleurs, et crée une véritable ambiance tropicale.'),
       (93234, 614, 'es', 'Guacamayo rojo claro', 'El guacamayo rojo claro es un loro de colores vivos originario de las zonas tropicales de América. Es inteligente, ruidoso y forma parejas para toda la vida. En tu zoológico, vuela con sus colores vivos por el aviario y crea un auténtico ambiente tropical.'),
       (93235, 615, 'nl', 'Helmkasuar', 'De helmkasuar is een grote loopvogel uit Australië en Nieuw-Guinea met een helmachtige kopversiering. Hij leeft in regenwouden en kan heel hard trappen. In jouw dierentuin lijkt hij met zijn kleuren en zijn indrukwekkende helm bijna een fabelwezen.'),
       (93236, 615, 'fr', 'cassuar à casque', 'Le casoar est un grand oiseau coureur originaire d''Australie et de Nouvelle-Guinée, doté d''une crête en forme de casque. Il vit dans les forêts tropicales et peut donner des coups de pied très puissants. Dans ton zoo, avec ses couleurs et son impressionnant casque, il ressemble presque à une créature mythique.'),
       (93237, 615, 'es', 'casuario de casco', 'El casuario es un gran ave corredora de Australia y Nueva Guinea con una cresta en forma de casco. Vive en las selvas tropicales y puede dar patadas muy fuertes. En tu zoológico, con sus colores y su impresionante casco, parece casi una criatura de cuento.'),
       (93238, 617, 'nl', 'Keizersnor-tamarin', 'De keizerbaardtamarin heeft een indrukwekkend lange, witte snor. Hij leeft in de Zuid-Amerikaanse regenwouden en beweegt zich behendig tussen de bomen. In jouw dierentuin springt hij levendig door het verblijf en pronkt hij trots met zijn keizerlijke gezichtsbeharing.'),
       (93239, 617, 'fr', 'Tamarin à moustache de l''empereur', 'Le tamarin à moustaches de l''empereur arbore des moustaches blanches d''une longueur impressionnante. Il vit dans les forêts tropicales d''Amérique du Sud et se déplace avec agilité entre les arbres. Dans ton zoo, il bondit avec vivacité dans son enclos et exhibe fièrement sa coiffure impériale.'),
       (93240, 617, 'es', 'Tamarino bigotudo del emperador', 'El tití imperial tiene unos bigotes blancos impresionantemente largos. Vive en las selvas tropicales sudamericanas y se mueve con agilidad entre los árboles. En tu zoológico, salta con energía por el recinto y luce con orgullo su «peinado» imperial.'),
       (93241, 618, 'nl', 'Kakapo', 'De kakapo is een niet-vliegende papegaai uit Nieuw-Zeeland die ernstig bedreigd is. Hij is nachtdier, nieuwsgierig en heeft een mosgroen camouflageverenkleed. In jouw dierentuin is hij een heel bijzondere gast en een boegbeeld voor het behoud van de soort.'),
       (93242, 618, 'fr', 'Kakapo', 'Le kakapo est un perroquet néo-zélandais incapable de voler et gravement menacé. Nocturne et curieux, il possède un plumage de couleur vert mousse qui lui sert de camouflage. Dans ton zoo, c''est un hôte très spécial qui suscite beaucoup de sympathie pour la protection des espèces.'),
       (93243, 618, 'es', 'Kakapo', 'El kakapo es un loro de Nueva Zelanda incapaz de volar y en grave peligro de extinción. Es nocturno, curioso y tiene un plumaje de color verde musgo que le sirve de camuflaje. En tu zoológico es un invitado muy especial y un símbolo de la conservación de las especies.'),
       (93244, 619, 'nl', 'Kledinghanger', 'De kledingaap, ook wel kledingaap genoemd, heeft een lange vacht met sterke kleurcontrasten. Hij komt uit de bossen van Afrika en leeft in sociale groepen. In jouw dierentuin slingert hij zich elegant van tak naar tak en laat hij zijn opvallende „kleding“ zien.'),
       (93245, 619, 'fr', 'singe à vêtements', 'Le singe-vêtement, également appelé « singe-vêtement », possède un pelage long et aux couleurs contrastées. Originaire des forêts africaines, il vit en groupes sociaux. Dans ton zoo, il se balance avec élégance de branche en branche et exhibe ses « vêtements » voyants.'),
       (93246, 619, 'es', 'Perro de peluche', 'El mono de pelaje, también conocido como «mono de ropa», tiene un pelaje largo y de colores muy contrastados. Es originario de los bosques de África y vive en grupos sociales. En tu zoológico se balancea con elegancia de rama en rama y luce su llamativo «atuendo».'),
       (93247, 620, 'nl', 'Koolschildpad', 'De Köhlerschildpad is een tropische landschildpad met een donker schild en gele vlekken. Hij leeft in Zuid-Amerika en eet graag fruit en groenten. In jouw dierentuin beweegt hij zich rustig tussen de planten en de voederplaatsen.'),
       (93248, 620, 'fr', 'Tortue de Köhler', 'La tortue de Köhler est une tortue terrestre tropicale au carapace foncé parsemé de taches jaunes. Elle vit en Amérique du Sud et se nourrit volontiers de fruits et de légumes. Dans ton zoo, elle se déplace tranquillement entre les plantes et les points d''alimentation.'),
       (93249, 620, 'es', 'Tortuga de Köhler', 'La tortuga Köhler es una tortuga terrestre tropical con el caparazón oscuro y manchas amarillas. Vive en Sudamérica y le gusta comer fruta y verdura. En tu zoológico se mueve tranquilamente entre las plantas y los comederos.'),
       (93250, 622, 'nl', 'koningstijger', 'De koningstijger is een ondersoort van de tijger en heeft een bijzonder krachtig postuur. Met zijn oranje-zwarte strepenpatroon is hij een iconische vertegenwoordiger van de grote katachtigen. In jouw dierentuin sluipt hij majestueus door het verblijf en laat hij af en toe een diep gebrul horen.'),
       (93251, 622, 'fr', 'tigre royal', 'Le tigre du Bengale est une sous-espèce du tigre, dotée d''une constitution particulièrement robuste. Avec son pelage rayé orange et noir, c''est un représentant emblématique des grands félins. Dans ton zoo, il se déplace majestueusement dans son enclos et laisse parfois échapper un rugissement profond.'),
       (93252, 622, 'es', 'Tigre de Bengala', 'El tigre de Bengala es una subespecie del tigre y tiene una complexión especialmente robusta. Con su pelaje rayado de color naranja y negro, es un ejemplar emblemático de los grandes felinos. En tu zoológico, se desliza majestuosamente por su recinto y, a veces, deja escapar un rugido profundo.'),
       (93253, 623, 'nl', 'Krabbenwasbeer', 'De krabbenwasbeer is een naaste verwant van de wasbeer en is dol op water. Met zijn behendige poten tast hij in het water naar krabben en andere lekkernijen. In jouw dierentuin spettert hij enthousiast in de waterbakken en doorzoekt hij elke voederplaats.'),
       (93254, 623, 'fr', 'Raton laveur des crevettes', 'Le raton laveur crabe est un proche parent du raton laveur et adore l''eau. À l''aide de ses pattes agiles, il fouille dans l''eau à la recherche de crabes et d''autres friandises. Dans ton zoo, il s''amuse avec enthousiasme dans les bassins et fouille chaque cachette à nourriture.'),
       (93255, 623, 'es', 'Mapache cangrejero', 'El mapache cangrejero es un pariente cercano del mapache y le encanta el agua. Con sus hábiles patas, busca cangrejos y otras delicias en el agua. En tu zoológico, chapotea con entusiasmo en los estanques y registra cada escondite donde haya comida.'),
       (93256, 624, 'nl', 'Kortoorvos', 'De kortoorvos heeft, zoals de naam al zegt, ongewoon korte oren voor een vos. Hij leeft in Zuid-Amerika en is een jager die in de schemering actief is. In jouw dierentuin sluipt hij stil door het verblijf en laat hij zijn nieuwsgierige, voorzichtige kant zien.'),
       (93257, 624, 'fr', 'renard à oreilles courtes', 'Comme son nom l''indique, le renard aux oreilles courtes a des oreilles exceptionnellement courtes pour un renard. Il vit en Amérique du Sud et chasse au crépuscule. Dans ton zoo, il se faufile silencieusement dans son enclos et se montre à la fois curieux et prudent.'),
       (93258, 624, 'es', 'Zorro de orejas cortas', 'El zorro de orejas cortas tiene, como su nombre indica, unas orejas inusualmente cortas para ser un zorro. Vive en Sudamérica y es un cazador crepuscular. En tu zoológico se desliza silenciosamente por el recinto y muestra su lado curioso y cauteloso.'),
       (93259, 625, 'nl', 'leeuwenaapje', 'Het leeuwenaapje is een klein aapje met een indrukwekkende manen rond zijn gezicht. Zijn gouden of roodachtige vacht doet denken aan een kleine leeuw. In jouw dierentuin flitst hij door het gebladerte en is hij een bijzonder fotogeniek lid van de apenfamilie.'),
       (93260, 625, 'fr', 'singe-lion', 'Le singe-lion est un petit singe doté d''une impressionnante crinière autour du visage. Son pelage doré ou roux fait penser à un minuscule lion. Dans ton zoo, il file à toute allure à travers les branches et est l''un des membres les plus photogéniques de la famille des singes.'),
       (93261, 625, 'es', 'mono león', 'El mono león es un pequeño simio con una impresionante melena que le rodea la cara. Su pelaje dorado o rojizo recuerda al de un león en miniatura. En tu zoológico, corretea entre las ramas y es uno de los miembros más fotogénicos de la familia de los simios.'),
       (93262, 626, 'nl', 'Maikong', 'De maikong, ook wel krabvos genoemd, is een kleine wilde hond uit Zuid-Amerika. Hij is flexibel in zijn voedselzoektocht en maakt gebruik van verschillende leefgebieden. In jouw dierentuin beweegt hij zich stil voort en blijft hij meestal in de buurt van dekking.'),
       (93263, 626, 'fr', 'Maikong', 'Le maikong, également appelé « renard à crabes », est un petit chien sauvage originaire d''Amérique du Sud. Il fait preuve de souplesse dans sa recherche de nourriture et occupe divers habitats. Dans ton zoo, il se déplace silencieusement et reste la plupart du temps à l''abri.'),
       (93264, 626, 'es', 'Maikong', 'El maikong, también conocido como «zorro cangrejero», es un pequeño perro salvaje de Sudamérica. Es flexible a la hora de buscar alimento y habita en diversos hábitats. En tu zoológico se mueve en silencio y suele permanecer cerca de algún refugio.'),
       (93265, 627, 'nl', 'Mandrill', 'De mandrill is een van de kleurrijkste apen die er bestaan, met een felblauw-rode snuit. Hij leeft in Afrikaanse regenwouden en is een uiterst sociaal dier. In jouw dierentuin is hij een kleurrijke blikvanger die zelden onopgemerkt blijft.'),
       (93266, 627, 'fr', 'mandrill', 'Le mandrill est l''un des singes les plus colorés qui soient, avec son museau d''un bleu et d''un rouge éclatants. Il vit dans les forêts tropicales africaines et est un animal extrêmement sociable. Dans ton zoo, c''est une star haute en couleur qui passe rarement inaperçue.'),
       (93267, 627, 'es', 'mandríl', 'El mandril es uno de los monos más coloridos que existen, con un hocico de un azul y rojo brillantes. Vive en las selvas tropicales africanas y es un animal extremadamente sociable. En tu zoológico es una estrella llena de colorido que rara vez pasa desapercibida.'),
       (93268, 628, 'nl', 'mantelap', 'De mantelap heeft een lange, zwart-witte vacht met een wapperende mantel. Hij leeft in de bossen van Afrika en voedt zich voornamelijk met bladeren. In jouw dierentuin springt hij elegant van tak naar tak en laat hij zijn vacht als een mantel achter zich wapperen.'),
       (93269, 628, 'fr', 'singe à manteau', 'Le singe-manteau possède un long pelage noir et blanc et une fourrure qui flotte au vent. Il vit dans les forêts d''Afrique et se nourrit principalement de feuilles. Dans ton zoo, il bondit avec élégance de branche en branche, laissant sa fourrure flotter derrière lui comme une cape.'),
       (93270, 628, 'es', 'mono de capa', 'El mono de manto tiene un pelaje largo, blanco y negro, con un manto que ondea al viento. Vive en los bosques de África y se alimenta principalmente de hojas. En tu zoológico salta con elegancia de rama en rama y deja que su pelaje ondee a sus espaldas como si fuera una capa.'),
       (93271, 630, 'nl', 'Neusapen', 'De neusapen staan bekend om hun grote, hangende neus. Ze leven in de mangrovebossen van Zuidoost-Azië en brengen veel tijd door in de bomen. In jouw dierentuin zorgt hun opvallende uiterlijk regelmatig voor een glimlach en verbaasde gezichten.'),
       (93272, 630, 'fr', 'singe à nez long', 'Le singe-nez est célèbre pour son grand nez tombant. Il vit dans les forêts de mangroves d''Asie du Sud-Est et passe beaucoup de temps dans les arbres. Dans ton zoo, son profil caractéristique suscite régulièrement des sourires et des regards émerveillés.'),
       (93273, 630, 'es', 'mono narigudo', 'El mono narigudo es famoso por su gran nariz colgante. Vive en los bosques de manglares del sudeste asiático y pasa mucho tiempo en los árboles. En tu zoológico, su característico perfil suele provocar sonrisas y caras de asombro.'),
       (93274, 631, 'nl', 'nevelpanter', 'De nevelpanter is een middelgrote grote katachtige met grote, nevelachtige vlekken. Hij leeft in de bossen van Azië en is een uitstekende klimmer. In jouw dierentuin beweegt hij zich behendig door het gebladerte en maakt daarbij een bijna spookachtig stil geluid.'),
       (93275, 631, 'fr', 'panthère nébuleuse', 'La panthère nébuleuse est un grand félin de taille moyenne, caractérisé par de grandes taches ressemblant à des nappes de brouillard. Elle vit dans les forêts d''Asie et est une excellente grimpeuse. Dans ton zoo, elle se déplace avec agilité parmi les branches, dans un silence presque fantomatique.'),
       (93276, 631, 'es', 'Lince neblino', 'La pantera de la niebla es un felino de tamaño mediano con grandes manchas que parecen nubes de niebla. Vive en los bosques de Asia y es un excelente trepador. En tu zoológico se mueve con destreza entre las ramas y lo hace con un silencio casi fantasmal.'),
       (93277, 632, 'nl', 'Nepaluhu', 'De Nepaluhu is een uilensoort uit de bergachtige gebieden van Nepal. Met zijn verenoren en doordringende blik is hij een typische nachtjager. In jouw dierentuin slaapt hij overdag en wordt hij bij het vallen van de avond actief.'),
       (93278, 632, 'fr', 'Nepaluhu', 'Le népaluhu est une espèce de chouette originaire des régions montagneuses du Népal. Avec ses oreilles en plumes et son regard perçant, c''est un chasseur nocturne typique. Dans ton zoo, il dort pendant la journée et s''anime à la tombée de la nuit.'),
       (93279, 632, 'es', 'Nepaluhu', 'El nepaluhu es una especie de búho originaria de las regiones montañosas de Nepal. Con sus orejas plumosas y su mirada penetrante, es un típico cazador nocturno. En tu zoológico duerme durante el día y se despierta al caer la noche.'),
       (93280, 633, 'nl', 'Netpython', 'De netpython is een van de langste slangensoorten ter wereld. Dankzij zijn netpatroon blijft hij goed gecamoufleerd in de jungle. In jouw dierentuin kronkelt hij langzaam en majestueus door zijn terrarium.'),
       (93281, 633, 'fr', 'Python réticulé', 'Le python réticulé est l''une des espèces de serpents les plus longues au monde. Son motif en forme de filet lui permet de rester bien camouflé dans la jungle. Dans ton zoo, il se faufile lentement et majestueusement à travers son terrarium.'),
       (93282, 633, 'es', 'pitón reticulado', 'La pitón reticulada es una de las especies de serpientes más largas del mundo. Su patrón reticulado le ayuda a camuflarse bien en la selva. En tu zoológico, se desliza lenta y majestuosamente por su terrario.'),
       (93283, 634, 'nl', 'Nilkrokodil', 'De Nijlkrokodil is een grote, angstaanjagende rivierroofdier uit Afrika. Hij ligt vaak roerloos op de loer in het water, voordat hij bliksemsnel toeslaat. In jouw dierentuin ligt hij meestal schijnbaar traag aan de oever en vertoont dan verrassend snelle bewegingen.'),
       (93284, 634, 'fr', 'Crocodile du Nil', 'Le crocodile du Nil est un grand prédateur fluvial africain redoutable. Il reste souvent immobile dans l''eau avant de bondir à la vitesse de l''éclair. Dans ton zoo, il semble généralement paresseux, allongé sur la berge, puis effectue soudain des mouvements d''une rapidité surprenante.'),
       (93285, 634, 'es', 'Cocodrilo del Nilo', 'El cocodrilo del Nilo es un gran y temible depredador fluvial de África. A menudo permanece inmóvil en el agua, al acecho, antes de atacar con la rapidez de un rayo. En tu zoológico suele permanecer aparentemente inactivo en la orilla y, de repente, realiza movimientos sorprendentemente rápidos.'),
       (93286, 635, 'nl', 'Orang-oetan', 'De orang-oetan is een zeer intelligente mensaap die in de regenwouden van Borneo en Sumatra leeft. Zijn naam betekent ‘bosmens’, en hij brengt bijna zijn hele leven in de bomen door. In jouw dierentuin bouwt hij nestjes en lost hij behendig lastige voedselpuzzels op.'),
       (93287, 635, 'fr', 'Orang-outan', 'L''orang-outan est un grand singe très intelligent qui vit dans les forêts tropicales de Bornéo et de Sumatra. Son nom signifie « homme de la forêt », et il passe presque toute sa vie dans les arbres. Dans ton zoo, il se construit des nids et résout avec habileté des énigmes alimentaires complexes.'),
       (93288, 635, 'es', 'Orangután', 'El orangután es un simio muy inteligente que vive en las selvas tropicales de Borneo y Sumatra. Su nombre significa «hombre del bosque», y pasa casi toda su vida en los árboles. En tu zoo, se construye nidos y resuelve con destreza complicados acertijos para conseguir comida.'),
       (93289, 636, 'nl', 'Pakarana', 'De pakarana is een zeldzaam, groot knaagdier uit Zuid-Amerika. Hij beweegt zich vrij langzaam en leeft meestal teruggetrokken. In jouw dierentuin laat hij zich van zijn rustige, vredige kant zien en wordt hij graag bekeken terwijl hij gezellig knabbelt.'),
       (93290, 636, 'fr', 'Pakarana', 'Le pakarana est un grand rongeur rare originaire d''Amérique du Sud. Il se déplace plutôt lentement et mène généralement une vie recluse. Dans ton zoo, il se montre calme et paisible, et on aime l''observer lorsqu''il grignote tranquillement.'),
       (93291, 636, 'es', 'Pakarana', 'El pakarana es un roedor grande y poco común de Sudamérica. Se mueve con bastante lentitud y suele llevar una vida solitaria. En tu zoológico muestra su lado tranquilo y pacífico, y a la gente le encanta observarlo mientras roe tranquilamente.'),
       (93292, 637, 'nl', 'Panamese kapucijnaap', 'De Panamese kapucijnaap is een intelligente Nieuwwereld-aap met een contrastrijke zwart-witte vacht. Hij gebruikt zijn behendige handen graag om te klimmen, dingen vast te pakken en gereedschap te gebruiken. In jouw dierentuin is hij altijd in beweging en bedenkt hij creatieve manieren om aan voedsel te komen.'),
       (93293, 637, 'fr', 'Singe capucin du Panama', 'Le singe capucin du Panama est un singe du Nouveau Monde intelligent, au pelage noir et blanc très contrasté. Il aime utiliser ses mains agiles pour grimper, saisir des objets et se servir d’outils. Dans ton zoo, il est toujours en mouvement et imagine des moyens créatifs pour se procurer de la nourriture.'),
       (93294, 637, 'es', 'Mono capuchino de Panamá', 'El mono capuchino de Panamá es un mono del Nuevo Mundo muy inteligente, con un pelaje en blanco y negro muy contrastado. Le encanta utilizar sus hábiles manos para trepar, agarrar objetos y utilizar herramientas. En tu zoológico no para quieto ni un momento e inventa formas creativas de conseguir comida.'),
       (93295, 638, 'nl', 'Panter', 'De panter is een zwartgekleurde variant van de luipaard of de jaguar. Onder de donkere vacht zijn de kenmerkende vlekken nog steeds te zien. In jouw dierentuin straalt hij een mysterieuze uitstraling uit en glijdt hij geruisloos door schaduw en licht.'),
       (93296, 638, 'fr', 'Panter', 'Le panthère est une variante de couleur noire du léopard ou du jaguar. Sous son pelage sombre, on distingue encore ses taches caractéristiques. Dans ton zoo, il dégage une aura mystérieuse et se faufile sans bruit entre l''ombre et la lumière.'),
       (93297, 638, 'es', 'Pantera', 'El panter es una variante de color negro de los leopardos o los jaguares. Bajo su pelaje oscuro aún se distinguen las manchas típicas. En tu zoológico tiene un aire misterioso y se desliza en silencio entre las sombras y la luz.'),
       (93298, 639, 'nl', 'Reuzenkoningshamster', 'De reuzenkoningseekhoorn is een grote eekhoorn met een kleurrijk vachtpatroon. Hij leeft in bomen en kan grote sprongen maken tussen takken. In jouw dierentuin zorgt hij met zijn kleurrijke uiterlijk en behendigheid voor veel verwondering.'),
       (93299, 639, 'fr', 'Écureuil géant', 'L''écureuil royal géant est un grand écureuil au pelage bigarré. Il vit dans les arbres et peut effectuer de longs sauts d''une branche à l''autre. Dans ton zoo, il suscite l''émerveillement grâce à ses couleurs vives et à son agilité.'),
       (93300, 639, 'es', 'Ardilla gigante real', 'La ardilla real gigante es una ardilla de gran tamaño con un pelaje de colores vivos. Vive en los árboles y es capaz de dar grandes saltos entre las ramas. En tu zoológico, su colorido y su agilidad causarán gran asombro.'),
       (93301, 640, 'nl', 'Reuzenotter', 'De reuzenotter is de grootste otter ter wereld en leeft in de rivieren van Zuid-Amerika. Hij is erg sociaal en jaagt in groep op vis. In jouw dierentuin spettert hij uitgelaten in het water en communiceert hij met zijn groep via allerlei geluiden.'),
       (93302, 640, 'fr', 'couleuvre géante', 'La loutre géante est la plus grande loutre du monde et vit dans les fleuves d''Amérique du Sud. C''est un animal très sociable qui chasse le poisson en groupe. Dans ton zoo, elle s''amuse joyeusement dans l''eau et communique avec son groupe à l''aide de nombreux cris.'),
       (93303, 640, 'es', 'Cobra gigante', 'La nutria gigante es la nutria más grande del mundo y vive en los ríos de Sudamérica. Es un animal muy sociable y caza peces en grupo. En tu zoológico, chapotea alegremente en el agua y se comunica con su grupo mediante diversos sonidos.'),
       (93304, 641, 'nl', 'Gigantische kan', 'De reuzentukan is een tropische vogel met een enorme, kleurrijke snavel. Hij gebruikt die om fruit te pakken en zich af te koelen. In jouw dierentuin is hij met zijn snavel een echte blikvanger als hij op takken zit.'),
       (93305, 641, 'fr', 'Riesunakan', 'Le tukang géant est un oiseau tropical doté d''un bec énorme et aux couleurs chatoyantes. Il s''en sert pour attraper des fruits et se rafraîchir. Dans ton zoo, il attire tous les regards avec son bec lorsqu''il est perché sur une branche.'),
       (93306, 641, 'es', 'Riesaghanas', 'El tucán gigante es un ave tropical con un pico enorme y de colores vivos. Lo utiliza para coger frutos y refrescarse. En tu zoológico, con su pico, llama mucho la atención cuando se posa en las ramas.'),
       (93307, 642, 'nl', 'Rode uakari', 'De rode uakari is een aap met een felrood gezicht en een korte staart. Hij leeft in de oeverbossen van het Amazonegebied. In jouw dierentuin valt hij vooral op door zijn opvallende gezicht, dat eruitziet alsof het geschminkt is.'),
       (93308, 642, 'fr', 'Uakari rouge', 'L''uakari rouge est un singe au visage d''un rouge vif et à la queue courte. Il vit dans les forêts inondables d''Amazonie. Dans ton zoo, il se distingue particulièrement par son visage aux couleurs intenses, qui semble maquillé.'),
       (93309, 642, 'es', 'Uakari rojo', 'El uakari rojo es un mono con la cara de un rojo intenso y una cola corta. Vive en los bosques inundables de la Amazonía. En tu zoológico llama especialmente la atención por su cara de colores intensos, que parece maquillada.'),
       (93310, 643, 'nl', 'Roodhalsfilander', 'De roodnekfilander is een middelgroot kangoeroe met een roodachtige nek. Hij leeft in Australië en geeft de voorkeur aan rotsachtige of beboste gebieden. In jouw dierentuin huppelt hij lichtvoetig rond en rust hij graag uit in schaduwrijke hoekjes.'),
       (93311, 643, 'fr', 'Filandre à cou rouge', 'Le kangourou à cou roux est un kangourou de taille moyenne au cou de couleur rougeâtre. Il vit en Australie et préfère les zones rocheuses ou boisées. Dans ton zoo, il bondit avec agilité et aime se reposer dans des coins ombragés.'),
       (93312, 643, 'es', 'Filandro de cuello rojo', 'El canguro de cuello rojo es un canguro de tamaño mediano con el cuello de color rojizo. Vive en Australia y prefiere las zonas rocosas o boscosas. En tu zoo salta con agilidad y le gusta descansar en rincones sombreados.'),
       (93313, 644, 'nl', 'Saola', 'De saola is een zeer zeldzame, in het bos levende rundersoort uit Vietnam en Laos. Hij wordt soms wel de ‘Aziatische eenhoorn’ genoemd, hoewel hij twee hoorns heeft. In jouw dierentuin staat hij symbool voor mysterieuze bosbewoners, waarover we nog veel moeten leren.'),
       (93314, 644, 'fr', 'Saola', 'Le saola est une espèce de bovidé très rare vivant dans les forêts du Vietnam et du Laos. On l''appelle parfois « licorne d''Asie », bien qu''il possède deux cornes. Dans ton zoo, il incarne ces mystérieux habitants de la forêt, dont nous avons encore beaucoup à apprendre.'),
       (93315, 644, 'es', 'Saola', 'El saola es una especie de bovino muy rara que habita en los bosques de Vietnam y Laos. A veces se le conoce como «unicornio asiático», aunque tiene dos cuernos. En tu zoológico representa a los misteriosos habitantes del bosque, de los que aún nos queda mucho por aprender.'),
       (93316, 645, 'nl', 'duivelse aap', 'De satanaap dankt zijn dramatische naam aan zijn donkere gezicht en zijn intense ogen. Verder is het echter een heel gewone, sociale aap. In jouw dierentuin vertoont hij levendig sociaal gedrag en bewijst hij dat zijn naam weliswaar veelzeggend is, maar niet kwaadaardig.'),
       (93317, 645, 'fr', 'singe du diable', 'Le singe de Satan doit son nom évocateur à son visage sombre et à son regard intense. Pour le reste, c''est toutefois un singe tout à fait normal, qui vit en groupe. Dans ton zoo, il fait preuve d''un comportement social très vif et prouve que son nom est bien à la hauteur de sa réputation, sans pour autant être malveillant.'),
       (93318, 645, 'es', 'Maldito', 'El mono de Satanás debe su dramático nombre a su rostro oscuro y a sus ojos intensos. Por lo demás, sin embargo, es un mono totalmente normal y sociable. En tu zoológico muestra un comportamiento social muy animado y demuestra que, aunque su nombre lo dice todo, no es malicioso.'),
       (93319, 647, 'nl', 'Sumatra-tijger', 'De Sumatra-tijger is de kleinste ondersoort van de tijger en staat onder strikte bescherming. Hij leeft in de regenwouden van Sumatra en is een meester in het zich camoufleren. In jouw dierentuin staat hij symbool voor bedreigde grote katachtigen en betovert hij bezoekers met zijn aanwezigheid.'),
       (93320, 647, 'fr', 'Tigre de Sumatra', 'Le tigre de Sumatra est la plus petite sous-espèce de tigre et bénéficie d''une protection stricte. Il vit dans les forêts tropicales de Sumatra et est passé maître dans l''art du camouflage. Dans ton zoo, il incarne les grands félins menacés d''extinction et captive les visiteurs par sa présence.'),
       (93321, 647, 'es', 'Tigre de Sumatra', 'El tigre de Sumatra es la subespecie de tigre más pequeña y está estrictamente protegida. Vive en las selvas tropicales de Sumatra y es un maestro del camuflaje. En tu zoológico es un símbolo de los grandes felinos en peligro de extinción y cautiva a los visitantes con su presencia.'),
       (93322, 648, 'nl', 'Tamandua', 'De tamandua is een kleinere verwant van de grote miereneter. Hij kan goed klimmen en gebruikt zijn lange tong om insecten uit spleten te halen. In jouw dierentuin verkent hij nieuwsgierig klimconstructies en voerverbergplaatsen.'),
       (93323, 648, 'fr', 'Tamandua', 'Le tamandua est un petit cousin du grand fourmilier. C''est un excellent grimpeur qui utilise sa longue langue pour attraper des insectes dans les fissures. Dans ton zoo, il explore avec curiosité les structures d''escalade et les cachettes à nourriture.'),
       (93324, 648, 'es', 'Tamandúa', 'El tamandúa es un pariente más pequeño del oso hormiguero grande. Trepa bien y utiliza su larga lengua para sacar insectos de las grietas. En tu zoológico, explora con curiosidad las estructuras para trepar y los escondites donde se guarda la comida.'),
       (93325, 649, 'nl', 'Tamarau', 'De Tamarau is een kleine buffel van het Filipijnse eiland Mindoro. Hij is ernstig bedreigd en leeft in bos- en graslandgebieden. In jouw dierentuin is hij een zeldzame gast en vestigt hij de aandacht op het belang van eilandecosystemen.'),
       (93326, 649, 'fr', 'Tamarau', 'Le tamarau est un petit buffle originaire de l''île de Mindoro, aux Philippines. Espèce gravement menacée, il vit dans les forêts et les prairies. C''est un hôte rare dans ton zoo, qui attire l''attention sur l''importance des écosystèmes insulaires.'),
       (93327, 649, 'es', 'Tamarau', 'El tamarau es un pequeño búfalo originario de la isla filipina de Mindoro. Se encuentra en grave peligro de extinción y habita en bosques y praderas. En tu zoológico es un visitante poco habitual y llama la atención sobre la importancia de los ecosistemas insulares.'),
       (93328, 650, 'nl', 'Couscous met stippels', 'De gevlekte couscous is een in bomen levend buideldier met een gevlekte vacht. Hij komt voor in Nieuw-Guinea en voedt zich met bladeren en vruchten. In jouw dierentuin klimt hij langzaam en bedachtzaam door het takkenwerk en slaapt hij overdag graag op een verborgen plekje.'),
       (93329, 650, 'fr', 'Couscous aux pois', 'Le couscous tacheté est un marsupial arboricole au pelage tacheté. Il vit en Nouvelle-Guinée et se nourrit de feuilles et de fruits. Dans ton zoo, il grimpe lentement et prudemment dans les branches et aime se cacher pour dormir pendant la journée.'),
       (93330, 650, 'es', 'Cuscús con motitas', 'El cuscús moteado es un marsupial arbóreo con pelaje moteado. Vive en Nueva Guinea y se alimenta de hojas y frutos. En tu zoológico trepa lenta y cuidadosamente por las ramas y, durante el día, le gusta dormir escondido.'),
       (93331, 651, 'nl', 'Witvingergibbon', 'De witvingergibbon is een behendige boomklimmer met witte handen en voeten. Hij beweegt zich al hangend aan zijn armen door de boomtoppen en zingt luide duetten. In jouw dierentuin slingert hij elegant tussen touwen en takken en begeleidt hij de bezoekers met zijn kenmerkende kreten.'),
       (93332, 651, 'fr', 'gibbon à mains blanches', 'Le gibbon à mains blanches est un grimpeur acrobatique aux mains et aux pieds blancs. Il se déplace en se suspendant aux branches dans la cime des arbres et chante des duos retentissants. Dans ton zoo, il se balance avec élégance entre les cordes et les branches et accompagne la visite de ses cris caractéristiques.'),
       (93333, 651, 'es', 'Gibón de manos blancas', 'El gibón de manos blancas es un ágil trepador de árboles con manos y pies blancos. Se desplaza columpiándose de las copas de los árboles y entona duetos a todo volumen. En tu zoológico se balancea con elegancia entre cuerdas y ramas y acompaña la visita con sus característicos gritos.'),
       (93334, 652, 'nl', 'Westelijke laaglandgorilla', 'De westelijke laaglandgorilla is een van de bekendste gorilla-ondersoorten en wordt ernstig bedreigd. Hij leeft in de regenwouden van Afrika en voedt zich voornamelijk met planten. In jouw dierentuin is hij een vriendelijke reus die samen met zijn familie voor veel ontroerende momenten zorgt.'),
       (93335, 652, 'fr', 'Gorille des plaines de l''Ouest', 'Le gorille des plaines de l''Ouest est l''une des sous-espèces les plus connues de gorilles et est gravement menacé. Il vit dans les forêts tropicales d''Afrique et se nourrit principalement de végétaux. Dans ton zoo, c''est un géant au caractère doux qui, avec sa famille, offre de nombreux moments émouvants.'),
       (93336, 652, 'es', 'Gorila de llanura occidental', 'El gorila de las llanuras occidentales es una de las subespecies más conocidas de gorila y se encuentra en grave peligro de extinción. Vive en las selvas tropicales de África y se alimenta principalmente de plantas. En tu zoológico es un gigante bondadoso que, junto con su familia, nos regala muchos momentos conmovedores.'),
       (93337, 653, 'nl', 'Wikkelbeertje', 'De kinkajou is een nachtdier dat in bomen leeft en een grijpstaart heeft. Hij is dol op fruit en nectar en beweegt zich geruisloos door het gebladerte. In jouw dierentuin laat hij vooral ’s nachts zijn behendige klimkunsten zien.'),
       (93338, 653, 'fr', 'Ourson à emmailloter', 'L''ours-enrouleur, également appelé kinkajou, est un animal arboricole nocturne doté d''une queue préhensile. Il adore les fruits et le nectar et se déplace silencieusement à travers les branches. Dans ton zoo, il fait la démonstration de ses talents d''escaladeur, surtout la nuit.'),
       (93339, 653, 'es', 'Osito de peluche', 'El oso enroscado, también conocido como kinkajú, es un animal arbóreo nocturno con cola prensil. Le encantan las frutas y el néctar, y se desplaza silenciosamente entre las ramas. En tu zoológico, muestra sus hábiles dotes trepadoras, sobre todo por la noche.'),
       (93340, 654, 'nl', 'dwergnijlpaard', 'Het dwergnijlpaard is de kleinere, schuwe verwant van het nijlpaard. Het leeft in de bossen van West-Afrika en brengt veel tijd in het water door. In jouw dierentuin is het een vrij rustige, maar zeer charmante waterbewoner.'),
       (93341, 654, 'fr', 'Hippopotame nain', 'L''hippopotame nain est le cousin plus petit et plus timide de l''hippopotame. Il vit dans les forêts d''Afrique de l''Ouest et passe beaucoup de temps dans l''eau. Dans ton zoo, c''est un habitant aquatique plutôt calme, mais très charmant.'),
       (93342, 654, 'es', 'Hipopótamo enano', 'El hipopótamo enano es el pariente más pequeño y tímido del hipopótamo. Vive en los bosques de África Occidental y pasa mucho tiempo en el agua. En tu zoológico es un habitante acuático bastante tranquilo, pero muy encantador.'),
       (93343, 655, 'nl', 'Scharlakensik', 'De scharlakenhamerkop is een felrode vogel uit de moerasgebieden van Zuid-Amerika. Zijn intense kleuren dankt hij aan zijn voedsel. In jouw dierentuin lijkt hij een klein rood kleurvlekje dat door het water waadt.'),
       (93344, 655, 'fr', 'Faucille écarlate', 'Le martin-chasseur écarlate est un oiseau d''un rouge vif originaire des zones humides d''Amérique du Sud. Il doit ses couleurs vives à son alimentation. Dans ton zoo, il ressemble à une petite touche de rouge qui patauge dans l''eau.'),
       (93345, 655, 'es', 'Hormiguero escarlata', 'El pájaro de la hoz escarlata es un ave de color rojo brillante originaria de los humedales de Sudamérica. Debe sus intensos colores a su alimentación. En tu zoológico parece una pequeña mancha roja que vadea el agua.'),
       (93346, 656, 'nl', 'Aziatische olifant', 'De Aziatische olifant is iets kleiner dan zijn Afrikaanse verwant en heeft kleinere oren. Hij leeft in de bossen en graslanden van Azië. In jouw dierentuin laat hij zien hoe behendig hij met zijn slurf is en hoe sociaal hij zich gedraagt in de kudde.'),
       (93347, 656, 'fr', 'Éléphant d''Asie', 'L''éléphant d''Asie est légèrement plus petit que son cousin africain et a des oreilles plus petites. Il vit dans les forêts et les prairies d''Asie. Dans ton zoo, il montre l''agilité de sa trompe et son côté sociable au sein de son troupeau.'),
       (93348, 656, 'es', 'Elefante asiático', 'El elefante asiático es algo más pequeño que su pariente africano y tiene las orejas más pequeñas. Vive en los bosques y praderas de Asia. En tu zoológico demuestra su destreza con la trompa y su carácter sociable al vivir en manada.'),
       (93349, 702, 'nl', 'Arctische grondeekhoorn', 'De arctische grondeekhoorn is een klein knaagdier uit de koude gebieden in het noorden. Hij houdt een lange winterslaap en legt daarvoor flink wat reserves aan. In jouw dierentuin lijkt hij in de zomer bijzonder actief en rent hij druk door zijn verblijf.'),
       (93350, 702, 'fr', 'Soreillette de l''Arctique', 'Le ground squirrel arctique est un petit rongeur originaire des régions froides du Nord. Il hiberne longtemps et constitue au préalable de solides réserves. Dans ton zoo, il semble particulièrement actif en été et file à toute allure dans son enclos.'),
       (93351, 702, 'es', 'Ardilla ártica', 'El ardilla ártica es un pequeño roedor de las frías regiones del norte. Entra en un largo letargo invernal y, antes de ello, acumula abundantes reservas. En tu zoológico se muestra especialmente activa en verano y corre sin parar por su recinto.'),
       (93352, 703, 'nl', 'IJsbeer', 'De ijsbeer is het grootste landroofdier van het Noordpoolgebied en een uitstekende zwemmer. Zijn witte vacht zorgt ervoor dat hij in de sneeuw onopgemerkt blijft; daaronder zit een donkere huid. In jouw dierentuin geniet hij van koudebaden, ijsblokken en lange rustpauzes.'),
       (93353, 703, 'fr', 'Ours polaire', 'L''ours polaire est le plus grand prédateur terrestre de l''Arctique et un excellent nageur. Son pelage blanc lui permet de se fondre dans la neige, sous laquelle se cache une peau foncée. Dans ton zoo, il apprécie les bassins d''eau froide, les blocs de glace et de longues pauses pour se reposer.'),
       (93354, 703, 'es', 'Oso polar', 'El oso polar es el mayor depredador terrestre del Ártico y un excelente nadador. Su pelaje blanco le camufla en la nieve; debajo se esconde una piel oscura. En tu zoológico disfruta de piscinas de agua fría, bloques de hielo y largos descansos.'),
       (93355, 704, 'nl', 'Glansfazant', 'De glansfazant staat bekend om zijn schitterende verenkleed en komt voor in de bergen van Azië. Hij schittert in vele kleuren, vooral in het zonlicht. In jouw dierentuin loopt hij trots door het verblijf en laat hij zich graag van zijn beste kant zien.'),
       (93356, 704, 'fr', 'Faisan brillant', 'Le faisan doré, originaire des montagnes d''Asie, est réputé pour son plumage chatoyant. Il resplendit de mille couleurs, surtout lorsqu''il est exposé au soleil. Dans ton zoo, il se promène fièrement dans son enclos et aime se montrer sous son meilleur jour.'),
       (93357, 704, 'es', 'Faisán brillante', 'El faisán brillante es conocido por su plumaje iridiscente y habita en las montañas de Asia. Resplandece con muchos colores, sobre todo cuando le da el sol. En tu zoológico, se pasea con orgullo por el recinto y le encanta mostrarse en todo su esplendor.'),
       (93358, 705, 'nl', 'Himalaya-tahr', 'De Himalaya-tahr is een behendig klimmend hoefdier uit de bergen van Azië. Zijn dichte vacht beschermt hem tegen kou en wind. In jouw dierentuin maakt hij gebruik van elke rotsformatie en toont hij een indrukwekkende trefzekerheid.'),
       (93359, 705, 'fr', 'Tahr de l''Himalaya', 'Le tahr de l''Himalaya est un ongulé habile grimpeur originaire des montagnes d''Asie. Son pelage épais le protège du froid et du vent. Dans ton zoo, il profite de chaque formation rocheuse et fait preuve d''une agilité impressionnante.'),
       (93360, 705, 'es', 'Tahr del Himalaya', 'El tahr del Himalaya es un ungulado experto en escalada originario de las montañas de Asia. Su denso pelaje le protege del frío y del viento. En tu zoológico aprovecha cada formación rocosa y demuestra una impresionante seguridad al caminar.'),
       (93361, 706, 'nl', 'Jakuten-paard', 'Het Jakuten-paard leeft in extreem koude gebieden van Siberië en is erg robuust. Zijn dikke wintervacht is bestand tegen temperaturen ver onder het vriespunt. In jouw dierentuin trotseert hij ook koelere temperaturen zonder problemen en ziet hij er daarbij bijzonder pluizig uit.'),
       (93362, 706, 'fr', 'Cheval yakoute', 'Le cheval de Yakoutie vit dans les régions extrêmement froides de Sibérie et est très robuste. Son épais pelage d''hiver lui permet de résister à des températures bien inférieures à zéro. Dans ton zoo, il affronte sereinement les températures plus fraîches et a l''air particulièrement douillet.'),
       (93363, 706, 'es', 'Caballo de Yakutia', 'El caballo de Yakutia vive en regiones extremadamente frías de Siberia y es muy resistente. Su denso pelaje de invierno le permite soportar temperaturas muy por debajo de cero. En tu zoológico, aguanta con tranquilidad incluso las temperaturas más frescas y, además, tiene un aspecto especialmente mullido.'),
       (93364, 707, 'nl', 'Japanse Serau', 'De Japanse serau is een geitachtig dier dat in de bergbossen van Japan leeft. Hij kan behendig klimmen en heeft een dikke vacht. In jouw dierentuin laat hij zijn klimvaardigheden zien op rotsachtige parcoursen.'),
       (93365, 707, 'fr', 'Serau japonais', 'Le serau japonais est un animal ressemblant à une chèvre qui vit dans les forêts de montagne du Japon. C''est un grimpeur habile doté d''un pelage épais. Dans ton zoo, il fait la démonstration de ses talents de grimpeur sur des parcours rocheux.'),
       (93366, 707, 'es', 'Serau japonés', 'El serau japonés es un animal parecido a una cabra que vive en los bosques de montaña de Japón. Es un hábil trepador y tiene un pelaje denso. En tu zoológico muestra sus habilidades para trepar en las instalaciones rocosas.'),
       (93367, 708, 'nl', 'Japanse makaak', 'De Japanse makaak staat bekend als de ‘sneeuw aap’, omdat hij ook in koele gebieden leeft en gebruikmaakt van warmwaterbronnen. Hij heeft een dichte vacht en uitgesproken sociale structuren. In jouw dierentuin speelt hij in de winter graag in de sneeuw en kruipt hij dicht tegen zijn groep aan.'),
       (93368, 708, 'fr', 'macaque du Japon', 'Le macaque du Japon est connu sous le nom de « singe des neiges », car il vit également dans des régions froides et fréquente les sources chaudes. Il possède un pelage épais et des structures sociales bien développées. Dans ton zoo, il aime jouer dans la neige en hiver et se blottir contre les membres de son groupe.'),
       (93369, 708, 'es', 'Macaco japonés', 'El macaco japonés es conocido como «mono de la nieve», ya que vive también en regiones frías y se beneficia de las aguas termales. Tiene un pelaje denso y unas estructuras sociales muy marcadas. En tu zoológico, en invierno le gusta jugar en la nieve y acurrucarse junto a su grupo.'),
       (93370, 710, 'nl', 'Canadese lynx', 'De Canadese lynx heeft bijzonder grote poten, die als sneeuwschoenen fungeren. Hij leeft in noordelijke bossen en jaagt vooral op sneeuwkonijnen. In jouw dierentuin ziet hij er met zijn puntige oren en zijn dikke vacht bijzonder gracieus uit.'),
       (93371, 710, 'fr', 'Lynx du Canada', 'Le lynx du Canada possède des pattes particulièrement grandes qui lui servent de raquettes. Il vit dans les forêts nordiques et chasse principalement le lièvre des neiges. Dans ton zoo, il est particulièrement gracieux avec ses oreilles en pinceaux et son pelage épais.'),
       (93372, 710, 'es', 'Lince canadiense', 'El lince canadiense tiene unas patas especialmente grandes que actúan como raquetas de nieve. Vive en los bosques nórdicos y caza sobre todo liebres de las nieves. En tu zoológico, sus orejas en forma de pincel y su espeso pelaje le dan un aspecto especialmente elegante.'),
       (93373, 711, 'nl', 'muskusos', 'De muskusos is een primitief aandoend dier met een lange, ruige vacht. Hij leeft in de arctische toendra en trotseert daar de ijzige winden. In jouw dierentuin lijkt hij wel een overblijfsel uit de ijstijd, dat rustig in zijn verblijf staat.'),
       (93374, 711, 'fr', 'bœuf musqué', 'Le bœuf musqué est un animal à l''allure primitive, doté d''une longue fourrure hirsute. Il vit dans la toundra arctique, où il brave les vents glacials. Dans ton zoo, il fait figure de vestige de la période glaciaire, se tenant sereinement dans son enclos.'),
       (93375, 711, 'es', 'buey almizclero', 'El buey almizclero es un animal de aspecto primitivo con un pelaje largo y hirsuto. Vive en la tundra ártica, donde desafía los vientos gélidos. En tu zoológico parece una reliquia de la Edad de Hielo, que permanece sereno en su recinto.'),
       (93376, 712, 'nl', 'muskusdier', 'Het muskusdier is een klein, hertenachtig zoogdier zonder gewei. Vroeger werd het bejaagd vanwege zijn muskus. In jouw dierentuin gedraagt het zich terughoudend en blijft het liever in de buurt van dekking.'),
       (93377, 712, 'fr', 'muscardine', 'Le cerf musqué est un petit mammifère ressemblant à un cerf, mais dépourvu de bois. Autrefois, on le chassait pour son musc. Dans ton zoo, il se montre timide et préfère rester près d''un abri.'),
       (93378, 712, 'es', 'muso', 'El almizclero es un pequeño mamífero parecido a un ciervo que carece de cuernos. Antiguamente se le cazaba por su almizcle. En tu zoológico se muestra tímido y prefiere permanecer cerca de algún refugio.'),
       (93379, 713, 'nl', 'Poolvos', 'De poolvos verandert, afhankelijk van het seizoen, van een witte naar een bruine vachtkleur. Hij is perfect aangepast aan de arctische omstandigheden. In jouw dierentuin valt hij op door zijn donzige wintervacht en zijn behendige karakter.'),
       (93380, 713, 'fr', 'renard polaire', 'Selon la saison, le renard polaire change de couleur de fourrure, passant du blanc au brun. Il est parfaitement adapté aux conditions arctiques. Dans ton zoo, il se distingue par son pelage d''hiver duveteux et son caractère vif.'),
       (93381, 713, 'es', 'Zorro ártico', 'El zorro polar cambia el color de su pelaje de blanco a marrón según la estación del año. Está perfectamente adaptado a las condiciones árticas. En tu zoo destaca por su mullido pelaje invernal y su carácter ágil.'),
       (93382, 714, 'nl', 'Poolwolf ', 'De poolwolf is aangepast aan de kou van het hoge noorden en heeft een dichte, witte vacht. Hij leeft in roedels en jaagt in groep. In jouw dierentuin laat hij zijn sociale kant zien en beweegt hij zich elegant door de sneeuw.'),
       (93383, 714, 'fr', 'Loup polaire ', 'Le loup polaire est adapté au froid du Grand Nord et porte un pelage épais et blanc. Il vit en meute et chasse en groupe. Dans ton zoo, il montre son côté sociable et se déplace avec élégance dans la neige.'),
       (93384, 714, 'es', 'Lobo polar ', 'El lobo polar está adaptado al frío del extremo norte y tiene un pelaje denso y blanco. Vive en manadas y caza en grupo. En tu zoo muestra su lado social y se mueve con elegancia por la nieve.'),
       (93385, 716, 'nl', 'Sneeuwgans', 'De sneeuwgans is een trekvogel met een licht gekleurd verenkleed. Ze broedt in arctische gebieden en overwintert verder naar het zuiden. In jouw dierentuin zorgt ze op de waterpartijen voor een winterse sfeer.'),
       (93386, 716, 'fr', 'Oie des neiges', 'L''oie des neiges est un oiseau migrateur au plumage clair. Elle niche dans les régions arctiques et hiverne plus au sud. Dans ton zoo, elle apporte une ambiance hivernale au bord des plans d''eau.'),
       (93387, 716, 'es', 'Ganso de las nieves', 'El ganso de las nieves es un ave migratoria de plumaje claro. Cría en las regiones árticas y pasa el invierno más al sur. En tu zoológico, aporta un ambiente invernal a las zonas acuáticas.'),
       (93388, 717, 'nl', 'Sneeuwhaas', 'Het sneeuwkonijn verandert tussen de zomer en de winter van bruin naar wit. Zo is hij het hele jaar door goed gecamoufleerd. In jouw dierentuin huppelt hij behendig door de sneeuwverblijven en gaat hij perfect op in het winterlandschap.'),
       (93389, 717, 'fr', 'lièvre des neiges', 'Le lièvre des neiges change de pelage entre l''été et l''hiver, passant du brun au blanc. Il est ainsi bien camouflé tout au long de l''année. Dans ton zoo, il bondit agilement à travers les enclos enneigés et se fond parfaitement dans le paysage hivernal.'),
       (93390, 717, 'es', 'liebre de nieve', 'La liebre de las nieves cambia el pelaje de marrón a blanco entre el verano y el invierno. Así está bien camuflada durante todo el año. En tu zoológico, salta ágilmente por los recintos nevados y se integra a la perfección en el paisaje invernal.'),
       (93391, 718, 'nl', 'Sneeuwluipaard', 'De sneeuwluipaard leeft in de hoge bergen van Azië en heeft een dichte, gevlekte vacht. Zijn lange staart dient als evenwichtsorgaan en als knuffeldeken. In jouw dierentuin beweegt hij zich elegant over de rotsen en lijkt hij wel een berggeest.'),
       (93392, 718, 'fr', 'léopard des neiges', 'Le léopard des neiges vit dans les hautes montagnes d''Asie et possède un pelage épais et tacheté. Sa longue queue lui sert d''aide à l''équilibre et de couverture douillette. Dans ton zoo, il se déplace avec élégance sur les rochers et ressemble à un esprit des montagnes.'),
       (93393, 718, 'es', 'Leopardo de las nieves', 'El leopardo de las nieves vive en las altas montañas de Asia y tiene un pelaje denso y moteado. Su larga cola le sirve para mantener el equilibrio y como manta con la que acurrucarse. En tu zoológico se mueve con elegancia por las rocas y parece un espíritu de la montaña.'),
       (93394, 719, 'nl', 'Sneeuwgeit', 'De sneeuwgeit is een bergdier uit Noord-Amerika met een dichte, witte vacht. Ze klimt behendig op steile hellingen. In jouw dierentuin laat ze haar klimkunsten zien op rotsachtige constructies en houdt ze van daaruit alles in de gaten.'),
       (93395, 719, 'fr', 'chèvre des neiges', 'La chèvre des neiges est un animal de montagne d''Amérique du Nord au pelage blanc et épais. Elle grimpe avec aisance sur les pentes raides. Dans ton zoo, elle fait la démonstration de ses talents d''escaladeuse sur des structures rocheuses et, de là-haut, elle surveille tout ce qui se passe.'),
       (93396, 719, 'es', 'Cabra de las nieves', 'La cabra de las nieves es un animal de montaña de América del Norte con un pelaje denso y blanco. Trepa con seguridad por laderas empinadas. En tu zoológico, muestra sus habilidades trepadoras en estructuras rocosas y, desde allí, lo tiene todo a la vista.'),
       (93397, 720, 'nl', 'Siberische tijger', 'De Siberische tijger is de grootste ondersoort van de tijger en leeft in de bossen van Rusland. Zijn dikke vacht beschermt hem tegen de kou. In jouw dierentuin ziet hij er bijzonder indrukwekkend uit wanneer hij door de met sneeuw bedekte verblijven loopt.'),
       (93398, 720, 'fr', 'Tigre de Sibérie', 'Le tigre de Sibérie est la plus grande sous-espèce de tigre et vit dans les forêts de Russie. Son pelage épais le protège du froid. Dans ton zoo, il est particulièrement impressionnant lorsqu''il arpente ses enclos enneigés.'),
       (93399, 720, 'es', 'Tigre siberiano', 'El tigre siberiano es la subespecie de tigre más grande y vive en los bosques de Rusia. Su espeso pelaje le protege del frío. En tu zoológico resulta especialmente imponente cuando se pasea por los recintos nevados.'),
       (93400, 721, 'nl', 'Tibetaanse vos', 'De Tibetaanse vos heeft een karakteristieke, hoekige kop en leeft in hooggelegen gebieden. Zijn dichte vacht beschermt hem tegen wind en kou. In jouw dierentuin valt hij op door zijn bijzondere gezicht en zijn rustige karakter.'),
       (93401, 721, 'fr', 'renard du Tibet', 'Le renard du Tibet a une tête aux traits anguleux caractéristiques et vit dans les régions de haute montagne. Son pelage épais le protège du vent et du froid. Dans ton zoo, il se distingue par son visage particulier et son caractère calme.'),
       (93402, 721, 'es', 'Zorro del Tíbet', 'El zorro del Tíbet tiene una cabeza característicamente angulosa y vive en regiones de alta montaña. Su denso pelaje le protege del viento y del frío. En tu zoológico llama la atención por su peculiar rostro y su carácter tranquilo.'),
       (93403, 722, 'nl', 'Vraatzak', 'De veelvraat is een krachtige marter met een indrukwekkend uithoudingsvermogen. Hij doorkruist uitgestrekte gebieden en is een behendige aaseter en jager. In jouw dierentuin laat hij zien dat er in een relatief klein lichaam veel temperament kan schuilen.'),
       (93404, 722, 'fr', 'glouton', 'Le glouton est une martre robuste dotée d''une endurance impressionnante. Il parcourt de vastes territoires et est à la fois un charognard et un chasseur habile. Dans ton zoo, il prouve qu''un corps relativement petit peut receler beaucoup de fougue.'),
       (93405, 722, 'es', 'Glotón', 'El glotón es una martilla robusta con una resistencia impresionante. Recorre grandes extensiones de terreno y es un hábil carroñero y cazador. En tu zoológico demuestra que un cuerpo relativamente pequeño puede albergar mucho temperamento.'),
       (93406, 723, 'nl', 'Witwanggans', 'De witwanggans heeft een opvallende zwart-witte koptekening. Ze broedt in het hoge noorden en overwintert verder naar het zuiden. In jouw dierentuin vormt ze in de vijvers een levendige, kwakende groep.'),
       (93407, 723, 'fr', 'Oie à joues blanches', 'L''oie à joues blanches présente un motif noir et blanc caractéristique sur la tête. Elle niche dans le Grand Nord et hiverne plus au sud. Dans ton zoo, elle forme un groupe animé et caquetant autour des bassins.'),
       (93408, 723, 'es', 'Ganso de mejillas blancas', 'El ganso de mejillas blancas tiene un característico patrón de colores blanco y negro en la cabeza. Cría en el extremo norte y pasa el invierno más al sur. En tu zoológico forma un grupo animado y ruidoso en los estanques.'),
       (93409, 724, 'nl', 'Yak', 'De jak is een rund uit de hooglanden van Azië met een dikke, lange vacht. Hij is perfect aangepast aan de ijle lucht en de kou. In jouw dierentuin lijkt hij wel een gezellige vachtberg die rustig door het verblijf loopt.'),
       (93410, 724, 'fr', 'Yak', 'Le yack est un bovin originaire des hautes altitudes d''Asie, doté d''une fourrure épaisse et longue. Il est parfaitement adapté à l''air raréfié et au froid. Dans ton zoo, il ressemble à une montagne de fourrure douillette qui se déplace tranquillement dans son enclos.'),
       (93411, 724, 'es', 'Yak', 'El yak es un bovino de las zonas altas de Asia con un pelaje denso y largo. Está perfectamente adaptado al aire enrarecido y al frío. En tu zoológico parece una acogedora montaña de pelaje que se desplaza tranquilamente por el recinto.'),
       (93412, 725, 'nl', 'Zobel', 'De sabelmarter is een kleine marter met een zeer zachte, zeer gewilde vacht. Hij leeft in Noordse bossen en is een behendige jager. In jouw dierentuin beweegt hij zich behendig en nieuwsgierig, meestal in de buurt van schuilplaatsen.'),
       (93413, 725, 'fr', 'zibeline', 'La zibeline est une petite martre à la fourrure très douce et très prisée. Elle vit dans les forêts nordiques et est une chasseuse habile. Dans ton zoo, elle se déplace avec agilité et curiosité, le plus souvent près de ses cachettes.'),
       (93414, 725, 'es', 'Zobel', 'La marta cibelina es un pequeño animal de la familia de las martas con un pelaje muy suave y muy codiciado. Vive en los bosques nórdicos y es una hábil cazadora. En tu zoológico se mueve con agilidad y curiosidad, sobre todo cerca de sus escondites.'),
       (93415, 801, 'nl', 'Amazone-dolfijn', 'De Amazone-dolfijn, ook wel ‘boto’ genoemd, heeft een roze kleur in het troebele rivierwater. Hij leeft in de rivieren van het Amazonebekken. In jouw dierentuin betovert hij de bezoekers met zijn speelse karakter en zijn bijzondere kleurnuances.'),
       (93416, 801, 'fr', 'Dauphin de l''Amazone', 'Le dauphin de l''Amazone, également appelé « boto », se distingue par sa couleur rose dans les eaux troubles du fleuve. Il vit dans les fleuves du bassin amazonien. Dans ton zoo, il enchante les visiteurs par son caractère enjoué et ses nuances de couleur particulières.'),
       (93417, 801, 'es', 'Delfín del Amazonas', 'El delfín del Amazonas, también conocido como «boto», presenta una coloración rosada en las turbias aguas del río. Vive en los ríos de la cuenca del Amazonas. En tu zoológico, cautiva a los visitantes con su carácter juguetón y sus singulares matices de color.'),
       (93418, 802, 'nl', 'bandrobbe', 'De bandrob heeft een lichte ring rond haar lichaam, waaraan ze haar naam te danken heeft. Ze leeft in de arctische zeeën en gebruikt ijsvlakten om uit te rusten. In jouw dierentuin zwemt ze elegant door het bassin en rust ze graag uit op koele rotsen.'),
       (93419, 802, 'fr', 'phoque à bande', 'Le phoque annelé porte un anneau clair autour du corps, d’où son nom. Il vit dans les mers arctiques et utilise les étendues de glace pour se reposer. Dans ton zoo, il nage avec élégance dans son bassin et aime se reposer sur des rochers frais.'),
       (93420, 802, 'es', 'foca de banda', 'La foca anillada tiene un anillo claro alrededor del cuerpo, que le da nombre. Vive en los mares árticos y utiliza las superficies de hielo para descansar. En tu zoológico, nada con elegancia por el estanque y le gusta descansar sobre rocas frescas.'),
       (93421, 803, 'nl', 'Belugawal', 'De beloega is een witte walvis uit de Noordelijke IJszee. Hij kan communiceren met een breed scala aan geluiden en wordt soms ook wel de ‘kanarie van de zee’ genoemd. In jouw dierentuin fascineert hij met zijn zachtaardige uitstraling en vriendelijke gelaatstrekken.'),
       (93422, 803, 'fr', 'Belugawal', 'La baleine blanche est une baleine originaire de la mer Arctique. Elle est capable de communiquer à l''aide d''une grande variété de sons et est parfois surnommée « le canari des mers ». Dans ton zoo, elle fascine par son allure douce et ses traits sympathiques.'),
       (93423, 803, 'es', 'Belugawal', 'La ballena beluga es una ballena blanca del mar Ártico. Es capaz de comunicarse mediante una gran variedad de sonidos y, a veces, se la conoce como «el canario de los mares». En tu zoológico, fascina por su aspecto apacible y sus rasgos faciales amables.'),
       (93424, 804, 'nl', 'Brillenpelikaan', 'De brilpelikaan heeft een lichte tekening rond de ogen die aan een bril doet denken. Hij is een behendige visser en gebruikt zijn keelzak om prooien te vangen. In jouw dierentuin maakt hij indruk terwijl hij in het waterbassin aan het vissen is.'),
       (93425, 804, 'fr', 'Pélican à lunettes', 'Le pélican à lunettes présente un motif clair autour des yeux qui rappelle des lunettes. C''est un pêcheur habile qui utilise sa poche gulaire pour attraper ses proies. Dans ton zoo, il impressionne les visiteurs lorsqu''il pêche dans le bassin.'),
       (93426, 804, 'es', 'Pelícano de anteojos', 'El pelícano de anteojos tiene un dibujo claro alrededor de los ojos que recuerda a unas gafas. Es un hábil pescador y utiliza su bolsa gorguera para capturar presas. En tu zoológico, impresiona a los visitantes cuando pesca en el estanque.'),
       (93427, 805, 'nl', 'Brilpinguïn', 'De brilpinguïn dankt zijn naam aan een lichte tekening rond zijn ogen. Hij leeft aan de kusten van Zuid-Afrika. In jouw dierentuin zorgt hij met zijn waggelende bewegingen en elegante duikvluchten voor een vrolijke sfeer.'),
       (93428, 805, 'fr', 'Pingouin à lunettes', 'Le manchot à lunettes doit son nom à une tache claire autour des yeux. Il vit sur les côtes sud-africaines. Dans ton zoo, il met tout le monde de bonne humeur avec sa démarche dandinante et ses plongeons élégants.'),
       (93429, 805, 'es', 'Pingüino con gafas', 'El pingüino de gafas debe su nombre a unas manchas claras que tiene alrededor de los ojos. Vive en las costas de Sudáfrica. En tu zoológico, te alegra el día con sus movimientos contoneados y sus elegantes zambullidas.'),
       (93430, 806, 'nl', 'Bultrug', 'De bultrug staat bekend om zijn spectaculaire sprongen en gezang. Hij legt grote afstanden af tussen zijn voedsel- en voortplantingsgebieden. In jouw dierentuin staat hij symbool voor de fascinatie voor de grote oceanen.'),
       (93431, 806, 'fr', 'baleine à bosse', 'La baleine à bosse est connue pour ses sauts spectaculaires et ses chants. Elle parcourt de longues distances entre ses zones d''alimentation et de reproduction. Dans ton zoo, elle incarne la fascination exercée par les grands océans.'),
       (93432, 806, 'es', 'ballena jorobada', 'La ballena jorobada es conocida por sus espectaculares saltos y sus cantos. Recorre largas distancias entre sus zonas de alimentación y reproducción. En tu zoológico, representa la fascinación que despiertan los grandes océanos.'),
       (93433, 808, 'nl', 'Dugong', 'De doejong wordt ook wel ‘zeekoe’ genoemd en voedt zich met zeegras. Hij leeft in warme kustwateren. In jouw dierentuin glijdt hij rustig door het water en straalt hij een vredige sfeer uit.'),
       (93434, 808, 'fr', 'Dugong', 'Le dugong, également appelé « vache marine », se nourrit d''algues marines. Il vit dans les eaux côtières chaudes. Dans ton zoo, il glisse tranquillement dans l''eau et dégage une atmosphère paisible.'),
       (93435, 808, 'es', 'Dugongo', 'El dugongo, también conocido como «vaca marina», se alimenta de algas marinas. Vive en aguas costeras cálidas. En tu zoo, se desliza tranquilamente por el agua y transmite una sensación de paz.'),
       (93436, 811, 'nl', 'Fransenschildpad', 'De franjeschildpad heeft een plat lichaam en franjachtige huidflappen. Ze is uitstekend gecamoufleerd en leeft in zoet water. In jouw dierentuin lijkt ze op een levend blad dat in het water drijft.'),
       (93437, 811, 'fr', 'Tortue à franges', 'La tortue à franges a un corps plat et des lambeaux de peau effilochés. Elle est parfaitement camouflée et vit en eau douce. Dans ton zoo, elle ressemble à une feuille vivante flottant sur l''eau.'),
       (93438, 811, 'es', 'Tortuga de flecos', 'La tortuga de flecos tiene el cuerpo aplanado y unos pliegues de piel con flecos. Está magníficamente camuflada y vive en agua dulce. En tu zoológico parece una hoja viva que flota en el agua.'),
       (93439, 812, 'nl', 'Ganges-gaviaal', 'De Gangesgaviaal is een viseter met een lange, smalle snavel vol tanden. Hij leeft in rivieren op het Indiase subcontinent. In jouw dierentuin zwemt hij rustig rond en laat daarbij zijn indrukwekkende gebit zien.'),
       (93440, 812, 'fr', 'gavial du Gange', 'Le gavial du Gange est un poisson-mangeur doté d''un long bec étroit parsemé de dents. Il vit dans les fleuves du sous-continent indien. Dans ton zoo, il nage tranquillement tout en exhibant son impressionnante dentition.'),
       (93441, 812, 'es', 'caviar del Ganges', 'El gavial del Ganges es un animal piscívoro con un pico largo y estrecho lleno de dientes. Vive en los ríos del subcontinente indio. En tu zoológico nada tranquilamente, mostrando su impresionante dentadura.'),
       (93442, 814, 'nl', 'Hamerhaai', 'De hamerhaai heeft een karakteristieke, brede kop met zijdelings geplaatste ogen. Deze vorm helpt hem bij het oriënteren en het zoeken naar prooi. In jouw dierentuin zwemt hij majestueus zijn rondjes en zorgt hij voor kippenvelmomenten.'),
       (93443, 814, 'fr', 'Requin-marteau', 'Le requin-marteau se caractérise par une tête élargie et des yeux décalés sur les côtés. Cette morphologie l''aide à s''orienter et à repérer ses proies. Dans ton zoo, il nage majestueusement en cercles et te donne la chair de poule.'),
       (93444, 814, 'es', 'Tiburón martillo', 'El tiburón martillo tiene una cabeza característicamente ancha con los ojos desplazados hacia los lados. Esta forma le ayuda a orientarse y a buscar presas. En tu zoológico, nada majestuosamente en círculos y te pone la piel de gallina.'),
       (93445, 815, 'nl', 'Irawadi-dolfijn', 'De Irrawaddy-dolfijn heeft een ronde kop en leeft in riviermondingen en kustwateren van Azië. Hij is nogal schuw en zeldzaam. In jouw dierentuin is hij een stille, maar heel bijzondere zeebewoner.'),
       (93446, 815, 'fr', 'dauphin de l''Irrawaddy', 'Le dauphin de l''Irrawaddy a une tête arrondie et vit dans les estuaires et les eaux côtières d''Asie. Il est plutôt timide et rare. Dans ton zoo, c''est un habitant marin discret, mais très particulier.'),
       (93447, 815, 'es', 'Delfín del Iravadi', 'El delfín del Irrawaddy tiene la cabeza redondeada y vive en las desembocaduras de los ríos y en las aguas costeras de Asia. Es bastante tímido y poco común. En tu zoológico es un habitante marino tranquilo, pero muy especial.'),
       (93448, 816, 'nl', 'Californische bruinvis', 'De Californische bruinvis is een van de kleinste walvissen en leeft aan de westkust van Noord-Amerika. Hij valt niet op en blijft vaak dicht bij de kust. In jouw dierentuin zwemt hij rustig rond en laat hij zien dat groot niet altijd groot hoeft te zijn.'),
       (93449, 816, 'fr', 'Marsouin de Californie', 'Le marsouin de Californie est l''une des plus petites espèces de cétacés et vit sur la côte ouest de l''Amérique du Nord. Discret, il reste souvent près des côtes. Dans ton zoo, il nage tranquillement et prouve que la grandeur ne se mesure pas toujours à la taille.'),
       (93450, 816, 'es', 'Marsopa de California', 'La marsopa californiana es una de las ballenas más pequeñas y vive en la costa occidental de Norteamérica. Es discreta y suele permanecer cerca de la costa. En tu zoológico nada tranquilamente de un lado a otro y demuestra que lo grande no siempre tiene por qué ser grande.'),
       (93451, 817, 'nl', 'Klappmuts', 'De klapmuts is een zeehondensoort waarvan de mannetjes een opblaasbare bult op hun kop hebben. Die gebruiken ze tijdens de paring als indrukwekkend spektakel. In jouw dierentuin zorgt dit bijzondere kenmerk voor veel verbaasde gezichten.'),
       (93452, 817, 'fr', 'Casquette à visière rabattable', 'La casquette rabattable est une espèce de phoque dont les mâles possèdent une protubérance gonflable sur la tête. Ils s''en servent lors de la parade nuptiale pour faire forte impression. Dans ton zoo, cette particularité suscite beaucoup d''étonnement.'),
       (93453, 817, 'es', 'Gorra plegable', 'La foca de gorro es una especie de foca cuyos machos presentan una protuberancia inflable en la cabeza. La utilizan durante el cortejo como un impresionante número de exhibición. En tu zoológico, esta característica tan especial provoca muchas miradas de asombro.'),
       (93454, 818, 'nl', 'manenrob', 'De manenrob heeft een dichte vachtkraag die op een manen lijkt. Ze leeft aan de kusten van het zuidelijk halfrond. In jouw dierentuin ligt ze graag in de zon en laat ze tijdens het voeren zien hoe behendig ze in het water is.'),
       (93455, 818, 'fr', 'phoque à crinière', 'Le phoque à crinière possède un col de fourrure épais qui ressemble à une crinière. Il vit sur les côtes de l''hémisphère sud. Dans ton zoo, il aime se prélasser au soleil et, lors des repas, il fait preuve d''une grande agilité dans l''eau.'),
       (93456, 818, 'es', 'foca de melena', 'La foca de melena tiene un collar de pelaje denso que parece una melena. Vive en las costas del hemisferio sur. En tu zoológico le gusta descansar al sol y, a la hora de comer, demuestra su agilidad en el agua.'),
       (93457, 819, 'nl', 'Mandarijneend', 'De mandarijneend is een van de kleurrijkste eendensoorten ter wereld. Het mannetje heeft tijdens de paartijd een spectaculair verenkleed. In jouw dierentuin lijkt hij wel een kleine, levende verfdoos op het water.'),
       (93458, 819, 'fr', 'canard mandarin', 'Le canard mandarin est l''une des espèces de canards les plus colorées au monde. Pendant la période de parade nuptiale, le mâle arbore un plumage spectaculaire. Dans ton zoo, il ressemble à une petite palette de couleurs vivante sur l''eau.'),
       (93459, 819, 'es', 'Pato mandarín', 'El pato mandarín es una de las especies de patos más coloridas del mundo. Durante la época de apareamiento, el macho luce un plumaje espectacular. En tu zoológico parece una pequeña caja de colores viviente sobre el agua.'),
       (93460, 820, 'nl', 'Mississippi-alligator', 'De Mississippi-alligator is een grote krokodilachtige uit Noord-Amerika. Hij leeft in moerassen en rivieren en kan erg oud worden. In jouw dierentuin ligt hij graag ogenschijnlijk traag in het water – maar staat hij altijd klaar voor snelle bewegingen.'),
       (93461, 820, 'fr', 'Alligator du Mississippi', 'L''alligator du Mississippi est un grand crocodilien d''Amérique du Nord. Il vit dans les marécages et les rivières et peut atteindre un âge très avancé. Dans ton zoo, il aime se prélasser dans l''eau, l''air indolent, mais il est toujours prêt à se déplacer rapidement.'),
       (93462, 820, 'es', 'Caimán del Misisipi', 'El caimán del Misisipi es un gran cocodrilo de América del Norte. Vive en pantanos y ríos y puede llegar a vivir muchos años. En tu zoológico le gusta permanecer en el agua, aparentemente indolente, pero siempre listo para moverse rápidamente.'),
       (93463, 822, 'nl', 'Orca', 'De orka, ook wel zwaardwalvis genoemd, is een intelligent toproofdier van de oceanen. Hij leeft in familiegroepen en jaagt in teamverband. In jouw dierentuin maakt hij indruk met zijn krachtige zwembewegingen en zijn slimme speelsheid.'),
       (93464, 822, 'fr', 'Orque', 'L''orque, également appelé « orque à nageoire caudale en forme d''épée », est un prédateur intelligent au sommet de la chaîne alimentaire océanique. Il vit en groupes familiaux et chasse en équipe. Dans ton zoo, il impressionne par ses mouvements de nage puissants et son espièglerie intelligente.'),
       (93465, 822, 'es', 'Orca', 'La orca, también conocida como «orca», es un depredador inteligente y de primer orden de los océanos. Vive en grupos familiares y caza en equipo. En tu zoológico impresiona por sus potentes movimientos al nadar y su inteligente alegría.'),
       (93466, 823, 'nl', 'papegaaiduiker', 'De papegaaiduiker is een kleine zeevogel met een kleurrijke snavel. Hij broedt in holtes in de grond aan steile kusten. In jouw dierentuin lijkt hij met zijn kleurrijke snavel bijna op een stripvogel.'),
       (93467, 823, 'fr', 'Plongeon à bec de perroquet', 'Le macareux moine est un petit oiseau marin au bec coloré. Il niche dans des cavités creusées dans la terre, sur des côtes escarpées. Dans ton zoo, avec son bec coloré, il ressemble presque à un oiseau de bande dessinée.'),
       (93468, 823, 'es', 'colimbo papagayo', 'El frailecillo es un pequeño ave marina con un pico de colores. Anida en madrigueras excavadas en acantilados escarpados. En tu zoológico, con su pico de colores, parece casi un pájaro de cómic.'),
       (93469, 824, 'nl', 'Pracht-eend', 'Het mannetje van de pracht-eend heeft een spectaculair, kleurrijk verenkleed op zijn kop. Deze eend broedt in arctische gebieden. In jouw dierentuin zorgt hij met zijn opvallende uiterlijk voor veel kleur in de koude bassins.'),
       (93470, 824, 'fr', 'Canard à tête dorée', 'Le canard à crête arbore, chez le mâle, un plumage spectaculaire et coloré sur la tête. Il niche dans les régions arctiques. Dans ton zoo, son apparence singulière apporte beaucoup de couleur dans les bassins froids.'),
       (93471, 824, 'es', 'Pato de la época dorada', 'El pato real tiene, en el caso del macho, un espectacular y colorido plumaje en la cabeza. Cría en las regiones árticas. En tu zoológico, con su curioso aspecto, aporta mucho color a los estanques fríos.'),
       (93472, 825, 'nl', 'riemvis', 'De riemvis is een zeer lange, lintvormige diepzeevis. Hij wordt zelden gezien en vormt de basis voor talrijke zeelegendes. In jouw dierentuin laat hij zien hoe mysterieus de diepzee kan zijn.'),
       (93473, 825, 'fr', 'poisson-courroie', 'Le poisson-courroie est un poisson des grands fonds très long, en forme de ruban. On l''aperçoit rarement et il est à l''origine de nombreuses légendes marines. Dans ton zoo, il montre à quel point les grands fonds peuvent être mystérieux.'),
       (93474, 825, 'es', 'pez correa', 'El pez cinta es un pez de aguas profundas muy largo y con forma de cinta. Rara vez se le ve y es protagonista de muchas leyendas marinas. En tu acuario, nos muestra lo misterioso que puede ser el fondo del mar.'),
       (93475, 826, 'nl', 'Reuzenmanta', 'De reuzenmanta is een grote rog met een majestueuze spanwijdte. Hij filtert plankton uit het water. In jouw dierentuin glijdt hij zwevend door het bassin en lijkt hij wel een onderwaterzweefvliegtuig.'),
       (93476, 826, 'fr', 'raie manta géante', 'La raie manta géante est une grande raie à l''envergure majestueuse. Elle filtre le plancton présent dans l''eau. Dans ton zoo, elle glisse en planant dans le bassin et ressemble à un planeur sous-marin.'),
       (93477, 826, 'es', 'Manta gigante', 'La manta gigante es una raya de gran tamaño con una envergadura majestuosa. Se alimenta filtrando el plancton del agua. En tu zoológico, se desliza flotando por el tanque y parece un planeador submarino.'),
       (93478, 827, 'nl', 'Reuzenzoetwaterrog', 'De reusachtige zoetwaterrog leeft in de grote rivieren van Azië. Hij kan enorm groot worden, maar is toch vaak moeilijk te zien. In jouw dierentuin is hij een indrukwekkende, maar rustige reus.'),
       (93479, 827, 'fr', 'Raie géante d''eau douce', 'La raie géante d''eau douce vit dans les grands fleuves d''Asie. Elle peut atteindre des tailles impressionnantes, mais reste souvent difficile à repérer. Dans ton zoo, c''est un géant impressionnant, mais paisible.'),
       (93480, 827, 'es', 'Raya gigante de agua dulce', 'La raya gigante de agua dulce habita en los grandes ríos de Asia. Puede alcanzar tamaños enormes y, sin embargo, a menudo es difícil de avistar. En tu zoológico es un gigante impresionante, pero tranquilo.'),
       (93481, 828, 'nl', 'Rifmanta', 'De rifmanta is kleiner dan de reuzenmanta, maar net zo elegant. Hij leeft bij koraalriffen en filtert plankton. In je aquarium zwemt hij in elegante cirkels en geeft hij het aquarium een tropische sfeer.'),
       (93482, 828, 'fr', 'Raie de récif', 'La raie de récif est plus petite que la raie géante, mais tout aussi élégante. Elle vit dans les récifs coralliens et se nourrit de plancton par filtration. Dans ton zoo, elle décrit d''élégants cercles et apporte une touche tropicale à l''aquarium.'),
       (93483, 828, 'es', 'Manta de arrecife', 'La manta de arrecife es más pequeña que la manta gigante, pero igual de elegante. Vive en los arrecifes de coral y se alimenta filtrando plancton. En tu acuario, traza elegantes círculos y le da un toque tropical.'),
       (93484, 829, 'nl', 'Rode reuzenoctopus', 'De rode reuzenoctopus is een grote inktvis met acht armen. Ze is slim en nieuwsgierig. In jouw dierentuin lost ze graag voedselpuzzels op en laat ze zien hoe behendig tentakels kunnen zijn.'),
       (93485, 829, 'fr', 'Poulpe géant rouge', 'La pieuvre géante rouge est un grand céphalopode doté de huit bras. Elle est intelligente et curieuse. Dans ton zoo, elle adore les casse-têtes alimentaires et montre à quel point ses tentacules peuvent être agiles.'),
       (93486, 829, 'es', 'Pulpo gigante rojo', 'El pulpo gigante rojo es un gran cefalópodo con ocho tentáculos. Es inteligente y curioso. En tu zoológico le encanta resolver acertijos alimenticios y demuestra lo hábiles que pueden ser los tentáculos.'),
       (93487, 830, 'nl', 'Rondstaartzeekoe', 'De rondstaartzeekoe is een vreedzame planteneter die in ondiepe wateren leeft. Ze glijdt langzaam door het water en maakt een zeer rustige indruk. In jouw aquarium is ze een rustige, sympathieke onderwaterbewoner.'),
       (93488, 830, 'fr', 'Vache marine à queue ronde', 'La vache de mer à queue ronde est un herbivore paisible des eaux peu profondes. Elle glisse lentement dans l''eau et semble très sereine. Dans ton zoo, c''est un habitant sous-marin calme et sympathique.'),
       (93489, 830, 'es', 'Vaca marina de cola redonda', 'La vaca marina de cola redonda es un herbívoro pacífico de las aguas poco profundas. Se desliza lentamente por el agua y da la impresión de ser muy tranquila. En tu acuario es un habitante submarino tranquilo y simpático.'),
       (93490, 832, 'nl', 'Salmaa-gestreepte zeehond', 'De Salmaa-ringrob is een kleine rotssoort met ringvormige patronen in de vacht. Hij leeft in arctische wateren. In jouw dierentuin laat hij zien hoe divers de wereld van de rotsen is.'),
       (93491, 832, 'fr', 'Phoque annelé de Salmaa', 'Le phoque annelé de Salmaa est une petite espèce de phoque dont le pelage présente des motifs annelés. Il vit dans les eaux arctiques. Dans ton zoo, il illustre toute la diversité du monde des phoques.'),
       (93492, 832, 'es', 'Foca anillada de Salmaa', 'La foca anillada de Salmaa es una especie de foca de pequeño tamaño con un patrón anular en el pelaje. Vive en aguas árticas. En tu zoológico muestra lo variado que es el mundo de las focas.'),
       (93493, 833, 'nl', 'vogelbekdier', 'Het vogelbekdier is een unieke eierlegger onder de zoogdieren. Het heeft een eendenbek, een beverstaart en zwemvliezen. In jouw dierentuin is het een echte exoot en het favoriete raadsel van veel bezoekers.'),
       (93494, 833, 'fr', 'ornithorynque', 'L''ornithorynque est un mammifère ovipare unique en son genre. Il possède un bec de canard, une queue de castor et des palmures. Dans ton zoo, c''est une véritable curiosité et l''une des attractions préférées de nombreux visiteurs.'),
       (93495, 833, 'es', 'Ornitorrinco', 'El ornitorrinco es un mamífero único entre los que ponen huevos. Tiene pico de pato, cola de castor y membranas interdigitales. En tu zoológico es una auténtica rareza y el acertijo favorito de muchos visitantes.'),
       (93496, 834, 'nl', 'Zwarthalszwaan', 'De zwartnekzwaan heeft, zoals de naam al zegt, een zwarte nek en een wit lichaam. Hij leeft in Zuid-Amerika. In jouw dierentuin vormt hij een elegant contrast met de witte zwanen.'),
       (93497, 834, 'fr', 'cygne à cou noir', 'Comme son nom l''indique, le cygne à cou noir a le cou noir et le corps blanc. Il vit en Amérique du Sud. Dans ton zoo, il offre un contraste élégant avec les cygnes blancs.'),
       (93498, 834, 'es', 'Cisne de cuello negro', 'El cisne de cuello negro tiene, como su nombre indica, el cuello negro y el cuerpo blanco. Vive en Sudamérica. En tu zoológico, crea un elegante contraste con los cisnes blancos.'),
       (93499, 835, 'nl', 'zeeolifant', 'De zeeolifant is de grootste zeehondensoort en heeft, bij het mannetje, een slurfachtige neus. Hij leeft aan koele kusten en kan diep duiken. In jouw dierentuin maakt hij met zijn omvang en luide kreten een bijzonder indrukwekkende indruk.'),
       (93500, 835, 'fr', 'éléphant de mer', 'L''éléphant de mer est la plus grande espèce de phoque ; chez le mâle, le nez ressemble à une trompe. Il vit sur les côtes froides et peut plonger à de grandes profondeurs. Dans ton zoo, il est particulièrement impressionnant par sa taille et ses cris puissants.'),
       (93501, 835, 'es', 'elefante marino', 'El elefante marino es la especie de foca más grande y los machos tienen una protuberancia nasal similar a una trompa. Vive en costas frías y es capaz de sumergirse a gran profundidad. En tu zoológico resulta especialmente impresionante por su tamaño y sus fuertes gritos.'),
       (93502, 836, 'nl', 'Zee-luipaard', 'De zee-luipaard is een groot, roofzuchtig dier uit de familie van de zeehonden dat op Antarctica leeft. Hij heeft een gevlekte vacht die doet denken aan die van een luipaard. In jouw dierentuin laat hij de wilde kant van de poolzeeën zien.'),
       (93503, 836, 'fr', 'Léopard de mer', 'Le léopard de mer est un grand prédateur de l''Antarctique, apparenté aux phoques. Son pelage tacheté rappelle celui du léopard. Dans ton zoo, il incarne le côté sauvage des mers polaires.'),
       (93504, 836, 'es', 'Leopardo marino', 'La foca leopardo es un gran animal depredador de la Antártida, emparentado con las focas. Tiene un pelaje manchado que recuerda al de los leopardos. En tu zoológico muestra el lado salvaje de los océanos polares.'),
       (93505, 837, 'nl', 'zeeotter', 'De zeeotter staat erom bekend dat hij op zijn rug in het water drijft als hij rust. Hij gebruikt stenen als gereedschap om schelpen open te breken. In jouw dierentuin is hij een speelse publiekslieveling.'),
       (93506, 837, 'fr', 'loutre de mer', 'La loutre de mer est connue pour flotter sur le dos lorsqu''elle se repose dans l''eau. Elle utilise des pierres comme outils pour casser les coquillages. Dans ton zoo, c''est un animal espiègle très apprécié du public.'),
       (93507, 837, 'es', 'nutria marina', 'La nutria marina es conocida por flotar boca arriba en el agua cuando descansa. Utiliza piedras como herramientas para romper las conchas. En tu zoológico es una mascota juguetona y muy querida por el público.'),
       (93508, 838, 'nl', 'Tijgerhaai', 'De tijgerhaai is een grote haai met strepen op zijn lichaam. Hij is niet erg kieskeurig wat eten betreft. In jouw dierentuin zwemt hij majestueus rond en maakt hij indruk met zijn kracht.'),
       (93509, 838, 'fr', 'Requin-tigre', 'Le requin-tigre est un grand requin au corps rayé. Il n''est pas très difficile en matière de nourriture. Dans ton zoo, il nage majestueusement en rond et impressionne par sa force.'),
       (93510, 838, 'es', 'Tiburón tigre', 'El tiburón tigre es un tiburón de gran tamaño con un patrón de rayas en el cuerpo. No es muy exigente a la hora de alimentarse. En tu zoológico, nada majestuosamente de un lado a otro e impresiona por su fuerza.'),
       (93511, 839, 'nl', 'Trompetzwaan', 'De trompetzwaan is een grote zwaansoort met een diepe, trompetachtige roep. Hij komt voor in Noord-Amerika. In jouw dierentuin zorgt zijn gezang voor bijzondere akoestische momenten.'),
       (93512, 839, 'fr', 'Cygne à bec de trompette', 'Le cygne trompette est une grande espèce de cygne au cri grave, semblable à celui d''une trompette. Il vit en Amérique du Nord. Dans ton zoo, son chant offre des moments acoustiques exceptionnels.'),
       (93513, 839, 'es', 'Cisne trompeta', 'El cisne trompetero es una especie de cisne de gran tamaño con un canto grave, similar al sonido de una trompeta. Habita en América del Norte. En tu zoológico, su canto ofrece momentos acústicos muy especiales.'),
       (93514, 840, 'nl', 'Walrus', 'De walrus is een groot zeezoogdier met enorme slagtanden. Hij houdt van ijsschotsen en rust graag in groepen. In jouw dierentuin zorgt hij met zijn geluiden en zijn uiterlijk voor een arctische sfeer.'),
       (93515, 840, 'fr', 'morse', 'Le morse est un grand mammifère marin doté d''énormes défenses. Il adore les banquises et aime se reposer en groupe. Dans ton zoo, ses cris et son apparence apportent une touche arctique.'),
       (93516, 840, 'es', 'morsa', 'La morsa es un mamífero marino de gran tamaño con colmillos enormes. Le encantan los témpanos de hielo y le gusta descansar en grupo. En tu zoológico, con sus sonidos y su aspecto, aporta un toque ártico.'),
       (93517, 841, 'nl', 'Wandel-albatros', 'De wanderalbatros heeft de grootste spanwijdte van alle vogels. Hij kan urenlang boven de zee zweven zonder veel met zijn vleugels te slaan. In jouw dierentuin staat hij symbool voor de vrijheid van de wereldzeeën.'),
       (93518, 841, 'fr', 'Albatros migrateur', 'L''albatros des mers possède la plus grande envergure de tous les oiseaux. Il peut planer pendant des heures au-dessus de la mer sans battre des ailes. Dans ton zoo, il symbolise la liberté des océans.'),
       (93519, 841, 'es', 'Albatros migratorio', 'El albatros errante tiene la mayor envergadura de todas las aves. Puede planear sobre el mar durante horas sin batir mucho las alas. En tu zoológico simboliza la libertad de los océanos.'),
       (93520, 842, 'nl', 'Witte haai', 'De witte haai is een van de bekendste haaien en een toproofdier van de oceanen. Hij heeft een krachtig gebit en scherpe zintuigen. In jouw dierentuin zorgt hij zowel voor kippenvel als voor bewondering.'),
       (93521, 842, 'fr', 'Requin blanc', 'Le grand requin blanc est l''un des requins les plus connus et l''un des principaux prédateurs des océans. Il possède une mâchoire puissante et des sens très développés. Dans ton zoo, il suscite à la fois la frayeur et l''admiration.'),
       (93522, 842, 'es', 'Tiburón blanco', 'El tiburón blanco es uno de los tiburones más conocidos y uno de los principales depredadores de los océanos. Tiene una dentadura poderosa y unos sentidos muy agudos. En tu zoológico, provoca escalofríos y admiración a la vez.'),
       (93523, 843, 'nl', 'Lijstkrokodil', 'De estuariumkrokodil is een van de grootste krokodillen ter wereld. Hij leeft in riviermondingen en kustwateren in het Indo-Pacifische gebied. In jouw dierentuin ligt hij vaak roerloos in het water en lijkt hij wel een levend fossiel.'),
       (93524, 843, 'fr', 'Crocodile à crête', 'Le crocodile à crête est l''un des plus grands crocodiles du monde. Il vit dans les estuaires et les eaux côtières de la région indo-pacifique. Dans ton zoo, il reste souvent immobile dans l''eau et ressemble à un fossile vivant.'),
       (93525, 843, 'es', 'Cocodrilo de la costa', 'El cocodrilo de la cuenca del Indo es uno de los cocodrilos más grandes del mundo. Vive en las desembocaduras de los ríos y en las aguas costeras de la región del Indo-Pacífico. En tu zoológico suele permanecer inmóvil en el agua y parece un fósil viviente.'),
       (93526, 844, 'nl', 'Roze pelikaan', 'De roze pelikaan is een grote watervogel met een zachtroze verenkleed. Hij vist met zijn grote keelzak naar prooien. In jouw dierentuin glijdt hij elegant over het water en droogt hij zijn vleugels in de zon.'),
       (93527, 844, 'fr', 'Pélican rose', 'Le pélican rose est un grand oiseau aquatique au plumage d''un rose tendre. Il pêche ses proies à l''aide de sa grande poche gulaire. Dans ton zoo, il glisse avec élégance à la surface de l''eau et sèche ses ailes au soleil.'),
       (93528, 844, 'es', 'Pelícano rosa', 'El pelícano rosado es una gran ave acuática con un plumaje de un delicado color rosa. Utiliza su gran saco golar para pescar a sus presas. En tu zoológico, se desliza con elegancia sobre la superficie del agua y se seca las alas al sol.'),
       (93529, 1102, 'nl', 'Eigenlijke eendenontspanning', 'De streepdonder is een klein, egelachtig diertje uit Madagaskar. Hij heeft opvallende strepen op zijn rug en kan bij gevaar zijn stekels rechtop zetten. In jouw dierentuin is hij een exotische, nachtactieve bewoner.'),
       (93530, 1102, 'fr', 'Désencrage proprement dit', 'Le véritable tétou rayé est un petit animal ressemblant à un hérisson, originaire de Madagascar. Il arbore des rayures bien visibles sur le dos et peut hérisser ses piquants en cas de danger. Dans ton zoo, c''est un résident exotique et nocturne.'),
       (93531, 1102, 'es', 'Descripción detallada de la pato real', 'El verdadero erizo rayado es un pequeño animal de Madagascar parecido a un erizo. Tiene unas llamativas rayas en el lomo y, ante el peligro, puede erizar sus púas. En tu zoológico es un habitante exótico y nocturno.'),
       (93532, 1103, 'nl', 'vuursalamander', 'De vuursalamander is een opvallende, zwart-geel gekleurde amfibiesoort. Zijn kleur waarschuwt roofdieren voor zijn giftigheid. In jouw dierentuin leeft hij in vochtige terraria en laat hij zich graag zien na een kunstmatige „regenbui“.'),
       (93533, 1103, 'fr', 'salamandre', 'La salamandre tachetée est une espèce d''amphibien aux couleurs vives, noire et jaune. Sa couleur sert à avertir ses prédateurs de sa toxicité. Dans ton zoo, elle vit dans des terrariums humides et aime se montrer après une « averse » artificielle.'),
       (93534, 1103, 'es', 'Salamandra de fuego', 'La salamandra de fuego es una especie de anfibio que destaca por su llamativo color negro y amarillo. Su coloración advierte a los depredadores de su toxicidad. En tu zoológico vive en terrarios húmedos y le gusta salir después de un «aguacero» artificial.'),
       (93535, 1104, 'nl', 'Gevleugelde stokspringer', 'De gevleugelde stoksprinkhaan camoufleert zich perfect als een takje of blad. Pas als hij vliegt, zie je zijn vleugels. In jouw dierentuin is hij een meester in camouflage in het insectarium.'),
       (93536, 1104, 'fr', 'Sauterelle ailée', 'La sauterelle ailée se camoufle parfaitement en se faisant passer pour une branche ou une feuille. Ce n’est qu’en vol que l’on distingue ses ailes. Dans ton zoo, c’est la reine du camouflage dans l’insectarium.'),
       (93537, 1104, 'es', 'Saltamontes alado', 'El saltamontes alado se camufla a la perfección como una rama o una hoja. Solo cuando vuela se le ven las alas. En tu zoológico es un maestro del camuflaje en el insectario.'),
       (93538, 1105, 'nl', 'Goudboomklimmer', 'De goudboomklimmer is een kleine, felgekleurde kikker uit de tropen. Zijn felle kleuren waarschuwen voor zijn giftigheid. In je dierentuin schittert hij als een piepklein edelsteentje in het terrarium.'),
       (93539, 1105, 'fr', 'Grimpereau doré', 'La grenouille arborescente dorée est une petite grenouille aux couleurs vives originaire des régions tropicales. Ses couleurs vives signalent qu''elle est venimeuse. Dans ton zoo, elle brille comme une minuscule pierre précieuse dans son terrarium.'),
       (93540, 1105, 'es', 'Trepador dorado', 'La rana trepadora dorada es una rana pequeña de colores vivos procedente de los trópicos. Sus colores intensos advierten de su toxicidad. En tu zoológico brilla como una pequeña gema en el terrario.'),
       (93541, 1106, 'nl', 'hazelmuis', 'De hazelmuis is een klein knaagdier dat graag in heggen en bossen leeft. Hij houdt een winterslaap en is vooral in het warme seizoen actief. In jouw dierentuin laat hij zien hoe graag hij in vertakte takken klimt.'),
       (93542, 1106, 'fr', 'muscardin', 'Le muscardin est un petit rongeur qui aime vivre dans les haies et les forêts. Il hiberne et est surtout actif pendant la saison chaude. Dans ton zoo, il montre à quel point il aime grimper dans les branches noueuses.'),
       (93543, 1106, 'es', 'Ratón de avellano', 'El lirón es un pequeño roedor al que le gusta vivir en setos y bosques. Hiberna y está activo sobre todo durante la temporada cálida. En tu zoológico, demuestra su habilidad para trepar por ramas ramificadas.'),
       (93544, 1107, 'nl', 'Ili-fluithaas', 'De Ili-fluithaas is een klein zoogdier uit de berggebieden van China. Het is een zeldzame soort die pas laat werd ontdekt. In jouw dierentuin is het een kleine, maar voor kenners zeer bijzondere bewoner.'),
       (93545, 1107, 'fr', 'Lapin siffleur d''Ili', 'Le lièvre siffleur d''Ili est un petit mammifère originaire des régions montagneuses de Chine. Il est rare et n''a été découvert que récemment. Dans ton zoo, c''est un petit pensionnaire très particulier, apprécié des connaisseurs.'),
       (93546, 1107, 'es', 'Liebre silbadora de Ili', 'La liebre silbadora del Ili es un pequeño mamífero originario de las regiones montañosas de China. Es una especie rara y no se descubrió hasta hace poco. En tu zoológico es un habitante pequeño, pero muy especial para los entendidos.'),
       (93547, 1108, 'nl', 'Keizersschorpioen', 'De keizerschorpioen is een van de grootste schorpioenen ter wereld. Onder UV-licht geeft hij een mysterieus licht. In jouw dierentuin wekt hij in de terrariumsectie een gevoel van voorzichtig respect en fascinatie op.'),
       (93548, 1108, 'fr', 'Scorpion impérial', 'Le scorpion impérial est l''un des plus grands scorpions au monde. Sous la lumière UV, il brille d''un éclat mystérieux. Dans votre zoo, il suscite à la fois un respect prudent et une grande fascination dans l''espace dédié aux terrariums.'),
       (93549, 1108, 'es', 'Escorpión del Emperador', 'El escorpión emperador es uno de los escorpiones más grandes del mundo. Bajo la luz ultravioleta, brilla de forma misteriosa. En tu zoológico, despierta un respeto cauteloso y fascinación en la zona de los terrarios.'),
       (93550, 1109, 'nl', 'Kortkopglijbuidelrat', 'De kortkopglijbuidelrat is een kleine glijder met vliezen van huid. Hij zweeft van boom naar boom op zoek naar voedsel. In jouw dierentuin is hij een stille nachtelijke acrobaat.'),
       (93551, 1109, 'fr', 'phalanger à tête courte', 'Le phalanger à tête courte est un petit animal planeur doté de membranes de vol membraneuses. Il plane d''arbre en arbre à la recherche de nourriture. Dans ton zoo, c''est un acrobate nocturne silencieux.'),
       (93552, 1109, 'es', 'Canguro de cabeza corta', 'El petauro de cabeza corta es un pequeño animal planeador dotado de membranas de vuelo. Se desplaza volando de árbol en árbol en busca de alimento. En tu zoológico es un silencioso acróbata nocturno.'),
       (93553, 1110, 'nl', 'Madagaskische daggekko', 'De Madagaskische daggekko is felgroen en overdag actief. Hij leeft op planten en jaagt op insecten. In jouw dierentuin zorgt hij voor een tropisch kleuraccent in het terrarium.'),
       (93554, 1110, 'fr', 'Gecko diurne de Madagascar', 'Le gecko diurne de Madagascar est d''un vert éclatant et actif pendant la journée. Il vit sur les plantes et chasse les insectes. Dans ton zoo, il apporte une touche de couleur tropicale au terrarium.'),
       (93555, 1110, 'es', 'Gecko diurno de Madagascar', 'El gecko diurno de Madagascar es de un color verde brillante y está activo durante el día. Vive en las plantas y caza insectos. En tu zoológico, aportará un toque de color tropical al terrario.'),
       (93556, 1111, 'nl', 'manenrat', 'De manenrat heeft een opvallende, lange vacht op zijn rug. Hij kan gif uit planten in zijn vacht opslaan om zichzelf te beschermen. In jouw dierentuin is hij een klein, maar zeer boeiend onderzoeksobject.'),
       (93557, 1111, 'fr', 'rat à crinière', 'Le rat à crinière possède un pelage dorsal long et remarquable. Il peut stocker du venin provenant de plantes dans son pelage afin de se protéger. Dans ton zoo, c''est un sujet d''étude modeste mais très passionnant.'),
       (93558, 1111, 'es', 'Rata de melena', 'La rata de melena tiene un llamativo y largo pelaje dorsal. Es capaz de almacenar veneno de las plantas en su pelaje para protegerse. En tu zoológico es un objeto de investigación pequeño, pero muy interesante.'),
       (93559, 1112, 'nl', 'muizenwezel', 'De muiswezel is de kleinste vertegenwoordiger van de marterfamilie. Hij jaagt op behendige knaagdieren en is zelf ook erg snel. In jouw dierentuin is het een piepklein, druk rondrennend roofdiertje.'),
       (93560, 1112, 'fr', 'belette', 'La belette est le plus petit représentant de la famille des mustélidés. Elle chasse les rongeurs agiles et est elle-même très rapide. Dans ton zoo, c''est un minuscule prédateur très vif.'),
       (93561, 1112, 'es', 'comadreja', 'La comadreja es el miembro más pequeño de la familia de las martas. Caza roedores ágiles y es muy rápida. En tu zoológico es un depredador diminuto y muy inquieto.'),
       (93562, 1115, 'nl', 'Roodoogbladkikker', 'De roodogige bladkikker is met zijn felrode ogen en groene lichaam een tropische blikvanger. Overdag zit hij rustig op bladeren en ’s nachts wordt hij actief. In je dierentuin lijkt hij wel een klein, levend kunstwerk.'),
       (93563, 1115, 'fr', 'Grenouille à yeux rouges', 'Avec ses yeux rouge vif et son corps vert, la grenouille feuillue aux yeux rouges est une véritable star des tropiques. Elle reste tranquillement perchée sur les feuilles pendant la journée et s''active la nuit. Dans ton zoo, elle ressemble à une petite œuvre d''art vivante.'),
       (93564, 1115, 'es', 'Rana arbórea de ojos rojos', 'La rana de hojas de ojos rojos, con sus ojos de un rojo intenso y su cuerpo verde, es una estrella tropical. Durante el día permanece tranquila sobre las hojas y se vuelve activa por la noche. En tu zoológico parece una pequeña obra de arte viviente.'),
       (93565, 1116, 'nl', 'Snuifhondje', 'Het slurfhondje is een klein zoogdier met een lange, beweeglijke slurf. Het gebruikt die om insecten en andere kleine dieren op te sporen. In jouw dierentuin rent het door zijn verblijf en verkent het nieuwsgierig elk hoekje.'),
       (93566, 1116, 'fr', 'Petit chien à trompe', 'Le petit chien à trompe est un petit mammifère doté d''une longue trompe très souple. Il s''en sert pour débusquer des insectes et d''autres petits animaux. Dans ton zoo, il file à toute allure dans son enclos et explore chaque recoin avec curiosité.'),
       (93567, 1116, 'es', 'Perrito de hocico largo', 'El perrito de hocico largo es un pequeño mamífero con un hocico largo y ágil. Lo utiliza para localizar insectos y otros animales pequeños. En tu zoológico, corre de un lado a otro por su recinto y explora con curiosidad cada rincón.'),
       (93568, 1117, 'nl', 'Zonnedak', 'De zonnedak is een kleine marter met een lichte vlek op de borst. Hij is een behendige klimmer en jager. In jouw dierentuin is hij een levendige, nieuwsgierige bewoner van het roofdierenhuis.'),
       (93569, 1117, 'fr', 'Pare-soleil', 'Le martre tachetée est une petite martre dotée d''une tache claire sur la poitrine. C''est une habile grimpeuse et une chasseuse redoutable. Dans ton zoo, c''est une habitante vive et curieuse du pavillon des prédateurs.'),
       (93570, 1117, 'es', 'Toldo', 'El Sonnendachs es una pequeña marta con una mancha clara en el pecho. Es un hábil trepador y cazador. En tu zoológico es un habitante vivaz y curioso del pabellón de los depredadores.'),
       (93571, 1118, 'nl', 'Gestreepte bakhoorn', 'Het gestreepte bakkhoornje is een klein knaagdier met opvallende strepen. Het verzamelt voedsel in zijn wangzakken. In je dierentuin is het altijd druk bezig en is het een genot om naar te kijken.'),
       (93572, 1118, 'fr', 'Écureuil rayé des bois', 'Le tamia rayé est un petit rongeur aux rayures bien visibles. Il stocke de la nourriture dans ses joues. Dans ton zoo, il est toujours très actif et c''est un vrai plaisir de l''observer.'),
       (93573, 1118, 'es', 'Cornetilla rayada', 'El roedor rayado es un pequeño roedor con unas llamativas rayas. Acumula comida en sus bolsas bucales. En tu zoológico está siempre ocupado y es un placer observarlo.'),
       (93574, 1119, 'nl', 'dwergmiereneter', 'De dwergmiereneter is een klein, klimmend dier dat mieren eet. Hij brengt veel tijd door in bomen. In jouw dierentuin laat hij zien dat ook kleine dieren grote specialisten kunnen zijn.'),
       (93575, 1119, 'fr', 'fourmilier nain', 'Le fourmilier nain est un petit animal grimpeur qui se nourrit de fourmis. Il passe beaucoup de temps dans les arbres. Dans ton zoo, il montre que même les petits animaux peuvent être de grands spécialistes.'),
       (93576, 1119, 'es', 'Osito hormiguero enano', 'El osito hormiguero enano es un pequeño animal trepador que se alimenta de hormigas. Pasa mucho tiempo en los árboles. En tu zoológico demuestra que incluso los animales pequeños pueden ser grandes especialistas.'),
       (93577, 1120, 'nl', 'Europese hamster', 'De Europese hamster is groter dan zijn verwanten die als huisdier worden gehouden en leeft in het wild. Hij heeft een kleurrijke vacht en houdt ervan om voorraden in zijn hol aan te leggen. In jouw dierentuin laat hij zien hoe ijverig hij is bij het verzamelen en verstoppen van voedsel.'),
       (93578, 1120, 'fr', 'Hamster européen', 'Le hamster européen est plus grand que ses cousins de compagnie et vit à l''état sauvage. Il arbore des couleurs vives et adore faire des réserves dans son terrier. Dans ton zoo, il montre son côté travailleur en ramassant et en cachant de la nourriture.'),
       (93579, 1120, 'es', 'Hámster europeo', 'El hámster europeo es más grande que sus parientes domésticos y vive en libertad. Tiene un pelaje de colores vivos y le encanta acumular provisiones en su madriguera. En tu zoológico, muestra su lado más trabajador al recolectar y esconder comida.'),
       (93580, 1201, 'nl', 'Kleine riemmoll', 'Het kleine gordeldier is een piepklein gordeldier met een dunne pantser. Het leeft ondergronds in Zuid-Amerika. In jouw dierentuin is het een mysterieuze graver die zelden aan de oppervlakte komt.'),
       (93581, 1201, 'fr', 'Petite mousseline à ceinture', 'Le petit tatou à ceinture est un minuscule tatou doté d''une carapace délicate. Il vit sous terre en Amérique du Sud. Dans ton zoo, c''est un fouisseur mystérieux qui ne remonte que rarement à la surface.'),
       (93582, 1201, 'es', 'Pequeña gasa de cinturón', 'El armadillo de cinturón pequeño es un armadillo minúsculo con un caparazón delicado. Vive bajo tierra en Sudamérica. En tu zoológico es un misterioso excavador que rara vez sale a la superficie.'),
       (93583, 1202, 'nl', 'padhagedis', 'De padhagedis is een kleine hagedis met een gedrongen lichaamsbouw. Sommige soorten kunnen bij gevaar bloed uit hun ogen spuiten. In jouw dierentuin blijft hij liever rustig en vertrouwt hij op zijn camouflage.'),
       (93584, 1202, 'fr', 'lézard crapaud', 'Le lézard crapaud est un petit lézard au corps trapu. Certaines espèces peuvent projeter du sang par les yeux en cas de danger. Dans ton zoo, il préfère rester calme et se fier à son camouflage.'),
       (93585, 1202, 'es', 'lagarto sapo', 'El lagarto sapo es un lagarto pequeño de cuerpo robusto. Algunas especies pueden lanzar chorros de sangre por los ojos cuando se sienten amenazadas. En tu zoológico, sin embargo, prefiere mantenerse tranquilo y confiar en su camuflaje.'),
       (93586, 1203, 'nl', 'Langoor-egels', 'De langooregel is een insecteneter met opvallend grote oren. Hij gebruikt ze om af te koelen en om te luisteren. In jouw dierentuin is hij een nachtelijke, stekelige kleine ontdekkingsreiziger.'),
       (93587, 1203, 'fr', 'hérisson aux longues oreilles', 'Le hérisson aux longues oreilles est un insectivore doté d’oreilles remarquablement grandes. Il s’en sert pour se rafraîchir et pour tendre l’oreille. Dans ton zoo, c’est un petit explorateur nocturne tout en piquants.'),
       (93588, 1203, 'es', 'Erizo de orejas largas', 'El erizo de orejas largas es un insectívoro con unas orejas llamativamente grandes. Las utiliza para refrescarse y para escuchar. En tu zoológico es un pequeño explorador nocturno y espinoso.'),
       (93589, 1204, 'nl', 'lepelneus', 'De lepelneusmuis is een klein woestijnknaagdier met grote oren. Hij is nachtdier en graaft zich graag in. In jouw dierentuin laat hij zijn woestijnleven in miniatuurformaat zien.'),
       (93590, 1204, 'fr', 'Raton laveur à queue en cuillère', 'Le rat-cuillère est un petit rongeur du désert aux grandes oreilles. Il est nocturne et aime s''enfouir. Dans ton zoo, il te présente sa vie dans le désert en miniature.'),
       (93591, 1204, 'es', 'Armadillo de cuchara', 'El pica-cuchara es un pequeño roedor del desierto con orejas grandes. Es nocturno y le gusta enterrarse. En tu zoo muestra su vida en el desierto a escala reducida.'),
       (93592, 1205, 'nl', 'Numbat', 'De numbat is een Australische miereneter met een gestreepte rug. Hij is dagactief en zeer gespecialiseerd in termieten. In jouw dierentuin is hij een zeldzame, maar bijzonder charmante bewoner.'),
       (93593, 1205, 'fr', 'Numbat', 'Le numbat est un fourmilier australien au dos rayé. C''est un animal diurne, spécialisé dans la chasse aux termites. Dans ton zoo, c''est un résident rare, mais particulièrement charmant.'),
       (93594, 1205, 'es', 'Numbat', 'El numbat es un carnívoro australiano que se alimenta de hormigas y tiene el lomo rayado. Es diurno y está muy especializado en la alimentación de termitas. En tu zoológico es un habitante poco común, pero especialmente encantador.'),
       (93595, 1206, 'nl', 'Pantserrandstaart', 'De gepantserde hagedis is een hagedis met schubben die in een ringvorm zijn gerangschikt. Bij gevaar rolt hij zich gedeeltelijk op en bijt in zijn eigen staart. In jouw dierentuin ziet hij eruit als een kleine levende draak.'),
       (93596, 1206, 'fr', 'Queue en forme de ceinture de char', 'Le lézard à queue en ceinture est un lézard dont les écailles sont disposées en anneaux. En cas de danger, il s''enroule partiellement sur lui-même et se mord la queue. Dans ton zoo, il ressemble à un petit dragon vivant.'),
       (93597, 1206, 'es', 'Cola de cinturón blindado', 'La lagartija de cola acorazada es un lagarto con escamas dispuestas en forma de anillo. Ante el peligro, se enrosca parcialmente y se muerde la propia cola. En tu zoológico parece un pequeño dragón vivo.'),
       (93598, 1207, 'nl', 'Rode koningsslang', 'De rode koningsslang is een kleurrijk gestreepte slang. Haar kleurpatroon lijkt op dat van giftige soorten, hoewel ze zelf niet giftig is. In jouw dierentuin laat ze op indrukwekkende wijze zien hoe slim camouflage en misleiding kunnen zijn.'),
       (93599, 1207, 'fr', 'Serpent royal rouge', 'Le serpent royal rouge est un serpent aux anneaux colorés. Sa couleur imite celle d''espèces venimeuses, bien qu''il ne soit pas venimeux lui-même. Dans ton zoo, il illustre de manière impressionnante à quel point le camouflage et la tromperie peuvent être ingénieux.'),
       (93600, 1207, 'es', 'Serpiente real roja', 'La serpiente real roja es una serpiente con anillos de colores. Su coloración imita a la de especies venenosas, aunque ella misma no lo es. En tu zoológico demuestra de forma impresionante lo ingeniosos que pueden ser el camuflaje y el engaño.'),
       (93601, 1208, 'nl', 'Steppegekko', 'De steppevaran is een krachtige varan uit de droge gebieden van Afrika. Hij is overdag actief en een behendige jager. In jouw dierentuin zoekt hij graag warme plekjes in de zon op en verkent hij nieuwsgierig elk hoekje van zijn terrarium.'),
       (93602, 1208, 'fr', 'varan des steppes', 'Le varan des steppes est un varan robuste originaire des régions arides d''Afrique. C''est un animal diurne et un chasseur habile. Dans ton zoo, il aime se prélasser au soleil et explore avec curiosité chaque recoin de son terrarium.'),
       (93603, 1208, 'es', 'Lagarto de las estepas', 'El varano de las estepas es un varano robusto originario de las regiones áridas de África. Es diurno y un hábil cazador. En tu zoológico le gusta disfrutar de los lugares cálidos al sol y explora con curiosidad cada rincón de su terrario.'),
       (93604, 2101, 'nl', 'Axolotl', 'De axolotl is een bijzondere staartamfibie die zijn larvale stadium in het water behoudt. Hij kan verloren lichaamsdelen regenereren. In jouw dierentuin glimlacht hij met zijn kenmerkende gezichtsuitdrukking vanuit het aquarium.'),
       (93605, 2101, 'fr', 'Axolotl', 'L''axolotl est un amphibien à queue particulier qui conserve son stade larvaire dans l''eau. Il est capable de régénérer les parties de son corps qu''il a perdues. Dans ton zoo, il te sourit depuis son aquarium avec son expression caractéristique.'),
       (93606, 2101, 'es', 'Axolotl', 'El ajolote es un anfibio especial que conserva su fase larvaria en el agua. Es capaz de regenerar las partes del cuerpo que pierde. En tu zoológico, te sonríe desde el acuario con su típica expresión facial.'),
       (93607, 2102, 'nl', 'Blauwe Florida-kreeft', 'De blauwe Florida-rivierkreeft is een felblauwe rivierkreeft. Hij komt oorspronkelijk uit Noord-Amerika en valt in het aquarium bijzonder op. In je aquarium beweegt hij zijn scharen behendig en zorgt hij voor kleurrijke accenten in het water.'),
       (93608, 2102, 'fr', 'Écrevisse bleue de Floride', 'L''écrevisse bleue de Floride est une écrevisse d''un bleu éclatant. Originaire d''Amérique du Nord, elle attire particulièrement l''attention dans un aquarium. Dans ton aquarium, elle manie habilement ses pinces et apporte une touche de couleur dans l''eau.'),
       (93609, 2102, 'es', 'Cangrejo azul de Florida', 'El cangrejo azul de Florida es un cangrejo de río de un azul brillante. Es originario de Norteamérica y llama especialmente la atención en el acuario. En tu acuario, mueve sus pinzas con destreza y aporta toques de color al agua.'),
       (93610, 2103, 'nl', 'schijfvis', 'De discusvis is een ronde, kleurrijke siervis uit het Amazonegebied. Hij zwemt rustig en leeft graag in een school. In jouw aquarium lijkt zijn aquarium op een levend schilderij.'),
       (93611, 2103, 'fr', 'discus', 'Le discus est un poisson d''ornement rond aux couleurs chatoyantes originaire de l''Amazonie. Il nage d''un mouvement tranquille et aime vivre en banc. Dans ton aquarium, son bac ressemble à un tableau vivant.'),
       (93612, 2103, 'es', 'pez disco', 'El disco es un pez ornamental redondeado y de colores vivos procedente del Amazonas. Nade con movimientos tranquilos y le gusta vivir en bancos. En tu acuario, su pecera parece un cuadro viviente.'),
       (93613, 2104, 'nl', 'Goudvis', 'De goudvis is een van de bekendste aquariumvissen. Hij is al eeuwen geleden uit wilde karpers gekweekt. In jouw dierentuin zwemt hij in heldere bassins en is vooral bij jonge bezoekers erg populair.'),
       (93614, 2104, 'fr', 'Poisson rouge', 'Le poisson rouge est l''un des poissons d''aquarium les plus connus. Il a été sélectionné à partir de carpes sauvages il y a déjà plusieurs siècles. Dans ton zoo, il nage dans des bassins limpides et fait le bonheur des jeunes visiteurs en particulier.'),
       (93615, 2104, 'es', 'Pececito de colores', 'El pez dorado es uno de los peces de acuario más conocidos. Se obtuvo hace ya siglos a partir de la carpa silvestre. En tu zoológico nada en peceras de agua clara y hace las delicias, sobre todo, de los visitantes más jóvenes.'),
       (93616, 2105, 'nl', 'Pauwaal', 'De pauw-stekelaal is een langgerekte vis met opvallende vlekken rond de ogen. Overdag verstopt hij zich graag in de bodem. In je aquarium kunnen oplettende toeschouwers hem zien terwijl hij voorzichtig tevoorschijn gluurt.'),
       (93617, 2105, 'fr', 'Anguille épineuse paon', 'L''anguille-paon est un poisson allongé doté de taches oculaires très voyantes. Elle aime se cacher dans le substrat pendant la journée. Dans ton aquarium, les observateurs attentifs pourront l''apercevoir lorsqu''elle jette prudemment un coup d''œil hors de sa cachette.'),
       (93618, 2105, 'es', 'Anguila espinosa del pavo real', 'La anguila espinosa del pavo real es un pez alargado con llamativas manchas alrededor de los ojos. Durante el día suele esconderse en el fondo. En tu acuario, los observadores atentos podrán verla asomarse con cautela.'),
       (93619, 2106, 'nl', 'Rode piranha', 'De rode piranha is een Zuid-Amerikaanse schoolvis met scherpe tanden. Zijn reputatie is wilder dan zijn werkelijke gedrag. In jouw dierentuin zwemt hij in een school en laat hij zien hoe indrukwekkend gecoördineerde vissen kunnen overkomen.'),
       (93620, 2106, 'fr', 'Piranha rouge', 'Le piranha rouge est un poisson sud-américain vivant en bancs et doté de dents acérées. Sa réputation est plus redoutable que son comportement réel. Dans ton zoo, il nage en bancs et montre à quel point des poissons coordonnés peuvent être impressionnants.'),
       (93621, 2106, 'es', 'Piraña roja', 'La piraña roja es un pez sudamericano que vive en bancos y tiene dientes afilados. Su reputación es más salvaje que su comportamiento real. En tu acuario nada en bancos y demuestra lo impresionantes que pueden resultar los peces cuando se coordinan.'),
       (93622, 2107, 'nl', 'Zuid-Amerikaanse vlindercichlide', 'De Zuid-Amerikaanse vlinderbaars is een kleine, kleurrijke cichlide. Hij vertoont interessant broedgedrag. In je aquarium zorgt hij voor kleur in kleinere aquariumhoeken.'),
       (93623, 2107, 'fr', 'Cichlidé papillon d''Amérique du Sud', 'Le cichlidé papillon d''Amérique du Sud est un petit cichlidé aux couleurs vives. Il présente un comportement de reproduction intéressant. Dans ton aquarium, il apporte de la couleur aux petits espaces.'),
       (93624, 2107, 'es', 'Cichlido mariposa de Sudamérica', 'El cíclido mariposa sudamericano es un cíclido pequeño y colorido. Presenta un interesante comportamiento reproductivo. En tu acuario, aporta color a las zonas más pequeñas.'),
       (93625, 2109, 'nl', 'Pauwoogrog', 'De pauwoogrog heeft opvallende oogvlekken op zijn rug. Hij leeft in zoet water en glijdt over de bodem. In jouw dierentuin lijkt hij wel een zwevend tapijt met een patroon.'),
       (93626, 2109, 'fr', 'Raie-paon', 'La raie-paon présente des taches en forme d''yeux très voyantes sur le dos. Elle vit en eau douce et glisse sur le fond. Dans ton zoo, elle ressemble à un tapis à motifs qui flotte dans l''eau.'),
       (93627, 2109, 'es', 'Raya de ojos de pavo real', 'La raya de ojos de pavo real tiene unas llamativas manchas en forma de ojo en el lomo. Vive en agua dulce y se desliza por el fondo. En tu zoológico parece una alfombra flotante con dibujos.'),
       (93628, 2202, 'nl', 'Dumbo-octopus', 'De Dumbo-octopus is een diepzeeoctopus met vinnen die op oren lijken. Daardoor ziet hij er bijzonder schattig uit. In jouw dierentuin laat hij zien hoe bizar diepzeebewoners kunnen zijn.'),
       (93629, 2202, 'fr', 'Poulpe Dumbo', 'La pieuvre Dumbo est une pieuvre des grands fonds dotée de nageoires en forme d''oreilles. Cela lui donne un air particulièrement mignon. Dans ton zoo, elle montre à quel point les habitants des grands fonds peuvent être insolites.'),
       (93630, 2202, 'es', 'Pulpo Dumbo', 'El pulpo «Dumbo» es un pulpo de aguas profundas con aletas que parecen orejas. Esto le da un aspecto especialmente adorable. En tu zoológico, demuestra lo extravagantes que pueden llegar a ser los habitantes de las profundidades marinas.'),
       (93631, 2203, 'nl', 'Grote flardenvis', 'De grote flardenvis heeft lange huidaanhangsels waardoor hij eruitziet als drijvend zeegras. Hij leeft in koele zeegebieden. In jouw aquarium is hij een meester in het zich camoufleren in zeegrassbassen.'),
       (93632, 2203, 'fr', 'Grand poisson-chasseur', 'Le grand poisson-lambeau possède de longs appendices cutanés qui lui donnent l''apparence d''une algue flottante. Il vit dans les régions marines froides. Dans ton aquarium, c''est un maître du camouflage dans les bassins d''algues.'),
       (93633, 2203, 'es', 'Pez grande de trozas', 'El pez trapo grande tiene largos apéndices cutáneos que le dan el aspecto de algas marinas a la deriva. Vive en regiones marinas frías. En tu acuario es un maestro del camuflaje en los tanques de algas marinas.'),
       (93634, 2204, 'nl', 'Japanse vuurvis', 'De Japanse vuurvis is een giftige rifbewoner met lange, straalvormige vinnen. Zijn kleurpatroon waarschuwt roofdieren. In je aquarium lijkt hij wel een levend vuurwerk in het water.'),
       (93635, 2204, 'fr', 'Poisson-lion japonais', 'Le poisson-lion japonais est un poisson de récif venimeux doté de longues nageoires en forme de rayons. Ses motifs servent à mettre en garde ses prédateurs. Dans ton aquarium, il ressemble à un feu d''artifice vivant dans l''eau.'),
       (93636, 2204, 'es', 'Pez león japonés', 'El pez león japonés es un habitante venenoso de los arrecifes con aletas largas y en forma de rayos. Su patrón de colores sirve para advertir a los depredadores. En tu acuario parece un fuego artificial viviente en el agua.'),
       (93637, 2205, 'nl', 'Carnavalsinktvis', 'De carnavalsinktvis valt op door zijn intense kleurveranderingen en patronen. Hij gebruikt zijn kleuren om te communiceren en zich te camoufleren. In jouw dierentuin laat hij zien dat de zee zijn eigen carnavalsartiesten heeft.'),
       (93638, 2205, 'fr', 'Calamar de carnaval', 'Le calmar « carnaval » se distingue par ses changements de couleur intenses et ses motifs. Il utilise ses couleurs pour communiquer et se camoufler. Dans ton zoo, il montre que la mer a ses propres artistes de carnaval.'),
       (93639, 2205, 'es', 'Calamar de carnaval', 'El calamar de carnaval destaca por sus intensos cambios de color y sus patrones. Utiliza sus colores para comunicarse y camuflarse. En tu zoológico, demuestra que el mar tiene sus propios artistas de carnaval.'),
       (93640, 2206, 'nl', 'kompasqual', 'De kompasquallen hebben straalvormige patronen die aan een kompas doen denken. Hun lange tentakels zweven elegant in het water. In jouw dierentuin lijkt ze op een zwevende ster in het kwallenaquarium.'),
       (93641, 2206, 'fr', 'méduse boussole', 'La méduse « boussole » présente des motifs rayonnants qui rappellent une boussole. Ses longs tentacules virevoltent avec élégance dans l''eau. Dans ton zoo, elle ressemble à une étoile flottante dans l''aquarium des méduses.'),
       (93642, 2206, 'es', 'medusa brújula', 'La medusa brújula presenta un dibujo radial que recuerda a una brújula. Sus largos tentáculos se mueven con elegancia en el agua. En tu acuario, parece una estrella flotante en el acuario de medusas.'),
       (93643, 2207, 'en', 'Mandarin fish', 'The mandarin fish is a small reef dweller with spectacular coloring. It’s rather shy and popular among aquarium enthusiasts. In your aquarium, it sparkles like a colorful gem among the corals.'),
       (93644, 30126, 'nl', 'African Wolf',
        'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\\\'s known for its adaptability and social behavior in packs.\\n\\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
       (93645, 30126, 'fr', 'African Wolf',
        'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\\\'s known for its adaptability and social behavior in packs.\\n\\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
       (93646, 30126, 'es', 'African Wolf',
        'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\\\'s known for its adaptability and social behavior in packs.\\n\\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
       (93647, 30127, 'nl', 'Alpine Marmot', 'De alpenmarmot is een grote, op de grond levende eekhoorn uit het geslacht van de marmotten. Een volwassen alpiene marmot heeft een kop-romplengte van 43 tot 73 cm (17–29 inch) en een staartlengte van 13 tot 20 cm (5–8 inch); zijn vacht bestaat uit een mengeling van blonde, roodachtige en donkergrijze haren. \\nAlpensmurfen eten planten zoals grassen en kruiden, maar ook graan, insecten, spinnen en wormen. \\n\\nDeze dieren zijn uitstekende gravers; hun leefgebied bestaat doorgaans uit subalpiene en alpiene weiden en graslanden, waar ze in kolonies leven in rotsachtige gebieden met alluviale grond, in diepe holenstelsels.'),
       (93648, 30127, 'fr', 'Marmotte des Alpes', 'La marmotte des Alpes est un grand écureuil terrestre, appartenant au genre des marmottes. Un marmotte des Alpes adulte mesure entre 43 et 73 cm (17–29 pouces) de longueur tête-corps et sa queue mesure de 13 à 20 cm (5–8 pouces) ; son pelage est un mélange de poils blonds, roux et gris foncé. \\nLes marmottes des Alpes se nourrissent de plantes telles que les graminées et les herbes, ainsi que de céréales, d’insectes, d’araignées et de vers. \\n\\nCes animaux sont d''excellents fouisseurs ; leur habitat se compose généralement de prairies et de pâturages subalpins et alpins, où ils vivent en colonies dans des zones rocheuses, dans un sol alluvial, au sein de réseaux de terriers profonds.'),
       (93649, 30127, 'es', 'Marmota alpina', 'La marmota alpina es una ardilla grande que vive en el suelo, perteneciente al género de las marmotas. Una marmota alpina adulta mide entre 43 y 73 cm (17–29 pulgadas) de longitud de cabeza a cola, y la cola mide entre 13 y 20 cm (5–8 pulgadas); su pelaje es una mezcla de tonos rubios, rojizos y gris oscuro. \\nLas marmotas alpinas se alimentan de plantas como gramíneas y hierbas, así como de cereales, insectos, arañas y gusanos. \\n\\nEstos animales son excelentes excavadores; su hábitat suele ser prados y pastos subalpinos y alpinos, donde viven en colonias en zonas rocosas, en suelos aluviales, dentro de profundos sistemas de madrigueras.'),
       (93650, 30128, 'nl', 'Bengaalse vos', 'De Bengaalse vos is een kleine, slanke vos met een smal, puntig gezicht, grote, rechtopstaande oren en een lange, borstelige staart met een zwarte punt. Zijn vacht is zandgrijs tot lichtbruin en past goed bij droge graslanden en struikgewas. De poten zijn relatief lang en dun, waardoor hij er licht en behendig uitziet, en de ogen zijn donker en expressief.\\n\\nDe Bengaalse vos voedt zich met kleine zoogdieren, insecten, vogels, reptielen en fruit.'),
       (93651, 30128, 'fr', 'Renard du Bengale', 'Le renard du Bengale est un petit renard élancé, au museau étroit et pointu, aux grandes oreilles dressées et à la longue queue touffue dont l''extrémité est noire. Son pelage, qui va du gris sable au brun pâle, lui permet de se fondre parfaitement dans les prairies sèches et les zones de broussailles. Ses pattes sont relativement longues et fines, ce qui lui confère une allure légère et agile, et ses yeux sont foncés et expressifs.\\n\\nLe renard du Bengale se nourrit de petits mammifères, d''insectes, d''oiseaux, de reptiles et de fruits.'),
       (93652, 30128, 'es', 'Zorro de Bengala', 'El zorro de Bengala es un zorro pequeño y esbelto, con un hocico estrecho y puntiagudo, orejas grandes y erguidas, y una cola larga y tupida con la punta negra. Su pelaje es de color gris arena a marrón pálido, lo que le permite camuflarse bien en los hábitats de praderas secas y matorrales. Las patas son relativamente largas y delgadas, lo que le da un aspecto ligero y ágil, y los ojos son oscuros y expresivos.\\n\\nEl zorro de Bengala se alimenta de pequeños mamíferos, insectos, aves, reptiles y frutos.'),
       (93653, 30129, 'nl', 'Adéliepinguïn', 'Adéliepinguïns zijn een pinguïnsoort die veel voorkomt langs de gehele kust van het Antarctische continent, de enige plek waar deze soort voorkomt. Ze brengen de winter door in de zeeën rondom het Antarctische pakijs. De volwassen vogel is zwart op de kop, keel en bovenkant, met een sneeuwwitte onderkant. Hij heeft een opvallende witte oogring rond een zwarte iris. \\n\\nAdéliepinguïns voeden zich met kleine waterdieren, zoals garnalenachtige krill, maar eten ook vis en inktvis.'),
       (93654, 30129, 'fr', 'Manchot d''Adélie', 'Le manchot Adélie est une espèce de manchot répandue sur toute la côte du continent antarctique, seul endroit où on le trouve.  Il passe l''hiver au large, dans les mers entourant la banquise antarctique. L''adulte présente une tête, une gorge et des parties supérieures noires, ainsi que des parties inférieures d''un blanc neigeux. Il est doté d''un anneau oculaire blanc bien visible autour d''un iris noir. \\n\\nLes manchots Adélie se nourrissent de minuscules créatures aquatiques, telles que le krill, qui ressemble à une crevette, mais mangent également du poisson et des calmars.'),
       (93655, 30129, 'es', 'Pingüino de Adelia', 'El pingüino de Adelia es una especie de pingüino común a lo largo de toda la costa del continente antártico, que es el único lugar donde se encuentra. Pasan el invierno en alta mar, en las aguas que rodean el hielo marino antártico. El adulto es de color negro en la cabeza, la garganta y las partes superiores, con las partes inferiores de un blanco níveo. Presenta un llamativo anillo ocular blanco alrededor del iris negro. \\n\\nLos pingüinos de Adelia se alimentan de diminutos animales acuáticos, como el krill, similar a un camarón, pero también comen peces y calamares.'),
       (93656, 30130, 'nl', 'Amethist Starling', 'De amethistspreeuw, ook wel paarse spreeuw genoemd, is een kleine, schitterende, iriserende vogel met een glanzend violetpaars verenkleed dat van kleur verandert in het zonlicht, een geel oog en zwarte vleugels en staart. Ze komen voor in bossen en savannes van Sub-Sahara-Afrika. Mannetjes pronken tijdens de balts met hun glinsterende veren. \\n\\nDe amethistspreeuw eet voornamelijk fruit, bessen, nectar en insecten zoals termieten.\\n\\n'),
       (93657, 30130, 'fr', 'Amethyst Starling', 'L''étourneau améthyste, également appelé étourneau pourpre, est un petit oiseau aux couleurs chatoyantes et irisées, doté d''un plumage violet-pourpre brillant qui change de teinte à la lumière du soleil, d''un œil jaune et d''ailes et d''une queue noires. On le trouve dans les zones boisées et les savanes d''Afrique subsaharienne. Les mâles exhibent leur plumage chatoyant lors de la parade nuptiale. \\n\\nL''étourneau améthyste se nourrit principalement de fruits, de baies, de nectar et d''insectes tels que les termites.\\n\\n'),
       (93658, 30130, 'es', 'Amethyst Starling', 'El estornino amatista, también llamado estornino púrpura, es un ave pequeña y deslumbrante, de plumaje iridiscente y brillante en tonos violeta-púrpura que cambia de color a la luz del sol, con ojos amarillos y alas y cola negras. Se encuentra en los bosques y las sabanas del África subsahariana. Los machos exhiben sus plumas brillantes durante el cortejo. \\n\\nEl estornino amatista se alimenta principalmente de frutas, bayas, néctar e insectos como las termitas.\\n\\n'),
       (93659, 30131, 'nl', 'Andean Condor',
        'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\\\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\\n\\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\\n\\n'),
       (93660, 30131, 'fr', 'Andean Condor',
        'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\\\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\\n\\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\\n\\n'),
       (93661, 30131, 'es', 'Andean Condor',
        'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\\\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\\n\\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\\n\\n'),
       (93662, 30134, 'nl', 'Ankole Watusi', 'De Ankole Watusi is een opvallend Afrikaans runderras dat bekend staat om zijn enorme, liervormige hoorns en elegante gestalte. Het heeft een gladde vacht die rood, bruin, zwart of gevlekt kan zijn, met lange poten, een slank postuur en een rustig karakter. Ze worden in kleine groepen gehouden en werden vroeger door Maasai/Watusi-krijgers tegen leeuwen beschermd, waarbij ze hun hoorns als wapens gebruikten.\\n\\nHun dieet bestaat voornamelijk uit grassen en struiken, en ze hebben maar weinig water nodig.\\n\\n'),
       (93663, 30134, 'fr', 'Ankole Watusi', 'L''Ankole Watusi est une race bovine africaine remarquable, réputée pour ses cornes imposantes en forme de lyre et sa stature élégante. Elle possède un pelage lisse qui peut être roux, brun, noir ou tacheté, de longues pattes, une silhouette élancée et un tempérament calme. Ces animaux sont élevés en petits troupeaux et étaient autrefois protégés des lions par des guerriers Masaï/Watusi, qui utilisaient leurs cornes comme armes.\\n\\nLeur alimentation se compose principalement d’herbes et d’arbustes, et leurs besoins en eau sont minimes.\\n\\n'),
       (93664, 30134, 'es', 'Ankole Watusi', 'La Ankole Watusi es una llamativa raza bovina africana, famosa por sus enormes cuernos en forma de lira y su elegante complexión. Tiene un pelaje liso que puede ser rojo, marrón, negro o moteado, con patas largas, una complexión esbelta y un carácter tranquilo. Se crían en pequeños rebaños y, históricamente, los guerreros masái/watusi las protegían de los leones utilizando sus cuernos como armas.\\n\\nSu dieta se compone principalmente de hierbas y arbustos, y sus necesidades de agua son mínimas.\\n\\n'),
       (93665, 30135, 'nl', 'Arabische tahr', 'De Arabische tahr is een kleine, robuuste wilde geit met een gedrongen lichaamsbouw, een ruige vacht die varieert van roodbruin tot donkergrijs, en gebogen hoorns die bij mannetjes groter zijn. Hij komt alleen voor in de bergachtige gebieden van Oman en de Verenigde Arabische Emiraten. Deze dieren leven in kleine kuddes op steile, rotsachtige hellingen en zijn schuw en behendig; ze balanceren vakkundig op kliffen.\\n\\nDe Arabische tahr voedt zich voornamelijk met grassen, kruiden, bladeren en struiken.\\n\\n'),
       (93666, 30135, 'fr', 'Tahr d''Arabie', 'Le tahr d''Arabie est une petite chèvre sauvage robuste, de constitution trapue, au pelage hirsute allant du brun rougeâtre au gris foncé, et dotée de cornes recourbées, plus grandes chez les mâles. On ne le trouve que dans les régions montagneuses d''Oman et des Émirats arabes unis. Ces animaux vivent en petits troupeaux sur des pentes escarpées et rocheuses ; discrets et agiles, ils se déplacent avec une grande aisance sur les falaises.\\n\\nLe tahr d''Arabie se nourrit principalement d''herbes, de plantes aromatiques, de feuilles et d''arbustes.\\n\\n'),
       (93667, 30135, 'es', 'Tahr árabe', 'El tahr árabe es una cabra salvaje pequeña y robusta, de complexión fornida, con un pelaje hirsuto que varía del marrón rojizo al gris oscuro, y cuernos curvados que son más grandes en los machos. Solo se encuentra en las regiones montañosas de Omán y los Emiratos Árabes Unidos. Estos animales viven en pequeñas manadas en laderas escarpadas y rocosas; son reservados y ágiles, y se desplazan con gran destreza por los acantilados.\\n\\nEl tahr árabe se alimenta principalmente de pastos, hierbas, hojas y arbustos.\\n\\n'),
       (93668, 30136, 'nl', 'Poolster', 'De Noordse stern is een kleine tot middelgrote zeevogel die bekendstaat om zijn opmerkelijke trekgedrag; hij legt de langste trektocht van alle vogelsoorten af. Noordse sterns hebben een slank lichaam, lange vleugels en een kenmerkende gevorkte staart. Ze zijn overwegend wit met een zwarte kap op hun kop, een grijsachtige rug en een rode snavel. Hun verenkleed is aangepast aan het leven op zee, waardoor ze behendige vliegers en bekwame jagers zijn.\\n\\nNoordse sterns zijn carnivoren (viseters). Deze vogels voeden zich met kleine vissoorten (zandspiering, zandaal en lodde) en met rivierkreeften.\\n\\n'),
       (93669, 30136, 'fr', 'Sterne arctique', 'La sterne arctique est un oiseau marin de taille petite à moyenne, connu pour son comportement migratoire remarquable : c''est l''espèce d''oiseau qui effectue la plus longue migration. Les sternes arctiques ont un corps élancé, de longues ailes et une queue fourchue caractéristique. Elles sont principalement blanches, avec une calotte noire sur la tête, un dos grisâtre et un bec rouge. Leur plumage est adapté à la vie en mer, ce qui leur permet d''être des volatrices agiles et des chasseuses habiles.\\n\\nLes sternes arctiques sont carnivores (piscivores). Ces oiseaux se nourrissent de petites espèces de poissons (launaes des sables, lançons et capelans) ainsi que d''écrevisses.\\n\\n'),
       (93670, 30136, 'es', 'Charrán ártico', 'El charrán ártico es un ave marina de tamaño pequeño a mediano conocida por su extraordinario comportamiento migratorio, ya que realiza la migración más larga de todas las especies de aves. Los charranes árticos tienen un cuerpo esbelto, alas largas y una cola bifurcada característica. Son principalmente blancas, con una caperuza negra en la cabeza, el dorso grisáceo y el pico rojo. Su plumaje está adaptado a la vida en el mar, lo que les permite volar con agilidad y ser hábiles cazadoras.\\n\\nLas charranas árticas son carnívoras (piscívoras). Estas aves se alimentan de pequeñas especies de peces (launas de arena, anguilas de arena y capelines), así como de cangrejos de río.\\n\\n'),
       (93671, 30137, 'nl', 'Argentijnse zwart-witte tegu', 'De Argentijnse zwart-witte tegu is een grote, robuuste hagedis die inheems is in Zuid-Amerika. Deze soort staat bekend om zijn opvallende zwart-witte kleurstelling en heeft een patroon van duidelijke zwart-witte strepen of vlekken, waardoor hij visueel heel herkenbaar is. Deze hagedissen kunnen tot 1,2 meter (4 voet) lang worden en staan erom bekend dat ze holen graven, die ze gebruiken als schuilplaats en om aan extreme temperaturen te ontsnappen. \\n\\nArgentijnse zwart-witte tegu''s zijn alleseters en voeden zich met een gevarieerd dieet dat bestaat uit fruit, insecten en kleine dieren.\\n\\n'),
       (93672, 30137, 'fr', 'Tégou noir et blanc d''Argentine', 'Le tégu noir et blanc d''Argentine est un grand lézard robuste originaire d''Amérique du Sud. Réputée pour sa coloration noir et blanc saisissante, cette espèce se caractérise par un motif de larges bandes ou taches noires et blanches qui la rend visuellement unique. Ces lézards peuvent atteindre 1,2 mètre (4 pieds) de long et sont connus pour creuser des terriers, qu’ils utilisent comme abri et pour échapper aux températures extrêmes. \\n\\nLes tégu noir et blanc d''Argentine sont omnivores et se nourrissent d''un régime varié comprenant des fruits, des insectes et de petits animaux.\\n\\n'),
       (93673, 30137, 'es', 'Tegu argentino blanco y negro', 'El tegu argentino blanco y negro es un lagarto grande y robusto, originario de Sudamérica. Conocida por su llamativa coloración en blanco y negro, esta especie presenta un patrón de franjas o manchas negras y blancas muy marcadas, lo que la hace visualmente distintiva. Estos lagartos pueden alcanzar hasta 1,2 metros (4 pies) de longitud y son conocidos por cavar madrigueras, que utilizan como refugio y para protegerse de las temperaturas extremas. \\n\\nLos tegues argentinos blancos y negros son omnívoros y se alimentan de una dieta variada que incluye frutas, insectos y pequeños animales.\\n\\n'),
       (93674, 30138, 'nl', 'Aziatische gouden kat', 'De Aziatische goudkat is een middelgrote wilde kat die van nature voorkomt in de bossen van Zuidoost-Azië. Hij heeft een opvallende vacht die varieert van goudkleurig tot roodbruin, vaak met donkerdere vlekken of strepen. Hij heeft een gespierd postuur, met een brede kop en korte poten. De Aziatische goudkat weegt doorgaans tussen de 8 en 16 kg (18 tot 35 lbs) en heeft een lichaamslengte van ongeveer 70 tot 100 cm (28 tot 39 inches), met een lange staart die nog eens 60 cm (24 inches) kan toevoegen.\\n\\nDe Aziatische goudkat is een carnivoor die voornamelijk jaagt op kleine tot middelgrote zoogdieren, vogels en reptielen.\\n\\n'),
       (93675, 30138, 'fr', 'Chat doré d''Asie', 'Le chat doré d''Asie est un félin sauvage de taille moyenne originaire des forêts d''Asie du Sud-Est. Il possède un pelage caractéristique dont la couleur va du doré au brun rougeâtre, souvent parsemé de taches ou de rayures plus foncées. Sa silhouette est musclée, avec une tête large et des pattes courtes. Le chat doré d''Asie pèse généralement entre 8 et 16 kg (18 à 35 livres) et mesure environ 70 à 100 cm (28 à 39 pouces) de long, avec une longue queue pouvant atteindre 60 cm (24 pouces) supplémentaires.\\n\\nLe chat doré d''Asie est un carnivore qui se nourrit principalement de mammifères de petite à moyenne taille, d''oiseaux et de reptiles.\\n\\n'),
       (93676, 30138, 'es', 'Gato dorado asiático', 'El gato dorado asiático es un felino salvaje de tamaño mediano originario de los bosques del sudeste asiático. Tiene un pelaje característico que varía del dorado al marrón rojizo, a menudo con manchas o rayas más oscuras. Su complexión es musculosa, con una cabeza ancha y patas cortas. El gato dorado asiático suele pesar entre 8 y 16 kg (18 y 35 libras) y mide entre 70 y 100 cm (28 y 39 pulgadas) de longitud, con una larga cola que puede añadir hasta 60 cm (24 pulgadas) adicionales.\\n\\nEl gato dorado asiático es carnívoro y se alimenta principalmente de mamíferos pequeños y medianos, aves y reptiles.\\n\\n'),
       (93677, 30139, 'nl', 'Australische zeeleeuw', 'De Australische zeeleeuw is een zeldzame, kleine zeehond die alleen in Zuid-Australië voorkomt. Mannetjes worden 2,5 m (8 ft 2 in) lang en wegen 300 kg (660 lbs); ze hebben een dikke manenkrans rond de nek, een donkerbruine vacht, een stompe snuit en een prominent voorhoofd. Vrouwtjes zijn kleiner: ze worden 1,8 m (5 ft 11 in) lang en wegen 100 kg (220 lbs) en hebben een lichtere, roodachtige vacht. Beide geslachten hebben uitwendige oorkleppen en peddelachtige zwemvliezen. Bedreigd, met nog ongeveer 20.000 exemplaren. \\n\\nAustralische zeeleeuwen eten vis zoals Australische zalm en harder, maar ook inktvis, octopus en zeekat.\\n\\n'),
       (93678, 30139, 'fr', 'Lion de mer australien', 'Le lion de mer d''Australie est un phoque à petites oreilles rare que l''on ne trouve que dans le sud de l''Australie. Les mâles mesurent jusqu''à 2,5 m (8 pieds 2 pouces) de long et pèsent jusqu''à 300 kg (660 livres) ; ils sont dotés d''une épaisse crinière au niveau du cou, d''un pelage brun foncé, d''un museau arrondi et d''un front proéminent. Les femelles sont plus petites : elles mesurent 1,8 m (5 ft 11 in) et pèsent 100 kg (220 lbs), avec un pelage plus clair, tirant vers le rouge. Les deux sexes possèdent des oreilles externes et des nageoires en forme de pagaies. Espèce menacée d''extinction, dont il ne reste qu''environ 20 000 individus. \\n\\nLes lions de mer d''Australie se nourrissent de poissons tels que le saumon australien et le mulet, ainsi que de calmars, de poulpes et de seiches.\\n\\n'),
       (93679, 30139, 'es', 'León marino australiano', 'El león marino australiano es una especie rara de foca de orejas pequeñas que solo se encuentra en el sur de Australia. Los machos alcanzan los 2,5 m (8 pies y 2 pulgadas) de longitud y los 300 kg (660 libras), con una espesa melena en el cuello, pelaje marrón oscuro, hocico romo y frente prominente. Las hembras son más pequeñas, con 1,8 m (5 pies 11 pulgadas) de longitud y 100 kg (220 libras) de peso, y presentan un pelaje rojizo más claro. Ambos tienen pabellones auditivos externos y aletas en forma de remo. Se encuentra en peligro de extinción, con una población de aproximadamente 20 000 ejemplares. \\n\\nLos leones marinos australianos se alimentan de peces como el salmón australiano y el mújol, además de calamares, pulpos y sepias.\\n\\n'),
       (93680, 30140, 'nl', 'Bay Cat', 'De baai-kat is een kleine, schuwe wilde kat die inheems is op Borneo. Hij heeft een gladde, roodbruine vacht met donkerdere vlekken en strepen, en een lange staart. Hij weegt doorgaans tussen de 3 en 5 kg (6,6 tot 11 lbs) en staat bekend om zijn solitaire en nachtelijke levenswijze. Door het verlies van leefgebied en de jacht wordt hij als bedreigd beschouwd.\\n\\nDe Bay Cat leeft voornamelijk in tropische regenwouden, waar hij jaagt op kleine zoogdieren, vogels en reptielen.\\n\\n'),
       (93681, 30140, 'fr', 'Bay Cat', 'Le chat de la baie est un petit félin sauvage insaisissable originaire de Bornéo. Il possède un pelage lisse, brun rougeâtre, parsemé de taches et de rayures plus foncées, ainsi qu''une longue queue. Pesant généralement entre 3 et 5 kg (6,6 à 11 livres), il est connu pour son mode de vie solitaire et nocturne. En raison de la destruction de son habitat et de la chasse, il est considéré comme une espèce en voie de disparition.\\n\\nLe chat de Bornéo vit principalement dans les forêts tropicales humides, où il se nourrit de petits mammifères, d''oiseaux et de reptiles.\\n\\n'),
       (93682, 30140, 'es', 'Bay Cat', 'El gato de la bahía es un felino salvaje pequeño y esquivo, originario de Borneo. Tiene un pelaje liso de color marrón rojizo con manchas y rayas más oscuras, y una cola larga. Su peso suele oscilar entre los 3 y los 5 kg (6,6 y 11 libras), y es conocido por su comportamiento solitario y nocturno. Debido a la pérdida de su hábitat y a la caza, se considera una especie en peligro de extinción.\\n\\nEl gato de Borneo habita principalmente en las selvas tropicales, donde se alimenta de pequeños mamíferos, aves y reptiles.\\n\\n'),
       (93683, 30141, 'nl', 'Bengaalse traagloris', 'De Bengaalse traagloeris is een kleine, nachtactieve primaat die van nature voorkomt in de bossen van Zuidoost-Azië. Deze soort, die zich kenmerkt door zijn grote, ronde ogen en een opvallend gezichtspatroon, beweegt zich langzaam en bedachtzaam, wat hem helpt zich door zijn boomrijke leefgebied te verplaatsen. De Bengaalse traaglooris staat bekend om zijn unieke verdedigingsmechanisme: hij scheidt een giftige stof af uit zijn elleboogklieren, die hij op zijn vacht kan aanbrengen of via beten kan overbrengen.\\n\\nHij is voornamelijk herbivoor en voedt zich met fruit, bladeren en insecten.\\n\\n'),
       (93684, 30141, 'fr', 'Loris lent du Bengale', 'Le loris lent du Bengale est un petit primate nocturne originaire des forêts d’Asie du Sud-Est. Caractérisée par ses grands yeux ronds et un motif facial distinctif, cette espèce se déplace lentement et avec précaution, ce qui l’aide à se déplacer dans son habitat arboricole. Le loris paresseux du Bengale est connu pour son mécanisme de défense unique : il sécrète une substance toxique à partir de ses glandes situées au niveau des coudes, qu''il peut appliquer sur son pelage ou transmettre par morsure.\\n\\nPrincipalement herbivore, il se nourrit de fruits, de feuilles et d''insectes.\\n\\n'),
       (93685, 30141, 'es', 'Loris lento de Bengala', 'El loris lento de Bengala es un pequeño primate nocturno originario de los bosques del sudeste asiático. Caracterizada por sus grandes ojos redondos y un patrón facial distintivo, esta especie tiene un estilo de movimiento lento y pausado, lo que le ayuda a desplazarse por su hábitat arbóreo. El loris perezoso de Bengala es conocido por su mecanismo de defensa único: segrega una sustancia tóxica a través de las glándulas de los codos, que puede untar en su pelaje o inyectar mediante mordeduras.\\n\\nEs principalmente herbívoro y se alimenta de frutos, hojas e insectos.\\n\\n'),
       (93686, 30142, 'nl', 'Bilby', 'De bilby, ook wel bekend als de grote bilby, is een nachtdier uit de orde van de buideldieren dat inheems is in Australië. Het is een middelgroot dier met een lichaamslengte van 29–55 cm (11–22 inch) en een staart van 20–34 cm (8–13 inch). De bilby heeft opvallende grote oren voor warmteafvoer en gehoor, een lange, puntige snuit, zijdezachte blauwgrijze vacht met een witte onderkant, en krachtige voorpoten met lange klauwen om mee te graven. \\n\\nHij is een alleseter en voedt zich met insecten, zaden, bollen, fruit, paddenstoelen en kleine gewervelde dieren. \\n\\n'),
       (93687, 30142, 'fr', 'Bilby', 'Le bilby, également appelé « grand bilby », est un marsupial nocturne originaire d''Australie. C''est un animal de taille moyenne, mesurant entre 29 et 55 cm (11 à 22 pouces) de longueur, avec une queue de 20 à 34 cm (8 à 13 pouces). Le bilby se caractérise par de grandes oreilles qui lui permettent de dissiper la chaleur et d’entendre, un long museau pointu, un pelage soyeux bleu-gris avec le ventre blanc, ainsi que de puissants membres antérieurs dotés de longues griffes lui servant à creuser. \\n\\nC''est un animal omnivore qui se nourrit d''insectes, de graines, de bulbes, de fruits, de champignons et de petits vertébrés. \\n\\n'),
       (93688, 30142, 'es', 'Bilby', 'El bilby, también conocido como «bilby mayor», es un marsupial nocturno originario de Australia. Es un animal de tamaño mediano, con una longitud corporal de entre 29 y 55 cm (11-22 pulgadas) y una cola de entre 20 y 34 cm (8-13 pulgadas). El bilby tiene unas orejas grandes y características que le sirven para disipar el calor y para oír, un hocico largo y puntiagudo, un pelaje sedoso de color azul grisáceo con el vientre blanco, y unas poderosas extremidades delanteras con largas garras para excavar. \\n\\nSu dieta es omnívora y se compone de insectos, semillas, bulbos, frutos, hongos y pequeños vertebrados. \\n\\n'),
       (93689, 30143, 'nl', 'Black Mamba',
        'The Black Mamba is one of the world\\\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\\n\\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\\n\\n'),
       (93690, 30143, 'fr', 'Black Mamba',
        'The Black Mamba is one of the world\\\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\\n\\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\\n\\n'),
       (93691, 30143, 'es', 'Black Mamba',
        'The Black Mamba is one of the world\\\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\\n\\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\\n\\n'),
       (93692, 30144, 'nl', 'Zwartrugjakhals', 'De zwartrugjakhals is een middelgrote hondachtige die inheems is in Zuid- en Oost-Afrika. Hij wordt gekenmerkt door een opvallende zwarte, zadelachtige vlek op zijn rug en heeft een slank lichaam, lange poten en een bossige staart. Deze dieren staan bekend om hun aanpassingsvermogen aan verschillende leefgebieden, waaronder savannes, graslanden en droge gebieden. Op sociaal vlak leven ze in monogame paren of kleine familiegroepen, waarbij ze vaak vocale communicatie vertonen door middel van een scala aan roepgeluiden.\\n\\nZwartrugjakhalzen zijn opportunistische alleseters die zich voeden met kleine zoogdieren, vogels, insecten en fruit. \\n\\n'),
       (93693, 30144, 'fr', 'Chacal à dos noir', 'Le chacal à dos noir est un canidé de taille moyenne originaire d''Afrique australe et orientale. Caractérisé par sa tache noire distinctive en forme de selle sur le dos, il présente un corps élancé, de longues pattes et une queue touffue. Il est connu pour sa capacité d''adaptation à divers habitats, notamment les savanes, les prairies et les régions arides. Sur le plan social, on les trouve en couples monogames ou en petits groupes familiaux, et ils communiquent souvent par la voix à l''aide d''une gamme variée de cris.\\n\\nLes chacals à dos noir sont des omnivores opportunistes qui se nourrissent de petits mammifères, d''oiseaux, d''insectes et de fruits. \\n\\n'),
       (93694, 30144, 'es', 'Chacal de lomo negro', 'El chacal de lomo negro es un cánido de tamaño mediano originario del sur y el este de África. Se caracteriza por su distintiva mancha negra en forma de silla de montar en el lomo, y tiene un cuerpo esbelto, patas largas y una cola tupida. Son conocidos por su capacidad de adaptación a diversos hábitats, como las sabanas, las praderas y las regiones áridas. En cuanto a su vida social, se les puede encontrar en parejas monógamas o en pequeños grupos familiares, y suelen comunicarse vocalmente mediante una variedad de llamadas.\\n\\nLos chacales de lomo negro son omnívoros oportunistas que se alimentan de pequeños mamíferos, aves, insectos y frutos. \\n\\n'),
       (93695, 30145, 'nl', 'Zwartwenkbraualbatros', 'De zwartbraualbatros is een middelgrote albatros met een lengte van 80–95 cm (31–37 in). Hij heeft een witte kop met een opvallende zwarte wenkbrauw, een donkergrijze rug en bovenvleugels, en een fel geeloranje snavel met een roodoranje punt. Deze vogels zijn uitstekende langeafstandsvliegers, die moeiteloos over de zuidelijke oceanen zweven, en kunnen meer dan 70 jaar oud worden.\\n\\nDe zwartbraualbatros voedt zich voornamelijk met vis, inktvis en schaaldieren, waarbij hij zijn prooi vaak van het oceaanoppervlak grijpt of aas zoekt in de buurt van vissersboten.\\n\\n'),
       (93696, 30145, 'fr', 'Albatros à sourcils noirs', 'L''albatros à sourcils noirs est un albatros de taille moyenne, mesurant entre 80 et 95 cm (31 à 37 pouces) de long. Il possède une tête blanche ornée d''un sourcil noir caractéristique, un dos et le dessus des ailes gris foncé, ainsi qu''un bec jaune-orange vif dont l''extrémité est rouge-orange. Ces oiseaux sont de superbes voiliers de longue distance, planant sans effort au-dessus des océans du Sud, et peuvent vivre plus de 70 ans.\\n\\nL''albatros à sourcils noirs se nourrit principalement de poissons, de calmars et de crustacés, qu''il attrape souvent à la surface de l''océan ou qu''il récupère près des bateaux de pêche.\\n\\n'),
       (93697, 30145, 'es', 'Albatros de ceja negra', 'El albatros de ceja negra es un albatros de tamaño mediano, que mide entre 80 y 95 cm (31-37 pulgadas) de longitud. Tiene la cabeza blanca con una ceja negra característica, el dorso y la parte superior de las alas de color gris oscuro, y un pico de color amarillo anaranjado brillante con la punta de color rojo anaranjado. Estas aves son magníficas voladoras de larga distancia, que planean sin esfuerzo sobre los océanos del sur, y pueden vivir más de 70 años.\\n\\nEl albatros de ceja negra se alimenta principalmente de peces, calamares y crustáceos, y a menudo captura a sus presas en la superficie del océano o se alimenta de restos cerca de los barcos pesqueros.\\n\\n'),
       (93698, 30146, 'nl', 'Zwartkoplepelaar', 'De zwartkoplepelaar is een ernstig bedreigde waadvogel die van nature voorkomt in de kustgebieden van Oost-Azië. Hij heeft een opvallend wit verenkleed, een kenmerkend zwart gezicht en een zwarte snavelpunt, en een lange, lepelvormige snavel. Volwassen exemplaren zijn ongeveer 70-80 cm (28-31 inch) groot en hebben een spanwijdte van 110-120 cm (43-47 inch).\\n\\nZijn dieet bestaat voornamelijk uit kleine vissen, schaaldieren en insecten, die hij vangt door met zijn lepelvormige snavel door ondiep water te vegen.\\n\\n'),
       (93699, 30146, 'fr', 'Spatule à face noire', 'La spatule à face noire est un oiseau limicole en danger critique d''extinction, originaire des régions côtières d''Asie de l''Est. Elle se caractérise par un plumage blanc saisissant, une face et une pointe de bec noires distinctives, ainsi qu''un long bec en forme de cuillère. Les adultes mesurent environ 70 à 80 cm (28 à 31 pouces) de haut et ont une envergure de 110 à 120 cm (43 à 47 pouces).\\n\\nSon régime alimentaire se compose principalement de petits poissons, de crustacés et d''insectes, qu''elle capture en balayant les eaux peu profondes avec son bec en forme de cuillère.\\n\\n'),
       (93700, 30146, 'es', 'Espátula de cara negra', 'La espátula de cara negra es un ave zancuda en peligro crítico de extinción, originaria de las regiones costeras del este de Asia. Presenta un llamativo plumaje blanco, una cara y la punta del pico de color negro muy característicos, y un pico largo con forma de cuchara. Los adultos miden entre 70 y 80 cm (28-31 pulgadas) de altura y tienen una envergadura de entre 110 y 120 cm (43-47 pulgadas).\\n\\nSu dieta se compone principalmente de pequeños peces, crustáceos e insectos, que captura barriendo con su pico en forma de cuchara las aguas poco profundas.\\n\\n'),
       (93701, 30147, 'nl', 'Zwartkopibis', 'De zwartkopibis is een slanke waadvogel met een lange, dunne, naar beneden gebogen zwarte snavel die geschikt is om mee te wroeten. Hij heeft een glanzend zwarte kop en nek, die contrasteren met zijn overwegend witte lichaamsverenkleed. De vleugels en schouderveren zijn zwart en hebben tijdens de vlucht een iriserende groen-paarse glans.\\n\\nHij foerageert door met zijn snavel heen en weer te zwaaien in modder of ondiep water, op zoek naar insecten, regenwormen, schaaldieren, kikkers en kleine vissen.\\n\\n'),
       (93702, 30147, 'fr', 'Ibis à tête noire', 'L''ibis à tête noire est un échassier élancé doté d''un long bec noir, fin et recourbé vers le bas, adapté à la recherche de nourriture. Sa tête et son cou d''un noir brillant contrastent avec le plumage de son corps, principalement blanc. Ses ailes et ses scapulaires sont noirs et présentent des reflets vert-violet irisés en vol.\\n\\nIl se nourrit en balayant le sol de son bec d''un côté à l''autre dans la boue ou les eaux peu profondes, à la recherche d''insectes, de vers de terre, de crustacés, de grenouilles et de petits poissons.\\n\\n'),
       (93703, 30147, 'es', 'Ibis de cabeza negra', 'El ibis de cabeza negra es un ave zancuda esbelta con un pico negro, largo, delgado y curvado hacia abajo, adaptado para hurgar. Tiene la cabeza y el cuello de un negro brillante, que contrasta con el plumaje de su cuerpo, predominantemente blanco. Las alas y las escápulares son negras, con un brillo iridiscente verde-púrpura cuando vuela.\\n\\nSe alimenta barriendo el pico de un lado a otro en el barro o en aguas poco profundas en busca de insectos, lombrices, crustáceos, ranas y peces pequeños.\\n\\n'),
       (93704, 30148, 'nl', 'Bontebok', 'De bontebok is een Zuid-Afrikaanse antilope met een opvallende paarsbruine vacht en witte aftekeningen op het gezicht, de achterhand en de buik. Hij is 70-90 cm (28-35 in) hoog bij de schouder en weegt 50-75 kg (110-165 lbs). Mannetjes hebben opvallende liervormige hoorns die tot 40 cm (16 in) lang kunnen worden. Deze sociale kuddedieren waren ooit bijna uitgestorven, maar gedijen nu goed in beschermde reservaten.\\n\\nDe bontebok graast op kort gras in het fynbos.\\n'),
       (93705, 30148, 'fr', 'Bontebok', 'Le bontebok est une antilope sud-africaine au pelage brun violacé caractéristique, avec des marques blanches sur le visage, la croupe et le ventre. Il mesure entre 70 et 90 cm (28 à 35 pouces) au garrot et pèse entre 50 et 75 kg (110 à 165 livres). Les mâles arborent des cornes proéminentes en forme de lyre pouvant atteindre 40 cm (16 pouces). Autrefois au bord de l''extinction, ces animaux sociables vivant en troupeaux prospèrent désormais dans des réserves protégées.\\n\\nLe bontebok broute les herbes courtes de l''habitat du fynbos.\\n'),
       (93706, 30148, 'es', 'Bontebok', 'El bontebok es un antílope sudafricano que se caracteriza por su pelaje de color marrón violáceo y sus marcas blancas en la cara, la grupa y el vientre. Mide entre 70 y 90 cm (28-35 pulgadas) de altura a la cruz y pesa entre 50 y 75 kg (110-165 libras). Los machos presentan unos cuernos prominentes en forma de lira que miden hasta 40 cm (16 pulgadas). Estos animales, que viven en manadas y son muy sociables, estuvieron a punto de extinguirse, pero ahora prosperan en reservas protegidas.\\n\\nEl bontebok se alimenta de pastos cortos en el hábitat del fynbos.\\n'),
       (93707, 30149, 'nl', 'Borneo-olifant', 'De Borneo-olifant is een ondersoort van de Aziatische olifant die voornamelijk op het eiland Borneo voorkomt. Het is de kleinste ondersoort van de Aziatische olifanten; volwassen dieren zijn doorgaans ongeveer 2 tot 2,5 meter (6,6 tot 8,2 voet) hoog bij de schouder en wegen tussen de 400 en 1.000 kg (880 tot 2.200 pond). Ze worden gekenmerkt door hun kleinere omvang, grotere oren en relatief rechte slagtanden in vergelijking met andere Aziatische olifanten. \\n\\nBorneo-olifanten voeden zich voornamelijk met bladeren, vruchten en schors. \\n\\n'),
       (93708, 30149, 'fr', 'Éléphant de Bornéo', 'L''éléphant de Bornéo est une sous-espèce de l''éléphant d''Asie que l''on trouve principalement sur l''île de Bornéo. C''est la plus petite sous-espèce d''éléphants d''Asie ; les adultes mesurent généralement entre 2 et 2,5 mètres (6,6 à 8,2 pieds) au garrot et pèsent entre 400 et 1 000 kg (880 à 2 200 livres). Ils se caractérisent par leur taille plus petite, leurs oreilles plus grandes et leurs défenses relativement droites par rapport aux autres éléphants d''Asie. \\n\\nLes éléphants de Bornéo se nourrissent principalement de feuilles, de fruits et d''écorce. \\n\\n'),
       (93709, 30149, 'es', 'Elefante de Borneo', 'El elefante de Borneo es una subespecie del elefante asiático que se encuentra principalmente en la isla de Borneo. Es la subespecie más pequeña de los elefantes asiáticos; los adultos suelen medir entre 2 y 2,5 metros (6,6 y 8,2 pies) de altura a la cruz y pesan entre 400 y 1.000 kg (880 y 2.200 libras). Se caracterizan por su menor tamaño, sus orejas más grandes y sus colmillos relativamente rectos en comparación con otros elefantes asiáticos. \\n\\nLos elefantes de Borneo se alimentan principalmente de hojas, frutos y corteza. \\n\\n'),
       (93710, 30150, 'nl', 'Bottle Nosed Dolphin',
        'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\\\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\\n\\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\\n\\n'),
       (93711, 30150, 'fr', 'Bottle Nosed Dolphin',
        'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\\\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\\n\\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\\n\\n'),
       (93712, 30150, 'es', 'Bottle Nosed Dolphin',
        'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\\\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\\n\\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\\n\\n'),
       (93713, 30151, 'nl', 'Bowheadwalvis', 'De Groenlandse walvis is een enorme, donkergekleurde Arctische walvis met een reusachtige, boogvormige kop die bijna een derde van zijn lichaam uitmaakt. Hij heeft geen rugvin, een dik, afgerond lichaam bedekt met een dikke vetlaag, en een sterk gewelfde kaak met de langste baleinplaten van alle walvissen.\\n\\nGrondwalvissen zijn filtervoeders die zich voeden met zoöplankton, zoals copepoden, krill en andere kleine kreeftachtigen.\\n\\n'),
       (93714, 30151, 'fr', 'Baleine boréale', 'La baleine boréale est une baleine arctique massive, de couleur foncée, dotée d’une tête énorme en forme d’arc qui représente près d’un tiers de son corps. Elle est dépourvue de nageoire dorsale, possède un corps épais et arrondi recouvert d’une épaisse couche de graisse, ainsi qu’une mâchoire fortement arquée qui abrite les plus longues fanons de toutes les baleines.\\n\\nLes baleines boréales sont des filtreurs qui se nourrissent de zooplancton, notamment de copépodes, de krill et d’autres petits crustacés.\\n\\n'),
       (93715, 30151, 'es', 'Ballena boreal', 'La ballena boreal es una ballena ártica de gran tamaño y color oscuro, con una enorme cabeza en forma de proa que constituye casi un tercio de su cuerpo. Carece de aleta dorsal, tiene un cuerpo grueso y redondeado cubierto de una densa capa de grasa y una mandíbula muy arqueada que alberga las placas de barbas más largas de todas las ballenas.\\n\\nLas ballenas boreales se alimentan por filtración y consumen zooplancton, como copépodos, krill y otros pequeños crustáceos.\\n\\n'),
       (93716, 30152, 'nl', 'Brahma-kip', 'De Brahma-kip is een groot ras dat bekend staat om zijn indrukwekkende omvang, zachtaardige karakter en opvallende bevederde poten. Ze hebben een opvallend uiterlijk met een breed lichaam, een korte nek en een bevederde kam, en ze komen voor in verschillende kleurvariëteiten, waaronder licht, donker en geelbruin. Brahma-kippen staan ook bekend om hun weerbaarheid in verschillende klimaten, waardoor ze een populaire keuze zijn onder pluimveeliefhebbers.\\n\\nHet dieet van Brahma-kippen moet bestaan uit hoogwaardig legkippenvoer, aangevuld met granen, verse groenten en fruit, en grit voor de spijsvertering.\\n\\n'),
       (93717, 30152, 'fr', 'Poulet Brahma', 'La poule Brahma est une race de grande taille réputée pour son gabarit impressionnant, son tempérament docile et ses pattes emplumées caractéristiques. Elle se distingue par son apparence saisissante, avec un corps large, un cou court et une crête emplumée, et se décline en plusieurs variétés de couleurs, notamment claire, foncée et fauve. Les poulets Brahma sont également réputés pour leur résistance à divers climats, ce qui en fait un choix très apprécié des amateurs de volaille.\\n\\nL''alimentation des poulets Brahma doit se composer d''aliments pour poules pondeuses de haute qualité, complétés par des céréales, des légumes et des fruits frais, ainsi que du gravier pour faciliter la digestion.\\n\\n'),
       (93718, 30152, 'es', 'Pollo Brahma', 'La gallina Brahma es una raza de gran tamaño conocida por su impresionante corpulencia, su temperamento dócil y sus características patas emplumadas. Tiene un aspecto llamativo, con un cuerpo ancho, un cuello corto y una cresta emplumada, y se presenta en varias variedades de color, entre ellas claro, oscuro y beige. Las gallinas Brahma también son conocidas por su resistencia en diversos climas, lo que las convierte en una opción muy popular entre los aficionados a la avicultura.\\n\\nLa dieta de las gallinas Brahma debe consistir en pienso para ponedoras de alta calidad, complementado con cereales, verduras y frutas frescas, y arena para facilitar la digestión.\\n\\n'),
       (93719, 30153, 'nl', 'Californisch konijn', 'Het Californische konijn is een gedomesticeerd ras dat bekend staat om zijn opvallende uiterlijk en vriendelijke karakter. Ze worden gekenmerkt door hun witte vacht met zwarte, grijze of chocoladekleurige aftekeningen op de oren, neus en poten. Californische konijnen zijn middelgroot tot groot en wegen doorgaans tussen de 8 en 10 pond (3,6 tot 4,5 kg).\\n\\nHet dieet van Californische konijnen moet voornamelijk bestaan uit hoogwaardig hooi, verse bladgroenten, een beperkte hoeveelheid brokjes en vers water.\\n\\n'),
       (93720, 30153, 'fr', 'Lapin californien', 'Le lapin californien est une race domestiquée connue pour son apparence caractéristique et son tempérament docile. Il se distingue par son pelage blanc parsemé de taches noires, grises ou chocolat sur les oreilles, le nez et les pattes. Les lapins californiens sont de taille moyenne à grande, pesant généralement entre 8 et 10 livres (3,6 à 4,5 kg).\\n\\nL''alimentation des lapins californiens doit se composer principalement de foin de haute qualité, de légumes-feuilles frais, d''une quantité limitée de granulés et d''eau fraîche.\\n\\n'),
       (93721, 30153, 'es', 'Conejo californiano', 'El conejo californiano es una raza domesticada conocida por su aspecto característico y su temperamento afable. Se caracteriza por su pelaje blanco con manchas negras, grises o de color chocolate en las orejas, la nariz y las patas. Los conejos californianos son de tamaño mediano a grande y suelen pesar entre 8 y 10 libras (3,6 y 4,5 kg).\\n\\nLa dieta de los conejos californianos debe consistir principalmente en heno de alta calidad, verduras de hoja frescas, una cantidad limitada de pienso y agua fresca.\\n\\n'),
       (93722, 30154, 'nl', 'Cape Fox', 'De Kaapse vos is een kleine, behendige hondachtige die inheems is in zuidelijk Afrika, met name in de Kaapregio. Hij heeft een slank lichaam, lange poten en een pluimstaart, met een vacht die doorgaans grijsbruin is en een lichtere onderbuik heeft. Kaapse vossen zijn voornamelijk nachtdieren en staan bekend om hun aanpassingsvermogen aan verschillende leefgebieden, waaronder graslanden en savannes. \\n\\nKaapse vossen zijn alleseters en voeden zich met kleine zoogdieren, vogels, insecten en fruit.\\n\\n'),
       (93723, 30154, 'fr', 'Cape Fox', 'Le renard du Cap est un petit canidé agile originaire d''Afrique australe, que l''on trouve notamment dans la région du Cap. Il présente un corps élancé, de longues pattes et une queue touffue, ainsi qu''un pelage généralement brun grisâtre avec un ventre plus clair. Les renards du Cap sont principalement nocturnes et sont connus pour leur capacité d''adaptation à divers habitats, notamment les prairies et les savanes. \\n\\nLes renards du Cap sont omnivores et se nourrissent de petits mammifères, d''oiseaux, d''insectes et de fruits.\\n\\n'),
       (93724, 30154, 'es', 'Cabo Fox', 'El zorro del Cabo es un cánido pequeño y ágil, originario del sur de África, que se encuentra sobre todo en la región del Cabo. Tiene un cuerpo esbelto, patas largas y una cola tupida, con un pelaje que suele ser de color marrón grisáceo y el vientre más claro. Los zorros del Cabo son principalmente nocturnos y destacan por su capacidad de adaptación a diversos hábitats, como las praderas y las sabanas. \\n\\nLos zorros del Cabo son omnívoros y se alimentan de pequeños mamíferos, aves, insectos y frutos.\\n\\n'),
       (93725, 30155, 'nl', 'Caquetá-titi-aap', 'De Caquetá-titi-aap is een kleine, bedreigde primaat die endemisch is in de Caquetá-regio in Colombia. Met een lichaamslengte van 30-40 cm (12-16 inch) en een gewicht van 1-1,5 kg (2,2-3,3 lbs) heeft hij een zachte, roodbruine vacht, een ronde kop en grote ogen die zijn aangepast aan zijn leven in de bomen.\\n\\nCaquetá-titiaapjes zijn alleseters; ze voeden zich voornamelijk met fruit en insecten, aangevuld met bladeren, zaden en kleine gewervelde dieren.\\n\\n'),
       (93726, 30155, 'fr', 'Singe titi de Caquetá', 'Le titi du Caquetá est un petit primate menacé d''extinction, endémique de la région du Caquetá en Colombie. Mesurant entre 30 et 40 cm (12 à 16 pouces) de long et pesant entre 1 et 1,5 kg (2,2 à 3,3 livres), il possède un pelage doux de couleur brun-rougeâtre, une tête arrondie et de grands yeux adaptés à son mode de vie arboricole.\\n\\nLes titi du Caquetá sont omnivores ; leur régime alimentaire se compose principalement de fruits et d’insectes, complétés par des feuilles, des graines et de petits vertébrés.\\n\\n'),
       (93727, 30155, 'es', 'Mono titi de Caquetá', 'El tití del Caquetá es un pequeño primate en peligro de extinción, endémico de la región del Caquetá, en Colombia. Con una longitud corporal de entre 30 y 40 cm (12-16 pulgadas) y un peso de entre 1 y 1,5 kg (2,2-3,3 libras), tiene un pelaje suave de color marrón rojizo, una cabeza redondeada y ojos grandes adaptados a su estilo de vida arbóreo.\\n\\nLos titíes del Caquetá son omnívoros y se alimentan principalmente de frutos e insectos, complementando su dieta con hojas, semillas y pequeños vertebrados.\\n\\n'),
       (93728, 30156, 'nl', 'Caribou', 'De kariboe is een groot poolhert dat is aangepast aan koude klimaten. Hun vacht verandert van kleur met de seizoenen: bruin in de zomer en grijs in de winter, met een witte achterkant en borst. Beide geslachten hebben een gewei, hoewel dat van de mannetjes groter en vertakter is. Ze staan bekend om hun lange trektochten, soms in groepen van wel 500.000 dieren.\\n\\nHet kariboe is een planteneter die zich voornamelijk voedt met korstmossen, mossen, grassen, bladeren en twijgen, waarbij het met zijn hoeven door de sneeuw graaft om bij het voedsel te komen.\\n\\n'),
       (93729, 30156, 'fr', 'Caribou', 'Le caribou est un grand cervidé arctique adapté aux climats froids. Son pelage change de couleur au fil des saisons : il est brun en été et gris en hiver, avec la croupe et la poitrine blanches. Les deux sexes portent des bois, mais ceux des mâles sont plus grands et plus ramifiés. Ils sont connus pour leurs longues migrations, parfois en groupes pouvant compter jusqu''à 500 000 individus.\\n\\nLe caribou est un herbivore qui se nourrit principalement de lichens, de mousses, d''herbes, de feuilles et de brindilles, qu''il déterre dans la neige à l''aide de ses sabots pour atteindre sa nourriture.\\n\\n'),
       (93730, 30156, 'es', 'Caribú', 'El caribú es un gran ciervo ártico adaptado a los climas fríos. Su pelaje cambia de color con las estaciones: es marrón en verano y gris en invierno, con la grupa y el pecho blancos. Ambos sexos tienen cuernos, aunque los de los machos son más grandes y ramificados. Son conocidos por sus largas migraciones, a veces en grupos de hasta 500 000 ejemplares.\\n\\nEl caribú es un herbívoro que se alimenta principalmente de líquenes, musgos, hierbas, hojas y ramitas, y excava en la nieve con sus pezuñas para alcanzar el alimento.\\n\\n'),
       (93731, 30157, 'nl', 'Chaco Eagle', 'De Chaco-arend is een grote roofvogel die voornamelijk voorkomt in de Chaco-regio in Zuid-Amerika. De Chaco-arend, die zich kenmerkt door zijn opvallende donkerbruine verenkleed en zijn kenmerkende witte kop en staart, staat bekend om zijn krachtige lichaamsbouw en indrukwekkende spanwijdte, die kan oplopen tot 6 feet (1,8 meter).  De Chaco-arend wordt beschouwd als een bijna bedreigde soort als gevolg van habitatverlies en jachtdruk, waardoor natuurbeschermingsmaatregelen essentieel zijn voor zijn voortbestaan.\\n\\nDeze arend voedt zich voornamelijk met kleine tot middelgrote zoogdieren, reptielen en vogels, en jaagt vaak vanaf een zitplaats of door hoog in de lucht te zweven.\\n\\n'),
       (93732, 30157, 'fr', 'Chaco Eagle', 'L''aigle du Chaco est un grand oiseau de proie que l''on trouve principalement dans la région du Chaco, en Amérique du Sud. Caractérisé par son plumage brun foncé saisissant et sa tête et sa queue blanches distinctives, l''aigle du Chaco est connu pour sa constitution puissante et son envergure impressionnante, qui peut atteindre 6 pieds (1,8 mètre).  L''aigle du Chaco est considéré comme une espèce quasi menacée en raison de la perte de son habitat et de la pression exercée par la chasse, ce qui rend les efforts de conservation essentiels à sa survie.\\n\\nCet aigle se nourrit principalement de mammifères de petite à moyenne taille, de reptiles et d''oiseaux, chassant souvent depuis un perchoir ou planant haut dans le ciel.\\n\\n'),
       (93733, 30157, 'es', 'Chaco Eagle', 'El águila del Chaco es una gran ave rapaz que se encuentra principalmente en la región del Chaco, en Sudamérica. Caracterizada por su llamativo plumaje marrón oscuro y su distintiva cabeza y cola blancas, el águila del Chaco es conocida por su poderosa complexión y su impresionante envergadura, que puede alcanzar hasta 6 pies (1,8 metros).  El águila del Chaco está considerada una especie «casi amenazada» debido a la pérdida de hábitat y a la presión cinegética, por lo que las medidas de conservación son esenciales para su supervivencia.\\n\\nEsta águila se alimenta principalmente de mamíferos de tamaño pequeño a mediano, reptiles y aves, y suele cazar desde una percha o planeando a gran altura en el cielo.\\n\\n'),
       (93734, 30158, 'nl', 'Kinbandpinguïn', 'De kinbandpinguïn is een middelgrote pinguïnsoort die voornamelijk voorkomt in het sub-Antarctische gebied. Hij is gemakkelijk te herkennen aan de opvallende smalle zwarte band onder zijn kop, die lijkt op een kinband en waaraan de soort zijn naam ontleent. Ze hebben een slank, gestroomlijnd lichaam, met een zwarte rug, een witte buik en een karakteristieke zwarte kap op hun kop.\\n\\nKinbandpinguïns zijn carnivoren (viseters). Ze hebben een zeer eenvoudig dieet, dat doorgaans bestaat uit waterdieren zoals kleine vissen en rondzwemmende mariene schaaldieren, waaronder krill.\\n\\n'),
       (93735, 30158, 'fr', 'Pingouin à jugulaire', 'Le manchot à jugulaire est une espèce de manchot de taille moyenne que l''on trouve principalement dans la région subantarctique. Il est facilement identifiable grâce à la bande noire étroite et caractéristique qui s''étend sous sa tête, ressemblant à une jugulaire, d''où le nom de l''espèce. Ils ont un corps élancé et profilé, avec un dos noir, un ventre blanc et une calotte noire caractéristique sur la tête.\\n\\nLes manchots à jugulaire sont carnivores (piscivores). Leur régime alimentaire est très simple et se compose généralement d''animaux aquatiques tels que de petits poissons et de crustacés marins errants, notamment le krill.\\n\\n'),
       (93736, 30158, 'es', 'Pingüino de barbilla', 'El pingüino de barbilla es una especie de pingüino de tamaño mediano que se encuentra principalmente en la región subantártica. Se identifica fácilmente por la característica banda negra y estrecha que le recorre la parte inferior de la cabeza, parecida a una correa de barbilla, de ahí el nombre de la especie. Tienen un cuerpo esbelto y aerodinámico, con el dorso negro, el vientre blanco y una característica corona negra en la cabeza.\\n\\nLos pingüinos de barbilla son carnívoros (piscívoros). Tienen una dieta muy sencilla, que suele consistir en animales acuáticos como peces pequeños y crustáceos marinos errantes, incluido el krill.\\n\\n'),
       (93737, 30159, 'nl', 'Commerson\\\'s Dolphin',
        'Commerson\\\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\\n\\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \\n\\n'),
       (93738, 30159, 'fr', 'Commerson\\\'s Dolphin',
        'Commerson\\\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\\n\\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \\n\\n'),
       (93739, 30159, 'es', 'Commerson\\\'s Dolphin',
        'Commerson\\\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\\n\\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \\n\\n'),
       (93740, 30160, 'nl', 'Gewone torenvalk', 'De gewone torenvalk is een kleine roofvogel die voorkomt in heel Europa, Azië en delen van Afrika. Het mannetje heeft een roodbruin verenkleed met een grijze kop, terwijl het vrouwtje meer egaal bruin is. Torenvalken staan bekend om hun scherpe zicht en hun vermogen om prooien vanaf grote hoogte te spotten. Ze nestelen doorgaans in rotswanden, bomen of door mensen gemaakte constructies, waardoor ze zich aan verschillende omgevingen kunnen aanpassen.\\n\\nDe torenvalk jaagt vaak op kleine zoogdieren, vogels en insecten.\\n\\n'),
       (93741, 30160, 'fr', 'Faucon crécerelle', 'Le faucon crécerelle est un petit rapace présent en Europe, en Asie et dans certaines régions d''Afrique. Le mâle a un plumage brun-rougeâtre et une tête grise, tandis que la femelle est d''un brun plus uniforme. Les crécerelles sont connues pour leur vue perçante et leur capacité à repérer leurs proies depuis de grandes hauteurs. Elles nichent généralement dans des falaises, des arbres ou des structures construites par l''homme, ce qui leur permet de s''adapter à divers environnements.\\n\\nLa crécerelle commune chasse souvent de petits mammifères, des oiseaux et des insectes.\\n\\n'),
       (93742, 30160, 'es', 'Cernícalo común', 'El cernícalo común es un pequeño ave rapaz que se encuentra en toda Europa, Asia y algunas zonas de África. El macho tiene un plumaje de color marrón rojizo con la cabeza gris, mientras que la hembra es de un marrón más uniforme. Los cernícalos son conocidos por su aguda vista y su capacidad para detectar a sus presas desde grandes alturas. Suelen anidar en acantilados, árboles o estructuras construidas por el hombre, lo que les permite adaptarse a diversos entornos.\\n\\nEl cernícalo común suele cazar pequeños mamíferos, aves e insectos.\\n\\n'),
       (93743, 30161, 'nl', 'Common Murre',
        'The Common Murre is a large seabird belonging to the auk family. The bird\\\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \\n\\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \\n\\n'),
       (93744, 30161, 'fr', 'Common Murre',
        'The Common Murre is a large seabird belonging to the auk family. The bird\\\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \\n\\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \\n\\n'),
       (93745, 30161, 'es', 'Common Murre',
        'The Common Murre is a large seabird belonging to the auk family. The bird\\\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \\n\\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \\n\\n'),
       (93746, 30162, 'nl', 'Gewone vampiervleermuis', 'De gewone vampiervleermuis is een kleine vleermuis met een bladachtige neus die inheems is in Latijns-Amerika. Hij heeft kort haar, met een zilvergrijze vacht aan de onderkant, die afsteekt tegen de donkerdere vacht op zijn rug. Een goed ontwikkelde duim met klauw aan elke vleugel wordt gebruikt om op prooien te klimmen en het dier te helpen bij het opstijgen. Terwijl de meeste andere vleermuizen het vermogen om zich op het land te verplaatsen bijna volledig hebben verloren, vormen vampiervleermuizen hierop een uitzondering. Ze kunnen rennen met een unieke, springende gang, waarbij de voorpoten in plaats van de achterpoten worden gebruikt om zich voort te stuwen, aangezien de vleugels veel krachtiger zijn dan de poten.\\n\\nGewone vampiervleermuizen zijn carnivoren en voeden zich voornamelijk met het bloed van zoogdieren, met name dat van vee zoals runderen en paarden.\\n\\n'),
       (93747, 30162, 'fr', 'Chauve-souris vampire commune', 'La chauve-souris vampire commune est une petite chauve-souris au museau en forme de feuille, originaire d''Amérique latine. Elle possède un pelage court, gris argenté sur le ventre, qui contraste avec le pelage plus foncé de son dos. Un pouce griffu et bien développé sur chaque aile lui sert à s''agripper à ses proies et l''aide à prendre son envol. Alors que la plupart des autres chauves-souris ont presque entièrement perdu leur capacité à se déplacer sur terre, les chauves-souris vampires font exception. Elles peuvent courir en adoptant une démarche unique, par bonds, dans laquelle elles utilisent leurs membres antérieurs plutôt que leurs membres postérieurs pour se propulser vers l''avant, leurs ailes étant bien plus puissantes que leurs pattes.\\n\\nLes chauves-souris vampires communes sont carnivores et se nourrissent principalement de sang de mammifères, en particulier celui du bétail, comme les bovins et les chevaux.\\n\\n'),
       (93748, 30162, 'es', 'Murciélago vampiro común', 'El murciélago vampiro común es un murciélago pequeño, de nariz en forma de hoja, originario de América Latina. Tiene el pelaje corto, de color gris plateado en la parte ventral, que contrasta con el pelaje más oscuro del dorso. Cuenta con un pulgar bien desarrollado y provisto de garras en cada ala, que utiliza para trepar sobre sus presas y ayudarse a levantar el vuelo. Mientras que la mayoría de los demás murciélagos han perdido casi por completo la capacidad de moverse por tierra, los murciélagos vampiros son una excepción. Pueden correr con un estilo de locomoción único y saltilante en el que utilizan las extremidades delanteras en lugar de las traseras para impulsarse hacia delante, ya que sus alas son mucho más poderosas que sus patas.\\n\\nLos murciélagos vampiros comunes son carnívoros y se alimentan principalmente de sangre de mamíferos, en particular de ganado como vacas y caballos.\\n\\n'),
       (93749, 30163, 'nl', 'Gewone wombat', 'Gewone wombats zijn kortbenige, gespierde viervoetige buideldieren die inheems zijn in Australië. De gewone wombat is zelfs het grootste gravende herbivore zoogdier ter wereld. Gewone wombats zijn stevig gebouwd en zitten laag bij de grond. Ze onderscheiden zich van beide harige-neuswombats door hun kale neus. Ze zijn ongeveer 1 m (40 inch) lang, hebben kleine, stompe staarten en wegen tussen de 20 en 35 kg (44 en 77 lb).\\n\\nDe gewone wombat is een herbivoor (bladeter) dat zich voornamelijk voedt met gras en mos. Het dieet van dit dier omvat ook struiken, wortels en schors. \\n\\n'),
       (93750, 30163, 'fr', 'Wombat commun', 'Les wombats communs sont des marsupiaux quadrupèdes musclés aux pattes courtes, originaires d''Australie. En effet, le wombat commun est le plus grand mammifère herbivore fouisseur au monde. Les wombats communs sont robustes et ont une silhouette proche du sol. Ils se distinguent des wombats à nez poilu par leur nez glabre. Ils mesurent environ 1 m (40 pouces) de long, ont une petite queue trapue et pèsent entre 20 et 35 kg (44 et 77 livres).\\n\\nLe wombat commun est un animal herbivore (folivore) qui se nourrit principalement d''herbe et de mousse. Son régime alimentaire comprend également des arbustes, des racines et de l''écorce. \\n\\n'),
       (93751, 30163, 'es', 'Wombat común', 'Los wombats comunes son marsupiales cuadrúpedos, musculosos y de patas cortas, originarios de Australia. De hecho, el wombat común es el mamífero herbívoro excavador más grande del mundo. Los wombats comunes son robustos y tienen una complexión cercana al suelo. Se distinguen de los wombats de nariz peluda por su nariz sin pelo. Miden aproximadamente 1 m (40 pulgadas) de longitud, tienen colas pequeñas y rechonchas y pesan entre 20 y 35 kg (44 y 77 libras).\\n\\nEl wombat común es un animal herbívoro (folívoro) que se alimenta principalmente de hierba y musgo. Su dieta también incluye arbustos, raíces y corteza. \\n\\n'),
       (93752, 30164, 'nl', 'Gewone wollige aap', 'De gewone wollige aap is een grote, in bomen levende primaat die inheems is in het Amazonewoud in Zuid-Amerika. Hij staat bekend om zijn dikke, wollige vacht en zijn grijpstaart, die hij gebruikt om zich aan takken vast te klampen. Hij weegt 5-9 kg (11-20 lbs) en heeft een lichaamslengte tot 70 cm (28 inches). Hij heeft een grijsbruine vacht, een lange snuit en een levensduur van 20-30 jaar in het wild.\\n\\nGewone wolapen zijn voornamelijk frugivoor (fruiteter), aangevuld met bladeren, zaden en insecten.\\n\\n'),
       (93753, 30164, 'fr', 'Singe laineux commun', 'Le singe laineux commun est un grand primate arboricole originaire de la forêt amazonienne en Amérique du Sud, connu pour son épais pelage laineux et sa queue préhensile qui lui sert à s’agripper aux branches. Pesant entre 5 et 9 kg (11 à 20 livres) et mesurant jusqu’à 70 cm (28 pouces) de longueur, il possède un pelage brun grisâtre, un long museau et une espérance de vie de 20 à 30 ans à l’état sauvage.\\n\\nLes singes laineux communs sont principalement frugivores (ils se nourrissent de fruits), mais complètent leur alimentation avec des feuilles, des graines et des insectes.\\n\\n'),
       (93754, 30164, 'es', 'Mono lanudo común', 'El mono lanudo común es un primate arbóreo de gran tamaño, originario de la selva amazónica de Sudamérica, conocido por su espeso pelaje lanudo y su cola prensil, que utiliza para agarrarse a las ramas. Pesa entre 5 y 9 kg (11-20 libras) y mide hasta 70 cm (28 pulgadas) de longitud corporal; tiene un pelaje de color marrón grisáceo, un hocico alargado y una esperanza de vida de entre 20 y 30 años en estado silvestre.\\n\\nLos monos lanudos comunes son principalmente frugívoros (se alimentan de frutas), aunque también consumen hojas, semillas e insectos.\\n\\n'),
       (93755, 30165, 'nl', 'Koraalkathaai', 'De koraalkat haai is een kleine haaiensoort die voorkomt in de ondiepe wateren van de koraalriffen in het westelijke deel van de Stille Oceaan en de Indische Oceaan. Deze haai wordt doorgaans maximaal 1,2 meter (4 voet) lang en wordt gekenmerkt door zijn slanke lichaam, grote ogen en opvallend patroon van donkerbruine of zwarte vlekken en strepen op een lichtere achtergrond, waardoor hij zich goed kan camoufleren tussen het koraal.\\n\\nKoraalkatvissen zijn nachtdieren en voeden zich voornamelijk met kleine vissen, schaaldieren en ongewervelde dieren, waarbij ze hun scherpe reukzin gebruiken om prooien op te sporen. \\n\\n'),
       (93756, 30165, 'fr', 'Requin-chat de corail', 'Le requin-chat des coraux est une petite espèce de requin que l''on trouve dans les eaux peu profondes des récifs coralliens de l''ouest du Pacifique et de l''océan Indien. Atteignant généralement une longueur maximale de 1,2 mètre (4 pieds), ce requin se caractérise par son corps élancé, ses grands yeux et son motif distinctif de taches et de rayures brun foncé ou noires sur un fond plus clair, qui lui assure un camouflage efficace parmi les coraux.\\n\\nLes requins-chats des coraux sont nocturnes et se nourrissent principalement de petits poissons, de crustacés et d''invertébrés, utilisant leur odorat très développé pour localiser leurs proies. \\n\\n'),
       (93757, 30165, 'es', 'Tiburón gato coralino', 'El tiburón gato de coral es una especie pequeña de tiburón que se encuentra en las aguas poco profundas de los arrecifes de coral del Pacífico occidental y del océano Índico. Este tiburón, que suele alcanzar una longitud de hasta 1,2 metros (4 pies), se caracteriza por su cuerpo esbelto, sus grandes ojos y su distintivo patrón de manchas y rayas de color marrón oscuro o negro sobre un fondo más claro, lo que le proporciona un camuflaje eficaz entre los corales.\\n\\nLos tiburones gato de coral son nocturnos y se alimentan principalmente de peces pequeños, crustáceos e invertebrados, utilizando su agudo sentido del olfato para localizar a sus presas. \\n\\n'),
       (93758, 30166, 'nl', 'Dalmatian Pelican',
        'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\\\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \\"curly-headed\\" look.\\n\\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\\n\\n'),
       (93759, 30166, 'fr', 'Dalmatian Pelican',
        'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\\\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \\"curly-headed\\" look.\\n\\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\\n\\n'),
       (93760, 30166, 'es', 'Dalmatian Pelican',
        'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\\\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \\"curly-headed\\" look.\\n\\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\\n\\n'),
       (93761, 30167, 'nl', 'De Brazza\\\'s Monkey',
        'De Brazza\\\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \\\'\\\'neglectus,\\\'\\\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\\n\\nAs omnivorous animals, De Brazza\\\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\\n\\n'),
       (93762, 30167, 'fr', 'De Brazza\\\'s Monkey',
        'De Brazza\\\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \\\'\\\'neglectus,\\\'\\\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\\n\\nAs omnivorous animals, De Brazza\\\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\\n\\n'),
       (93763, 30167, 'es', 'De Brazza\\\'s Monkey',
        'De Brazza\\\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \\\'\\\'neglectus,\\\'\\\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\\n\\nAs omnivorous animals, De Brazza\\\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\\n\\n'),
       (93764, 30168, 'nl', 'Dingo',
        'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\\\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\\n\\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\\n\\n'),
       (93765, 30168, 'fr', 'Dingo',
        'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\\\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\\n\\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\\n\\n'),
       (93766, 30168, 'es', 'Dingo',
        'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\\\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\\n\\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\\n\\n'),
       (93767, 30170, 'nl', 'Oostelijke grijze kangoeroe', 'De oostelijke grijze kangoeroe is het grootste buideldier van Australië. Hij heeft een zilvergrijze vacht met een lichtere buik; mannetjes hebben vaak een roodachtige vacht op hun onderarmen en schouders. Ze hebben grote, gespierde achterpoten om mee te springen (tot 9 m/30 ft in één sprong bij snelheden van 50 km/u of 30 mph), een lange, dikke staart voor het evenwicht en korte voorpoten.\\n\\nOostelijke grijze kangoeroes zijn herbivore grazers die zich voeden met grassen, kruidachtige planten, bladeren en struiken.\\n\\n'),
       (93768, 30170, 'fr', 'Kangourou gris de l''Est', 'Le kangourou gris de l''Est est le plus grand marsupial d''Australie. Il possède un pelage gris argenté et un ventre plus clair ; les mâles ont souvent un pelage rougeâtre sur les avant-bras et les épaules. Ils possèdent de grandes pattes arrière musclées qui leur permettent de sauter (jusqu''à 9 m/30 ft d''un seul bond à une vitesse de 50 km/h ou 30 mph), une longue queue épaisse qui leur assure l''équilibre, et des pattes avant courtes.\\n\\nLes kangourous gris de l''Est sont des brouteurs herbivores qui se nourrissent d''herbes, de plantes herbacées, de feuilles et d''arbustes.\\n\\n'),
       (93769, 30170, 'es', 'Canguro gris del este', 'El canguro gris oriental es el marsupial más grande de Australia. Tiene un pelaje gris plateado con el vientre más claro; los machos suelen tener el pelaje rojizo en los antebrazos y los hombros. Tienen unas patas traseras grandes y musculosas para saltar (hasta 9 m/30 pies en un solo salto a velocidades de 50 km/h o 30 mph), una cola larga y gruesa que les ayuda a mantener el equilibrio, y unas patas delanteras cortas.\\n\\nLos canguros grises del este son herbívoros que se alimentan de pastos, plantas herbáceas, hojas y arbustos.\\n\\n'),
       (93770, 30171, 'nl', 'Keizerspinguïn', 'De keizerspinguïn is de grootste en zwaarste van alle levende pinguïnsoorten en komt uitsluitend voor op Antarctica; de grootste exemplaren kunnen bijna 100 pond (45 kg) wegen. De keizerspinguïn heeft een gestroomlijnd verenkleed, bestaande uit glanzende, waterafstotende veren, die voorkomen dat de huid nat wordt. De zwartblauwe kop is bedekt met grote witte en gele vlekken bij de oren. De bovenkant is blauwgrijs, terwijl de onderkant wit is. Deze loopvogels kunnen tot wel 18 minuten onder water blijven wanneer ze op jacht zijn naar voedsel. Keizerspinguïns worden in het wild regelmatig 20 jaar oud.\\n\\nDeze pinguïn is een carnivoor (vis- en weekdiereter) en voedt zich uitsluitend met waterdieren. Hun dieet bestaat voornamelijk uit krill en vis, aangevuld met inktvis en schaaldieren.\\n\\n'),
       (93771, 30171, 'fr', 'Manchot empereur', 'Le manchot empereur est la plus grande et la plus lourde de toutes les espèces de manchots existantes ; endémique de l''Antarctique, il peut atteindre près de 100 livres (45 kg) chez les plus grands spécimens. Il possède un plumage aérodynamique, composé de plumes brillantes et hydrofuges qui empêchent sa peau de se mouiller. Sa tête bleu noirâtre est parsemée de grandes taches blanches et jaunes au niveau des oreilles. Le dessus de son corps est gris-bleu, tandis que le dessous est blanc. Ces oiseaux incapables de voler peuvent rester sous l''eau jusqu''à 18 minutes lorsqu''ils chassent pour se nourrir. Les manchots empereurs vivent généralement jusqu’à 20 ans à l’état sauvage.\\n\\nCe manchot est carnivore (piscivore et molluscivore) et se nourrit exclusivement d’animaux aquatiques. Son régime alimentaire se compose principalement de krill et de poissons, complété par des calmars et des crustacés.\\n\\n'),
       (93772, 30171, 'es', 'Pingüino emperador', 'El pingüino emperador es la especie de pingüino viva más alta y pesada, y es endémica de la Antártida, llegando a pesar casi 100 libras en su tamaño máximo (45 kg). El pingüino emperador tiene un plumaje aerodinámico, formado por plumas brillantes e impermeables que evitan que la piel se moje. La cabeza, de color azul negruzco, está cubierta de grandes marcas blancas y amarillas en las orejas. Las partes superiores son de color gris azulado, mientras que las inferiores son blancas. Estas aves no voladoras pueden permanecer bajo el agua hasta 18 minutos cuando cazan para alimentarse. Los pingüinos emperador suelen vivir hasta los 20 años en libertad.\\n\\nEste pingüino es carnívoro (piscívoro y molusquívoro) y se alimenta exclusivamente de animales acuáticos. Su dieta se compone principalmente de krill y peces, complementada con calamares y crustáceos.\\n\\n'),
       (93773, 30172, 'nl', 'Rechtkuifpinguïn', 'De rechtopstaande kuifpinguïn is een middelgrote pinguïn die endemisch is in de regio Nieuw-Zeeland en alleen broedt op de Bounty- en Antipodes-eilanden. Hij is gemakkelijk te herkennen aan zijn opvallende gele kuifveren die rechtop op zijn kop staan. Hij heeft een zwarte bovenkant, een witte onderkant en een gele oogstreep. Volwassen exemplaren wegen doorgaans tussen de 5,5 en 8,5 pond (2,5 tot 4 kg) en zijn ongeveer 20 tot 25 inch (50 tot 65 cm) hoog.\\n\\nRechthoofdpinguïns zijn carnivoren (viseters). Het dieet van deze vogels bestaat voornamelijk uit vis, krill, schaaldieren en inktvissen.\\n\\n'),
       (93774, 30172, 'fr', 'Pingouin à crête dressée', 'Le manchot à crête dressée est un manchot de taille moyenne, endémique de la région néo-zélandaise, qui ne se reproduit que sur les îles Bounty et Antipodes. Il est facilement reconnaissable à sa crête jaune éclatante, dont les plumes se dressent sur sa tête. Il présente un plumage noir sur le dessus, blanc sur le dessous et une bande jaune autour des yeux. Les adultes pèsent généralement entre 5,5 et 8,5 livres (2,5 à 4 kg) et mesurent environ 20 à 25 pouces (50 à 65 cm) de hauteur.\\n\\nLes manchots à crête dressée sont carnivores (piscivores). Le régime alimentaire de ces oiseaux se compose principalement de poissons, de krill, de crustacés et de céphalopodes.\\n\\n'),
       (93775, 30172, 'es', 'Pingüino de cresta erguida', 'El pingüino de cresta erguida es un pingüino de tamaño mediano, endémico de la región de Nueva Zelanda, que solo se reproduce en las islas Bounty y Antípodas. Se reconoce fácilmente por sus llamativas plumas amarillas de la cresta, que se yerguen erguidas sobre su cabeza. Tiene las partes superiores negras, las inferiores blancas y una franja amarilla alrededor del ojo. Los adultos suelen pesar entre 5,5 y 8,5 libras (2,5 y 4 kg) y miden entre 20 y 25 pulgadas (50 y 65 cm) de altura.\\n\\nLos pingüinos de cresta erguida son carnívoros (piscívoros). La dieta de estas aves se compone principalmente de peces, krill, crustáceos y cefalópodos.\\n\\n'),
       (93776, 30173, 'nl', 'Ethiopische leeuw', 'De Ethiopische leeuw is een ondersoort van de leeuw die in Ethiopië en delen van Oost-Afrika voorkomt. Hij heeft een kenmerkende donkere manen bij mannetjes, een geelbruine vacht en een krachtig postuur. Volwassen mannetjes zijn ongeveer 110-120 cm (43-47 inch) hoog bij de schouder en wegen 150-250 kg (330-550 pond), terwijl vrouwtjes kleiner zijn. \\n\\nZijn dieet bestaat voornamelijk uit grote hoefdieren zoals zebra''s, antilopen en gnoes, waarop hij in troepen jaagt met behulp van gecoördineerde strategieën.\\n\\n'),
       (93777, 30173, 'fr', 'Lion d''Éthiopie', 'Le lion d''Éthiopie est une sous-espèce de lion originaire d''Éthiopie et de certaines régions d''Afrique de l''Est. Il se caractérise par une crinière foncée distinctive chez les mâles, un pelage fauve et une constitution puissante. Les adultes mesurent environ 110 à 120 cm (43 à 47 pouces) au garrot et pèsent entre 150 et 250 kg (330 à 550 livres) pour les mâles, les femelles étant plus petites. \\n\\nSon régime alimentaire se compose principalement de grands ongulés tels que les zèbres, les antilopes et les gnous, qu’il chasse en troupeau à l’aide de stratégies coordonnées.\\n\\n'),
       (93778, 30173, 'es', 'León etíope', 'El león etíope es una subespecie de león originaria de Etiopía y algunas zonas de África Oriental. Se caracteriza por una melena oscura muy distintiva en los machos, un pelaje leonado y una complexión robusta. Los adultos miden entre 110 y 120 cm (43-47 pulgadas) de altura a la altura del hombro y pesan entre 150 y 250 kg (330-550 libras) en el caso de los machos, mientras que las hembras son más pequeñas. \\n\\nSu dieta se compone principalmente de grandes ungulados como cebras, antílopes y ñus, a los que caza en manadas utilizando estrategias coordinadas.\\n\\n'),
       (93779, 30174, 'nl', 'Ethiopian Wolf',
        'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\\\'s rarest canids, and Africa\\\'s most endangered carnivore.\\n\\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \\n\\n'),
       (93780, 30174, 'fr', 'Ethiopian Wolf',
        'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\\\'s rarest canids, and Africa\\\'s most endangered carnivore.\\n\\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \\n\\n'),
       (93781, 30174, 'es', 'Ethiopian Wolf',
        'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\\\'s rarest canids, and Africa\\\'s most endangered carnivore.\\n\\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \\n\\n'),
       (93782, 30175, 'nl', 'Eurasian Golden Oriole',
        'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\\\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \\n\\nEurasian Golden Oriole\\\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\\n\\n'),
       (93783, 30175, 'fr', 'Eurasian Golden Oriole',
        'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\\\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \\n\\nEurasian Golden Oriole\\\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\\n\\n'),
       (93784, 30175, 'es', 'Eurasian Golden Oriole',
        'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\\\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \\n\\nEurasian Golden Oriole\\\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\\n\\n'),
       (93785, 30176, 'nl', 'Eurasian Hoopoe',
        'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \\"hoop-hoop\\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\\n\\nThe Eurasian Hoopoe\\\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\\n\\n'),
       (93786, 30176, 'fr', 'Eurasian Hoopoe',
        'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \\"hoop-hoop\\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\\n\\nThe Eurasian Hoopoe\\\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\\n\\n'),
       (93787, 30176, 'es', 'Eurasian Hoopoe',
        'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \\"hoop-hoop\\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\\n\\nThe Eurasian Hoopoe\\\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\\n\\n'),
       (93788, 30177, 'nl', 'Europese moeflon', 'De Europese moeflon is een kleine, wilde schapenondersoort die van nature voorkomt op de mediterrane eilanden Sardinië en Corsica. Het wordt beschouwd als de voorouder van het gedomesticeerde schaap en staat bekend om zijn behendige, in de bergen levende levenswijze. Ze hebben een roodbruine vacht met een witte buik, donkere strepen op de poten en grote, gebogen hoorns bij de rammen (tot 80 cm (32 inch) lang) ter verdediging en om indruk te maken.\\n\\nDe Europese moeflon is een herbivore grazer en bladeter, aangepast aan de voedselarme mediterrane vegetatie. \\n\\n'),
       (93789, 30177, 'fr', 'Mouflon européen', 'Le mouflon européen est une petite sous-espèce de mouton sauvage originaire des îles méditerranéennes de Sardaigne et de Corse. Il est considéré comme l''ancêtre du mouton domestique et est connu pour son mode de vie agile et montagnard. Il présente un pelage brun-rougeâtre avec un ventre blanc, des rayures foncées sur les pattes et, chez les béliers, de grandes cornes recourbées (pouvant atteindre 80 cm (32 pouces) de long) servant à la défense et à la parade.\\n\\nLe mouflon européen est un herbivore qui se nourrit de broutage et de broutage d''arbustes, adapté à la végétation méditerranéenne pauvre en nutriments. \\n\\n'),
       (93790, 30177, 'es', 'Muflón europeo', 'El muflón europeo es una subespecie de oveja salvaje de pequeño tamaño, originaria de las islas mediterráneas de Cerdeña y Córcega. Se considera el antepasado de la oveja doméstica y destaca por su estilo de vida ágil y de montaña. Presentan un pelaje de color marrón rojizo con el vientre blanco, rayas oscuras en las patas y, en el caso de los carneros, cuernos grandes y curvados (de hasta 80 cm (32 pulgadas) de longitud) que utilizan para defenderse y para el cortejo.\\n\\nEl muflón europeo es un herbívoro que se alimenta de pastos y brotes, adaptado a la vegetación mediterránea, pobre en nutrientes. \\n\\n'),
       (93791, 30178, 'nl', 'Fea\\\'s Muntjac',
        'Fea\\\'s Muntjac, also known as the Fea\\\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\\\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\\n\\nFea\\\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\\n\\n'),
       (93792, 30178, 'fr', 'Fea\\\'s Muntjac',
        'Fea\\\'s Muntjac, also known as the Fea\\\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\\\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\\n\\nFea\\\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\\n\\n'),
       (93793, 30178, 'es', 'Fea\\\'s Muntjac',
        'Fea\\\'s Muntjac, also known as the Fea\\\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\\\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\\n\\nFea\\\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\\n\\n'),
       (93794, 30179, 'nl', 'IJzerkleurige havik', 'De roestkleurige havik is een grote, krachtige Noord-Amerikaanse havik die in twee kleurvarianten voorkomt. Lichte exemplaren hebben roestrode (ferruginous) bovendelen, een witte borst en roodbruine pootveren; donkere exemplaren zijn over het algemeen bruin. Hij komt voor in open graslanden, woestijnen en prairies in het westen van Noord-Amerika. \\n\\nDe roestbuikbuizerd jaagt op kleine zoogdieren zoals konijnen, grondeekhoorns en muizen, maar ook op vogels en insecten.\\n\\n'),
       (93795, 30179, 'fr', 'Faucon ferrugineux', 'La buse ferrugineuse est une grande et puissante buse d''Amérique du Nord qui se décline en deux variétés de couleur. Les individus de la variété claire ont le dessus rouge-rouille (ferrugineux), la poitrine blanche et les plumes des pattes rousses ; ceux de la variété foncée sont globalement bruns. On le trouve dans les prairies ouvertes, les déserts et les plaines de l''ouest de l''Amérique du Nord. \\n\\nLa buse ferrugineuse chasse de petits mammifères tels que les lapins, les écureuils terrestres et les souris, ainsi que des oiseaux et des insectes.\\n\\n'),
       (93796, 30179, 'es', 'Gavilán ferruginoso', 'El halcón ferruginoso es un halcón norteamericano grande y poderoso que presenta dos variantes de color. Las variantes claras tienen las partes superiores de color rojo óxido (ferruginoso), el pecho blanco y las plumas de las patas de color rojizo; las variantes oscuras son de color marrón en su conjunto. Se encuentra en praderas abiertas, desiertos y praderas del oeste de América del Norte. \\n\\nEl halcón ferruginoso caza pequeños mamíferos como conejos, ardillas terrestres y ratones; también aves e insectos.\\n\\n'),
       (93797, 30180, 'nl', 'Fossa',
        'The Fossa is a sleek, agile predator endemic to Madagascar\\\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\\n\\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\\n\\n'),
       (93798, 30180, 'fr', 'Fossa',
        'The Fossa is a sleek, agile predator endemic to Madagascar\\\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\\n\\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\\n\\n'),
       (93799, 30180, 'es', 'Fossa',
        'The Fossa is a sleek, agile predator endemic to Madagascar\\\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\\n\\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\\n\\n'),
       (93800, 30181, 'nl', 'Galah', 'De Galah, ook wel bekend als de rozenborstkaketoe, is een middelgrote papegaai die inheems is in Australië. De galah is herkenbaar aan zijn opvallende roze en grijze verenkleed en heeft een kenmerkende kuif die hij kan opzetten of neerlaten. Volwassen exemplaren zijn doorgaans ongeveer 32 tot 38 cm (12 tot 15 inch) lang. Het zijn zeer sociale vogels, die vaak in grote zwermen voorkomen, en staan bekend om hun speelse en intelligente gedrag.\\n\\nGalahs voeden zich voornamelijk met zaden, fruit en noten, waarbij ze hun sterke snavels gebruiken om harde schillen open te breken.\\n\\n'),
       (93801, 30181, 'fr', 'Cacatoès rose', 'Le galah, également connu sous le nom de cacatoès à poitrine rose, est un perroquet de taille moyenne originaire d''Australie. Reconnaissable à son plumage rose et gris éclatant, le galah possède une crête caractéristique qu’il peut dresser ou abaisser. Les adultes mesurent généralement entre 32 et 38 cm (12 à 15 pouces) de long. Ce sont des oiseaux très sociables, que l''on trouve souvent en grands groupes, et qui sont connus pour leur comportement enjoué et intelligent.\\n\\nLes galahs se nourrissent principalement de graines, de fruits et de noix, utilisant leur bec puissant pour casser les coques dures.\\n\\n'),
       (93802, 30181, 'es', 'Galah', 'La galah, también conocida como cacatúa de pecho rosa, es un loro de tamaño mediano originario de Australia. Reconocible por su llamativo plumaje rosa y gris, la galah tiene una cresta característica que puede levantar o bajar. Los adultos suelen medir entre 32 y 38 cm (12 y 15 pulgadas) de longitud. Son aves muy sociables, que suelen formar grandes bandadas, y son conocidas por su comportamiento juguetón e inteligente.\\n\\nLas galahes se alimentan principalmente de semillas, frutas y frutos secos, y utilizan sus fuertes picos para romper las cáscaras duras.\\n\\n'),
       (93803, 30183, 'nl', 'Ganges-rivierdolfijn', 'De Ganges-dolfijn is een zoetwaterdolfijnsoort die inheems is in de Ganges. Ze zijn doorgaans grijsachtig van kleur, waarbij sommige exemplaren een roze tint vertonen, vooral wanneer ze opgewonden of geagiteerd zijn. Ze kunnen 2,5 tot 3 meter (8 tot 10 voet) lang worden en tussen de 100 en 150 kg (220 tot 330 pond) wegen. Deze dolfijnen staan bekend om hun echolocatievermogen, dat ze gebruiken om te navigeren en te jagen in de troebele wateren van hun rivierhabitats.\\n\\nDe Ganges-rivierdolfijn voedt zich voornamelijk met een verscheidenheid aan vissen en ongewervelde dieren die in zijn zoetwaterhabitat voorkomen.\\n\\n'),
       (93804, 30183, 'fr', 'Dauphin du Gange', 'Le dauphin du Gange est une espèce de dauphin d''eau douce originaire du Gange. Il est généralement de couleur grisâtre, certains individus présentant une teinte rosâtre, notamment lorsqu''ils sont excités ou agités. Ils peuvent atteindre une longueur de 2,5 à 3 mètres (8 à 10 pieds) et peser entre 100 et 150 kg (220 à 330 livres). Ces dauphins sont connus pour leurs capacités d''écholocation, qu''ils utilisent pour s''orienter et chasser dans les eaux troubles de leur habitat fluvial.\\n\\nLe dauphin du Gange se nourrit principalement d''une grande variété de poissons et d''invertébrés présents dans son habitat d''eau douce.\\n\\n'),
       (93805, 30183, 'es', 'Delfín del río Ganges', 'El delfín del Ganges es una especie de delfín de agua dulce originaria del Ganges. Suele ser de color grisáceo, aunque algunos ejemplares presentan un tono rosáceo, sobre todo cuando están emocionados o agitados. Pueden alcanzar una longitud de entre 2,5 y 3 metros (de 8 a 10 pies) y pesar entre 100 y 150 kg (de 220 a 330 libras). Estos delfines son conocidos por su capacidad de ecolocalización, que utilizan para orientarse y cazar en las aguas turbias de sus hábitats fluviales.\\n\\nEl delfín del Ganges se alimenta principalmente de una variedad de peces e invertebrados que se encuentran en su hábitat de agua dulce.\\n\\n'),
       (93806, 30184, 'nl', 'Gaur', 'De gaur, ook wel bekend als de Indische bizon, is een grote wilde rundersoort die inheems is in Zuid-Azië en Zuidoost-Azië. Hij wordt gekenmerkt door zijn massieve bouw, donkerbruine tot zwarte vacht en opvallende witte aftekeningen op zijn poten en gezicht.  Zowel mannetjes als vrouwtjes hebben lange, gebogen hoorns die tot 3 voet (ongeveer 1 meter) lang kunnen worden. \\n\\nGaurs zijn herbivoren en leven voornamelijk in bossen en graslanden, waar ze grazen op een verscheidenheid aan vegetatie. \\n\\n'),
       (93807, 30184, 'fr', 'Gaur', 'Le gaur, également connu sous le nom de bison indien, est une grande espèce de bovin sauvage originaire d''Asie du Sud et d''Asie du Sud-Est. Il se caractérise par sa corpulence imposante, son pelage brun foncé à noir et ses marques blanches distinctives sur les pattes et le museau.  Les mâles comme les femelles possèdent de longues cornes recourbées pouvant atteindre 3 pieds (environ 1 mètre) de longueur. \\n\\nLes gaurs sont herbivores et vivent principalement dans les forêts et les prairies, où ils se nourrissent d''une végétation variée. \\n\\n'),
       (93808, 30184, 'es', 'Gaur', 'El gaur, también conocido como bisonte indio, es una especie de bovino salvaje de gran tamaño originaria del sur y el sudeste de Asia. Se caracteriza por su complexión robusta, su pelaje de color marrón oscuro a negro y sus distintivas manchas blancas en las patas y la cara.  Tanto los machos como las hembras poseen cuernos largos y curvados que pueden alcanzar hasta 3 pies (aproximadamente 1 metro) de longitud. \\n\\nLos gaurs son herbívoros y habitan principalmente en bosques y praderas, donde pastan una gran variedad de vegetación. \\n\\n'),
       (93809, 30185, 'nl', 'Gila-monster', 'Het Gila-monster is een grote, giftige hagedis die inheems is in het zuidwesten van de Verenigde Staten en het noordwesten van Mexico. Het wordt gekenmerkt door zijn opvallende zwarte lichaam met feloranje of roze patronen. Gila-monsters zijn voornamelijk nachtdieren en brengen een groot deel van hun tijd door met het graven van holen onder de grond. Hun gif, dat via groeven in hun tanden wordt toegediend, wordt voornamelijk gebruikt ter verdediging en om prooien te overmeesteren.\\n\\nHet gilamonster is een vleesetende hagedis die zich voornamelijk voedt met kleine zoogdieren, zoals knaagdieren, en vogels, inclusief hun eieren.\\n\\n'),
       (93810, 30185, 'fr', 'Monstre de Gila', 'Le monstre de Gila est un grand lézard venimeux originaire du sud-ouest des États-Unis et du nord-ouest du Mexique. Il se caractérise par son corps noir distinctif orné de motifs orange vif ou roses. Les monstres de Gila sont principalement nocturnes et passent la majeure partie de leur temps à creuser des terriers sous terre. Leur venin, injecté par des rainures situées sur leurs dents, sert principalement à se défendre et à maîtriser leurs proies.\\n\\nLe monstre de Gila est un lézard carnivore dont le régime alimentaire se compose principalement de petits mammifères, tels que les rongeurs, et d''oiseaux, y compris leurs œufs.\\n\\n'),
       (93811, 30185, 'es', 'Monstruo de Gila', 'El monstruo de Gila es un lagarto grande y venenoso, originario del suroeste de Estados Unidos y el noroeste de México. Se caracteriza por su característico cuerpo negro adornado con motivos de color naranja brillante o rosa. Los monstruos de Gila son principalmente nocturnos y pasan gran parte de su tiempo excavando bajo tierra. Su veneno, que inyectan a través de los surcos de sus dientes, lo utilizan principalmente para defenderse y para someter a sus presas.\\n\\nEl monstruo de Gila es un lagarto carnívoro cuya dieta se compone principalmente de pequeños mamíferos, como roedores, y aves, incluidos sus huevos.\\n\\n'),
       (93812, 30186, 'nl', 'Goudbuikmangabey', 'De goudbuikmangabey is een middelgrote aap uit de Oude Wereld met olijfgrijze bovenkant, helder goudoranje vacht op de buik en de binnenkant van de ledematen, en een donker gezicht met een lichte wenkbrauwboog. Deze aap komt alleen voor in de bossen van het stroomgebied van de Congorivier in de Democratische Republiek Congo. Hij leeft in groepen in de buurt van rivieroevers en moerassige regenwouden.\\n\\nDe goudbuikmangabey eet voornamelijk fruit, zaden, bladeren, insecten en kleine ongewervelde dieren. \\n\\n'),
       (93813, 30186, 'fr', 'Mangabey à ventre doré', 'Le mangabey à ventre doré est un singe de l''Ancien Monde de taille moyenne, au plumage gris olive sur le dessus, au ventre et à l''intérieur des membres d''un orange doré vif, et au visage foncé surmonté d''un arc sourcilier pâle. On ne le trouve que dans les forêts du bassin du fleuve Congo, en République démocratique du Congo. Il vit en groupes près des berges des cours d''eau et dans les forêts tropicales marécageuses.\\n\\nLe mangabey à ventre doré se nourrit principalement de fruits, de graines, de feuilles, d''insectes et de petits invertébrés. \\n\\n'),
       (93814, 30186, 'es', 'Mangabey de vientre dorado', 'El mangabey de vientre dorado es un mono del Viejo Mundo de tamaño mediano con el dorso de color gris oliva, pelaje de un brillante tono naranja dorado en el vientre y la parte interna de las extremidades, y una cara oscura con un arco superciliar claro. Se encuentra únicamente en los bosques de la cuenca del río Congo, en la República Democrática del Congo. Vive en grupos cerca de las riberas de los ríos y en selvas tropicales pantanosas.\\n\\nEl mangabey de vientre dorado se alimenta principalmente de frutos, semillas, hojas, insectos y pequeños invertebrados. \\n\\n'),
       (93815, 30187, 'nl', 'Grote varkensdas', 'De grote varkensdas is een middelgroot zoogdier dat inheems is in Zuidoost-Azië. Het heeft een opvallend uiterlijk, gekenmerkt door een gedrongen lichaam, korte poten en een brede, platte snuit die lijkt op die van een varken. De vacht is grof en meestal grijsbruin, met een lichtere onderkant. Ze zijn voornamelijk nachtdieren en staan bekend om hun gravende gewoonten, waarbij ze vaak uitgebreide tunnelsystemen aanleggen. \\n\\nGrote varkensdassen zijn alleseters en voeden zich met een gevarieerd dieet dat bestaat uit insecten, kleine zoogdieren, fruit en wortels.\\n\\n'),
       (93816, 30187, 'fr', 'Grand blaireau', 'Le grand blaireau-sanglier est un mammifère de taille moyenne originaire d''Asie du Sud-Est. Il présente une apparence caractéristique, marquée par un corps trapu, des pattes courtes et un museau large et plat ressemblant à celui d''un sanglier. Son pelage est rugueux et généralement brun grisâtre, avec un ventre plus clair. Principalement nocturnes, ils sont connus pour leurs habitudes de fouisseurs, créant souvent de vastes réseaux de galeries. \\n\\nLes blaireaux-porcs sont omnivores et ont un régime alimentaire varié comprenant des insectes, des petits mammifères, des fruits et des racines.\\n\\n'),
       (93817, 30187, 'es', 'Tejón grande', 'El tejón cerdo mayor es un mamífero de tamaño mediano originario del sudeste asiático. Tiene un aspecto característico, que se distingue por un cuerpo robusto, patas cortas y un hocico ancho y plano que se asemeja al de un cerdo. El pelaje es áspero y suele ser de color marrón grisáceo, con la parte inferior más clara. Son principalmente nocturnos y destacan por su costumbre de excavar madrigueras, creando a menudo extensos sistemas de túneles. \\n\\nLos tejones-cerdo grandes son omnívoros y se alimentan de una dieta variada que incluye insectos, pequeños mamíferos, frutos y raíces.\\n\\n'),
       (93818, 30188, 'nl', 'Grote Rhea', 'De grote nandoe is een grote, loopvogel die inheems is in Zuid-Amerika en vooral voorkomt in open graslanden en savannes. Hij wordt tot 1,5 meter (5 voet) hoog, heeft lange poten, een lange nek en een groot lichaam dat bedekt is met zachte, grijsbruine veren. Grote nandoes zijn sociale dieren die vaak in groepen worden waargenomen en staan bekend om hun grote snelheid bij het rennen. \\n\\nGrote nandoes zijn alleseters en voeden zich met planten, zaden, insecten en kleine dieren. \\n\\n'),
       (93819, 30188, 'fr', 'Nandou géant', 'Le nandou est un grand oiseau incapable de voler, originaire d''Amérique du Sud, que l''on trouve principalement dans les prairies ouvertes et les savanes. Mesurant jusqu''à 1,5 mètre (5 pieds) de haut, il possède de longues pattes, un long cou et un corps imposant recouvert de plumes douces, de couleur brun grisâtre. Les nandous sont des animaux sociables, que l''on observe souvent en groupes, et sont connus pour leurs grandes capacités de course. \\n\\nLes nandous sont omnivores ; leur régime alimentaire se compose de plantes, de graines, d''insectes et de petits animaux. \\n\\n'),
       (93820, 30188, 'es', 'Nandú mayor', 'El nandú es un ave grande e incapaz de volar, originaria de Sudamérica, que se encuentra principalmente en praderas abiertas y sabanas. Mide hasta 1,5 metros (5 pies) de altura, tiene patas largas, un cuello largo y un cuerpo grande cubierto de plumas suaves de color marrón grisáceo. Los nandúes son animales sociables, que suelen verse en grupos, y son conocidos por su gran capacidad para correr. \\n\\nLos nandúes son omnívoros y se alimentan de plantas, semillas, insectos y pequeños animales. \\n\\n'),
       (93821, 30189, 'nl', 'Grote saliehoen', 'De grote saliehoen is een grote, op de grond levende vogel. Mannetjes hebben een gevlekt verenkleed van bruin, grijs, zwart en wit, met een grote witte borst en twee gelige luchtzakken op de borst die tijdens de paringsdans worden gebruikt. Vrouwtjes zijn minder opvallend, met een gevlekt grijs-bruin-zwart verenkleed dat opgaat in de salie-habitats, wat bescherming biedt tijdens het nestelen.\\n\\nDe soort is herbivoor en voedt zich voornamelijk met salie, vooral in de winter.\\n\\n'),
       (93822, 30189, 'fr', 'Tétras des armoises', 'Le tétras des armoises est un grand oiseau vivant au sol. Les mâles présentent un plumage tacheté de brun, de gris, de noir et de blanc, avec une large poitrine blanche et deux sacs aériens jaunâtres sur la poitrine qu’ils utilisent lors des parades nuptiales. Les femelles sont plus discrètes, avec un plumage tacheté de gris, de brun et de noir qui leur permet de se fondre dans les habitats d''armoise afin de protéger leur nid.\\n\\nCette espèce est herbivore et se nourrit principalement d''armoise, surtout en hiver.\\n\\n'),
       (93823, 30189, 'es', 'Urogallo de las praderas', 'El urogallo grande de la artemisa es un ave grande que vive en el suelo. Los machos presentan un plumaje moteado en tonos marrones, grises, negros y blancos, con un pecho blanco de gran tamaño y dos sacos aéreos amarillentos en el pecho que utilizan durante las exhibiciones de cortejo. Las hembras son más discretas, con un plumaje moteado de tonos gris, marrón y negro que se mimetiza con los hábitats de artemisa para proteger la nidificación.\\n\\nLa especie es herbívora y se alimenta principalmente de artemisa, sobre todo en invierno.\\n\\n'),
       (93824, 30190, 'nl', 'Grijskruinkraanvogel', 'De grijskruinkraanvogel (Balearica regulorum) is een vogel uit de familie van de kraanvogels (Gruidae). Hij komt voor in Oost- en Zuid-Afrika en is de nationale vogel van Oeganda. Deze langbenige vogels, een van de 15 kraanvogelsoorten, hebben een grijs lichaam, witte vleugels met bruine en gouden veren, witte wangen en felrode keelzakken onder hun kin. Het meest opvallend is de kroon van stijve gouden veren rond hun kop.\\n\\nGrijskruinkranen zijn alleseters. Ze zoeken naar graszaden, kleine padden, insecten en andere ongewervelde dieren. \\n\\nVolgens de Rode Lijst van de IUCN worden ze geclassificeerd als ‘Bedreigd’ en neemt hun aantal tegenwoordig af.\\n\\n'),
       (93825, 30190, 'fr', 'Grue à couronne grise', 'La grue à couronne grise (Balearica regulorum) est un oiseau de la famille des Gruidae. On la trouve en Afrique orientale et australe ; c''est l''oiseau national de l''Ouganda. Comptant parmi les 15 espèces de grues, ces oiseaux aux longues pattes ont un corps gris, des ailes blanches parsemées de plumes brunes et dorées, des joues blanches et un sac gulaire rouge vif sous le menton. Leur trait le plus remarquable est une couronne de plumes dorées et raides qui entoure leur tête.\\n\\nLes grues à couronne grise sont omnivores. Elles se nourrissent de graines d''herbe, de petits crapauds, d''insectes et d''autres invertébrés. \\n\\nSelon la Liste rouge de l''UICN, elles sont classées comme « en danger » et leurs effectifs sont aujourd''hui en déclin.\\n\\n'),
       (93826, 30190, 'es', 'Grulla coronada gris', 'La grulla coronada gris (Balearica regulorum) es un ave de la familia de las grullas, Gruidae. Se encuentra en el este y el sur de África, y es el ave nacional de Uganda. Es una de las 15 especies de grullas; estas aves de patas largas tienen el cuerpo gris, alas blancas con plumas marrones y doradas, mejillas blancas y sacos gulares de color rojo vivo debajo de la barbilla. Lo más llamativo es que un penacho de plumas doradas y rígidas forma una corona alrededor de sus cabezas.\\n\\nLas grullas coronadas grises son omnívoras. Se alimentan de semillas de hierba, pequeños sapos, insectos y otros invertebrados. \\n\\nSegún la Lista Roja de la UICN, están clasificadas como «En peligro» y su población está disminuyendo en la actualidad.\\n\\n'),
       (93827, 30191, 'nl', 'Grizzlybeer', 'De grizzlybeer is een populatie of ondersoort van de bruine beer die voorkomt in Noord-Amerika. Hoewel de kleur varieert van blond tot bijna zwart, is de vacht van de grizzlybeer doorgaans bruin met donkerdere poten en vaak witte of blond getinte vacht op de flanken en de rug. Grizzlyberen worden gekenmerkt door hun opvallende bult op de schouders, die bestaat uit spieren die worden gebruikt om te graven en voedsel te zoeken. \\n\\nGrizzlyberen zijn alleseters en voeden zich met een gevarieerd dieet dat bestaat uit bessen, vis, kleine zoogdieren en aas.\\n\\n'),
       (93828, 30191, 'fr', 'Ours grizzli', 'L''ours grizzli est une population ou une sous-espèce de l''ours brun que l''on trouve en Amérique du Nord. Bien que sa couleur puisse varier du blond au presque noir, le pelage de l''ours grizzli est généralement brun, avec des pattes plus foncées et, souvent, des poils aux extrémités blanches ou blondes sur les flancs et le dos. Les grizzlis se caractérisent par leur bosse distinctive au niveau des épaules, constituée de muscles servant à creuser et à chercher de la nourriture. \\n\\nLes grizzlis sont omnivores et ont un régime alimentaire varié comprenant des baies, des poissons, de petits mammifères et des charognes.\\n\\n'),
       (93829, 30191, 'es', 'Oso pardo', 'El oso grizzly es una población o subespecie del oso pardo que se encuentra en América del Norte. Aunque su color varía desde el rubio hasta casi el negro, el pelaje del oso grizzly suele ser marrón, con las patas más oscuras y, habitualmente, puntas blancas o rubias en los flancos y la espalda. Los osos grizzly se caracterizan por su distintiva joroba en los hombros, formada por músculo que utilizan para excavar y buscar alimento. \\n\\nLos osos grizzly son omnívoros y se alimentan de una dieta variada que incluye bayas, peces, pequeños mamíferos y carroña.\\n\\n'),
       (93830, 30192, 'nl', 'Guanaco', 'De guanaco is een wilde kameelachtige die van nature voorkomt in de Andesgebieden van Zuid-Amerika. Het dier heeft een slank postuur met lange poten, een lange nek en een roodbruine tot grijze vacht, vaak met een witte buik. Guanaco''s staan bekend om hun behendigheid op ruig terrein en zijn de voorouders van gedomesticeerde lama''s en alpaca''s.\\n\\nHun dieet bestaat voornamelijk uit grassen, kruiden en struiken, waar ze van grazen in open graslanden en bergachtige gebieden.\\n\\n'),
       (93831, 30192, 'fr', 'Guanaco', 'Le guanaco est un camélidé sauvage originaire des régions andines d''Amérique du Sud. Il présente une silhouette élancée, avec de longues pattes, un long cou et un pelage allant du brun rougeâtre au gris, souvent avec le ventre blanc. Les guanacos sont connus pour leur agilité sur les terrains accidentés et sont les ancêtres des lamas et des alpagas domestiques.\\n\\nSon régime alimentaire se compose principalement d''herbes, de plantes aromatiques et d''arbustes, qu''il broute dans les prairies ouvertes et les zones montagneuses.\\n\\n'),
       (93832, 30192, 'es', 'Guanaco', 'El guanaco es un camélido salvaje originario de las regiones andinas de Sudamérica. Tiene una complexión esbelta, con patas largas, un cuello largo y un pelaje que va del marrón rojizo al gris, a menudo con el vientre blanco. Los guanacos son conocidos por su agilidad en terrenos accidentados y son los antepasados de las llamas y las alpacas domesticadas.\\n\\nSu dieta se compone principalmente de pastos, hierbas y arbustos, de los que se alimenta en praderas abiertas y zonas montañosas.\\n\\n'),
       (93833, 30193, 'nl', 'Gyrfalcon',
        'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \\"white\\", \\"silver\\", \\"brown\\", and \\"black\\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\\\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\\n\\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\\n\\n'),
       (93834, 30193, 'fr', 'Gyrfalcon',
        'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \\"white\\", \\"silver\\", \\"brown\\", and \\"black\\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\\\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\\n\\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\\n\\n'),
       (93835, 30193, 'es', 'Gyrfalcon',
        'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \\"white\\", \\"silver\\", \\"brown\\", and \\"black\\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\\\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\\n\\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\\n\\n'),
       (93836, 30194, 'nl', 'Zeehond', 'De harpzeehond is een soort oorloze zeehond, of echte zeehond, die inheems is in het noordelijkste deel van de Atlantische Oceaan en de Noordelijke IJszee. Ze hebben een unieke kleur die varieert naargelang de leeftijd. Volwassen harpzeehonden hebben een zilvergrijze vacht met een kenmerkend donker ‘harp’-patroon op hun rug, terwijl jongen worden geboren met een witte, donzige vacht waarmee ze goed opgaan in het ijs. Volwassen harpzeehonden wegen doorgaans tussen de 300 en 400 pond (136 tot 181 kg) en zijn ongeveer 5 tot 6,5 voet (1,5 tot 2 meter) lang.\\n\\nHarpzeehonden zijn vleesetende (visetende) dieren die zich voeden met vis, waaronder lodde, haring, kabeljauw, arctische kabeljauw en heilbot, en met krabben en andere ongewervelde dieren.\\n\\n'),
       (93837, 30194, 'fr', 'Phoque du Groenland', 'Le phoque de la harpe est une espèce de phoque sans oreilles, ou « vrai phoque », originaire de la partie la plus septentrionale de l''océan Atlantique et de l''océan Arctique. Il présente une coloration unique qui varie en fonction de son âge. Les phoques du Groenland adultes ont un pelage gris argenté orné d’un motif sombre caractéristique en forme de « harpe » sur le dos, tandis que les petits naissent avec un pelage blanc et duveteux qui leur permet de se fondre dans la glace. Les phoques du Groenland adultes pèsent généralement entre 300 et 400 livres (136 à 181 kg) et mesurent environ 5 à 6,5 pieds (1,5 à 2 mètres) de long.\\n\\nLes phoques du Groenland sont des animaux carnivores (piscivores) qui se nourrissent de poissons, notamment de capelan, de hareng, de morue, de morue arctique et de flétan, ainsi que de crabes et d’autres invertébrés.\\n\\n'),
       (93838, 30194, 'es', 'Foca arpa', 'La foca arpa es una especie de foca sin orejas, o foca verdadera, originaria de la zona más septentrional del océano Atlántico y del océano Ártico. Presentan una coloración única que varía con la edad. Las focas arpa adultas tienen un pelaje gris plateado con un característico dibujo oscuro en forma de «arpa» en el lomo, mientras que las crías nacen con un pelaje blanco y esponjoso que les ayuda a camuflarse entre el hielo. Las focas arpa adultas suelen pesar entre 300 y 400 libras (136 a 181 kg) y miden entre 5 y 6,5 pies (1,5 a 2 metros) de longitud.\\n\\nLas focas arpa son animales carnívoros (piscívoros) que se alimentan de peces, como el capelán, el arenque, el bacalao, el bacalao ártico y el fletán, así como de cangrejos y otros invertebrados.\\n\\n'),
       (93839, 30195, 'nl', 'Hawksbill Sea Turtle',
        'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\\\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\\n\\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \\n\\n'),
       (93840, 30195, 'fr', 'Hawksbill Sea Turtle',
        'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\\\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\\n\\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \\n\\n'),
       (93841, 30195, 'es', 'Hawksbill Sea Turtle',
        'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\\\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\\n\\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \\n\\n'),
       (93842, 30196, 'nl', 'Iberische lynx', 'De Iberische lynx is een ernstig bedreigde wilde kat die inheems is op het Iberisch Schiereiland in Zuidwest-Europa. Volwassen dieren zijn 65–110 cm (26–43 inch) lang en wegen 9–15 kg (20–33 pond). De Iberische lynx heeft een opvallende korte, geelbruine vacht met donkere vlekken, pluimachtige oren, een korte, ‘afgeknotte’ staart en lange poten met krachtige achterpoten.\\n\\nHet dieet van de Iberische lynx bestaat bijna uitsluitend uit Europese konijnen (tot 80–90% van zijn dieet), aangevuld met vogels, reptielen en kleine zoogdieren.\\n\\n'),
       (93843, 30196, 'fr', 'Lynx ibérique', 'Le lynx ibérique est un félin sauvage en danger critique d''extinction, originaire de la péninsule ibérique, dans le sud-ouest de l''Europe. Les adultes mesurent entre 65 et 110 cm (26 à 43 pouces) de long et pèsent entre 9 et 15 kg (20 à 33 livres). Le lynx ibérique se caractérise par un pelage court et fauve parsemé de taches sombres, des oreilles à touffes, une queue courte et « coupée » et de longues pattes avec un arrière-train puissant.\\n\\nLe régime alimentaire du lynx ibérique se compose presque exclusivement de lapins européens (jusqu’à 80 à 90 % de son alimentation), complété par des oiseaux, des reptiles et des petits mammifères.\\n\\n'),
       (93844, 30196, 'es', 'Lince ibérico', 'El lince ibérico es un felino salvaje en peligro crítico de extinción, originario de la Península Ibérica, en el suroeste de Europa. Los adultos miden entre 65 y 110 cm (26 y 43 pulgadas) de longitud y pesan entre 9 y 15 kg (20 y 33 libras). El lince ibérico tiene un pelaje característico, corto y de color leonado con manchas oscuras, orejas con mechones, una cola corta y «recortada», y patas largas con una parte trasera poderosa.\\n\\nLa dieta del lince ibérico se compone casi exclusivamente de conejos europeos (hasta un 80-90 % de su alimentación), complementada con aves, reptiles y pequeños mamíferos.\\n\\n'),
       (93845, 30197, 'nl', 'Indo-Pacifische zeilvis', 'De Indo-Pacifische zeilvis is een zeilvis die van nature voorkomt in de Indische en de Stille Oceaan. Ze zijn gemakkelijk te herkennen aan hun lange, slanke lichaam, grote rugvinnen (of zeilen) en langgerekte snuit. Indo-Pacifische zeilvissen kunnen een lengte bereiken van maximaal 3,4 meter (11 voet) en wel 100 kg (220 lbs) wegen. Ze staan bekend om hun opmerkelijke zwemvaardigheden en kunnen snelheden tot 68 mijl per uur (110 km/u) halen, waardoor ze tot de snelste vissen in de oceaan behoren. \\n\\nIndo-Pacifische zeilvissen voeden zich voornamelijk met kleinere vissen en inktvissen, waarbij ze hun snelheid en snuit gebruiken om door scholen prooidieren te snijden. \\n\\n'),
       (93846, 30197, 'fr', 'Espadon de l''Indo-Pacifique', 'Le voilier de l''Indo-Pacifique est une espèce de voilier originaire des océans Indien et Pacifique. On le reconnaît facilement à son corps long et élancé, à ses grandes nageoires dorsales (ou « voiles ») et à son bec allongé. Le voilier de l''Indo-Pacifique peut atteindre une longueur de 3,4 mètres (11 pieds) et peser jusqu''à 100 kg (220 livres). Ils sont connus pour leurs remarquables capacités de nage, pouvant atteindre des vitesses allant jusqu’à 68 miles par heure (110 km/h), ce qui en fait l’un des poissons les plus rapides de l’océan. \\n\\nLe voilier de l''Indo-Pacifique se nourrit principalement de petits poissons et de calmars, utilisant sa vitesse et son bec pour fendre les bancs de proies. \\n\\n'),
       (93847, 30197, 'es', 'Pez vela del Indo-Pacífico', 'El pez vela del Indo-Pacífico es una especie autóctona de los océanos Índico y Pacífico. Se reconoce fácilmente por su cuerpo largo y esbelto, sus grandes aletas dorsales (o velas) y su pico alargado. El pez vela del Indo-Pacífico puede alcanzar una longitud de hasta 3,4 metros (11 pies) y pesar hasta 100 kg (220 libras). Son conocidos por sus extraordinarias habilidades natatorias, ya que son capaces de alcanzar velocidades de hasta 68 millas por hora (110 km/h), lo que los convierte en uno de los peces más rápidos del océano. \\n\\nEl pez vela del Indo-Pacífico se alimenta principalmente de peces más pequeños y calamares, utilizando su velocidad y su pico para atravesar bancos de presas. \\n\\n'),
       (93848, 30198, 'nl', 'Indri',
        'The Indri is the largest living species of lemur, native exclusively to Madagascar\\\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\\n\\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\\n\\n'),
       (93849, 30198, 'fr', 'Indri',
        'The Indri is the largest living species of lemur, native exclusively to Madagascar\\\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\\n\\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\\n\\n'),
       (93850, 30198, 'es', 'Indri',
        'The Indri is the largest living species of lemur, native exclusively to Madagascar\\\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\\n\\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\\n\\n'),
       (93851, 30199, 'nl', 'Jentink\\\'s Duiker',
        'Jentink\\\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\\\'Ivoire and Sierra Leone. Jentink\\\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\\\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\\n\\nJentink\\\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\\n\\n'),
       (93852, 30199, 'fr', 'Jentink\\\'s Duiker',
        'Jentink\\\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\\\'Ivoire and Sierra Leone. Jentink\\\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\\\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\\n\\nJentink\\\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\\n\\n'),
       (93853, 30199, 'es', 'Jentink\\\'s Duiker',
        'Jentink\\\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\\\'Ivoire and Sierra Leone. Jentink\\\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\\\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\\n\\nJentink\\\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\\n\\n'),
       (93854, 30200, 'nl', 'Koningspinguïn', 'De koningspinguïn is de op één na grootste pinguïnsoort en kan tot 100 cm (39 in) hoog worden. Hij is gemakkelijk te herkennen aan zijn gladde zwarte rug, witte buik en fel oranje-gele vlekken aan de zijkanten van zijn kop en bovenborst. In tegenstelling tot veel andere vogels bouwen ze geen nesten; in plaats daarvan broeden ze hun enige ei uit op hun poten, onder een huidplooi.\\n\\nDe koningspinguïn voedt zich voornamelijk met kleine vissen, inktvis en krill en duikt diep in de oceaan om zijn prooi te vangen.\\n\\n'),
       (93855, 30200, 'fr', 'Manchot royal', 'Le manchot royal est la deuxième plus grande espèce de manchot, pouvant atteindre 100 cm (39 pouces) de haut. On le reconnaît facilement à son dos noir lisse, à son ventre blanc et à ses taches jaune-orange vives sur les côtés de la tête et le haut de la poitrine. Contrairement à de nombreux oiseaux, il ne construit pas de nid ; il couve plutôt son unique œuf sur ses pattes, sous un repli de peau.\\n\\nLe manchot royal se nourrit principalement de petits poissons, de calmars et de krill, plongeant en profondeur dans l''océan pour attraper ses proies.\\n\\n'),
       (93856, 30200, 'es', 'Pingüino rey', 'El pingüino rey es la segunda especie de pingüino más grande, con una altura de hasta 100 cm (39 pulgadas). Se reconoce fácilmente por su elegante espalda negra, su vientre blanco y las manchas de un intenso color amarillo anaranjado a los lados de la cabeza y en la parte superior del pecho. A diferencia de muchas aves, no construyen nidos; en su lugar, incuban su único huevo sobre las patas, bajo un pliegue de piel.\\n\\nEl pingüino rey se alimenta principalmente de peces pequeños, calamares y krill, y se sumerge a gran profundidad en el océano para capturar a sus presas.\\n\\n'),
       (93857, 30201, 'nl', 'Kingfisher',
        'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \\n\\nThe Kingfisher\\\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\\n\\n'),
       (93858, 30201, 'fr', 'Kingfisher',
        'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \\n\\nThe Kingfisher\\\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\\n\\n'),
       (93859, 30201, 'es', 'Kingfisher',
        'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \\n\\nThe Kingfisher\\\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\\n\\n'),
       (93860, 30202, 'nl', 'Lady Amherst\\\'s Pheasant',
        'Lady Amherst\\\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \\"cape\\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\\n\\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\\n\\n'),
       (93861, 30202, 'fr', 'Lady Amherst\\\'s Pheasant',
        'Lady Amherst\\\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \\"cape\\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\\n\\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\\n\\n'),
       (93862, 30202, 'es', 'Lady Amherst\\\'s Pheasant',
        'Lady Amherst\\\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \\"cape\\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\\n\\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\\n\\n'),
       (93863, 30203, 'nl', 'Lederrugschildpad', 'De lederschildpad is de grootste van alle zeeschildpadden en onderscheidt zich door zijn unieke, flexibele, leerachtige schild met zeven lengteribben in plaats van harde platen. Hij heeft een donkergrijze tot zwarte kleur met witte vlekken en een roze snuit. Deze soort komt wereldwijd voor in tropische en gematigde oceanen.\\n\\nDe lederschildpad voedt zich voornamelijk met kwallen en andere zeeorganismen met een zacht lichaam, maar ook met manteldieren, sponzen en vissen.\\n\\n'),
       (93864, 30203, 'fr', 'Tortue luth', 'La tortue luth est la plus grande de toutes les tortues marines ; elle se distingue par sa carapace unique, souple et semblable à du cuir, comportant sept crêtes longitudinales au lieu de plaques rigides. Elle présente une coloration allant du gris foncé au noir, avec des taches blanches et un museau rosâtre. Cette espèce est présente dans les océans tropicaux et tempérés du monde entier.\\n\\nLa tortue luth se nourrit principalement de méduses et d''autres créatures marines à corps mou, mais aussi de tuniciers, d''éponges et de poissons.\\n\\n'),
       (93865, 30203, 'es', 'Tortuga laúd', 'La tortuga laúd es la más grande de todas las tortugas marinas y se distingue por su caparazón único, flexible y de textura similar al cuero, que presenta siete crestas longitudinales en lugar de placas duras. Tiene una coloración que va del gris oscuro al negro, con manchas blancas y un hocico rosáceo. Esta especie se encuentra en los océanos tropicales y templados de todo el mundo.\\n\\nLa tortuga laúd se alimenta principalmente de medusas y otros animales marinos de cuerpo blando, así como de tunicados, esponjas y peces.\\n\\n'),
       (93866, 30204, 'nl', 'Luipaardschildpad', 'De luipaardschildpad is een grote, plantenetende schildpad die van nature voorkomt in de savannes en graslanden van Afrika. Hij wordt gekenmerkt door zijn opvallende, gepatrooneerde schild met gele en zwarte vlekken en kan tot 18 inch (0,45 meter) lang worden. Deze schildpadden staan bekend om hun zachtaardige karakter en kunnen tientallen jaren oud worden. \\n\\nLuipaardschildpadden voeden zich voornamelijk met grassen, bladeren en bloemen en hebben een warme, droge leefomgeving nodig om goed te gedijen.\\n\\n'),
       (93867, 30204, 'fr', 'Tortue léopard', 'La tortue léopard est une grande tortue herbivore originaire des savanes et des prairies d''Afrique. Caractérisée par sa carapace aux motifs distinctifs, avec des marques jaunes et noires, elle peut atteindre 18 pouces (0,45 mètre) de longueur. Ces tortues sont connues pour leur tempérament docile et peuvent vivre plusieurs décennies. \\n\\nLes tortues léopards se nourrissent principalement d''herbes, de feuilles et de fleurs, et ont besoin d''un habitat chaud et sec pour s''épanouir.\\n\\n'),
       (93868, 30204, 'es', 'Tortuga leopardo', 'La tortuga leopardo es una tortuga herbívora de gran tamaño, originaria de las sabanas y praderas de África. Se caracteriza por su caparazón con un patrón distintivo de manchas amarillas y negras, y puede alcanzar hasta 18 pulgadas (0,45 metros) de longitud. Estas tortugas son conocidas por su temperamento dócil y pueden vivir varias décadas. \\n\\nLas tortugas leopardo se alimentan principalmente de hierbas, hojas y flores, y necesitan un hábitat cálido y seco para desarrollarse bien.\\n\\n'),
       (93869, 30205, 'nl', 'Kleine egeltenrek', 'De kleine egeltenrec is een stevig gebouwd, nachtactief zoogdier dat endemisch is voor Madagaskar. De kleine egeltenrec is een spitsmuisachtig zoogdier, klein van gestalte met een lange snuit met snorharen. Zijn rug, flanken en staart zijn bedekt met donkerbruine tot zwarte, scherpe, dichte stekels met witte puntjes. Zijn buik is lichter van kleur en heeft geen stekels. In tegenstelling tot hun verwanten, de egels, zijn tenreks uitstekende klimmers en gebruiken ze hun lange tenen om zich aan takken vast te houden.\\n\\nKleine egeltenreks zijn alleseters en eten insecten en hun larven, spinnen, eieren en af en toe fruit.\\n\\n'),
       (93870, 30205, 'fr', 'Tenrec hérisson mineur', 'Le tenrec-hérisson mineur est un mammifère nocturne au corps trapu, endémique de Madagascar. Le petit tenrec-hérisson est un mammifère ressemblant à une musaraigne, de petite taille et doté d''un museau allongé orné de moustaches. Son dos, ses flancs et sa queue sont recouverts d''épines pointues, denses, de couleur brun foncé à noire, aux extrémités blanches. Son ventre est plus clair et dépourvu d''épines. Contrairement à leurs cousins les hérissons, les tenrecs sont d''excellents grimpeurs et utilisent leurs longs orteils pour s''agripper aux branches.\\n\\nLes tenrecs-hérissons mineurs sont omnivores : ils se nourrissent d''insectes et de leurs larves, d''araignées, d''œufs et, occasionnellement, de fruits.\\n\\n'),
       (93871, 30205, 'es', 'Tenrec erizo menor', 'El tenrec erizo menor es un mamífero nocturno de cuerpo robusto, endémico de Madagascar. El tenrec erizo menor es un mamífero parecido a una musaraña, de tamaño pequeño y hocico alargado con bigotes. Su lomo, flancos y cola presentan púas afiladas, densas y de color marrón oscuro a negro, con puntas blancas. Su parte ventral es más clara y carece de púas. A diferencia de sus primos, los erizos, los tenrecs son excelentes trepadores y utilizan sus largos dedos para agarrarse a las ramas.\\n\\nLos tenrecs erizo pequeños son omnívoros y se alimentan de insectos y sus larvas, arañas, huevos y, ocasionalmente, fruta.\\n\\n'),
       (93872, 30206, 'nl', 'Caretta-schildpad', 'De onechte karetschildpad is een grote zeeschildpadsoort die wereldwijd in gematigde en subtropische oceanen voorkomt. Volwassen exemplaren hebben doorgaans een schildlengte van 90–110 cm (35–43 inch) en wegen tussen de 100 en 200 kg (220–440 lbs). Ze hebben een roodbruin schild met vijf paar schubben en zwemvliezen die zijn aangepast om lange afstanden te zwemmen.\\n\\nZe zijn alleseters en hun dieet bestaat voornamelijk uit kwallen, krabben, vissen, weekdieren en zeeplanten. \\n\\n'),
       (93873, 30206, 'fr', 'Tortue caouanne', 'La tortue caouanne est une grande espèce de tortue marine présente dans les océans tempérés et subtropicaux du monde entier. Les adultes mesurent généralement entre 90 et 110 cm (35 à 43 pouces) de longueur de carapace et pèsent entre 100 et 200 kg (220 à 440 livres). Elles possèdent une carapace brun-rougeâtre comportant cinq paires d''écailles et des nageoires adaptées à la nage sur de longues distances.\\n\\nLeur régime alimentaire est omnivore et se compose principalement de méduses, de crabes, de poissons, de mollusques et de plantes marines. \\n\\n'),
       (93874, 30206, 'es', 'Tortuga bobina', 'La tortuga bobina es una especie de gran tamaño que habita en los océanos templados y subtropicales de todo el mundo. Los ejemplares adultos suelen medir entre 90 y 110 cm (35-43 pulgadas) de longitud de caparazón y pesan entre 100 y 200 kg (220-440 libras). Tienen un caparazón de color marrón rojizo con cinco pares de escamas y aletas adaptadas para nadar largas distancias.\\n\\nSu dieta es omnívora y se compone principalmente de medusas, cangrejos, peces, moluscos y plantas marinas. \\n\\n'),
       (93875, 30207, 'nl', 'Langoorjerboa', 'De langoorjerboa is een klein, nachtdier dat van nature voorkomt in de woestijnen van Centraal-Azië. Dit behendige dier, dat bekendstaat om zijn opvallende lange oren en grote achterpoten, is uitstekend aangepast om te springen en zich door zijn dorre leefomgeving te bewegen. De vachtkleur van de langoorjerboa is meestal zandkleurig of lichtbruin, waardoor hij goed opgaat in zijn woestijnomgeving.\\n\\nDe langoorjerboa voedt zich voornamelijk met zaden, insecten en ander plantaardig materiaal\\n\\n'),
       (93876, 30207, 'fr', 'Jerbou à longues oreilles', 'La gerboise à longues oreilles est un petit rongeur nocturne originaire des déserts d''Asie centrale. Reconnue pour ses longues oreilles caractéristiques et ses grandes pattes arrière, cette créature agile est parfaitement adaptée pour sauter et se déplacer dans son environnement aride. La couleur du pelage de la jerboa à longues oreilles est généralement d''une teinte sable ou marron clair, ce qui lui permet de se fondre dans son environnement désertique.\\n\\nLa jerboa à longues oreilles se nourrit principalement de graines, d''insectes et d''autres matières végétales\\n\\n'),
       (93877, 30207, 'es', 'Jerboa de orejas largas', 'La jerboa de orejas largas es un pequeño roedor nocturno originario de los desiertos de Asia Central. Conocida por sus características orejas largas y sus grandes patas traseras, esta ágil criatura está perfectamente adaptada para saltar y desplazarse por su entorno árido. El pelaje de la jerboa de orejas largas suele ser de un tono arenoso o marrón claro, lo que le ayuda a camuflarse en su entorno desértico.\\n\\nLa jerboa de orejas largas se alimenta principalmente de semillas, insectos y otros materiales vegetales\\n\\n'),
       (93878, 30208, 'nl', 'Chinchilla met lange staart', 'De langstaartchinchilla is een klein knaagdier dat van nature voorkomt in het Andesgebergte in Zuid-Amerika. Deze soort staat bekend om zijn zachte, dichte vacht en heeft een lange, borstelige staart die bijdraagt aan zijn evenwicht en behendigheid. De vachtkleur is doorgaans zachtgrijs, met variaties in tint van licht tot donker. Langstaartchinchilla’s zijn sociale dieren die vaak in groepen leven. Door het verlies van hun leefgebied en de jacht op hun vacht worden ze in het wild als kwetsbaar beschouwd. \\n\\nLangstaartchinchilla’s voeden zich voornamelijk met grassen, zaden en ander plantaardig materiaal.\\n\\n'),
       (93879, 30208, 'fr', 'Chinchilla à longue queue', 'Le chinchilla à longue queue est un petit rongeur originaire des Andes, en Amérique du Sud. Reconnu pour son pelage doux et dense, cette espèce possède une longue queue touffue qui lui confère équilibre et agilité. La couleur de son pelage est généralement d''un gris clair, dont la nuance peut varier du plus clair au plus foncé. Les chinchillas à longue queue sont des animaux sociables, que l''on trouve souvent en groupes. En raison de la destruction de leur habitat et de la chasse pour leur fourrure, ils sont considérés comme une espèce vulnérable à l''état sauvage. \\n\\nLes chinchillas à longue queue se nourrissent principalement d''herbes, de graines et d''autres végétaux.\\n\\n'),
       (93880, 30208, 'es', 'Chinchilla de cola larga', 'La chinchilla de cola larga es un pequeño roedor originario de la cordillera de los Andes, en Sudamérica. Conocida por su pelaje suave y denso, esta especie tiene una cola larga y tupida que le ayuda a mantener el equilibrio y la agilidad. El color de su pelaje suele ser un gris suave, cuyo tono puede variar de claro a oscuro. Las chinchillas de cola larga son animales sociables que suelen vivir en grupos. Debido a la pérdida de su hábitat y a la caza para obtener su pelaje, se consideran una especie vulnerable en estado silvestre. \\n\\nLas chinchillas de cola larga se alimentan principalmente de hierbas, semillas y otros materiales vegetales.\\n\\n'),
       (93881, 30209, 'nl', 'Lop Rabbit', 'Het Lop-konijn is een populair ras dat bekendstaat om zijn kenmerkende hangoren die naast zijn kop hangen. Deze konijnen hebben een compact, rond lichaam en een vriendelijk, zachtaardig karakter. Lop-konijnen zijn er in verschillende kleuren en patronen, en ze wegen doorgaans tussen de 1,5 en 4,5 kilogram (3 tot 10 pond), afhankelijk van de specifieke variant (zoals de Mini Lop of de Franse Lop). \\n\\nLop-konijnen eten voornamelijk een herbivoor dieet dat bestaat uit grassen, wilde kruiden, bladgroenten en jonge scheuten. \\n\\n'),
       (93882, 30209, 'fr', 'Lop Rabbit', 'Le lapin Lop est une race très appréciée, connue pour ses oreilles tombantes caractéristiques qui pendent de chaque côté de sa tête. Ces lapins ont un corps compact et arrondi, ainsi qu''un tempérament amical et doux. Les lapins Lop se déclinent en différentes couleurs et motifs, et leur poids varie généralement entre 1,5 et 4,5 kilogrammes (3 à 10 livres), selon la variété (comme le Mini Lop ou le Lop français). \\n\\nLes lapins Lop ont un régime principalement herbivore composé d''herbes, de plantes sauvages, de légumes verts à feuilles et de jeunes pousses. \\n\\n'),
       (93883, 30209, 'es', 'Lop Rabbit', 'El conejo Lop es una raza muy popular conocida por sus características orejas caídas que cuelgan a los lados de la cabeza. Estos conejos tienen un cuerpo compacto y redondeado, y un carácter amistoso y dócil. Los conejos Lop pueden presentar diversos colores y patrones, y suelen pesar entre 1,5 y 4,5 kilogramos (de 3 a 10 libras), dependiendo de la variedad concreta (como el Mini Lop o el French Lop). \\n\\nLos conejos Lop siguen principalmente una dieta herbívora compuesta por pastos, hierbas silvestres, verduras de hoja verde y brotes tiernos. \\n\\n'),
       (93884, 30210, 'nl', 'Prachtfregatvogel', 'De prachtige fregatvogel is een opvallende tropische zeevogel die bekendstaat om zijn enorme spanwijdte van 89-114 cm (35-45 inch) en zijn gracieuze zweefvlucht. Hij heeft een lange, haakvormige snavel en een diep gevorkte staart. Mannetjes schitteren met een glanzend zwart verenkleed en een felrode, opblaasbare keelzak die ze tijdens het baltsgedrag als een ballon opblazen.\\n\\nZe voeden zich voornamelijk met vliegende vissen en inktvissen die ze tijdens het zweven van het oceaanoppervlak weggrijpen.\\n\\n'),
       (93885, 30210, 'fr', 'Frégate magnifique', 'La frégate magnifique est un oiseau marin tropical remarquable, connu pour son immense envergure de 89 à 114 cm (35 à 45 pouces) et son vol plané gracieux. Elle possède un long bec recourbé et une queue profondément fourchue. Les mâles éblouissent par leur plumage noir brillant et leur poche gorgale rouge vif qu’ils gonflent comme un ballon lors des parades nuptiales.\\n\\nIls se nourrissent principalement de poissons volants et de calmars qu’ils capturent à la surface de l’océan tout en planant.\\n\\n'),
       (93886, 30210, 'es', 'Fregata magnífica', 'La fragata magnífica es una llamativa ave marina tropical conocida por su enorme envergadura, de entre 89 y 114 cm (35-45 pulgadas), y por su elegante vuelo planeador. Tiene un pico largo y ganchudo, y una cola profundamente bifurcada. Los machos deslumbran con un plumaje negro brillante y una bolsa gorguera de color rojo vivo que inflan como un globo durante las exhibiciones nupciales.\\n\\nSe alimentan principalmente de peces voladores y calamares que capturan de la superficie del océano mientras planean.\\n\\n'),
       (93887, 30211, 'nl', 'Maleisische tijger', 'De Maleisische tijger is een ernstig bedreigde ondersoort van de tijger die inheems is op het Maleisische schiereiland, bekend om zijn opvallende oranje vacht met zwarte strepen, zijn krachtige lichaamsbouw en zijn vermogen om in zijn eentje te jagen. Mannetjes kunnen 2,5-3 meter (8-10 voet) lang worden en 100-150 kg (220-330 pond) wegen, terwijl vrouwtjes iets kleiner zijn, met een lengte van 2-2,5 meter en een gewicht van 75-120 kg; ze hebben een levensduur van 15-20 jaar in het wild.\\n\\nMaleise tijgers zijn carnivoren en jagen op herten, wilde zwijnen, tapirs en kleinere zoogdieren.\\n\\n'),
       (93888, 30211, 'fr', 'Tigre de Malaisie', 'Le tigre de Malaisie est une sous-espèce de tigre en danger critique d''extinction, originaire de la péninsule malaise, connue pour son pelage orange éclatant strié de noir, sa constitution puissante et ses talents de chasseur solitaire. Les mâles peuvent atteindre 2,5 à 3 mètres (8 à 10 pieds) de long et peser entre 100 et 150 kg (220 à 330 livres), tandis que les femelles sont légèrement plus petites, mesurant entre 2 et 2,5 mètres et pesant entre 75 et 120 kg ; leur espérance de vie à l''état sauvage est de 15 à 20 ans.\\n\\nLes tigres de Malaisie sont carnivores et se nourrissent de cerfs, de sangliers, de tapirs et de petits mammifères.\\n\\n'),
       (93889, 30211, 'es', 'Tigre malayo', 'El tigre malayo es una subespecie de tigre en peligro crítico de extinción, originaria de la península malaya, conocida por su llamativo pelaje anaranjado con rayas negras, su complexión robusta y su destreza para cazar en solitario. Los machos pueden alcanzar una longitud de entre 2,5 y 3 metros (8-10 pies) y pesar entre 100 y 150 kg (220-330 libras), mientras que las hembras son ligeramente más pequeñas, con una longitud de entre 2 y 2,5 metros y un peso de entre 75 y 120 kg; tienen una esperanza de vida de entre 15 y 20 años en libertad.\\n\\nLos tigres malayos son carnívoros y se alimentan de ciervos, jabalíes, tapires y mamíferos más pequeños.\\n\\n'),
       (93890, 30212, 'nl', 'Mandarijnvis', 'De mandarijnvis is een klein, felgekleurd lid van de familie van de draakvisjes. Zijn levendige kleurstelling bestaat uit een helderblauwe achtergrond met wervelende oranje strepen en een blauwgroen gezicht met opvallende blauwe strepen. De ogen zijn meestal rood met zwarte pupillen.\\n\\nMandarijnvissen leven in riffen en geven de voorkeur aan beschutte lagunes en kustriffen. Ze zijn niet gemakkelijk te zien vanwege hun gewoonte om op de bodem te eten en hun kleine formaat (ze worden slechts ongeveer 6 cm groot). \\n\\nZe voeden zich voornamelijk met kleine kreeftachtigen en andere ongewervelde dieren.\\n\\n'),
       (93891, 30212, 'fr', 'Poisson-mandarine', 'Le poisson-mandarin est un petit poisson aux couleurs vives appartenant à la famille des dragonets. Sa coloration éclatante se caractérise par un fond bleu vif, des rayures orange en spirale et un visage bleu-verdâtre orné de larges rayures bleues. Ses yeux sont généralement rouges, avec des pupilles noires.\\n\\nLes poissons mandarins vivent dans les récifs et préfèrent les lagons abrités et les récifs côtiers. Ils sont difficiles à observer en raison de leur mode d''alimentation au fond de l''eau et de leur petite taille (ils ne mesurent qu''environ 6 cm). \\n\\nIls se nourrissent principalement de petits crustacés et d''autres invertébrés.\\n\\n'),
       (93892, 30212, 'es', 'Pez mandarina', 'El pez mandarín es un miembro pequeño y de colores vivos de la familia de los dragoncitos. Su llamativa coloración presenta un fondo azul brillante, con rayas naranjas en espiral y una cara de color azul verdoso con llamativas rayas azules. Los ojos suelen ser rojos con pupilas negras.\\n\\nLos peces mandarín habitan en los arrecifes y prefieren las lagunas protegidas y los arrecifes cercanos a la costa. No se ven fácilmente debido a su hábito de alimentarse en el fondo y a su pequeño tamaño (alcanzan solo unos 6 cm). \\n\\nSe alimentan principalmente de pequeños crustáceos y otros invertebrados.\\n\\n'),
       (93893, 30213, 'nl', 'Gemarmerde kat', 'De marmerkat is een kleine, schuwe wilde kat die in Zuidoost-Azië voorkomt en bekend staat om zijn opvallende gemarmerde vachtpatroon, dat lijkt op boomschors en dient als camouflage. Met een lichaamslengte van 45-60 cm (18-24 inch) plus een staart van 40-50 cm, en een gewicht van 2-5 kg (4,4-11 lbs), heeft hij een gedrongen lichaamsbouw, pluimachtige oren en intrekbare klauwen die geschikt zijn om mee te klimmen.\\n\\nGemarmerde katten zijn carnivoor en jagen op vogels, knaagdieren, eekhoorns en kleine zoogdieren; ze eten ook fruit en insecten, waardoor ze enigszins omnivoor zijn.\\n\\n'),
       (93894, 30213, 'fr', 'Chat marbré', 'Le chat marbré est un petit félin sauvage insaisissable originaire d''Asie du Sud-Est, connu pour son pelage marbré saisissant qui ressemble à de l''écorce d''arbre et lui sert de camouflage. Mesurant entre 45 et 60 cm (18 à 24 pouces) de long, plus une queue de 40 à 50 cm, et pesant entre 2 et 5 kg (4,4 à 11 livres), il présente une silhouette trapue, des oreilles à touffes et des griffes rétractables adaptées à l''escalade.\\n\\nLes chats marbrés sont carnivores et se nourrissent d''oiseaux, de rongeurs, d''écureuils et de petits mammifères ; ils consomment également des fruits et des insectes, ce qui en fait des animaux quelque peu omnivores.\\n\\n'),
       (93895, 30213, 'es', 'Gato marmolado', 'El gato marmolado es un felino salvaje pequeño y esquivo, originario del sudeste asiático, conocido por su llamativo pelaje marmolado, que se asemeja a la corteza de los árboles y le sirve de camuflaje. Mide entre 45 y 60 cm (18-24 pulgadas) de longitud corporal, más una cola de 40-50 cm, y pesa entre 2 y 5 kg (4,4-11 libras); tiene una complexión robusta, orejas con mechones y garras retráctiles adaptadas para trepar.\\n\\nLos gatos marmolados son carnívoros y se alimentan de aves, roedores, ardillas y pequeños mamíferos; también consumen frutas e insectos, lo que los convierte en animales algo omnívoros.\\n\\n'),
       (93896, 30214, 'nl', 'Markhor', 'De markhor is een wilde geitensoort die inheems is in Centraal- en Zuid-Azië, en vooral voorkomt in de bergachtige gebieden van Afghanistan, Pakistan en India. De markhor staat bekend om zijn indrukwekkende gedraaide hoorns, die tot 1,5 meter lang kunnen worden, en heeft een kenmerkende ruige vacht waarvan de kleur varieert van lichtbruin tot donkergrijs. Het is een behendige klimmer, die zich uitstekend kan verplaatsen over steile, rotsachtige terreinen. \\n\\nDe markhor is een herbivoor en voedt zich voornamelijk met grassen, struiken en bladeren.\\n\\n'),
       (93897, 30214, 'fr', 'Markhor', 'Le markhor est une espèce de chèvre sauvage originaire d''Asie centrale et d''Asie du Sud, que l''on trouve notamment dans les régions montagneuses de l''Afghanistan, du Pakistan et de l''Inde. Réputé pour ses impressionnantes cornes torsadées, qui peuvent atteindre 1,5 mètre de long, le markhor possède un pelage hirsute caractéristique dont la couleur varie du marron clair au gris foncé. C''est un excellent grimpeur, habile à se déplacer sur des terrains escarpés et rocheux. \\n\\nLe markhor est un herbivore qui se nourrit principalement d''herbes, d''arbustes et de feuilles.\\n\\n'),
       (93898, 30214, 'es', 'Markhor', 'El markhor es una especie de cabra salvaje originaria de Asia Central y Meridional, que se encuentra especialmente en las regiones montañosas de Afganistán, Pakistán y la India. Conocido por sus impresionantes cuernos retorcidos, que pueden alcanzar hasta 1,5 metros de longitud, el markhor tiene un pelaje hirsuto característico cuyo color varía del marrón claro al gris oscuro. Es un hábil trepador, experto en desplazarse por terrenos escarpados y rocosos. \\n\\nEl markhor es herbívoro y se alimenta principalmente de hierbas, arbustos y hojas.\\n\\n'),
       (93899, 30215, 'nl', 'Marsh Deer',
        'The Marsh Deer, also known as Pampas Deer, is South America\\\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\\n\\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \\n\\n'),
       (93900, 30215, 'fr', 'Marsh Deer',
        'The Marsh Deer, also known as Pampas Deer, is South America\\\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\\n\\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \\n\\n'),
       (93901, 30215, 'es', 'Marsh Deer',
        'The Marsh Deer, also known as Pampas Deer, is South America\\\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\\n\\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \\n\\n'),
       (93902, 30216, 'nl', 'Gemaskerde puffer', 'De gemaskerde kogelvis, ook wel bekend als de pandakogelvis, is een kogelvis uit de familie Tetraodontidae. Hij heeft zwarte vlekken rond beide ogen, heeft geen bekkenvinnen en kan zijn lichaam opblazen tot bijna twee keer zijn normale grootte. Bovendien steekt hij, wanneer hij zich bedreigd of gealarmeerd voelt, zijn stekels recht uit zijn lichaam. Niet te vergeten is ook de vergroeide, snavelachtige structuur die als tanden fungeert. De kogelvis behoort tot de meest giftige dieren ter wereld en staat op de tweede plaats, na de pijlgifkikkers.\\n\\nDe gemaskerde kogelvis is een alleseter, maar zijn dieet bestaat voornamelijk uit diverse ongewervelde dieren zoals weekdieren, sponzen, algen, stekelhuidigen en schaaldieren. Er is ook bekend dat hij af en toe koraal eet.\\n\\n'),
       (93903, 30216, 'fr', 'Puffer masqué', 'Le poisson-globe masqué, également connu sous le nom de poisson-globe panda, est un poisson-globe de la famille des Tetraodontidae. Il présente des taches noires autour des deux yeux, est dépourvu de nageoires pelviennes et a la capacité de gonfler son corps jusqu’à atteindre près du double de sa taille normale. De plus, lorsqu’il se sent menacé ou en alerte, il dresse ses épines à la verticale. Il ne faut pas oublier qu’il possède également une structure fusionnée en forme de bec qui lui sert de dents. Ce poisson-globe figure parmi les animaux les plus venimeux au monde, occupant la deuxième place, juste après les grenouilles dendrobates.\\n\\nLe poisson-globe masqué est omnivore, mais son régime alimentaire se compose principalement de divers invertébrés tels que des mollusques, des éponges, des algues, des échinodermes et des crustacés. On sait également qu''il consomme parfois du corail.\\n\\n'),
       (93904, 30216, 'es', 'Puffer enmascarado', 'El pez globo enmascarado, también conocido como pez globo panda, es un pez globo de la familia Tetraodontidae. Tiene manchas negras alrededor de ambos ojos, carece de aletas pélvicas y es capaz de inflar su cuerpo hasta casi el doble de su tamaño normal. Además, cuando se siente amenazado o alarmado, extiende sus espinas hacia fuera del cuerpo. No hay que pasar por alto que también cuenta con una estructura fusionada similar a un pico que le sirve de dientes. El pez globo es uno de los animales más venenosos del mundo, ocupando el segundo lugar, después de las ranas dardo venenosas.\\n\\nEl pez globo enmascarado es omnívoro, pero su dieta se compone principalmente de diversos invertebrados, como moluscos, esponjas, algas, equinodermos y crustáceos. También se sabe que, de vez en cuando, consume coral.\\n\\n'),
       (93905, 30217, 'nl', 'Matschie\\\'s Tree Kangaroo',
        'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \\n\\nMatschie\\\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\\n\\nUnder the IUCN classification, Matschie\\\'s Tree Kangaroo is an endangered species.\\n\\n'),
       (93906, 30217, 'fr', 'Matschie\\\'s Tree Kangaroo',
        'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \\n\\nMatschie\\\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\\n\\nUnder the IUCN classification, Matschie\\\'s Tree Kangaroo is an endangered species.\\n\\n'),
       (93907, 30217, 'es', 'Matschie\\\'s Tree Kangaroo',
        'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \\n\\nMatschie\\\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\\n\\nUnder the IUCN classification, Matschie\\\'s Tree Kangaroo is an endangered species.\\n\\n'),
       (93908, 30218, 'nl', 'Narwhal',
        'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\\\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\\n\\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \\n\\n'),
       (93909, 30218, 'fr', 'Narwhal',
        'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\\\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\\n\\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \\n\\n'),
       (93910, 30218, 'es', 'Narwhal',
        'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\\\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\\n\\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \\n\\n'),
       (93911, 30219, 'nl', 'Noordelijke pudu', 'De noordelijke pudu is de kleinste hertensoort ter wereld en komt van nature voor in de gematigde regenwouden van de Andes in het noorden van Chili en het zuiden van Argentinië. Volwassen noordelijke pudu’s zijn doorgaans ongeveer 30 tot 40 cm (12 tot 16 inch) hoog bij de schouder en wegen tussen de 6 en 10 kg (13 tot 22 lbs). Ze hebben een compact lichaam, korte poten en een roodbruine vacht met witte vlekken, waardoor ze goed opgaan in hun bosrijke leefgebied.\\n\\nHun dieet bestaat voornamelijk uit bladeren, vruchten en andere vegetatie. \\n\\n'),
       (93912, 30219, 'fr', 'Pudu du Nord', 'Le pudu du Nord est la plus petite espèce de cerf au monde ; il est originaire des forêts pluviales tempérées des Andes, dans le nord du Chili et le sud de l''Argentine. Les pudus du Nord adultes mesurent généralement entre 30 et 40 cm (12 à 16 pouces) au garrot et pèsent entre 6 et 10 kg (13 à 22 livres). Ils ont un corps compact, des pattes courtes et un pelage brun rougeâtre parsemé de taches blanches, ce qui leur permet de se fondre dans leur habitat forestier.\\n\\nLeur régime alimentaire se compose principalement de feuilles, de fruits et d''autres végétaux. \\n\\n'),
       (93913, 30219, 'es', 'Pudu del norte', 'El pudú del norte es la especie de ciervo más pequeña del mundo, originaria de los bosques pluviales templados de los Andes, en el norte de Chile y el sur de Argentina. Los pudúes del norte adultos suelen medir entre 30 y 40 cm (12 y 16 pulgadas) de altura a la cruz y pesan entre 6 y 10 kg (de 13 a 22 libras). Tienen un cuerpo compacto, patas cortas y un pelaje de color marrón rojizo con manchas blancas, lo que les ayuda a camuflarse en su hábitat boscoso.\\n\\nSu dieta se compone principalmente de hojas, frutos y otra vegetación. \\n\\n'),
       (93914, 30220, 'nl', 'Oceaanzonvis', 'De maanvis, ook wel bekend als de mola of sunfish, is de zwaarste beenvis ter wereld. Hij komt wereldwijd voor in tropische en gematigde oceanen, van het oppervlak tot een diepte van 600 meter (2.000 voet). Volwassen exemplaren kunnen tot 4,2 meter (14 voet) hoog en 3,2 meter (10,5 voet) lang worden. De ocean sunfish heeft een kenmerkend afgeplat, schijfvormig lichaam met een afgeknotte staartvin (clavus) en lange rug- en anaalvinnen die hij gebruikt om zich voort te stuwen.\\n\\nDe maanvis voedt zich voornamelijk met kwallen, plankton, kleine vissen en schaaldieren, waarvan hij grote hoeveelheden eet vanwege hun lage voedingswaarde. \\n\\n'),
       (93915, 30220, 'fr', 'Poisson lune', 'Le poisson-lune, également appelé « mola », est le poisson osseux le plus lourd au monde. Il vit dans les océans tropicaux et tempérés du monde entier, depuis les eaux de surface jusqu''à une profondeur de 600 mètres (2 000 pieds). Les adultes peuvent atteindre 4,2 mètres (14 pieds) de hauteur et 3,2 mètres (10,5 pieds) de longueur. Le poisson-lune possède un corps caractéristique, aplati et en forme de disque, avec une nageoire caudale tronquée (clavus) et de longues nageoires dorsales et anales qu’il utilise pour se propulser.\\n\\nLe poisson-lune se nourrit principalement de méduses, de plancton, de petits poissons et de crustacés, qu’il consomme en grandes quantités en raison de leur faible valeur nutritive. \\n\\n'),
       (93916, 30220, 'es', 'Peixe luna', 'El pez luna, también conocido como «mola» o «pez sol», es el pez óseo más pesado del mundo. Habita en los océanos tropicales y templados de todo el mundo, desde las aguas superficiales hasta profundidades de 600 metros (2.000 pies). Los ejemplares adultos pueden alcanzar hasta 4,2 metros (14 pies) de altura y 3,2 metros (10,5 pies) de longitud. El pez luna tiene un característico cuerpo aplanado, en forma de disco, con una aleta caudal truncada (clavus) y largas aletas dorsal y anal que utiliza para impulsarse.\\n\\nEl pez luna se alimenta principalmente de medusas, plancton, peces pequeños y crustáceos, consumiendo grandes cantidades debido a su bajo valor nutricional. \\n\\n'),
       (93917, 30221, 'nl', 'Gekleurde wobbegong', 'De sierlijke wobbegong is een soort tapijthaai die voorkomt in de ondiepe wateren van de westelijke Stille Oceaan. Hij heeft een afgeplat lichaam, een brede kop en een uniek patroon van ingewikkelde tekeningen waarmee hij zich in zijn omgeving kan verbergen. De sierlijke wobbegong heeft een gevlekte kleur met verschillende tinten bruin, geel en groen. Hij kan tot 3 meter (ongeveer 10 voet) lang worden, hoewel de meeste exemplaren kleiner zijn.\\n\\nSierlijke wobbegongs zijn vleeseters en voeden zich voornamelijk met vissen en ongewervelde dieren.\\n\\n'),
       (93918, 30221, 'fr', 'Wobbegong orné', 'Le wobbegong orné est une espèce de requin-tapis que l''on trouve dans les eaux peu profondes de l''océan Pacifique occidental. Il possède un corps aplati, une tête large et un motif unique composé de marques complexes qui lui permettent de se fondre dans son environnement. Le wobbegong orné présente une coloration marbrée composée de diverses nuances de brun, de jaune et de vert. Il peut atteindre 3 mètres (environ 10 pieds) de long, bien que la plupart des individus soient plus petits.\\n\\nLes wobbegongs ornés sont carnivores et se nourrissent principalement de poissons et d''invertébrés.\\n\\n'),
       (93919, 30221, 'es', 'Wobbegong ornamentado', 'El tiburón wobbegong ornamentado es una especie de tiburón alfombra que habita en las aguas poco profundas del océano Pacífico occidental. Tiene un cuerpo aplanado, una cabeza ancha y un patrón único de marcas intrincadas que le ayudan a camuflarse en su entorno. El wobbegong ornamentado presenta una coloración moteada con diversos tonos de marrón, amarillo y verde. Puede alcanzar hasta los 3 metros (unos 10 pies) de longitud, aunque la mayoría de los ejemplares son más pequeños.\\n\\nLos tiburones alfombra ornamentados son carnívoros y se alimentan principalmente de peces e invertebrados.\\n\\n'),
       (93920, 30222, 'nl', 'Owston\\\'s Palm Civet',
        'The Owston\\\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \\n\\nWhile most civet are omnivorous, Owston\\\'s Palm Civets are almost entirely plant and fruit eaters.\\n\\n'),
       (93921, 30222, 'fr', 'Owston\\\'s Palm Civet',
        'The Owston\\\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \\n\\nWhile most civet are omnivorous, Owston\\\'s Palm Civets are almost entirely plant and fruit eaters.\\n\\n'),
       (93922, 30222, 'es', 'Owston\\\'s Palm Civet',
        'The Owston\\\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \\n\\nWhile most civet are omnivorous, Owston\\\'s Palm Civets are almost entirely plant and fruit eaters.\\n\\n'),
       (93923, 30223, 'nl', 'Pacific Sea Eagle', 'De Pacifische zeearend, ook wel bekend als de witbuikzeearend, is een grote roofvogel die voornamelijk voorkomt in de kustgebieden van de Indische en de Stille Oceaan. Ze hebben een opvallend verenkleed, met een witte kop en buik, donkerbruine vleugels en rug, en een licht grijsbruin lichaam. Ze hebben een sterke, haakvormige snavel en krachtige klauwen, die essentieel zijn voor het vangen en vasthouden van hun prooi.\\n\\nDeze arenden zijn bekwame jagers die zich voornamelijk voeden met vis, maar ook jagen op vogels, kleine zoogdieren en aas. \\n\\n'),
       (93924, 30223, 'fr', 'Pacific Sea Eagle', 'L''aigle de mer du Pacifique, également connu sous le nom d''aigle de mer à ventre blanc, est un grand rapace que l''on trouve principalement dans les régions côtières des océans Indien et Pacifique. Il se distingue par son plumage caractéristique : tête et ventre blancs, ailes et dos brun foncé, et corps brun grisâtre pâle. Il est doté d''un bec robuste et recourbé ainsi que de serres puissantes, indispensables pour attraper et retenir ses proies.\\n\\nCes aigles sont d''habiles chasseurs qui se nourrissent principalement de poissons, mais s''attaquent également aux oiseaux, aux petits mammifères et aux charognes. \\n\\n'),
       (93925, 30223, 'es', 'Pacific Sea Eagle', 'El águila marina del Pacífico, también conocida como águila marina de vientre blanco, es una gran ave rapaz que se encuentra principalmente en las regiones costeras de los océanos Índico y Pacífico. Presenta un plumaje característico, con la cabeza y el vientre blancos, las alas y el dorso de color marrón oscuro, y el cuerpo de un tono marrón grisáceo pálido. Poseen un pico fuerte y ganchudo y unas garras poderosas, esenciales para capturar y sujetar a sus presas.\\n\\nEstas águilas son hábiles cazadoras que se alimentan principalmente de peces, aunque también cazan aves, pequeños mamíferos y carroña. \\n\\n'),
       (93926, 30224, 'nl', 'Pacman-kikker', 'De Pacman-kikker, ook wel bekend als de Zuid-Amerikaanse gehoornde kikker, is een stevige, kleurrijke amfibie die van nature voorkomt in de graslanden en bossen van Zuid-Amerika. Deze kikker staat bekend om zijn brede, ronde bek die lijkt op het videospelpersonage Pac-Man. Hij heeft een robuust lichaam van maximaal 15 cm (6 inch) lang, een levendig groene of bruine huid met rode vlekken en hoornachtige uitsteeksels boven zijn ogen.\\n\\nAls roofdier dat vanuit een hinderlaag toeslaat, graaft hij zich in de grond of in bladafval in om met zijn krachtige kaken insecten, kleine knaagdieren en zelfs andere kikkers te vangen.\\n\\n'),
       (93927, 30224, 'fr', 'Pacman Frog', 'La grenouille Pac-Man, également connue sous le nom de grenouille cornue d''Amérique du Sud, est un amphibien trapu et coloré originaire des prairies et des forêts d''Amérique du Sud. Réputée pour sa large bouche arrondie qui rappelle le personnage de jeu vidéo Pac-Man, elle possède un corps robuste pouvant atteindre 15 cm (6 pouces) de long, une peau d''un vert ou d''un brun éclatant parsemée de marques rouges, ainsi que des protubérances en forme de cornes au-dessus des yeux.\\n\\nPrédateur à l''affût, elle s''enfouit dans le sol ou la litière de feuilles pour capturer des insectes, de petits rongeurs et même d''autres grenouilles à l''aide de ses puissantes mâchoires.\\n\\n'),
       (93928, 30224, 'es', 'Rana Pacman', 'La rana Pac-Man, también conocida como rana cornuda sudamericana, es un anfibio robusto y colorido, originario de las praderas y los bosques de Sudamérica. Famosa por su boca ancha y redonda, que se asemeja al personaje del videojuego Pac-Man, tiene un cuerpo robusto de hasta 15 cm (6 pulgadas) de largo, una piel de color verde o marrón intenso con manchas rojas y unas protuberancias en forma de cuerno sobre los ojos.\\n\\nComo depredador de emboscada, se entierra en el suelo o entre la hojarasca para capturar insectos, pequeños roedores e incluso otras ranas con sus poderosas mandíbulas.\\n\\n'),
       (93929, 30225, 'nl', 'Parson\\\'s Chameleon',
        'Parson\\\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\\\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\\n\\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\\n\\n'),
       (93930, 30225, 'fr', 'Parson\\\'s Chameleon',
        'Parson\\\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\\\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\\n\\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\\n\\n'),
       (93931, 30225, 'es', 'Parson\\\'s Chameleon',
        'Parson\\\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\\\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\\n\\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\\n\\n'),
       (93932, 30226, 'nl', 'Pearl-Spotted Owlet',
        'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \\\'owlets\\\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \\\'eyes\\\' with a white outline.\\n\\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\\n\\n'),
       (93933, 30226, 'fr', 'Pearl-Spotted Owlet',
        'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \\\'owlets\\\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \\\'eyes\\\' with a white outline.\\n\\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\\n\\n'),
       (93934, 30226, 'es', 'Pearl-Spotted Owlet',
        'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \\\'owlets\\\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \\\'eyes\\\' with a white outline.\\n\\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\\n\\n'),
       (93935, 30227, 'nl', 'Pel\\\'s Fishing Owl',
        'Pel\\\'s Fishing Owl is one of Africa\\\'s largest owls, known for its exceptional fishing skills and striking appearance. With a wingspan of up to 1.5 meters (5 feet) and weighing 2-3 kg (4.4-6.6 lbs), it has mottled brown and white plumage, piercing yellow eyes, and powerful talons adapted for grasping slippery prey.\\n\\nPel\\\'s Fishing Owls are piscivorous (fish-eating), supplemented by frogs, crabs, and small rodents; hunts by perching near water and plunging in.\\n\\n'),
       (93936, 30227, 'fr', 'Pel\\\'s Fishing Owl',
        'Pel\\\'s Fishing Owl is one of Africa\\\'s largest owls, known for its exceptional fishing skills and striking appearance. With a wingspan of up to 1.5 meters (5 feet) and weighing 2-3 kg (4.4-6.6 lbs), it has mottled brown and white plumage, piercing yellow eyes, and powerful talons adapted for grasping slippery prey.\\n\\nPel\\\'s Fishing Owls are piscivorous (fish-eating), supplemented by frogs, crabs, and small rodents; hunts by perching near water and plunging in.\\n\\n'),
